import React from "react";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { PayrollExceptionsRegister } from "views/payroll/components/PayrollRegister";

export default function PayrollExceptionQueue({ exceptions, loading, compact }) {
  if (loading) {
    return (
      <LuxRegisterEmptyState
        className="lux-register-empty--compact"
        title="Loading exceptions"
        description="Fetching payroll exception queue."
      />
    );
  }

  const rows = (exceptions || []).filter((row) => !row.resolved);

  if (rows.length === 0) {
    return (
      <LuxRegisterEmptyState
        className="lux-register-empty--compact"
        icon="fe fe-check-circle"
        title="No open exceptions"
        description="Payroll runs are clear of blockers and warnings."
      />
    );
  }

  if (compact) {
    return (
      <ul className="lux-payroll-exception-list">
        {rows.map((row) => (
          <li key={row.id} className={classNames("lux-payroll-exception-card", {
            "is-blocker": row.severity === "Blocker",
            "is-warning": row.severity === "Warning",
          })}
          >
            <div className="lux-payroll-exception-card__head">
              <span className={classNames("lux-doc-badge", {
                "is-danger": row.severity === "Blocker",
                "is-warning": row.severity === "Warning",
              })}
              >
                {row.severity}
              </span>
              <span className="lux-payroll-exception-card__code">{row.code}</span>
            </div>
            <p className="lux-payroll-exception-card__message">{row.message || row.code}</p>
            <footer className="lux-payroll-exception-card__foot">
              <span>{row.employeeName || "General"}</span>
              {row.runId && (
                <Link to={`/payroll/runs/${row.runId}`} className="lux-doc-register__link">View run</Link>
              )}
            </footer>
          </li>
        ))}
      </ul>
    );
  }

  return <PayrollExceptionsRegister exceptions={rows} />;
}
