import React, { Component } from "react";
import { Modal } from "views/common/plugins/model/Modal";
import { Effect } from "views/common/plugins/model";
import { getAssistPanelModalStyle } from "./assistDock.utils";
import { escapeHtml, sanitizeRichHtml } from "_helpers/html-sanitize.utils";
import "./HelpSearchModal.css";

const DOCUMENTATION_INDEX_URL = "/documentation/documentation-search-index.json";

const FALLBACK_PAGES = [
  {
    title: "Home",
    url: "/documentation/index.html",
    description: "Documentation home and navigation",
    keywords: ["home", "overview", "guide"],
  },
  {
    title: "Getting Started",
    url: "/documentation/getting-started.html",
    description: "Login, SSO, onboarding basics",
    keywords: ["login", "sso", "getting started"],
  },
  {
    title: "FAQ",
    url: "/documentation/faq/index.html",
    description: "Frequently asked questions and troubleshooting",
    keywords: ["faq", "questions", "help"],
  },
  {
    title: "HRMS Overview",
    url: "/documentation/hrms/index.html",
    description: "HRMS module guides",
    keywords: ["hrms", "employees", "timesheet"],
  },
  {
    title: "Project Overview",
    url: "/documentation/project/index.html",
    description: "Project module guides",
    keywords: ["project", "deliverables", "taskboard"],
  },
  {
    title: "Application Configuration",
    url: "/documentation/hrms/application-config.html",
    description: "Org and role configuration",
    keywords: ["appconfig", "configuration", "permissions"],
  },
];

const QUICK_LINK_TITLES = [
  "Home",
  "Getting Started",
  "FAQ",
  "HRMS Overview",
  "Project Overview",
  "Timesheet",
  "Invoices",
  "Task Board",
  "Application Configuration",
];

class HelpSearchModal extends Component {
  constructor(props) {
    super(props);
    this.state = {
      searchQuery: "",
      searchResults: [],
      activeIndex: -1,
      searchTimeout: null,
      documentationPages: [],
      indexLoaded: false,
      indexError: false,
    };
    this.searchInputRef = React.createRef();
  }

  componentDidMount() {
    this.loadDocumentationIndex();
    setTimeout(() => {
      if (this.searchInputRef.current) {
        this.searchInputRef.current.focus();
      }
    }, 100);
  }

  loadDocumentationIndex = () => {
    fetch(`${DOCUMENTATION_INDEX_URL}?v=${Date.now()}`)
      .then((response) => {
        if (!response.ok) {
          throw new Error("Failed to load documentation index");
        }
        return response.json();
      })
      .then((data) => {
        const pages = Array.isArray(data) ? data : data.pages || [];
        this.setState({
          documentationPages: pages.length ? pages : FALLBACK_PAGES,
          indexLoaded: true,
          indexError: !pages.length,
        });
      })
      .catch(() => {
        this.setState({
          documentationPages: FALLBACK_PAGES,
          indexLoaded: true,
          indexError: true,
        });
      });
  };

  searchDocumentation = (query) => {
    const { documentationPages } = this.state;
    if (!query || query.trim().length < 2 || !documentationPages.length) {
      return [];
    }

    const searchTerm = query.toLowerCase().trim();
    const results = [];

    const terms = searchTerm.split(/\s+/).filter(Boolean);
    documentationPages.forEach((page) => {
      let score = 0;
      const title = (page.title || "").toLowerCase();
      const desc = (page.description || "").toLowerCase();
      const headings = (page.headings || []).join(" ").toLowerCase();
      const content = (page.content || "").toLowerCase();
      const keywords = (page.keywords || []).map((kw) => String(kw).toLowerCase());
      const haystack = [title, desc, headings, content, keywords.join(" ")].join(" ");
      const titleMatch = title.includes(searchTerm) || terms.every((t) => title.includes(t));
      const descMatch = desc.includes(searchTerm) || terms.every((t) => desc.includes(t));
      const headingMatch = headings.includes(searchTerm) || terms.every((t) => headings.includes(t));
      const contentMatch = content.includes(searchTerm) || terms.every((t) => content.includes(t));
      const keywordMatches = keywords.filter((kw) =>
        kw.includes(searchTerm) || terms.every((t) => kw.includes(t))
      ).length;

      if (titleMatch) score += 12;
      if (descMatch) score += 6;
      if (headingMatch) score += 5;
      if (contentMatch) score += 3;
      score += keywordMatches * 2;
      if (terms.length > 1 && terms.every((t) => haystack.includes(t))) score += 4;

      if (score > 0) {
        let snippet = page.description || "";
        if (!descMatch && contentMatch && content) {
          const idx = content.indexOf(terms[0]);
          const start = Math.max(0, idx - 60);
          snippet = (start > 0 ? "…" : "") + (page.content || "").slice(start, start + 160) + "…";
        }
        results.push({
          ...page,
          description: snippet,
          score,
          matchType: titleMatch
            ? "title"
            : headingMatch
              ? "heading"
              : descMatch
                ? "description"
                : contentMatch
                  ? "content"
                  : "keyword",
        });
      }
    });

    results.sort((a, b) => b.score - a.score);
    return results.slice(0, 20);
  };

  highlightText = (text, query) => {
    if (!text) return "";
    const safeText = escapeHtml(text);
    if (!query) return safeText;
    const escaped = query.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const regex = new RegExp(`(${escaped})`, "gi");
    return sanitizeRichHtml(safeText.replace(regex, "<mark>$1</mark>"));
  };

  handleSearchChange = (e) => {
    const query = e.target.value;
    this.setState({ searchQuery: query, activeIndex: -1 });

    if (this.state.searchTimeout) {
      clearTimeout(this.state.searchTimeout);
    }

    if (query.length < 2) {
      this.setState({ searchResults: [] });
      return;
    }

    const timeout = setTimeout(() => {
      const results = this.searchDocumentation(query);
      this.setState({ searchResults: results });
    }, 200);

    this.setState({ searchTimeout: timeout });
  };

  handleKeyDown = (e) => {
    const { searchResults, activeIndex } = this.state;

    if (e.key === "ArrowDown") {
      e.preventDefault();
      const nextIndex =
        activeIndex < searchResults.length - 1 ? activeIndex + 1 : activeIndex;
      this.setState({ activeIndex: nextIndex });
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      const prevIndex = activeIndex > 0 ? activeIndex - 1 : -1;
      this.setState({ activeIndex: prevIndex });
    } else if (e.key === "Enter" && activeIndex >= 0 && searchResults[activeIndex]) {
      e.preventDefault();
      this.handleResultClick(searchResults[activeIndex]);
    } else if (e.key === "Escape") {
      this.props.onRequestClose();
    }
  };

  handleResultClick = (result) => {
    if (result && result.url && this.isSafeDocumentationUrl(result.url)) {
      window.open(result.url, "_blank", "noopener,noreferrer");
    }
  };

  isSafeDocumentationUrl = (url) => {
    if (!url || typeof url !== "string") {
      return false;
    }
    const trimmed = url.trim();
    if (trimmed.startsWith("#")) {
      return true;
    }
    if (trimmed.includes("://") || trimmed.startsWith("//")) {
      return false;
    }
    return trimmed.startsWith("/documentation/")
      || trimmed.startsWith("../")
      || trimmed.startsWith("documentation/");
  };

  handleResultMouseEnter = (index) => {
    this.setState({ activeIndex: index });
  };

  componentWillUnmount() {
    if (this.state.searchTimeout) {
      clearTimeout(this.state.searchTimeout);
    }
  }

  handleQuickLink = (page) => {
    this.handleResultClick(page);
  };

  getQuickLinks = () => {
    const { documentationPages } = this.state;
    if (!documentationPages.length) {
      return FALLBACK_PAGES.slice(0, 6);
    }
    const picked = QUICK_LINK_TITLES.map((title) =>
      documentationPages.find((p) => p.title === title)
    ).filter(Boolean);
    return picked.length ? picked.slice(0, 8) : documentationPages.slice(0, 6);
  };

  render() {
    const { searchQuery, searchResults, activeIndex, indexLoaded, indexError } =
      this.state;
    const { onRequestClose, dockAnchor } = this.props;
    const quickLinks = this.getQuickLinks();

    return (
      <Modal
        onRequestClose={onRequestClose}
        effect={Effect.ScaleUp}
        style={getAssistPanelModalStyle(dockAnchor)}
      >
        <div className="help-search-modal lux-assist-panel lux-assist-panel--help">
          <div className="lux-assist-panel__hero lux-assist-panel__hero--help">
            <div className="lux-assist-panel__hero-bg" aria-hidden="true" />
            <div className="lux-assist-panel__hero-top">
              <div className="lux-assist-panel__brand">
                <span className="lux-assist-panel__brand-icon lux-assist-panel__brand-icon--help">
                  <i className="fa fa-life-ring" />
                </span>
                <div>
                  <span className="lux-assist-panel__kicker">Knowledge</span>
                  <h4 className="lux-assist-panel__title mb-0">Help Center</h4>
                </div>
              </div>
              <button
                type="button"
                onClick={onRequestClose}
                className="lux-assist-panel__close"
                aria-label="Close help panel"
              >
                <i className="fa fa-times" />
              </button>
            </div>
            <p className="lux-assist-panel__hero-lead">
              Search documentation, FAQ, and guides without leaving your page.
            </p>
          </div>

          <div className="lux-assist-panel__body">
            <div className="help-search-wrapper">
              <label className="lux-assist-panel__search-label" htmlFor="help-search-input">
                Search
              </label>
              <div className="lux-assist-panel__search">
                <i className="fa fa-search lux-assist-panel__search-icon" aria-hidden="true" />
                <input
                  id="help-search-input"
                  ref={this.searchInputRef}
                  type="text"
                  className="lux-assist-panel__search-input"
                  placeholder="Projects, HRMS, timesheet, invoices, FAQ…"
                  value={searchQuery}
                  onChange={this.handleSearchChange}
                  onKeyDown={this.handleKeyDown}
                  autoComplete="off"
                  disabled={!indexLoaded}
                />
              </div>

              {!indexLoaded && (
                <div className="help-search-hint">
                  <i className="fa fa-spinner fa-spin mr-2" aria-hidden="true" />
                  Loading documentation index…
                </div>
              )}

              {indexLoaded && indexError && (
                <div className="help-search-hint help-search-hint--warn">
                  <i className="fa fa-exclamation-triangle mr-2" aria-hidden="true" />
                  Using limited offline topics — regenerate documentation index if search seems incomplete.
                </div>
              )}

              {indexLoaded && searchQuery.length >= 2 && (
                <div className="help-search-results">
                  {searchResults.length === 0 ? (
                    <div className="no-results">
                      <i className="fa fa-search-minus mb-2" aria-hidden="true" />
                      <p>No results for &ldquo;{searchQuery}&rdquo;</p>
                      <span>Try a different keyword or browse topics below.</span>
                    </div>
                  ) : (
                    <div className="results-list">
                      {searchResults.map((result, index) => (
                        <div
                          key={`${result.url}-${index}`}
                          className={`result-item ${
                            index === activeIndex ? "active" : ""
                          }`}
                          onClick={() => this.handleResultClick(result)}
                          onMouseEnter={() => this.handleResultMouseEnter(index)}
                          role="button"
                          tabIndex={0}
                          onKeyDown={(ev) => {
                            if (ev.key === "Enter") this.handleResultClick(result);
                          }}
                        >
                          <div className="result-title">
                            <span
                              dangerouslySetInnerHTML={{
                                __html: this.highlightText(result.title, searchQuery),
                              }}
                            />
                          </div>
                          <div className="result-description">
                            <span
                              dangerouslySetInnerHTML={{
                                __html: this.highlightText(
                                  result.description,
                                  searchQuery
                                ),
                              }}
                            />
                          </div>
                          <div className="result-type">{result.matchType}</div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              )}

              {indexLoaded && searchQuery.length < 2 && (
                <>
                  <div className="help-search-hint">
                    <i className="fa fa-lightbulb mr-2" aria-hidden="true" />
                    Type at least 2 characters to search, or pick a topic below.
                  </div>
                  <div className="lux-assist-panel__quick-links">
                    <span className="lux-assist-panel__quick-label">Popular topics</span>
                    <div className="lux-assist-panel__quick-grid">
                      {quickLinks.map((page) => (
                        <button
                          key={page.url}
                          type="button"
                          className="lux-assist-panel__quick-chip"
                          onClick={() => this.handleQuickLink(page)}
                        >
                          {page.title}
                        </button>
                      ))}
                    </div>
                  </div>
                </>
              )}
            </div>
          </div>
        </div>
      </Modal>
    );
  }
}

export default HelpSearchModal;
