import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isIntegrationCenterEnabled } from "config/integration-center.config";
import { isDeveloperPortalEnabled } from "config/developer-portal.config";
import { INTEGRATION_API_ACCESS_PAGE_META } from "config/integration-center-nav.config";
import { developerPortalService } from "_services/developerPortal.service";
import { commonUtils } from "_helpers";
import IntegrationsLuxPage, {
  IntegrationActionButton,
  IntegrationLuxPanel,
} from "views/integrations/components/IntegrationsLuxShared";
import ApiKeyRegister from "views/developer/components/ApiKeyRegister";
import { ApiKeyCreateDrawer } from "views/developer/components/DeveloperCreateDrawers";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import { getApiErrorMessage } from "_helpers";

class IntegrationApiAccessPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    keys: [],
    statusFilter: "ALL",
    busy: false,
    createOpen: false,
  };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    const { statusFilter } = this.state;
    this.setState({ loading: true, loadError: null });
    try {
      const filters = statusFilter !== "ALL" ? { status: statusFilter } : {};
      const result = await developerPortalService.listApiKeys(filters);
      this.setState({
        loading: false,
        dataSource: result.source,
        keys: result.payload || [],
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: getApiErrorMessage(error, "Unable to load integration API keys."),
      });
    }
  };

  handleRevoke = async (key) => {
    this.setState({ busy: true });
    try {
      await developerPortalService.revokeApiKey(key.id);
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: getApiErrorMessage(error, "Unable to revoke key.") });
    } finally {
      this.setState({ busy: false });
    }
  };

  handleDelete = async (key) => {
    this.setState({ busy: true });
    try {
      await developerPortalService.deleteApiKey(key.id);
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: getApiErrorMessage(error, "Unable to delete key.") });
    } finally {
      this.setState({ busy: false });
    }
  };

  renderQuickStart() {
    const teamId = commonUtils.getCurrentUserTeamId();
    return (
      <IntegrationLuxPanel
        title="External project creation"
        meta="Use a scoped integration token against the existing v2 API"
        icon="fe fe-terminal"
        accent="emerald"
      >
        <pre className="lux-int-quickstart">
{`POST /api/v2/projects
Authorization: Bearer tk_live_...
Content-Type: application/json

{
  "name": "ERP project",
  "userTeamId": ${teamId || "<teamId>"},
  "purchaseOrderId": <purchaseOrderId>,
  "createdBy": <serviceEmployeeId>
}`}
        </pre>
        <p className="lux-int-quickstart-note">
          Grant <code>projects.write</code> on the key. The team on the key must match <code>userTeamId</code> in the body.
        </p>
      </IntegrationLuxPanel>
    );
  }

  render() {
    if (!isIntegrationCenterEnabled() || !isDeveloperPortalEnabled()) {
      return <PersonaAccessDenied featureLabel="Integration API access" />;
    }

    const { loading, loadError, dataSource, keys, statusFilter, busy, createOpen } = this.state;

    return (
      <IntegrationsLuxPage
        pageMeta={INTEGRATION_API_ACCESS_PAGE_META}
        pageId="integration-api-access"
        shellTitle="API access"
        dataSource={dataSource}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        onRefresh={this.loadData}
        refreshLoading={loading}
        heroActions={
          <>
            <IntegrationActionButton variant="primary" icon="fe fe-plus" onClick={() => this.setState({ createOpen: true })}>
              Create token
            </IntegrationActionButton>
            <IntegrationActionButton
              icon="fe fe-book"
              onClick={() => {
                window.location.assign("/documentation/integration-api-console.html");
              }}
            >
              API console
            </IntegrationActionButton>
            <IntegrationActionButton to="/integrations/hub" icon="fe fe-link">
              Integration hub
            </IntegrationActionButton>
          </>
        }
      >
        {loadError ? <LuxInlineAlert message={loadError} /> : null}
        {this.renderQuickStart()}
        <IntegrationLuxPanel
          title="Integration tokens"
          meta="Scoped credentials for external systems"
          icon="fe fe-key"
          accent="indigo"
          featured
          actions={
            <select
              className="lux-dev-filter"
              value={statusFilter}
              onChange={(e) => this.setState({ statusFilter: e.target.value }, this.loadData)}
            >
              <option value="ALL">All statuses</option>
              <option value="active">Active</option>
              <option value="revoked">Revoked</option>
              <option value="expired">Expired</option>
            </select>
          }
        >
          <ApiKeyRegister
            keys={keys}
            loading={loading}
            onRevoke={this.handleRevoke}
            onDelete={this.handleDelete}
            busy={busy}
          />
        </IntegrationLuxPanel>
        <ApiKeyCreateDrawer
          open={createOpen}
          onClose={() => this.setState({ createOpen: false })}
            onCreate={(payload) => developerPortalService.createApiKey({
            ...payload,
            serviceEmployeeId: commonUtils.getCurrentUserId(),
            createdByEmployeeId: commonUtils.getCurrentUserId(),
            ownerName: commonUtils.getCurrentUserName(),
          })}
          onCreated={this.loadData}
        />
      </IntegrationsLuxPage>
    );
  }
}

export default IntegrationApiAccessPage;
