import React from "react";
import LoadingButton from "views/common/fragments/LoadingButton";

export default function LuxNoteEditorFooter({
  isEdit,
  isSaving,
  canSubmit,
  onClose,
  onSubmit,
}) {
  return (
    <footer className="lux-create-footer lux-note-editor-footer">
      <div className="lux-create-footer__bar">
        <div className="lux-create-footer__options">
          <span className="lux-note-editor-footer__hint">
            <i className="fe fe-info" aria-hidden="true" />
            Title is required to save
          </span>
        </div>
        <div className="lux-create-footer__actions">
          <button
            type="button"
            className="lux-create-footer__btn lux-create-footer__btn--ghost"
            onClick={onClose}
            disabled={isSaving}
          >
            Cancel
          </button>
          <LoadingButton
            type="button"
            isLoading={isSaving}
            loadingText={isEdit ? "Saving…" : "Adding…"}
            variant="primary"
            size="sm"
            className="lux-create-footer__submit"
            disabled={!canSubmit || isSaving}
            onClick={onSubmit}
            icon="fe fe-check"
          >
            {isEdit ? "Save note" : "Add note"}
          </LoadingButton>
        </div>
      </div>
    </footer>
  );
}
