import React from "react";
import { EXPENSE_CATEGORIES, EXPENSE_CLAIM_STATUSES } from "config/expenses.config";
import ExpenseRegister from "views/expenses/components/ExpenseRegister";

const STATUS_OPTIONS = [
  { value: "ALL", label: "All statuses" },
  { value: EXPENSE_CLAIM_STATUSES.SUBMITTED, label: "Submitted" },
  { value: EXPENSE_CLAIM_STATUSES.MANAGER_APPROVED, label: "Manager approved" },
  { value: EXPENSE_CLAIM_STATUSES.FINANCE_APPROVED, label: "Finance approved" },
  { value: EXPENSE_CLAIM_STATUSES.REJECTED, label: "Rejected" },
];

export default function ExpenseFinanceQueuePanel({
  rows = [],
  loading,
  busyId,
  filters = {},
  onFilterChange,
  onApprove,
  onReject,
}) {
  const pendingCount = rows.filter((row) =>
    [EXPENSE_CLAIM_STATUSES.SUBMITTED, EXPENSE_CLAIM_STATUSES.MANAGER_APPROVED].includes(row.status)
  ).length;
  const violationCount = rows.filter((row) => row.policyViolations && row.policyViolations.length > 0).length;
  const queueTotalUsd = rows.reduce((sum, row) => sum + (row.totalUsd || 0), 0);

  return (
    <div className="lux-expense-snapshots">
      <div className="lux-expense-snapshots__summary">
        <article className="lux-expense-snapshots__stat is-amber">
          <span>Pending review</span>
          <strong>{loading ? "—" : pendingCount}</strong>
        </article>
        <article className="lux-expense-snapshots__stat is-rose">
          <span>Policy issues</span>
          <strong>{loading ? "—" : violationCount}</strong>
        </article>
        <article className="lux-expense-snapshots__stat is-indigo">
          <span>Queue value</span>
          <strong>{loading ? "—" : `$${queueTotalUsd.toLocaleString()}`}</strong>
        </article>
      </div>

      <div className="lux-expense-snapshots__toolbar">
        <div className="lux-expense-snapshots__filters">
          <label className="lux-expense-snapshots__field">
            <span>Search</span>
            <input
              type="search"
              placeholder="Employee, claim, project…"
              value={filters.query || ""}
              onChange={(event) => onFilterChange({ query: event.target.value })}
            />
          </label>
          <label className="lux-expense-snapshots__field">
            <span>Status</span>
            <select
              value={filters.status || "ALL"}
              onChange={(event) => onFilterChange({ status: event.target.value })}
            >
              {STATUS_OPTIONS.map((option) => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
          </label>
          <label className="lux-expense-snapshots__field">
            <span>Category</span>
            <select
              value={filters.category || "ALL"}
              onChange={(event) => onFilterChange({ category: event.target.value })}
            >
              <option value="ALL">All categories</option>
              {Object.keys(EXPENSE_CATEGORIES).map((key) => (
                <option key={key} value={EXPENSE_CATEGORIES[key]}>
                  {EXPENSE_CATEGORIES[key]}
                </option>
              ))}
            </select>
          </label>
          <label className="lux-expense-snapshots__field lux-expense-snapshots__field--check">
            <input
              type="checkbox"
              checked={filters.policyIssuesOnly === true}
              onChange={(event) => onFilterChange({ policyIssuesOnly: event.target.checked })}
            />
            <span>Policy issues only</span>
          </label>
        </div>
      </div>

      <ExpenseRegister
        rows={rows}
        loading={loading}
        mode="finance"
        busyId={busyId}
        onApprove={onApprove}
        onReject={onReject}
      />
    </div>
  );
}
