import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { commonUtils } from "_helpers";
import { isTicketManagementEnabled } from "config/ticket-management.config";
import { TICKET_PAGE_META } from "config/ticket-management-nav.config";
import { buildTicketKpis } from "config/ticket-management.utils";
import { ticketManagementService } from "_services/ticketManagement.service";
import TicketsLuxPage, {
  TicketActionButton,
  TicketInsightPanel,
  TicketLuxPanel,
} from "views/tickets/components/TicketsLuxShared";
import TicketAnalyticsPanel from "views/tickets/components/TicketAnalyticsPanel";
import TicketDetailDrawer from "views/tickets/components/TicketDetailDrawer";
import TicketQueueBoard from "views/tickets/components/TicketQueueBoard";
import TicketRegister from "views/tickets/components/TicketRegister";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class ProjectTicketsPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    tickets: [],
    queues: [],
    kpiCards: [],
    insights: [],
    analytics: null,
    queueFilter: "ALL",
    statusFilter: "ALL",
    drawerTicket: null,
    aiSuggestion: null,
    aiLoading: false,
    busy: false,
  };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    const { queueFilter, statusFilter } = this.state;
    this.setState({ loading: true, loadError: null });
    try {
      const filters = {};
      if (queueFilter !== "ALL") {
        filters.queue = queueFilter;
      }
      if (statusFilter !== "ALL") {
        filters.status = statusFilter;
      }
      const result = await ticketManagementService.getOverview(filters);
      const payload = result.payload || {};
      const tickets = payload.tickets || [];
      this.setState({
        loading: false,
        dataSource: result.source,
        tickets,
        queues: payload.queues || [],
        kpiCards: buildTicketKpis(tickets),
        insights: payload.insights || [],
        analytics: payload.analytics || null,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load tickets.",
      });
    }
  };

  openDrawer = async (ticket) => {
    this.setState({ drawerTicket: ticket, aiSuggestion: null, aiLoading: true });
    try {
      const result = await ticketManagementService.getTicketAiSuggestions(ticket.id);
      this.setState({ aiSuggestion: result.payload || null, aiLoading: false });
    } catch (error) {
      this.setState({ aiLoading: false });
    }
  };

  handleResolve = async (ticket) => {
    this.setState({ busy: true });
    try {
      await ticketManagementService.resolveTicket(ticket.id);
      await this.loadData();
      this.setState({ drawerTicket: null });
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to resolve ticket." });
    } finally {
      this.setState({ busy: false });
    }
  };

  handleEscalate = async (ticket) => {
    this.setState({ busy: true });
    try {
      await ticketManagementService.escalateTicket(ticket.id);
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to escalate ticket." });
    } finally {
      this.setState({ busy: false });
    }
  };

  handleExport = async () => {
    try {
      const result = await ticketManagementService.exportTicketsCsv();
      const blob = new Blob([result.payload || ""], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = "tickets.csv";
      link.click();
      URL.revokeObjectURL(url);
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to export tickets." });
    }
  };

  handleCreateTicket = async () => {
    const title = window.prompt("Ticket title");
    if (!title || !String(title).trim()) {
      return;
    }
    this.setState({ busy: true, loadError: null });
    try {
      const employeeId = commonUtils.getCurrentUserId();
      const employeeName = commonUtils.getCurrentUserName() || "";
      await ticketManagementService.createTicket({
        title: String(title).trim(),
        requesterEmployeeId: employeeId != null ? String(employeeId) : "",
        requesterName: employeeName,
        assigneeEmployeeId: employeeId != null ? String(employeeId) : "",
        assigneeName: employeeName,
        ownerEmployeeId: employeeId != null ? String(employeeId) : "",
        ticketType: "GENERAL",
        queue: "support",
        queueLabel: "Support",
        priority: "P3",
        category: "question",
      });
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to create ticket." });
    } finally {
      this.setState({ busy: false });
    }
  };

  render() {
    if (!isTicketManagementEnabled()) {
      return <PersonaAccessDenied title="Tickets & service" message="Ticket management is not enabled." />;
    }

    const {
      loading,
      loadError,
      dataSource,
      tickets,
      queues,
      kpiCards,
      insights,
      analytics,
      queueFilter,
      statusFilter,
      drawerTicket,
      aiSuggestion,
      aiLoading,
      busy,
    } = this.state;

    return (
      <TicketsLuxPage
        pageMeta={TICKET_PAGE_META}
        shellTitle="Tickets & service"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        onRefresh={this.loadData}
        refreshLoading={loading}
        heroActions={<><TicketActionButton icon="fe fe-download" onClick={this.handleExport}>
              Export CSV
            </TicketActionButton>
          </>}
      >
        {loadError ? <LuxInlineAlert message={loadError} onDismiss={() => this.setState({ loadError: null })} /> : null}
        <TicketInsightPanel insights={insights} />
        <TicketAnalyticsPanel analytics={analytics} loading={loading} />

        <TicketLuxPanel title="Queue board" meta="SLA posture by service queue" icon="fe fe-grid" accent="indigo" featured>
          <TicketQueueBoard
            queues={queues}
            tickets={tickets}
            loading={loading}
            activeQueue={queueFilter !== "ALL" ? queueFilter : null}
            onQueueSelect={(queueId) => this.setState({ queueFilter: queueId }, this.loadData)}
          />
        </TicketLuxPanel>

        <TicketLuxPanel
          title="Ticket register"
          meta="Linked projects, work items, timesheets, and external refs"
          icon="fe fe-list"
          accent="blue"
          featured
          actions={
            <select
              className="lux-ticket-filter"
              value={statusFilter}
              onChange={(event) => this.setState({ statusFilter: event.target.value }, this.loadData)}
            >
              <option value="ALL">All statuses</option>
              <option value="open">Open</option>
              <option value="in_progress">In progress</option>
              <option value="waiting">Waiting</option>
              <option value="resolved">Resolved</option>
            </select>
          }
        >
          <TicketRegister
            tickets={tickets}
            loading={loading}
            selectedId={drawerTicket && drawerTicket.id}
            onSelect={this.openDrawer}
          />
        </TicketLuxPanel>

        <TicketDetailDrawer
          ticket={drawerTicket}
          aiSuggestion={aiSuggestion}
          aiLoading={aiLoading}
          busy={busy}
          onClose={() => this.setState({ drawerTicket: null, aiSuggestion: null })}
          onResolve={this.handleResolve}
          onEscalate={this.handleEscalate}
        />
      </TicketsLuxPage>
    );
  }
}

export default ProjectTicketsPage;
