import React from "react";
import PropTypes from "prop-types";
import { forceReloadLatestApp } from "_helpers/appUpdate.utils";

/**
 * Compact top banner when /version.json is newer than the running build.
 */
function AppUpdateBanner({ show, remoteVersion, onReload }) {
  if (!show) return null;

  const handleReload = () => {
    if (typeof onReload === "function") {
      onReload();
      return;
    }
    forceReloadLatestApp();
  };

  return (
    <div className="lux-app-update-banner" role="status" data-testid="app-update-banner">
      <div className="lux-app-update-banner__inner">
        <span className="lux-app-update-banner__text">
          A newer version{remoteVersion ? ` (v${remoteVersion})` : ""} is available.
        </span>
        <button
          type="button"
          className="lux-app-update-banner__action"
          data-testid="app-update-reload"
          onClick={handleReload}
        >
          Reload latest
        </button>
      </div>
    </div>
  );
}

AppUpdateBanner.propTypes = {
  show: PropTypes.bool,
  remoteVersion: PropTypes.string,
  onReload: PropTypes.func,
};

AppUpdateBanner.defaultProps = {
  show: false,
  remoteVersion: "",
  onReload: undefined,
};

export default AppUpdateBanner;
