/**
 * W19 — Recruiting / ATS FE service. Real API only (no mock fallback).
 */
import { axiosUtils, commonUtils } from "../../_helpers";
import urlConfig from "url.config";

export const recruitingService = {
  listRequisitions,
  createRequisition,
  submitRequisition,
  approveRequisition,
  rejectRequisition,
  listPostings,
  createPosting,
  listCandidates,
  createCandidate,
  transitionStage,
  attachResume,
  listInterviews,
  createInterview,
  submitFeedback,
  listOffers,
  createOfferFromCandidate,
  approveOffer,
  declineOffer,
  acceptOffer,
  dashboardSummary,
  isValidStageTransition,
};

const API_ERROR = { payload: null, source: "api-error" };

const STAGE_NEXT = {
  APPLIED: ["SCREENING", "REJECTED", "WITHDRAWN"],
  SCREENING: ["INTERVIEW", "REJECTED", "WITHDRAWN"],
  INTERVIEW: ["OFFER", "REJECTED", "WITHDRAWN"],
  OFFER: ["HIRED", "REJECTED", "WITHDRAWN"],
  HIRED: [],
  REJECTED: [],
  WITHDRAWN: [],
};

export function isValidStageTransition(from, to) {
  const f = String(from || "APPLIED").toUpperCase();
  const t = String(to || "").toUpperCase();
  if (f === t) return true;
  return (STAGE_NEXT[f] || []).includes(t);
}

function resolveUserTeamId() {
  return commonUtils.getCurrentUserTeamId();
}

function resolveActorId() {
  return commonUtils.getCurrentUserId();
}

function withHr(params = {}) {
  return { ...params, userTeamId: resolveUserTeamId(), hrAdminOrRecruiter: true };
}

async function listRequisitions() {
  try {
    const response = await axiosUtils.getWithParam(
      `${urlConfig.RECRUITING_API_PATH}/requisitions`,
      withHr()
    );
    const payload = response && response.payload != null ? response.payload : response;
    return Array.isArray(payload) ? { payload, source: "api" } : { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

async function createRequisition(body = {}) {
  try {
    const response = await axiosUtils.post(`${urlConfig.RECRUITING_API_PATH}/requisitions`, {
      ...body,
      userTeamId: body.userTeamId || resolveUserTeamId(),
      actorId: body.actorId || resolveActorId(),
      hrAdminOrRecruiter: true,
      status: body.status || "DRAFT",
    });
    const payload = response && response.payload != null ? response.payload : response;
    return payload ? { payload, source: "api" } : { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

async function submitRequisition(requisitionRef) {
  return transitionReq(requisitionRef, "submit");
}

async function approveRequisition(requisitionRef) {
  return transitionReq(requisitionRef, "approve");
}

async function rejectRequisition(requisitionRef) {
  return transitionReq(requisitionRef, "reject");
}

async function transitionReq(ref, action) {
  try {
    const response = await axiosUtils.post(
      `${urlConfig.RECRUITING_API_PATH}/requisitions/${encodeURIComponent(ref)}/${action}?userTeamId=${resolveUserTeamId()}&actorId=${resolveActorId()}&hrAdminOrRecruiter=true`,
      {}
    );
    const payload = response && response.payload != null ? response.payload : response;
    return payload ? { payload, source: "api" } : { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

