import React, { Component } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import { getOrgNodeIcon } from "views/hrms/components/appConfigTree.utils";

const PANEL_GAP_PX = 8;
const VIEWPORT_MARGIN_PX = 12;
const PANEL_MIN_WIDTH_PX = 280;
const PANEL_MAX_WIDTH_PX = 420;
const PANEL_MAX_HEIGHT_PX = 360;

function isOptionDisabled(row, index) {
  if (!row) return true;
  if (row.disabled === true) return true;
  if (row.isRoot === true) return true;
  if (index === 0) return true;
  return false;
}

function categoryTone(category) {
  const key = String(category || "").toLowerCase();
  if (key === "team") return "blue";
  if (key === "department") return "indigo";
  if (key === "division") return "violet";
  if (key === "section") return "slate";
  if (key === "account") return "amber";
  return "slate";
}

function matchesQuery(row, query) {
  if (!query) return true;
  const haystack = `${row.name || ""} ${row.category || ""} ${row.label || ""}`.toLowerCase();
  return haystack.includes(query);
}

function getPanelPosition(anchorEl) {
  if (!anchorEl || typeof window === "undefined") {
    return { style: null, placement: "bottom" };
  }
  const rect = anchorEl.getBoundingClientRect();
  const viewportW = window.innerWidth;
  const viewportH = window.innerHeight;
  const width = Math.min(
    Math.max(rect.width, PANEL_MIN_WIDTH_PX),
    Math.min(PANEL_MAX_WIDTH_PX, viewportW - VIEWPORT_MARGIN_PX * 2)
  );
  const left = Math.max(
    VIEWPORT_MARGIN_PX,
    Math.min(rect.left, viewportW - width - VIEWPORT_MARGIN_PX)
  );
  const spaceBelow = viewportH - rect.bottom - VIEWPORT_MARGIN_PX;
  const spaceAbove = rect.top - VIEWPORT_MARGIN_PX;
  const openUp = spaceBelow < 200 && spaceAbove > spaceBelow;
  const maxHeight = Math.max(
    160,
    Math.min(PANEL_MAX_HEIGHT_PX, openUp ? spaceAbove - PANEL_GAP_PX : spaceBelow - PANEL_GAP_PX)
  );
  const style = {
    position: "fixed",
    left,
    width,
    maxHeight,
    zIndex: 1200,
  };
  if (openUp) {
    style.bottom = viewportH - rect.top + PANEL_GAP_PX;
    style.top = "auto";
  } else {
    style.top = rect.bottom + PANEL_GAP_PX;
    style.bottom = "auto";
  }
  return { style, placement: openUp ? "top" : "bottom" };
}

/**
 * Luxury org-unit picker for persona-navigation / pagePersonaMap writes.
 * Root (first) org node is shown but disabled — pick a child so inheritance
 * still flows downward from a real operational unit.
 */
export default class OrgConfigSaveTargetSelect extends Component {
  state = {
    open: false,
    query: "",
    panelStyle: null,
    placement: "bottom",
  };

  rootRef = React.createRef();
  triggerRef = React.createRef();
  panelRef = React.createRef();

  componentDidMount() {
    document.addEventListener("mousedown", this.handleDocMouseDown);
    document.addEventListener("keydown", this.handleDocKeyDown);
  }

  componentDidUpdate(prevProps, prevState) {
    if (this.state.open && !prevState.open) {
      this.syncPanelPosition();
      window.addEventListener("resize", this.syncPanelPosition);
      window.addEventListener("scroll", this.syncPanelPosition, true);
    }
    if (!this.state.open && prevState.open) {
      window.removeEventListener("resize", this.syncPanelPosition);
      window.removeEventListener("scroll", this.syncPanelPosition, true);
    }
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this.handleDocMouseDown);
    document.removeEventListener("keydown", this.handleDocKeyDown);
    window.removeEventListener("resize", this.syncPanelPosition);
    window.removeEventListener("scroll", this.syncPanelPosition, true);
  }

  syncPanelPosition = () => {
    if (!this.state.open) return;
    const { style, placement } = getPanelPosition(this.triggerRef.current);
    this.setState({ panelStyle: style, placement });
  };

  handleDocMouseDown = (event) => {
    if (!this.state.open) return;
    const root = this.rootRef.current;
    const panel = this.panelRef.current;
    const insideRoot = root && root.contains(event.target);
    const insidePanel = panel && panel.contains(event.target);
    if (!insideRoot && !insidePanel) {
      this.setState({ open: false, query: "" });
    }
  };

  handleDocKeyDown = (event) => {
    if (event.key === "Escape" && this.state.open) {
      this.setState({ open: false, query: "" });
    }
  };

  toggleOpen = () => {
    if (this.props.disabled) return;
    this.setState((prev) => ({
      open: !prev.open,
      query: prev.open ? "" : prev.query,
    }));
  };

  selectOption = (row, index) => {
    if (isOptionDisabled(row, index) || this.props.disabled) return;
    const { onChange } = this.props;
    if (onChange) onChange(row.id);
    this.setState({ open: false, query: "" });
  };

  renderPanel = (id, list, filtered, value) => {
    const { open, query, panelStyle, placement } = this.state;
    if (!open || typeof document === "undefined") return null;
    const queryText = String(query || "").trim().toLowerCase();
    return createPortal(
      <div
        ref={this.panelRef}
        className={classNames("lux-org-save-target__panel", "is-portal", `is-${placement}`)}
        role="listbox"
        aria-labelledby={`${id}-label`}
        style={panelStyle || undefined}
      >
        <header className="lux-org-save-target__panel-head">
          <div>
            <strong>Organization units</strong>
            <span>Root is locked · pick a child so sub-levels inherit</span>
          </div>
          <em>{filtered.length}</em>
        </header>
        {list.length > 6 ? (
          <div className="lux-org-save-target__search">
            <i className="fe fe-search" aria-hidden="true" />
            <input
              type="search"
              className="lux-org-save-target__search-input"
              placeholder="Filter team or org name"
              value={query}
              autoFocus
              onChange={(event) => this.setState({ query: event.target.value })}
              aria-label="Filter organization units"
            />
          </div>
        ) : null}
        <div className="lux-org-save-target__panel-scroll">
          {filtered.length === 0 ? (
            <p className="lux-org-save-target__empty">
              {queryText ? "No units match that name." : "No org configs"}
            </p>
          ) : (
            filtered.map((row) => {
              const index = list.findIndex((item) => String(item.id) === String(row.id));
              const locked = isOptionDisabled(row, index);
              const active = String(row.id) === String(value);
              const tone = categoryTone(row.category);
              const depth = Math.min(Number(row.depth) || 0, 8);
              return (
                <button
                  key={row.id}
                  type="button"
                  role="option"
                  aria-selected={active}
                  aria-disabled={locked}
                  disabled={locked}
                  title={row.name}
                  className={classNames("lux-org-save-target__option", `is-depth-${Math.min(depth, 5)}`, {
                    "is-active": active,
                    "is-locked": locked,
                    "is-root": row.isRoot || index === 0,
                  })}
                  style={{ "--org-depth": depth }}
                  onClick={() => this.selectOption(row, index)}
                >
                  <span
                    className={classNames("lux-org-save-target__option-glyph", `is-${tone}`)}
                    aria-hidden="true"
                  >
                    <i className={`fe ${getOrgNodeIcon(row.category)}`} />
                  </span>
                  <span className="lux-org-save-target__option-copy">
                    <strong>{row.name}</strong>
                    <em>
                      {row.category || "Unit"}
                      {locked ? " · locked" : ""}
                      {row.isRoot ? " · org root" : ""}
                    </em>
                  </span>
                  {locked ? (
                    <span className="lux-org-save-target__lock" title="Root cannot be selected">
                      <i className="fe fe-lock" aria-hidden="true" />
                    </span>
                  ) : active ? (
                    <span className="lux-org-save-target__check" aria-hidden="true">
                      <i className="fe fe-check" />
                    </span>
                  ) : null}
                </button>
              );
            })
          )}
        </div>
      </div>,
      document.body
    );
  };

  render() {
    const {
      options = [],
      value,
      disabled = false,
      compact = false,
      id = "org-config-save-target",
      className,
    } = this.props;
    const { open, query } = this.state;
    const list = options || [];
    const queryText = String(query || "").trim().toLowerCase();
    const filtered = queryText ? list.filter((row) => matchesQuery(row, queryText)) : list;
    const selectedIndex = list.findIndex((row) => String(row.id) === String(value));
    const selected = selectedIndex >= 0 ? list[selectedIndex] : null;
    const selectedDisabled = selected ? isOptionDisabled(selected, selectedIndex) : false;
    const selectableCount = list.filter((row, index) => !isOptionDisabled(row, index)).length;

    const hint = selected
      ? selectedDisabled
        ? "Root is locked — choose a child unit below"
        : `${selected.category || "Unit"} · children under this node inherit`
      : "Choose an org unit to write Application Config";

    return (
      <div
        ref={this.rootRef}
        className={classNames("lux-org-save-target", className, {
          "is-compact": compact,
          "is-open": open,
          "is-disabled": disabled || !list.length,
        })}
        data-testid="org-config-save-target"
      >
        <span className="lux-org-save-target__eyebrow" id={`${id}-label`}>
          <i className="fe fe-git-branch" aria-hidden="true" />
          Save to org
        </span>

        <button
          ref={this.triggerRef}
          type="button"
          id={id}
          className={classNames("lux-org-save-target__trigger", {
            "is-open": open,
            "has-value": Boolean(selected),
          })}
          disabled={disabled || !list.length}
          aria-haspopup="listbox"
          aria-expanded={open}
          aria-labelledby={`${id}-label`}
          title={selected ? selected.name : undefined}
          onClick={this.toggleOpen}
        >
          <span
            className={classNames(
              "lux-org-save-target__glyph",
              selected && `is-${categoryTone(selected.category)}`
            )}
            aria-hidden="true"
          >
            <i className={`fe ${getOrgNodeIcon(selected && selected.category)}`} />
          </span>
          <span className="lux-org-save-target__trigger-copy">
            <strong>{selected ? selected.name : "Select org unit"}</strong>
            <em>
              {selected
                ? `${selected.category || "Unit"}${selected.isRoot ? " · root locked" : ""}`
                : list.length
                  ? `${selectableCount} units available`
                  : "No org configs"}
            </em>
          </span>
          <span className="lux-org-save-target__chevron" aria-hidden="true">
            <i className={open ? "fe fe-chevron-up" : "fe fe-chevron-down"} />
          </span>
        </button>

        {this.renderPanel(id, list, filtered, value)}

        {!compact ? <p className="lux-org-save-target__hint">{hint}</p> : null}
      </div>
    );
  }
}
