import dateUtils from "_helpers/date.utils";

export const MEMBER_ROLES = {
  CREATOR: "Creator",
  UPDATER: "Last editor",
  ASSIGNEE: "Assigned",
};

export function getProjectMembers(projectInfo) {
  if (!projectInfo) return [];

  const byId = new Map();
  const add = (employee, role) => {
    if (!employee || !employee.id) return;
    const existing = byId.get(employee.id);
    if (existing) {
      if (!existing.roles.includes(role)) existing.roles.push(role);
      return;
    }
    byId.set(employee.id, { ...employee, roles: [role] });
  };

  add(projectInfo.createdByDetails, MEMBER_ROLES.CREATOR);
  add(projectInfo.updatedByDetails, MEMBER_ROLES.UPDATER);
  (projectInfo.restrictedByEmployeeDetails || []).forEach((e) => add(e, MEMBER_ROLES.ASSIGNEE));

  return Array.from(byId.values()).sort((a, b) => (a.name || "").localeCompare(b.name || ""));
}

export function filterMembers(members, query) {
  const q = (query || "").trim().toLowerCase();
  if (!q) return members;
  return members.filter((m) => {
    const haystack = [
      m.name,
      m.email,
      m.designation,
      ...(m.roles || []),
    ]
      .filter(Boolean)
      .join(" ")
      .toLowerCase();
    return haystack.includes(q);
  });
}

export function sumTaskStat(items, key) {
  if (!items || !items.length) return 0;
  return items.reduce((total, item) => total + (item[key] || 0), 0);
}

export function getDashboardTabStats(taskStatisticsByCategory) {
  const items = taskStatisticsByCategory || [];
  const total =
    sumTaskStat(items, "completedCount") +
    sumTaskStat(items, "inProgressCount") +
    sumTaskStat(items, "assignedCount") +
    sumTaskStat(items, "newCount");

  return [
    {
      key: "total",
      label: "Work items",
      value: total,
      hint: "Across deliverable categories",
      tone: "violet",
    },
    {
      key: "completed",
      label: "Completed",
      value: sumTaskStat(items, "completedCount"),
      hint: "Done or closed",
      tone: "mint",
    },
    {
      key: "inprogress",
      label: "In progress",
      value: sumTaskStat(items, "inProgressCount"),
      hint: "Active work",
      tone: "sky",
    },
    {
      key: "assigned",
      label: "Assigned",
      value: sumTaskStat(items, "assignedCount"),
      hint: "Queued for owners",
      tone: "sun",
    },
  ];
}

function enrichMilestoneDate(rawDate, withTime) {
  const m = dateUtils.convertDateStringToMoment(rawDate);
  if (!m || !m.isValid()) {
    return {
      display: withTime
        ? dateUtils.convertDateTimeFormat(rawDate)
        : dateUtils.convertDateFormat(rawDate),
      weekday: "",
      relative: "",
    };
  }
  return {
    display: withTime
      ? dateUtils.convertDateTimeFormat(rawDate)
      : dateUtils.convertDateFormat(rawDate),
    weekday: m.format("dddd"),
    relative: m.fromNow(),
  };
}

export function getProjectScheduleWindow(projectInfo) {
  if (!projectInfo) return null;
  const start = projectInfo.estStartTime
    ? dateUtils.convertDateStringToMoment(projectInfo.estStartTime)
    : null;
  const end = projectInfo.estCompletionTime
    ? dateUtils.convertDateStringToMoment(projectInfo.estCompletionTime)
    : null;
  if ((!start || !start.isValid()) && (!end || !end.isValid())) return null;

  const safeNow = dateUtils.getCurrentDayStart();
  let durationDays = null;
  let progressPct = null;
  let remainingDays = null;
  let elapsedDays = null;
  let phase = "unscheduled";

  if (start && start.isValid() && end && end.isValid()) {
    durationDays = Math.max(1, end.diff(start, "days"));
    elapsedDays = safeNow.diff(start, "days");
    remainingDays = end.diff(safeNow, "days");
    progressPct = Math.max(0, Math.min(100, Math.round((elapsedDays / durationDays) * 100)));
    if (safeNow.isBefore(start, "day")) phase = "upcoming";
    else if (safeNow.isAfter(end, "day")) phase = "complete";
    else phase = "active";
  } else if (start && start.isValid()) {
    phase = safeNow.isBefore(start, "day") ? "upcoming" : "active";
  } else if (end && end.isValid()) {
    remainingDays = end.diff(safeNow, "days");
    phase = safeNow.isAfter(end, "day") ? "complete" : "active";
  }

  return {
    startLabel: projectInfo.estStartTime
      ? dateUtils.convertDateFormat(projectInfo.estStartTime)
      : "Not set",
    endLabel: projectInfo.estCompletionTime
      ? dateUtils.convertDateFormat(projectInfo.estCompletionTime)
      : "Not set",
    durationDays,
    progressPct,
    remainingDays,
    elapsedDays,
    phase,
  };
}

export function getProjectCalendarMilestones(projectInfo) {
  if (!projectInfo) return [];

  const milestones = [];

  if (projectInfo.estStartTime) {
    const meta = enrichMilestoneDate(projectInfo.estStartTime, false);
    milestones.push({
      id: "est-start",
      label: "Estimated start",
      hint: "Planned kickoff for delivery work",
      date: projectInfo.estStartTime,
      ...meta,
      tone: "sky",
      icon: "fe fe-flag",
    });
  }
  if (projectInfo.estCompletionTime) {
    const meta = enrichMilestoneDate(projectInfo.estCompletionTime, false);
    milestones.push({
      id: "est-due",
      label: "Estimated due",
      hint: "Target completion for the project window",
      date: projectInfo.estCompletionTime,
      ...meta,
      tone: "violet",
      icon: "fe fe-target",
    });
  }
  if (projectInfo.createdDate) {
    const meta = enrichMilestoneDate(projectInfo.createdDate, true);
    milestones.push({
      id: "created",
      label: "Project created",
      hint: "When this project record was first saved",
      date: projectInfo.createdDate,
      ...meta,
      tone: "slate",
      icon: "fe fe-plus-circle",
    });
  }
  if (projectInfo.lastModifiedDate) {
    const meta = enrichMilestoneDate(projectInfo.lastModifiedDate, true);
    milestones.push({
      id: "updated",
      label: "Last updated",
      hint: "Most recent change on the project record",
      date: projectInfo.lastModifiedDate,
      ...meta,
      tone: "mint",
      icon: "fe fe-edit-2",
    });
  }

  return milestones.sort((a, b) => {
    const ta = dateUtils.convertDateStringToMoment(a.date);
    const tb = dateUtils.convertDateStringToMoment(b.date);
    if (!ta || !tb) return 0;
    return ta.valueOf() - tb.valueOf();
  });
}

export function getProjectAccessSummary(projectInfo) {
  if (!projectInfo) return { teams: [], skills: [], hasPeople: false };

  const teams = (projectInfo.restrictedByUserTeamDetails || []).map((t) => t.name);
  const skills = projectInfo.restrictedByEmployeeSkills || [];
  const hasPeople =
    (projectInfo.restrictedByEmployeeDetails && projectInfo.restrictedByEmployeeDetails.length > 0) ||
    teams.length > 0 ||
    skills.length > 0;

  return { teams, skills, hasPeople };
}

