export function buildScheduleSummary(items) {
  const list = items || [];
  const enabled = list.filter((i) => i.enabled && !i.deleted).length;
  const disabled = list.filter((i) => !i.enabled && !i.deleted).length;
  const removed = list.filter((i) => i.deleted).length;

  return {
    total: list.length,
    enabled,
    disabled,
    removed,
    stats: [
      { key: "total", label: "Schedulers", value: list.length, hint: "Background jobs" },
      { key: "enabled", label: "Active", value: enabled, tone: "green", hint: "Running on cron" },
      { key: "disabled", label: "Paused", value: disabled, tone: "amber", hint: "Manually stopped" },
      { key: "removed", label: "Removed", value: removed, tone: removed > 0 ? "rose" : "slate", hint: "Marked deleted" },
    ],
  };
}

export function getScheduleStatusMeta(item) {
  if (item.deleted) {
    return { label: "Removed", tone: "rose", icon: "fe fe-trash-2" };
  }
  if (item.enabled) {
    return { label: "Active", tone: "green", icon: "fe fe-play-circle" };
  }
  return { label: "Paused", tone: "amber", icon: "fe fe-pause-circle" };
}

export const SETTINGS_HEALTH_PATH = "/people/settings?tab=health";
export const HEADER_HEALTH_ISSUE_LIMIT = 8;

export function isServiceReportingUp(health) {
  return String((health && health.status) || "").toUpperCase() === "UP";
}

export function isServiceNeedingAttention(health) {
  if (!health || health.disabled) {
    return false;
  }
  return !isServiceReportingUp(health);
}

function serviceDisplayName(health) {
  return (health && (health.serviceName || health.hostName)) || "Unknown service";
}

function toHealthIssue(health, kind) {
  const name = serviceDisplayName(health);
  return {
    id: `${kind}-${(health && health.id) || name}`,
    kind,
    name,
    hostName: (health && health.hostName) || null,
    status: (health && health.status) || "FAILED",
    error: (health && health.error) || null,
    lastSeenInMins: health && health.lastSeenInMins,
  };
}

export function getServiceIssueHint(issue) {
  if (!issue) {
    return "Needs attention";
  }
  if (issue.error) {
    return issue.error;
  }
  if (issue.kind === "server" && issue.lastSeenInMins != null) {
    return `Last seen ${issue.lastSeenInMins} min ago · ${issue.status}`;
  }
  const status = String(issue.status || "FAILED").toUpperCase();
  if (status === "FAILED") {
    return "Health check failed";
  }
  if (status === "INITIALIZED") {
    return "Still starting";
  }
  return `Status: ${issue.status}`;
}

export function listUnhealthyServices(serviceHealth) {
  const servers = (serviceHealth && serviceHealth.healthStatusResponses) || [];
  const integrations = (serviceHealth && serviceHealth.serviceStatusResponses) || [];
  return {
    servers: servers.filter(isServiceNeedingAttention).map((h) => toHealthIssue(h, "server")),
    integrations: integrations.filter(isServiceNeedingAttention).map((h) => toHealthIssue(h, "integration")),
  };
}

export function buildHeaderHealthPulse(serviceHealth) {
  const servers = (serviceHealth && serviceHealth.healthStatusResponses) || [];
  const integrations = (serviceHealth && serviceHealth.serviceStatusResponses) || [];
  const listed = listUnhealthyServices(serviceHealth);
  const issues = [...listed.integrations, ...listed.servers];

  return {
    ready: true,
    total: servers.length + integrations.length,
    downCount: issues.length,
    integrationDownCount: listed.integrations.length,
    serverDownCount: listed.servers.length,
    issues,
  };
}

export function resolveSettingsTabFromSearch(search, tabs) {
  const list = tabs || [];
  const requested = new URLSearchParams(search || "").get("tab");
  if (requested && list.some((tab) => tab.id === requested)) {
    return requested;
  }
  return list[0] ? list[0].id : null;
}

export function buildServiceHealthSummary(serviceHealth) {
  const servers = (serviceHealth && serviceHealth.healthStatusResponses) || [];
  const integrations = (serviceHealth && serviceHealth.serviceStatusResponses) || [];
  const all = [...servers, ...integrations];
  const up = all.filter(isServiceReportingUp).length;
  const down = all.filter(isServiceNeedingAttention).length;

  return {
    total: all.length,
    up,
    down,
    serverCount: servers.length,
    integrationCount: integrations.length,
    stats: [
      { key: "total", label: "Services", value: all.length, hint: "Monitored endpoints" },
      { key: "up", label: "Healthy", value: up, tone: "green", hint: "Reporting UP" },
      { key: "down", label: "Issues", value: down, tone: down > 0 ? "rose" : "slate", hint: "Needs attention" },
    ],
  };
}

export function canRemoveHealthServer(health) {
  const id = health && health.id;
  return id != null && id !== "" && Number(id) > 0;
}

export function getHealthStatusMeta(status) {
  if (String(status || "").toUpperCase() === "UP") {
    return { label: "Operational", tone: "green", icon: "fe fe-check-circle" };
  }
  return { label: "Unavailable", tone: "rose", icon: "fe fe-alert-circle" };
}
