import React from "react";
import classNames from "classnames/bind";
import { Link, withRouter } from "react-router-dom";
import { useReportPageDataSource } from "views/common/PageChromeContext";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import LuxKpiStrip from "views/common/fragments/LuxKpiStrip";
import LuxActionButton from "views/common/lux/LuxActionButton";
import { AdminInsightStrip, AdminQuickNav } from "views/admin/components/AdminLuxShared";
import { LuxModulePanel } from "views/common/lux/createModuleLuxPage";
import {
  RECRUITING_MODULE_NAV,
  RECRUITING_QUICK_LINKS,
  getRecruitingNavActiveId,
} from "config/recruiting-platform-nav.config";
import "../recruiting.css";

export { RECRUITING_QUICK_LINKS };

export default function RecruitingLuxPage({
  pageMeta,
  dataSource,
  heroActions,
  kpiCards,
  loading,
  onRefresh,
  refreshLoading,
  testId,
  children,
  className,
  showSectionNav = true,
}) {
  useReportPageDataSource(dataSource);
  const meta = {
    tone: "indigo",
    icon: "fe fe-user-check",
    eyebrow: "People · ATS",
    titleLead: "Recruiting",
    titleAccent: "workspace",
    lede: "Requisitions, candidates, interviews, and offers on live ATS data.",
    ...(pageMeta || {}),
  };

  return (
    <div
      className={classNames(
        "lux-register-page",
        "lux-recruiting-lux",
        meta.tone && `is-${meta.tone}`,
        className
      )}
      {...(testId ? { "data-testid": testId } : {})}
    >
      <div className="lux-recruiting-lux__ambient" aria-hidden="true">
        <span className="lux-recruiting-lux__orb lux-recruiting-lux__orb--a" />
        <span className="lux-recruiting-lux__orb lux-recruiting-lux__orb--b" />
      </div>
      <LuxModuleIntro
        meta={meta}
        actions={heroActions || undefined}
        onRefresh={onRefresh}
        refreshLoading={refreshLoading != null ? refreshLoading : loading}
      />
      <div className="lux-register-page__body">
        {kpiCards && kpiCards.length ? (
          <LuxKpiStrip cards={kpiCards} loading={loading} className="lux-recruiting-lux__kpi-strip" />
        ) : null}
        <div className="lux-recruiting-lux__content">
          {showSectionNav ? <RecruitingSectionNav /> : null}
          {children}
        </div>
      </div>
    </div>
  );
}

export const RecruitingSectionNav = withRouter(function RecruitingSectionNav({ location }) {
  const activeId = getRecruitingNavActiveId(location.pathname);

  return (
    <nav className="lux-planner-nav lux-recruiting-section-nav" aria-label="Recruiting sections">
      {RECRUITING_MODULE_NAV.map((item) => (
        <Link
          key={item.id}
          to={item.path}
          className={classNames("lux-planner-nav__item", {
            "is-active": activeId === item.id,
          })}
        >
          <i className={item.icon} aria-hidden="true" />
          <span>{item.label}</span>
        </Link>
      ))}
    </nav>
  );
});

export function RecruitingActionButton(props) {
  return <LuxActionButton {...props} moduleClass="lux-recruiting-action" />;
}

export function RecruitingLuxPanel(props) {
  return <LuxModulePanel {...props} className="lux-recruiting-lux__panel" />;
}

export function RecruitingInsightPanel({ insights = [] }) {
  return <AdminInsightStrip insights={insights} className="lux-recruiting-lux__insights" />;
}

export function RecruitingQuickNav({
  links = RECRUITING_QUICK_LINKS,
  eyebrow = "Recruiting workspace",
  title = "Navigate requisitions, pipeline, and offers",
}) {
  return (
    <AdminQuickNav
      eyebrow={eyebrow}
      title={title}
      links={links}
      className="lux-recruiting-lux__quick-nav"
      ariaLabel="Recruiting navigation"
    />
  );
}

export function RecruitingStatusBadge({ status, label }) {
  const text = label != null ? label : status == null || status === "" ? "—" : String(status);
  return (
    <span className={classNames("lux-expansion-status", `is-${String(status || "draft").toLowerCase()}`)}>
      {text}
    </span>
  );
}
