/**
 * F05 — Attendance regularization feature flags.
 * Enablement and live API use follow Application Config (org attendanceAdditional).
 */
import { shouldUseAttendanceRegularization } from "config/tracopus-pilot.config";

export function isAttendanceRegularizationEnabled() {
  return shouldUseAttendanceRegularization();
}

/** Live regularization/intelligence APIs when org feature is enabled. */
export function shouldUseAttendanceRegularizationApi() {
  return isAttendanceRegularizationEnabled();
}
