import React from 'react';
import { Link } from 'react-router-dom';
import { accessUtils } from '_helpers';

/**
 * Switch between classic Leave admin (types + fallback entitlements)
 * and Global Policy Center within the single Leave admin product.
 */
export default function LeavePolicyModeSwitcher({ active }) {
  const menu = accessUtils.getMenuAccessControl() || {};
  const admin = menu.adminModules || {};
  const showClassic = admin.leavePoliciesEnabled === true;
  const showGlobal = admin.globalLeavePoliciesEnabled === true;

  if (!showClassic && !showGlobal) {
    return null;
  }

  return (
    <div className="glp-mode-switch" role="navigation" aria-label="Leave admin sections">
      <span className="glp-mode-switch__label">Leave admin</span>
      <div className="glp-mode-switch__pills">
        {showClassic && (
          <Link
            to="/admin/leave-policies"
            className={active === 'classic' ? 'glp-mode-switch__pill is-active' : 'glp-mode-switch__pill'}
          >
            <i className="fe fe-layers" aria-hidden="true" /> Types &amp; fallback
          </Link>
        )}
        {showGlobal && (
          <Link
            to="/admin/leave/global-policy-center"
            className={active === 'global' ? 'glp-mode-switch__pill is-active' : 'glp-mode-switch__pill'}
          >
            <i className="fe fe-globe" aria-hidden="true" /> Global policies
          </Link>
        )}
      </div>
      <p className="glp-mode-switch__hint">
        {showClassic && showGlobal
          ? active === 'global'
            ? 'Both modes are enabled. Published global policy wins accrual; Types & fallback remains the leave-type catalog for requests.'
            : 'Both modes are enabled. Classic entitlements apply only when no global policy is published; use Global policies for layered rules.'
          : active === 'global'
            ? showClassic
              ? 'Global Policy Center is the primary Leave admin. Use Types & fallback for the leave type catalog (classic entitlements apply only when no global policy is published).'
              : 'Global Leave Policy Center is enabled — classic Leave policies are not a separate admin entry. Manage rules here under Global policies.'
            : 'Leave type catalog for requests. Classic entitlements apply only when no global policy is published.'}
      </p>
    </div>
  );
}
