import { commonUtils } from "_helpers";
import workItemUtils from "_helpers/workitem.utils";

/** Normalize service line sources (array, object keys, PO payload) to react-select options. */
export function normalizeServiceLinesToOptions(lines) {
  if (!lines) return [];
  if (Array.isArray(lines)) {
    if (!lines.length) return [];
    if (typeof lines[0] === "string") {
      return commonUtils.convertConfigListToSelectObject(lines);
    }
    if (typeof lines[0] === "object" && (lines[0].name || lines[0].label)) {
      return commonUtils.convertObjectToSelectObject(lines);
    }
    return commonUtils.convertConfigListToSelectObject(lines.map(String));
  }
  if (typeof lines === "object") {
    return commonUtils.convertConfigListToSelectObject(Object.keys(lines));
  }
  return [];
}

export function resolveProjectServiceLineOptions(ctx) {
  const {
    projectRequest,
    purchaseOrderServiceLines,
    purchaseOrderServiceLineEstimate,
    createConfig,
  } = ctx;

  if (projectRequest && projectRequest.purchaseOrderId) {
    let lines = purchaseOrderServiceLines;
    if (!lines || (Array.isArray(lines) && !lines.length)) {
      lines =
        purchaseOrderServiceLineEstimate &&
        Object.keys(purchaseOrderServiceLineEstimate);
    }
    if (
      (!lines || (Array.isArray(lines) && !lines.length)) &&
      projectRequest.serviceLineEstimate
    ) {
      lines = Object.keys(projectRequest.serviceLineEstimate);
    }
    if (
      (!lines || (Array.isArray(lines) && !lines.length)) &&
      projectRequest.serviceLines
    ) {
      lines = projectRequest.serviceLines;
    }
    const fromPo = normalizeServiceLinesToOptions(lines);
    if (fromPo && fromPo.length) return fromPo;
  }

  const fromConfig = createConfig && workItemUtils.getServiceLines(createConfig);
  if (fromConfig && fromConfig.length) return fromConfig;

  const categoryMap = createConfig && commonUtils.getAppConfigValue(createConfig, "categoryMap");
  if (categoryMap) {
    return commonUtils.convertConfigListToSelectObject(commonUtils.mapKeysToList(categoryMap));
  }

  return [];
}

export function resolveServiceLineLabel(value, options) {
  if (!value) return "";
  const match = options && options.find((opt) => opt.value === value);
  return match && match.label ? match.label : value;
}

function hasEstimateValue(raw) {
  if (raw === null || raw === undefined || raw === "") return false;
  const num = parseFloat(raw);
  return !Number.isNaN(num) && num > 0;
}

export function formatEstimateHoursDisplay(raw) {
  if (!hasEstimateValue(raw)) {
    return { text: "--", isPlaceholder: true };
  }
  return { text: String(parseFloat(raw)), isPlaceholder: false };
}

export function formatEstimateRateDisplay(raw) {
  if (!hasEstimateValue(raw)) {
    return { text: "$--", isPlaceholder: true };
  }
  return { text: `$${parseFloat(raw)}`, isPlaceholder: false };
}

export function formatEstimateCostDisplay(estHours, estHourlyRate) {
  if (!hasEstimateValue(estHours) || !hasEstimateValue(estHourlyRate)) {
    return { text: "$--", isPlaceholder: true };
  }
  const cost = (parseFloat(estHours) * parseFloat(estHourlyRate)).toFixed(2);
  return { text: `$${cost}`, isPlaceholder: false };
}

export function getServiceLineEstimatePermissionFlags(permission = {}) {
  const hoursView = permission.enableServiceLineEstimateHourVisible !== false;
  const costView = permission.enableServiceLineEstimateCostVisible !== false;
  const hoursEdit = permission.enableServiceLineEstimateHourEditable !== false;
  const costEdit = permission.enableServiceLineEstimateCostEditable !== false;
  return { hoursView, costView, hoursEdit, costEdit };
}

export function getServiceLineEstimatePermissionNotes(flags) {
  const notes = [];
  if (!flags.hoursView) {
    notes.push("Est. hours: view disabled");
  } else if (!flags.hoursEdit) {
    notes.push("Est. hours: edit disabled");
  }
  if (!flags.costView) {
    notes.push("Rate & cost: view disabled");
  } else if (!flags.costEdit) {
    notes.push("Rate & cost: edit disabled");
  }
  return notes;
}

export function resolveSelectedServiceLineValues(mappingObject, mode) {
  if (!mappingObject) return [];
  let raw = mappingObject.serviceLines;
  if ((!raw || (Array.isArray(raw) && !raw.length)) && mode !== "category" && mappingObject.category) {
    raw = mappingObject.category;
  }
  if (mode === "category") {
    raw = mappingObject.category;
  }
  if (!raw) return [];
  return Array.isArray(raw) ? raw : [raw];
}
