import React, { Component } from "react";
import classNames from "classnames/bind";
import { GOVERNANCE_PAGE_IDS } from "config/project-governance-nav.config";
import { canDecideGate, getGateStatusTone } from "config/project-governance.utils";
import GovernanceLuxDrawerShell from "views/project/components/GovernanceLuxDrawerShell";
import {
  GovernanceDrawerBanner,
  GovernanceDrawerCard,
  GovernanceDrawerField,
  GovernanceDrawerMeta,
  GovernanceDrawerModuleLink,
  GovernanceDrawerStatStrip,
  buildGovernanceQuickLinks,
} from "views/project/components/GovernanceLuxDrawerShared";

export default class GateDrawer extends Component {
  state = {
    approverName: "",
    dueDate: "",
    criteria: "",
    decisionNotes: "",
    saving: false,
    deciding: false,
    error: null,
  };

  componentDidUpdate(prevProps) {
    const { gate, open } = this.props;
    if (open && gate && gate !== prevProps.gate) {
      this.setState({
        approverName: gate.approverName || "",
        dueDate: gate.dueDate || "",
        criteria: gate.criteria || "",
        decisionNotes: gate.decisionNotes || "",
        saving: false,
        deciding: false,
        error: null,
      });
    }
  }

  handleSave = async () => {
    const { gate, onSave, onClose } = this.props;
    const { approverName, dueDate, criteria, decisionNotes } = this.state;
    if (!gate || !onSave) {
      return;
    }
    this.setState({ saving: true, error: null });
    try {
      await onSave(gate.id, {
        approverName,
        dueDate: dueDate || null,
        criteria,
        decisionNotes,
      });
      onClose();
    } catch (e) {
      this.setState({
        saving: false,
        error: (e && e.message) || "Unable to update gate.",
      });
    }
  };

  handleDecision = async (action) => {
    const { gate, onApprove, onReject, onWaive, onClose } = this.props;
    const { decisionNotes } = this.state;
    if (!gate || !canDecideGate(gate)) {
      return;
    }
    const handler = action === "approve" ? onApprove : action === "reject" ? onReject : onWaive;
    if (!handler) {
      return;
    }
    this.setState({ deciding: true, error: null });
    try {
      await handler(gate.id, { decisionNotes });
      onClose();
    } catch (e) {
      this.setState({
        deciding: false,
        error: (e && e.message) || "Unable to record gate decision.",
      });
    }
  };

  render() {
    const { open, gate, onClose } = this.props;
    const { approverName, dueDate, criteria, decisionNotes, saving, deciding, error } = this.state;
    if (!open || !gate) {
      return null;
    }

    const tone = getGateStatusTone(gate.status);
    const canDecide = canDecideGate(gate);

    return (
      <GovernanceLuxDrawerShell
        open={open}
        onClose={onClose}
        wide
        accent="primary"
        icon="fe-shield"
        eyebrow={`Stage gate · ${gate.stage}`}
        title={gate.name}
        subtitle={gate.projectName}
        quickLinks={buildGovernanceQuickLinks(GOVERNANCE_PAGE_IDS.GOVERNANCE, [
          { to: "/project/milestones", label: "Milestones", hint: "Readiness", icon: "fe fe-flag" },
        ])}
        ariaLabel={`Gate ${gate.name}`}
        footer={
          <div className="lux-gov-drawer__foot-bar">
            <GovernanceDrawerModuleLink
              to="/project/governance"
              label="Open governance hub"
              onNavigate={onClose}
            />
            {canDecide ? (
              <div className="lux-gov-gate-decisions">
                <button
                  type="button"
                  className="lux-onb-action lux-onb-action--primary"
                  onClick={() => this.handleDecision("approve")}
                  disabled={deciding || saving}
                >
                  {deciding ? "Saving…" : "Approve"}
                </button>
                <button
                  type="button"
                  className="lux-onb-action lux-onb-action--ghost is-danger"
                  onClick={() => this.handleDecision("reject")}
                  disabled={deciding || saving}
                >
                  Reject
                </button>
                <button
                  type="button"
                  className="lux-onb-action lux-onb-action--ghost"
                  onClick={() => this.handleDecision("waive")}
                  disabled={deciding || saving}
                >
                  Waive
                </button>
              </div>
            ) : null}
            <div className="lux-onb-drawer__foot-actions">
              <button type="button" className="lux-onb-action lux-onb-action--ghost" onClick={onClose}>
                Cancel
              </button>
              <button
                type="button"
                className="lux-onb-action lux-onb-action--primary"
                onClick={this.handleSave}
                disabled={saving || deciding}
              >
                {saving ? "Saving…" : "Save gate"}
              </button>
            </div>
          </div>
        }
      >
        <GovernanceDrawerStatStrip
          stats={[
            { label: "Status", value: gate.status, tone },
            { label: "Stage", value: gate.stage || "—" },
            { label: "Approver", value: gate.approverName || "Unassigned" },
          ]}
        />

        <GovernanceDrawerCard title="Decision snapshot" subtitle="Current gate posture and timeline">
          <GovernanceDrawerMeta
            items={[
              {
                label: "Status",
                value: <span className={classNames("lux-doc-badge", `is-${tone}`)}>{gate.status}</span>,
              },
              { label: "Approver", value: gate.approverName || "—" },
              { label: "Due", value: gate.dueDate || "—" },
              { label: "Approved", value: gate.approvedAt || "Pending" },
            ]}
          />
          {canDecide ? (
            <GovernanceDrawerBanner icon="fe-zap" tone="warning">
              This gate is awaiting a steering decision — approve, reject, or waive using the actions below.
            </GovernanceDrawerBanner>
          ) : null}
        </GovernanceDrawerCard>

        <GovernanceDrawerCard title="Gate criteria & notes" subtitle="Entry requirements and steering commentary">
          <GovernanceDrawerField label="Criteria">
            <textarea rows={3} value={criteria} onChange={(e) => this.setState({ criteria: e.target.value })} />
          </GovernanceDrawerField>
          <GovernanceDrawerField label="Approver">
            <input value={approverName} onChange={(e) => this.setState({ approverName: e.target.value })} />
          </GovernanceDrawerField>
          <GovernanceDrawerField label="Due date">
            <input type="date" value={dueDate || ""} onChange={(e) => this.setState({ dueDate: e.target.value })} />
          </GovernanceDrawerField>
          <GovernanceDrawerField label="Decision notes">
            <textarea
              rows={2}
              value={decisionNotes}
              onChange={(e) => this.setState({ decisionNotes: e.target.value })}
              placeholder="Steering notes for approve, reject, or waive"
            />
          </GovernanceDrawerField>
          {error ? <p className="lux-gov-drawer__error">{error}</p> : null}
        </GovernanceDrawerCard>
      </GovernanceLuxDrawerShell>
    );
  }
}
