import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isKnowledgeRcaEnabled } from "config/knowledge-rca.config";
import { KNOWLEDGE_PAGE_META } from "config/knowledge-rca-nav.config";
import { knowledgeRcaService } from "_services/knowledgeRca.service";
import KnowledgeLuxPage, {
  KnowledgeActionButton,
  KnowledgeInsightPanel,
  KnowledgeLuxPanel,
} from "views/knowledge/components/KnowledgeLuxShared";
import KnowledgeArticleRegister from "views/knowledge/components/KnowledgeArticleRegister";
import PatternInsightsPanel from "views/knowledge/components/PatternInsightsPanel";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class KnowledgeBasePage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    articles: [],
    kpiCards: [],
    insights: [],
    analytics: null,
    query: "",
    searched: false,
    searching: false,
  };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await knowledgeRcaService.getKnowledgeOverview("");
      const payload = result.payload || {};
      this.setState({
        loading: false,
        dataSource: result.source,
        articles: payload.articles || [],
        kpiCards: payload.kpiCards || [],
        insights: payload.insights || [],
        analytics: payload.analytics || null,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load knowledge base.",
      });
    }
  };

  handleSearch = async (event) => {
    if (event) {
      event.preventDefault();
    }
    const { query } = this.state;
    this.setState({ searching: true, searched: true });
    try {
      const result = await knowledgeRcaService.searchKnowledge(query);
      this.setState({
        searching: false,
        articles: result.payload || [],
        dataSource: result.source,
      });
    } catch (error) {
      this.setState({ searching: false, articles: [] });
    }
  };

  render() {
    if (!isKnowledgeRcaEnabled()) {
      return <PersonaAccessDenied featureLabel="Knowledge base" />;
    }

    const { loading, loadError, dataSource, articles, kpiCards, insights, analytics, query, searching } = this.state;

    return (
      <KnowledgeLuxPage
        pageMeta={KNOWLEDGE_PAGE_META}
        shellTitle="Knowledge base"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        heroActions={
          <KnowledgeActionButton to="/project/rca" icon="fe fe-target">
            RCA workspace
          </KnowledgeActionButton>
        }
      >
        {loadError ? <LuxInlineAlert message={loadError} onDismiss={() => this.setState({ loadError: null })} /> : null}
        <KnowledgeInsightPanel insights={insights} loading={loading} />

        <div className="lux-krca-search-shell">
        <form className="lux-krca-search-form" onSubmit={this.handleSearch}>
          <input
            type="search"
            className="form-control lux-krca-search-input"
            placeholder="Search articles, tags, runbooks…"
            value={query}
            onChange={(e) => this.setState({ query: e.target.value })}
          />
          <button type="submit" className="lux-onb-action lux-onb-action--primary lux-krca-action" disabled={searching}>
            <i className="fe fe-search" aria-hidden="true" />
            Search
          </button>
        </form>
        </div>

        <PatternInsightsPanel analytics={analytics} loading={loading} />

        <KnowledgeLuxPanel
          title="Knowledge articles"
          meta="RCA and lesson-linked institutional memory"
          icon="fe fe-database"
          accent="violet"
          featured
        >
          <KnowledgeArticleRegister articles={articles} loading={loading || searching} />
        </KnowledgeLuxPanel>
      </KnowledgeLuxPage>
    );
  }
}

export default KnowledgeBasePage;
