const PREFERENCES_KEY_PREFIX = "famstack-profile-prefs-";
const NOTIFICATIONS_KEY_PREFIX = "famstack-profile-notifs-";

export const DEFAULT_PREFERENCES = {
  landingPage: "dashboard",
  compactLayout: false,
  showWeekNumbers: true,
  weekStartsMonday: true,
  timesheetView: "week",
  dateFormat: "client",
};

export const DEFAULT_NOTIFICATIONS = {
  channelEmail: true,
  channelInApp: true,
  channelPush: false,
  notifyTimesheet: true,
  notifyLeave: true,
  notifyProject: true,
  notifyHr: false,
  notifySecurity: true,
  quietHoursEnabled: false,
  quietHoursStart: "22:00",
  quietHoursEnd: "07:00",
};

function readJson(key, fallback) {
  try {
    const raw = localStorage.getItem(key);
    if (!raw) return { ...fallback };
    return { ...fallback, ...JSON.parse(raw) };
  } catch (e) {
    return { ...fallback };
  }
}

function writeJson(key, value) {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch (e) {
    /* ignore */
  }
}

export function readProfilePreferences(employeeId) {
  if (!employeeId) return { ...DEFAULT_PREFERENCES };
  return readJson(`${PREFERENCES_KEY_PREFIX}${employeeId}`, DEFAULT_PREFERENCES);
}

export function writeProfilePreferences(employeeId, prefs) {
  if (!employeeId) return;
  writeJson(`${PREFERENCES_KEY_PREFIX}${employeeId}`, prefs);
}

export function readProfileNotifications(employeeId) {
  if (!employeeId) return { ...DEFAULT_NOTIFICATIONS };
  return readJson(`${NOTIFICATIONS_KEY_PREFIX}${employeeId}`, DEFAULT_NOTIFICATIONS);
}

export function writeProfileNotifications(employeeId, notifs) {
  if (!employeeId) return;
  writeJson(`${NOTIFICATIONS_KEY_PREFIX}${employeeId}`, notifs);
}
