import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import {
  normalizeDocument,
  normalizePolicyAcknowledgment,
  shouldUseDocumentVaultApi,
} from "config/document-vault.config";
import { toEmployee360DocumentRow } from "config/document-vault.utils";
import { recordAuditEvent } from "config/audit-write.service";
import { AUDIT_ACTION_TYPES, AUDIT_ENTITY_TYPES } from "_constants/audit.constants";
import { apiErrorResult } from "config/mock-fallback.utils";

export const documentVaultService = {
  listDocuments,
  listPolicies,
  getEmployeeDocuments,
  uploadDocument,
  verifyDocument,
  rejectDocument,
  setLegalHold,
  acknowledgePolicy,
  getDownloadUrl,
};

function documentTeamQuery(extra) {
  const query = { userTeamId: commonUtils.getCurrentUserTeamId() };
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

function documentTeamQueryString(extra) {
  const query = documentTeamQuery(extra);
  return Object.keys(query)
    .map((key) => `${encodeURIComponent(key)}=${encodeURIComponent(query[key])}`)
    .join("&");
}

function recordDocumentAudit(actionType, headline, entityRef, metadata) {
  recordAuditEvent({
    actionType,
    entityType: AUDIT_ENTITY_TYPES.DOCUMENT,
    entityRef: entityRef || headline,
    headline,
    metadata,
  });
}

async function listDocumentsFromApi(filters = {}) {
  const response = await axiosUtils.getWithParam(
    urlConfig.DOCUMENT_VAULT_API_PATH,
    documentTeamQuery({
      employeeId: filters.employeeId || undefined,
      legalHold: filters.legalHold != null ? filters.legalHold : undefined,
      ocrStatus: filters.ocrStatus || undefined,
      sourceEntityType: filters.sourceEntityType || undefined,
      projectId: filters.projectId || filters.sourceEntityId || undefined,
    })
  );
  const rows = (response && response.payload) || response || [];
  const list = Array.isArray(rows) ? rows : [];
  return {
    payload: list.map((row) => normalizeDocument(row)).filter(Boolean),
    source: "api",
  };
}

async function listDocuments(filters = {}) {

  if (shouldUseDocumentVaultApi()) {
    try {
      return await listDocumentsFromApi(filters);
    } catch (e) {
      return apiErrorResult([]);
    }
  }

  return apiErrorResult([]);
}

async function listPoliciesFromApi() {
  const response = await axiosUtils.getWithParam(
    `${urlConfig.DOCUMENT_VAULT_API_PATH}/policies`,
    documentTeamQuery()
  );
  const rows = (response && response.payload) || response || [];
  const list = Array.isArray(rows) ? rows : [];
  return {
    payload: list.map((row) => normalizePolicyAcknowledgment(row)).filter(Boolean),
    source: "api",
  };
}

async function listPolicies() {

  if (shouldUseDocumentVaultApi()) {
    try {
      return await listPoliciesFromApi();
    } catch (e) {
      return apiErrorResult([]);
    }
  }

  return apiErrorResult([]);
}

async function getEmployeeDocuments(employeeId) {

  if (shouldUseDocumentVaultApi()) {
    try {
      return await (async () => {
        const result = await listDocumentsFromApi({ employeeId });
        return {
          payload: (result.payload || []).map((row) => toEmployee360DocumentRow(row)),
          source: result.source,
        };
      })();
    } catch (e) {
      return apiErrorResult([]);
    }
  }

  try {
      return await (async () => {
      const response = await axiosUtils.get(`${urlConfig.EMPLOYEE_GET_INFO}/${employeeId}/documents`);
      const rows = (response && response.payload) || response || [];
      const list = Array.isArray(rows) ? rows : [];
      return {
        payload: list.map((row) => normalizeDocument(row)).filter(Boolean),
        source: "api",
      };
    })();
    } catch (e) {
      return apiErrorResult([]);
    }
}

async function uploadDocument(payload) {
  if (shouldUseDocumentVaultApi()) {
    try {
      return await (async () => {
        const response = await axiosUtils.post(
          `${urlConfig.DOCUMENT_VAULT_API_PATH}?${documentTeamQueryString({
            actorId: commonUtils.getCurrentUserId(),
          })}`,
          payload
        );
        const row = normalizeDocument((response && response.payload) || response);
        recordDocumentAudit(AUDIT_ACTION_TYPES.CREATED, "Document uploaded", row && row.id, {
          title: row && row.title,
          employeeId: row && row.employeeId,
        });
        return { payload: row, source: "api" };
      })();
    } catch (e) {
      return apiErrorResult(null);
    }
  }

  return apiErrorResult(null);
}

