/** EH18 — PATCH legal hold (notes metadata on backend). */
async function setLegalHold(documentId, legalHold) {
  if (shouldUseDocumentVaultApi()) {
    try {
      const response = await axiosUtils.patch(
        `${urlConfig.DOCUMENT_VAULT_API_PATH}/${documentId}/legal-hold?${documentTeamQueryString({
          actorId: commonUtils.getCurrentUserId(),
        })}`,
        { legalHold: legalHold === true }
      );
      const row = normalizeDocument((response && response.payload) || response);
      recordDocumentAudit(AUDIT_ACTION_TYPES.UPDATED, "Document legal hold updated", documentId, {
        legalHold: legalHold === true,
      });
      return { payload: row, source: "api" };
    } catch (e) {
      console.warn("[DocumentVault] Legal hold API unavailable.", e);
      return { payload: null, source: "api-error", error: e };
    }
  }
  return apiErrorResult(null);
}

