async function getDownloadUrl(documentId, version) {
  if (shouldUseDocumentVaultApi()) {
    try {
      return await (async () => {
        const response = await axiosUtils.getWithParam(
          `${urlConfig.DOCUMENT_VAULT_API_PATH}/${documentId}/download-url`,
          documentTeamQuery({ version: version != null ? version : undefined })
        );
        return { payload: (response && response.payload) || response, source: "api" };
      })();
    } catch (e) {
      return apiErrorResult(null);
    }
  }
  return apiErrorResult(null);
}
