import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import LuxSegmentNav from "views/common/fragments/LuxSegmentNav";

export function PeopleActionButton({
  to,
  href,
  onClick,
  children,
  icon,
  variant = "primary",
  type = "button",
  disabled = false,
  className,
  testId,
}) {
  const content = (
    <>
      {icon ? <i className={icon} aria-hidden="true" /> : null}
      <span>{children}</span>
    </>
  );

  if (to) {
    return (
      <Link to={to} className={classNames("lux-module-hero__text-link", className)} data-testid={testId}>
        {content}
      </Link>
    );
  }
  if (href) {
    return (
      <a href={href} className={classNames("lux-module-hero__text-link", className)} data-testid={testId}>
        {content}
      </a>
    );
  }
  const classes = classNames("lux-onb-action", "lux-people-action", `lux-onb-action--${variant}`, className);
  return (
    <button
      type={type}
      className={classes}
      onClick={onClick}
      disabled={disabled}
      data-testid={testId}
    >
      {content}
    </button>
  );
}

export function PeopleSegmentNav({ items = [], activeId, onChange, ariaLabel, testId }) {
  return (
    <LuxSegmentNav
      items={items}
      activeId={activeId}
      onChange={onChange}
      ariaLabel={ariaLabel || "Section navigation"}
      testId={testId || "people-segment-nav"}
    />
  );
}

export function PeopleRowAction({
  to,
  onClick,
  children,
  icon,
  variant = "primary",
  disabled = false,
  type = "button",
}) {
  const classes = classNames("lux-people-row-action", `is-${variant}`);
  const content = (
    <>
      {icon ? <i className={icon} aria-hidden="true" /> : null}
      <span>{children}</span>
    </>
  );
  if (to) {
    return (
      <Link to={to} className={classes}>
        {content}
      </Link>
    );
  }
  return (
    <button type={type} className={classes} onClick={onClick} disabled={disabled}>
      {content}
    </button>
  );
}
