import React, { Component } from "react";
import moment from "moment";
import { connect } from "react-redux";
import { employeeActions, notificationActions } from "_actions";
import { employeeConstants } from "_constants";
import { accessUtils } from "_helpers";
import {
  loadApprovalDelegationConfig,
  APPROVAL_DELEGATION_CONFIG_CHANGED,
  shouldUseApprovalDelegation,
} from "_helpers/approvalDelegation.config";
import { approvalDelegationService } from "_services/approvalDelegation.service";
import {
  buildPendingApprovalOptions,
  canMarkAttendanceFor,
  canRemoveAttendanceFor,
  isAttendanceAwaitingManagerAction,
  isAttendanceLeave,
} from "./components/attendance/attendance.utils";
import { commonUtils, store } from "_helpers";
import { validationUtils } from "_helpers";
import dateUtils from "_helpers/date.utils";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import PageInnerHeader from "views/common/PageInnerHeader";
import AttendancePageSummary from "./components/attendance/AttendancePageSummary";
import AttendanceCurrentUserPanel from "./components/attendance/AttendanceCurrentUserPanel";
import AttendanceMatrix from "./components/attendance/AttendanceMatrix";
import AttendanceCalendarView from "./components/attendance/AttendanceCalendarView";
import AttendanceMarkPopover from "./components/attendance/AttendanceMarkPopover";
import AttendanceDetailsPopover from "./components/attendance/AttendanceDetailsPopover";
import AttendancePendingApprovals from "./components/attendance/AttendancePendingApprovals";
import { AUDIT_ENTITY_TYPES, AUDIT_SCOPES } from "_constants/audit.constants";
import CollapsibleAuditPanel from "views/common/fragments/CollapsibleAuditPanel";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import {
  buildAttendanceSummary,
  buildAttendanceDashboard,
  findAttendanceItem,
  findCurrentUserEmployee,
  getEmployeeStats,
  sortEmployeesCurrentFirst,
  filterEmployeesById,
  isHolidayTaskActivity,
} from "./components/attendance/attendance.utils";
import {
  buildAttendanceStubFromAuditEvent,
  resolveAttendanceAuditDeepLink,
} from "_helpers/audit.utils";
import AttendanceEmployeeFilter from "./components/attendance/AttendanceEmployeeFilter";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { isAttendanceRegularizationEnabled } from "config/attendance-enhancement.config";
import { attendanceRegularizationService } from "_services/attendance-regularization.service";
import {
  mergeRegularizations,
  permissionAllowsApprove,
} from "config/attendance-regularization.utils";
import RegularizationSubmitDrawer from "./components/attendance/RegularizationSubmitDrawer";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";
import RegularizationPendingApprovals from "./components/attendance/RegularizationPendingApprovals";
import AttendanceExceptionPolicyPanel from "./components/attendance/AttendanceExceptionPolicyPanel";
import AttendancePayrollLockBanner from "./components/attendance/AttendancePayrollLockBanner";
import AttendanceIntelligencePanel from "./components/attendance/AttendanceIntelligencePanel";
import LeaveCoveragePanel from "./components/leave/LeaveCoveragePanel";
import { leaveEnhancementService } from "_services/leave-enhancement.service";
import { leavePhase2Service } from "_services/leavePhase2.service";
import { employeeService } from "_services";
import { workItemService } from "_services/workitem.service";
import { isLeaveEnhancementsEnabled, shouldUseLeaveImpactApi } from "config/leave-enhancement.config";

class AttendancePage extends Component {
  constructor() {
    super();
    this.state = {
      selectedDate: dateUtils.convertDateToMoment(new Date()),
      monthDays: [],
      permission: accessUtils.getEmployeeAttendanceAccessControl(),
      markPopover: null,
      detailsPopover: null,
      selectedEmployeeId: null,
      actingDelegations: [],
      regularizationEnabled: isAttendanceRegularizationEnabled(),
      activeView: "calendar",
      regularizationDrawerOpen: false,
      regularizationDate: null,
      regularizationItem: null,
      regularizations: [],
      pendingRegularizations: [],
      regularizationPolicy: null,
      attendanceIntelligence: null,
      anomalyRecommendation: null,
      loadingRegularization: false,
      savingRegularizationPolicy: false,
      policySaveError: null,
      regWorkflowLoading: false,
      leaveCoverageEnabled: isLeaveEnhancementsEnabled() && shouldUseLeaveImpactApi(),
      leaveTeamCoverage: null,
      leaveCoverageUnavailable: false,
      loadingLeaveCoverage: false,
      workdays: [1, 2, 3, 4, 5],
      holidayDates: [],
      activityHolidayItems: [],
    };
  }

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(this.props.routeProp.name);
    this.handleApprovalDelegationConfigChanged = () => {
      this.refreshAttendancePermission(() => {
        this.loadActingDelegations();
      });
    };
    window.addEventListener(
      APPROVAL_DELEGATION_CONFIG_CHANGED,
      this.handleApprovalDelegationConfigChanged
    );
    loadApprovalDelegationConfig().then(() => {
      this.refreshAttendancePermission(() => {
        this.loadActingDelegations();
      });
    });
    this.refreshMonthDates(this.state.selectedDate);
    const existing = commonUtils.getUserTeams(this.props.userTeams) || [];
    const anyChecked = existing.some((team) => team && team.isChecked);
    const userTeams = anyChecked
      ? existing
      : existing.map((team) => ({ ...team, isChecked: true }));
    store.dispatch({
      type: employeeConstants.INITIALIZE_EMPLOYEE_ATTENDANCE_USER_TEAMS,
      userTeams,
    });
    if (!(this.props.employees && this.props.employees.length)) {
      this.reloadEmployeeItems(userTeams);
    }
    this.getTeamsAttendance(userTeams);
    this.loadCalendarContext(userTeams);
    if (this.state.regularizationEnabled) {
      this.loadRegularizationContext();
    }
    if (this.state.leaveCoverageEnabled) {
      this.loadLeaveCoverage(userTeams);
    }
  }

  componentWillUnmount() {
    if (this.handleApprovalDelegationConfigChanged) {
      window.removeEventListener(
        APPROVAL_DELEGATION_CONFIG_CHANGED,
        this.handleApprovalDelegationConfigChanged
      );
    }
  }

  refreshAttendancePermission = (callback) => {
    this.setState({ permission: accessUtils.getEmployeeAttendanceAccessControl() }, () => {
      if (callback) callback();
    });
  };

  loadActingDelegations = () => {
    if (!shouldUseApprovalDelegation()) {
      this.setState({ actingDelegations: [] });
      return Promise.resolve([]);
    }
    const delegateId = commonUtils.getCurrentUserId();
    if (!delegateId) {
      this.setState({ actingDelegations: [] });
      return Promise.resolve([]);
    }
    return approvalDelegationService
      .listActing(delegateId)
      .then((response) => {
        const actingDelegations = (response && response.payload) || [];
        this.setState({ actingDelegations });
        return actingDelegations;
      })
      .catch(() => {
        this.setState({ actingDelegations: [] });
        return [];
      });
  };

  loadLeaveCoverage = (userTeamsArg) => {
    if (!this.state.leaveCoverageEnabled) {
      return;
    }
    const teams = userTeamsArg || this.props.userTeams || [];
    let scopedIds = (teams || [])
      .filter((t) => t && t.isChecked)
      .map((t) => t.id)
      .filter((id) => id != null);
    if (!scopedIds.length) {
      scopedIds = (commonUtils.getCurrentUserTeamIds() || []).slice();
      const current = commonUtils.getCurrentUserTeamId();
      if (!scopedIds.length && current != null) {
        scopedIds = [current];
      }
    }
    const month = moment(this.state.selectedDate || new Date()).startOf("month");
    const startDate = month.clone().startOf("month").format(dateUtils.SERVER_DATE_FORMAT);
    const endDate = month.clone().endOf("month").format(dateUtils.SERVER_DATE_FORMAT);
    this.setState({ loadingLeaveCoverage: true });
    leaveEnhancementService
      .getTeamCoverage({
        userTeamIds: scopedIds,
        userTeamId: scopedIds[0],
        startDate,
        endDate,
        monthDate: month.toDate(),
        employees: this.props.employees || [],
        calendarLeaves: [],
      })
      .then((coverage) => {
        const failed = coverage && coverage.source === "api-error";
        this.setState({
          leaveTeamCoverage: failed ? null : coverage,
          leaveCoverageUnavailable: !!failed,
          loadingLeaveCoverage: false,
        });
      })
      .catch(() =>
        this.setState({
          leaveTeamCoverage: null,
          leaveCoverageUnavailable: true,
          loadingLeaveCoverage: false,
        })
      );
  };

  loadRegularizationContext = () => {
    const { regularizationEnabled } = this.state;
    if (!regularizationEnabled) return;

    const employee = this.resolveFocusEmployee();
    const teamIds = commonUtils.getCurrentUserTeamIds() || [];
    const currentTeamId = commonUtils.getCurrentUserTeamId();
    const scopedTeamIds =
      teamIds.length > 0
        ? teamIds
        : currentTeamId != null
          ? [currentTeamId]
          : [];
    const userTeamId = currentTeamId;
    const managerId = commonUtils.getCurrentUserId();
    const { employees, items, monthDays, selectedDate, regularizations } = {
      employees: this.props.employees,
      items: this.props.items,
      monthDays: this.state.monthDays,
      selectedDate: this.state.selectedDate,
      regularizations: this.state.regularizations,
    };

    this.setState({ loadingRegularization: true });

    Promise.all([
      employee
        ? attendanceRegularizationService.listByEmployee(employee.id)
        : Promise.resolve({ payload: [], source: "api" }),
      permissionAllowsApprove(this.state.permission) && scopedTeamIds.length && managerId
        ? attendanceRegularizationService.listPending(scopedTeamIds, managerId)
        : Promise.resolve({ payload: [], source: "api" }),
      userTeamId ? attendanceRegularizationService.getPolicy(userTeamId) : Promise.resolve({ payload: null, source: "api" }),
      attendanceRegularizationService.getIntelligence({
        employees,
        items,
        monthDays,
        selectedDate,
        regularizations,
        userTeamId,
      }),
    ]).then(async ([employeeRegsRes, pendingRegsRes, policyRes, intelligence]) => {
      const employeeRegs = Array.isArray(employeeRegsRes)
        ? employeeRegsRes
        : (employeeRegsRes && employeeRegsRes.payload) || [];
      const pendingRegs = Array.isArray(pendingRegsRes)
        ? pendingRegsRes
        : (pendingRegsRes && pendingRegsRes.payload) || [];
      const policy =
        policyRes && policyRes.payload !== undefined ? policyRes.payload : policyRes;
      const merged = mergeRegularizations(this.state.regularizations, employeeRegs, pendingRegs);
      const intelFailed = intelligence && intelligence.source === "api-error";
      const recommendation = intelFailed
        ? null
        : await attendanceRegularizationService.getAnomalyRecommendation(intelligence);
      this.setState({
        regularizations: merged,
        pendingRegularizations: pendingRegs,
        regularizationPolicy: policy,
        attendanceIntelligence: intelFailed ? null : intelligence,
        anomalyRecommendation:
          recommendation && recommendation.source === "api-error" ? null : recommendation,
        loadingRegularization: false,
      });
    }).catch((error) => {
      this.setState({ loadingRegularization: false });
      const message =
        (error && error.message) || "Unable to load attendance regularization context.";
      store.dispatch(notificationActions.error(message));
    });
  };

  handleSaveRegularizationPolicy = async (draft) => {
    const userTeamId = commonUtils.getCurrentUserTeamId();
    if (!userTeamId) {
      throw new Error("Select a team before saving attendance policy.");
    }
    this.setState({ savingRegularizationPolicy: true, policySaveError: null });
    try {
      const result = await attendanceRegularizationService.savePolicy(userTeamId, draft);
      if (result.unavailable || !result.payload) {
        throw new Error(result.error || "Unable to save attendance policy.");
      }
      this.setState({
        regularizationPolicy: result.payload,
        savingRegularizationPolicy: false,
        policySaveError: null,
      });
      return result.payload;
    } catch (error) {
      this.setState({
        savingRegularizationPolicy: false,
        policySaveError: (error && error.message) || "Unable to save attendance policy.",
      });
      throw error;
    }
  };

  resolveFocusEmployee = () => {
    const currentUserId = commonUtils.getCurrentUserId();
    const employees = this.props.allEmployees || this.props.employees || [];
    const { selectedEmployeeId } = this.state;
    if (selectedEmployeeId != null) {
      return employees.find((emp) => String(emp.id) === String(selectedEmployeeId));
    }
    return findCurrentUserEmployee(employees, currentUserId);
  };

  openRegularizationDrawer = (markDate, attendanceItem) => {
    this.setState({
      regularizationDrawerOpen: true,
      regularizationDate: markDate || moment(),
      regularizationItem: attendanceItem || null,
    });
  };

  closeRegularizationDrawer = () => {
    this.setState({
      regularizationDrawerOpen: false,
      regularizationDate: null,
      regularizationItem: null,
    });
  };

  submitRegularization = async (payload) => {
    this.setState({ regWorkflowLoading: true });
    try {
      const created = await attendanceRegularizationService.submitRegularization(payload);
      if (!created || !created.id || String(created.id).startsWith("local-")) {
        this.setState({ regWorkflowLoading: false });
        throw new Error("Regularization was not persisted by the live API");
      }
      this.setState(
        (prev) => ({
          regularizations: [...prev.regularizations, created],
          regWorkflowLoading: false,
          regularizationDrawerOpen: false,
        }),
        () => this.loadRegularizationContext()
      );
    } catch (e) {
      this.setState({ regWorkflowLoading: false });
      throw e;
    }
  };

  approveRegularization = async (request, comment) => {
    this.setState({ regWorkflowLoading: true });
    try {
      await attendanceRegularizationService.approveRegularization(
        request.id,
        commonUtils.getCurrentUserId(),
        comment,
        request.userTeamId
      );
      this.setState({ regWorkflowLoading: false }, () => this.loadRegularizationContext());
    } catch (e) {
      this.setState({ regWorkflowLoading: false });
      const message = (e && e.message) || "Unable to approve regularization.";
      store.dispatch(notificationActions.error(message));
    }
  };

  rejectRegularization = async (request, comment) => {
    this.setState({ regWorkflowLoading: true });
    try {
      await attendanceRegularizationService.rejectRegularization(
        request.id,
        commonUtils.getCurrentUserId(),
        comment,
        request.userTeamId
      );
      this.setState({ regWorkflowLoading: false }, () => this.loadRegularizationContext());
    } catch (e) {
      this.setState({ regWorkflowLoading: false });
      const message = (e && e.message) || "Unable to reject regularization.";
      store.dispatch(notificationActions.error(message));
    }
  };

  handleViewChange = (activeView) => {
    this.setState({ activeView }, () => {
      if (this.state.regularizationEnabled) {
        this.loadRegularizationContext();
      }
    });
  };

  refreshMonthDates = (date) => {
    this.setState(
      {
        selectedDate: date,
        monthDays: dateUtils.getDaysArrayByMonth(date),
      },
      () => {
        const teams = commonUtils.getUserTeams(this.props.userTeams);
        this.getTeamsAttendance(teams);
        this.loadCalendarContext(teams);
        if (this.state.regularizationEnabled) {
          this.loadRegularizationContext();
        }
        if (this.state.leaveCoverageEnabled) {
          this.loadLeaveCoverage();
        }
      }
    );
  };

  loadCalendarContext = (userTeams) => {
    const teams = userTeams || commonUtils.getUserTeams(this.props.userTeams) || [];
    const teamId =
      (teams.find((t) => t && t.isChecked) || teams[0] || {}).id ||
      (teams.find((t) => t && t.isChecked) || teams[0] || {}).userTeamId ||
      null;
    const month = this.state.selectedDate || moment();
    const startDate = month.clone().startOf("month").format(dateUtils.SERVER_DATE_FORMAT);
    const endDate = month.clone().endOf("month").format(dateUtils.SERVER_DATE_FORMAT);
    const currentUserId = commonUtils.getCurrentUserId();

    const workdayPromise = teamId
      ? leavePhase2Service
          .resolveWorkingDayPattern(teamId, currentUserId)
          .then((payload) =>
            payload && Array.isArray(payload.workdays) && payload.workdays.length
              ? payload.workdays.map(Number)
              : [1, 2, 3, 4, 5]
          )
          .catch(() => [1, 2, 3, 4, 5])
      : Promise.resolve([1, 2, 3, 4, 5]);

    const holidayPromise = employeeService
      .getHolidays({ startDate, endDate })
      .then((list) => {
        const rows = Array.isArray(list) ? list : (list && list.payload) || [];
        return rows.filter((h) => h && (h.holidayDate || h.date || h.holiday_date));
      })
      .catch(() => []);

    const focusEmployeeId =
      this.state.selectedEmployeeId || commonUtils.getCurrentUserId();
    const activityHolidayPromise = workItemService
      .getWorkItemActivities({
        employeeIds: focusEmployeeId != null ? [focusEmployeeId] : [],
        userTeamIds: commonUtils.getCurrentUserTeamIds() || [],
        startDate,
        endDate,
      })
      .then((list) => {
        const rows = Array.isArray(list) ? list : (list && list.payload) || [];
        return rows.filter(isHolidayTaskActivity);
      })
      .catch(() => []);

    Promise.all([workdayPromise, holidayPromise, activityHolidayPromise]).then(
      ([workdays, holidayDates, activityHolidayItems]) => {
        this.setState({ workdays, holidayDates, activityHolidayItems });
      }
    );
  };

  handleFilterChange = (filterOptions) => {
    store.dispatch({
      type: employeeConstants.CHANGE_FILTER_EMPLOYEES_ATTENDANCE,
      filterOptions,
    });
  };

  handleUserTeamsSelection = (userTeams) => {
    store.dispatch({
      type: employeeConstants.INITIALIZE_EMPLOYEE_ATTENDANCE_USER_TEAMS,
      userTeams,
    });
    this.setState({ selectedEmployeeId: null });
    this.reloadEmployeeItems(userTeams);
    this.getTeamsAttendance(userTeams);
    this.loadCalendarContext(userTeams);
    if (this.state.leaveCoverageEnabled) {
      this.loadLeaveCoverage(userTeams);
    }
  };

  reloadEmployeeItems = (userTeams) => {
    const selected = (userTeams || [])
      .filter((userTeam) => userTeam && userTeam.isChecked)
      .map((userTeam) => userTeam.id);
    let selectedUserTeams = commonUtils.resolveUserTeamIds(
      selected.length ? selected : null
    );
    if (!selectedUserTeams.length) {
      selectedUserTeams = (userTeams || []).map((t) => t && t.id).filter((id) => id != null);
    }
    if (selectedUserTeams.length > 0) {
      store.dispatch(this.props.getTeamsEmployees(selectedUserTeams));
    }
  };

  handleEmployeeFilterChange = (employeeId) => {
    this.setState({ selectedEmployeeId: employeeId }, () => {
      this.loadCalendarContext(commonUtils.getUserTeams(this.props.userTeams));
    });
  };

  onFilterTextChange = (value) => {
    const isValidChar = validationUtils.validateAlphaNumbericWithSpecial(value);
    if (!isValidChar) return;

    const filterOptions = {
      ...(this.props.filterOptions || {}),
      filterText: value,
    };
    this.handleFilterChange(filterOptions);
  };

  goToNext = () => {
    this.refreshMonthDates(this.state.selectedDate.clone().add(1, "months"));
  };

  goToBack = () => {
    this.refreshMonthDates(this.state.selectedDate.clone().subtract(1, "months"));
  };

  goToCurrent = () => {
    this.refreshMonthDates(dateUtils.getCurrentTime());
  };

  getTeamsAttendance = (userTeams) => {
    const range = dateUtils.getFirstAndLastDayofMonth(this.state.selectedDate);
    const startDate = range[0];
    const endDate = range[1];
    const selected = (userTeams || [])
      .filter((userTeam) => userTeam && userTeam.isChecked)
      .map((userTeam) => userTeam.id);
    let selectedUserTeams = commonUtils.resolveUserTeamIds(
      selected.length ? selected : null
    );
    if (!selectedUserTeams.length) {
      selectedUserTeams = (userTeams || []).map((t) => t && t.id).filter((id) => id != null);
    }
    if (selectedUserTeams.length > 0) {
      store.dispatch(
        this.props.getTeamsAttendance({
          userTeamIds: selectedUserTeams,
          startDate: startDate.format(dateUtils.SERVER_DATE_FORMAT),
          endDate: endDate.format(dateUtils.SERVER_DATE_FORMAT),
        })
      );
    }
  };

  createAttendance = (request) => {
    store.dispatch(this.props.createAttendance(request));
  };

  deleteAttendance = (id) => {
    store.dispatch(this.props.deleteAttendance({ id }));
  };

  openMarkPopover = (employeeId, employeeName, markDate, existingItem = null, options = {}) => {
    const { permission } = this.state;
    if (!canMarkAttendanceFor(permission, employeeId, commonUtils.getCurrentUserId())) {
      return;
    }
    // Leave / half-day attendance is owned by leave — block mark unless force.
    if (isAttendanceLeave(existingItem) && !(options && options.force === true)) {
      return;
    }
    this.setState({
      markPopover: { employeeId, employeeName, markDate, existingItem },
      detailsPopover: null,
    });
  };

  closeMarkPopover = () => {
    this.setState({ markPopover: null });
  };

  openDetailsPopover = (employeeId, employeeName, markDate, item) => {
    this.setState({
      detailsPopover: { employeeId, employeeName, markDate, item },
      markPopover: null,
    });
  };

  closeDetailsPopover = () => {
    this.setState({ detailsPopover: null });
  };

  resubmitAttendance = (employeeId, employeeName, markDate, item) => {
    this.openMarkPopover(employeeId, employeeName, markDate, item);
  };

  requestRemovalAttendance = (attendanceId) => {
    const { permission, detailsPopover } = this.state;
    const targetEmployeeId =
      (detailsPopover && detailsPopover.employeeId) ||
      (detailsPopover && detailsPopover.item && detailsPopover.item.employeeId);
    if (!canRemoveAttendanceFor(permission, targetEmployeeId, commonUtils.getCurrentUserId())) {
      return;
    }
    store.dispatch(
      this.props.requestAttendanceRemoval({
        id: attendanceId,
        requestedBy: commonUtils.getCurrentUserId(),
        onSuccess: () => this.closeDetailsPopover(),
      })
    );
  };

  submitMarkAttendance = (details) => {
    const { markPopover } = this.state;
    if (!markPopover) return;

    this.createAttendance({
      employeeId: markPopover.employeeId,
      markDate: details.markDate,
      markTime: details.markTime,
      hours: details.hours,
      checkoutTime: details.checkoutTime,
      markedBy: commonUtils.getCurrentUserId(),
    });
    this.closeMarkPopover();
  };

  approveAttendance = (attendanceId, approvalComment, attendanceItem) => {
    store.dispatch(
      this.props.approveAttendance({
        id: attendanceId,
        approverId: commonUtils.getCurrentUserId(),
        approvalComment: approvalComment ? approvalComment.trim() : null,
        removalRequest:
          attendanceItem && attendanceItem.status === "PENDING_REMOVAL",
        onSuccess: () => this.closeDetailsPopover(),
      })
    );
  };

  rejectAttendance = (attendanceId, approvalComment, attendanceItem) => {
    const comment = approvalComment ? approvalComment.trim() : "";
    if (!comment) return;

    store.dispatch(
      this.props.rejectAttendance({
        id: attendanceId,
        approverId: commonUtils.getCurrentUserId(),
        approvalComment: comment,
        onSuccess: () => this.closeDetailsPopover(),
      })
    );
  };

  openPendingItemDetails = (item) => {
    const employee = (this.props.allEmployees || this.props.employees || []).find(
      (emp) => String(emp.id) === String(item.employeeId)
    );
    if (!employee) return;
    const markDate = dateUtils.convertDateToMoment(item.markDate);
    this.openDetailsPopover(employee.id, employee.name, markDate, item);
  };

  handleAuditDeepLink = (event) => {
    const link = resolveAttendanceAuditDeepLink(event);
    if (!link) return;

    const employees = this.props.allEmployees || this.props.employees || [];
    const employeeId = link.employeeId;
    const employee =
      employees.find((emp) => String(emp.id) === String(employeeId)) || null;
    if (!employee || !link.markDate) return;

    const markMoment = dateUtils.convertDateToMoment(link.markDate);
    if (!markMoment) return;

    if (!markMoment.isSame(this.state.selectedDate, "month")) {
      this.refreshMonthDates(markMoment);
    }

    if (String(this.state.selectedEmployeeId) !== String(employee.id)) {
      this.handleEmployeeFilterChange(employee.id);
    }

    let item =
      (this.props.items || []).find(
        (entry) => link.attendanceId && String(entry.id) === String(link.attendanceId)
      ) || findAttendanceItem(this.props.items, employee.id, markMoment);

    if (!item) {
      item = buildAttendanceStubFromAuditEvent(event);
    }

    this.openDetailsPopover(employee.id, employee.name, markMoment, item);
  };

  render() {
    const { employees, items, isLoading, filterOptions, userTeams } = this.props;
    const {
      monthDays,
      permission,
      markPopover,
      detailsPopover,
      selectedEmployeeId,
      regularizationEnabled,
      activeView,
      regularizationDrawerOpen,
      regularizationDate,
      regularizationItem,
      pendingRegularizations,
      regularizationPolicy,
      attendanceIntelligence,
      anomalyRecommendation,
      loadingRegularization,
      regWorkflowLoading,
      leaveCoverageEnabled,
      leaveTeamCoverage,
      leaveCoverageUnavailable,
      loadingLeaveCoverage,
    } = this.state;
    const currentUserId = commonUtils.getCurrentUserId();
    const employeeFilterList = sortEmployeesCurrentFirst(
      this.props.allEmployees || employees,
      currentUserId
    );
    const teamEmployees = sortEmployeesCurrentFirst(employees, currentUserId);
    const sortedEmployees = filterEmployeesById(teamEmployees, selectedEmployeeId);
    const currentUserEmployee = findCurrentUserEmployee(employees, currentUserId);
    const focusEmployee =
      selectedEmployeeId != null
        ? (employeeFilterList || []).find(
            (emp) => String(emp.id) === String(selectedEmployeeId)
          )
        : currentUserEmployee;
    const focusStats =
      focusEmployee && getEmployeeStats(focusEmployee.id, items, monthDays);
    const isViewingSelf =
      !focusEmployee || String(focusEmployee.id) === String(currentUserId);
    const summaryStat = buildAttendanceSummary(
      teamEmployees,
      items,
      monthDays,
      this.state.selectedDate
    );
    const dashboard = buildAttendanceDashboard(
      teamEmployees,
      items,
      monthDays,
      currentUserId
    );
    const coverageActualByDate = {};
    (dashboard.dailyTrend || []).forEach((day) => {
      if (!day || !day.key || day.isFuture || !(day.possible > 0)) return;
      coverageActualByDate[day.key] = {
        pct: day.rate,
        present: day.present,
        possible: day.possible,
      };
    });
    const hasData = (employees && employees.length > 0) || isLoading;
    const teamMenuPermission = {
      ...permission,
      switchUserTeamsEnabled:
        (permission && permission.switchUserTeamsEnabled === true)
        || (userTeams || []).length > 1,
    };

    return (
      <div className="lux-attendance lux-register-page" data-testid="page-attendance">
        <PageDataSourceReporter dataSource="api" />
        <LuxModuleIntro
          meta={DENSE_PAGE_META.attendance}
          howToHref="/documentation/hrms/attendance.html"
          howToTestId="attendance-documentation-link"
        />

        <PageInnerHeader
          userTeams={userTeams}
          handleUserTeamsSelection={this.handleUserTeamsSelection}
          showUserTeamMenu={true}
          showFilter={true}
          isLoading={isLoading}
          permission={teamMenuPermission}
          filterOptions={filterOptions || { filterText: null }}
          onFilterTextChange={this.onFilterTextChange}
          employeeFilterSlot={
            employeeFilterList && employeeFilterList.length > 0 ? (
              <AttendanceEmployeeFilter
                variant="header"
                employees={employeeFilterList}
                selectedEmployeeId={selectedEmployeeId}
                onChange={this.handleEmployeeFilterChange}
                isLoading={isLoading}
              />
            ) : null
          }
        />

        <AttendancePageSummary
          stat={summaryStat}
          dashboard={dashboard}
          isLoading={isLoading && !employees}
          calendarControls={{
            goToBack: this.goToBack,
            goToCurrent: this.goToCurrent,
            goToNext: this.goToNext,
          }}
          calendarDisabled={isLoading}
        />

        <AttendancePendingApprovals
          employees={employeeFilterList || employees}
          items={items}
          currentUserId={currentUserId}
          pendingOptions={buildPendingApprovalOptions(
            this.state.permission,
            this.state.actingDelegations
          )}
          isLoading={isLoading}
          onApprove={this.approveAttendance}
          onReject={this.rejectAttendance}
          onViewDetails={this.openPendingItemDetails}
        />

        {regularizationEnabled && (
          <>
            <AttendancePayrollLockBanner
              policy={regularizationPolicy}
              intelligence={attendanceIntelligence}
            />
            <RegularizationPendingApprovals
              pending={pendingRegularizations}
              employees={this.props.allEmployees || employeeFilterList || employees}
              isLoading={regWorkflowLoading || loadingRegularization}
              actingDelegations={this.state.actingDelegations}
              onApprove={this.approveRegularization}
              onReject={this.rejectRegularization}
            />
          </>
        )}

        <nav className="lux-att-view-tabs" aria-label="Attendance views" data-testid="attendance-view-tabs">
          {[
            { id: "calendar", label: "Calendar", icon: "fe-calendar" },
            { id: "matrix", label: "Matrix", icon: "fe-grid" },
            ...(regularizationEnabled
              ? [
                  { id: "insights", label: "Intelligence", icon: "fe-activity" },
                  { id: "policy", label: "Policy", icon: "fe-shield" },
                ]
              : []),
          ].map((tab) => (
            <button
              key={tab.id}
              type="button"
              className={`lux-att-view-tabs__btn${activeView === tab.id ? " is-active" : ""}`}
              onClick={() => this.handleViewChange(tab.id)}
              data-testid={`attendance-view-${tab.id}`}
            >
              <i className={`fe ${tab.icon}`} aria-hidden="true" />
              {tab.label}
            </button>
          ))}
        </nav>

        {activeView === "calendar" && hasData && (
          <AttendanceCalendarView
            selectedDate={this.state.selectedDate}
            monthDays={monthDays}
            employees={teamEmployees}
            items={items}
            focusEmployee={focusEmployee}
            focusEmployeeId={focusEmployee && focusEmployee.id}
            permission={permission}
            currentUserId={currentUserId}
            isLoading={isLoading}
            isViewingSelf={isViewingSelf}
            employeeFilterEmployees={employeeFilterList}
            selectedEmployeeId={selectedEmployeeId}
            onEmployeeFilterChange={this.handleEmployeeFilterChange}
            workdays={this.state.workdays}
            holidayDates={this.state.holidayDates}
            activityHolidayItems={this.state.activityHolidayItems}
            goToBack={this.goToBack}
            goToCurrent={this.goToCurrent}
            goToNext={this.goToNext}
            onRequestMark={this.openMarkPopover}
            onRequestViewDetails={this.openDetailsPopover}
            onRequestRegularize={
              regularizationEnabled && isViewingSelf ? this.openRegularizationDrawer : null
            }
            leaveApplyPath={isViewingSelf ? "/people/leaves" : null}
          />
        )}

        {activeView === "matrix" && focusEmployee && focusStats && !isLoading && (
          <AttendanceCurrentUserPanel
            employee={focusEmployee}
            stats={focusStats}
            monthDays={monthDays}
            items={items}
            permission={permission}
            isLoading={isLoading}
            isViewingSelf={isViewingSelf}
            currentUserId={currentUserId}
            createAttendance={this.createAttendance}
            deleteAttendance={this.deleteAttendance}
            onRequestMark={this.openMarkPopover}
            onRequestViewDetails={this.openDetailsPopover}
            workdays={this.state.workdays}
            holidayDates={this.state.holidayDates}
            onRequestRegularize={
              regularizationEnabled && isViewingSelf ? this.openRegularizationDrawer : null
            }
            leaveApplyPath={isViewingSelf ? "/people/leaves" : null}
          />
        )}

        {activeView === "matrix" && hasData && (
          <AttendanceMatrix
            employees={sortedEmployees}
            monthDays={monthDays}
            items={items}
            permission={permission}
            isLoading={isLoading}
            currentUserId={currentUserId}
            createAttendance={this.createAttendance}
            deleteAttendance={this.deleteAttendance}
            onRequestMark={this.openMarkPopover}
            onRequestViewDetails={this.openDetailsPopover}
            employeeFilterEmployees={employeeFilterList}
            selectedEmployeeId={selectedEmployeeId}
            onEmployeeFilterChange={this.handleEmployeeFilterChange}
            workdays={this.state.workdays}
            holidayDates={this.state.holidayDates}
          />
        )}

        {regularizationEnabled && activeView === "insights" && (
          <AttendanceIntelligencePanel
            intelligence={attendanceIntelligence}
            recommendation={anomalyRecommendation}
            loading={loadingRegularization}
          />
        )}

        {leaveCoverageEnabled && (activeView === "calendar" || activeView === "matrix") && (
          <LeaveCoveragePanel
            coverage={leaveTeamCoverage}
            actualByDate={coverageActualByDate}
            loading={loadingLeaveCoverage}
            unavailableMessage={
              leaveCoverageUnavailable
                ? "Live leave coverage unavailable. Fail closed — client-invented coverage is not shown when the leave impact API flag is on."
                : null
            }
          />
        )}

        {regularizationEnabled && activeView === "policy" && (
          <AttendanceExceptionPolicyPanel
            policy={regularizationPolicy}
            loading={loadingRegularization}
            canEdit={permission && permission.createEnabled === true}
            saving={this.state.savingRegularizationPolicy}
            saveError={this.state.policySaveError}
            onSave={this.handleSaveRegularizationPolicy}
          />
        )}

        {hasData && sortedEmployees && sortedEmployees.length === 0 && !isLoading && (
          <LuxRegisterEmptyState
            className="lux-register-empty--compact lux-attendance-empty lux-attendance-empty--filter"
            variant="attendance"
            eyebrow="Employee filter"
            title="No employee matches this filter"
            description='Choose another employee or select "All employees" to see the full list.'
            showCreate={false}
          />
        )}

        <AttendanceMarkPopover
          show={!!markPopover}
          employeeId={markPopover && markPopover.employeeId}
          employeeName={markPopover && markPopover.employeeName}
          markDate={markPopover && markPopover.markDate}
          existingItem={markPopover && markPopover.existingItem}
          isLoading={isLoading}
          onClose={this.closeMarkPopover}
          onSubmit={this.submitMarkAttendance}
        />

        <AttendanceDetailsPopover
          show={!!detailsPopover}
          employeeId={detailsPopover && detailsPopover.employeeId}
          employeeName={detailsPopover && detailsPopover.employeeName}
          markDate={detailsPopover && detailsPopover.markDate}
          attendanceItem={detailsPopover && detailsPopover.item}
          isLoading={isLoading}
          canRequestRemoval={
            detailsPopover &&
            canRemoveAttendanceFor(
              permission,
              detailsPopover.employeeId,
              currentUserId
            )
          }
          canResubmit={
            detailsPopover &&
            canMarkAttendanceFor(
              permission,
              detailsPopover.employeeId,
              currentUserId
            )
          }
          canApprove={
            detailsPopover &&
            detailsPopover.item &&
            (employeeFilterList || employees || []).some(
              (emp) =>
                String(emp.id) === String(detailsPopover.item.employeeId) &&
                String(emp.managerId) === String(currentUserId)
            )
          }
          permission={permission}
          showRemindApprover={
            detailsPopover &&
            detailsPopover.item &&
            String(detailsPopover.employeeId) === String(currentUserId) &&
            isAttendanceAwaitingManagerAction(detailsPopover.item)
          }
          onClose={this.closeDetailsPopover}
          onResubmit={this.resubmitAttendance}
          onRequestRemoval={this.requestRemovalAttendance}
          onApprove={this.approveAttendance}
          onReject={this.rejectAttendance}
          employees={this.props.allEmployees || employeeFilterList || employees}
        />

        <RegularizationSubmitDrawer
          open={regularizationDrawerOpen}
          employee={focusEmployee}
          actorId={currentUserId}
          initialDate={regularizationDate}
          attendanceItem={regularizationItem}
          policy={regularizationPolicy}
          timesheetWeeks={[]}
          onClose={this.closeRegularizationDrawer}
          onSubmit={this.submitRegularization}
        />

        {focusEmployee && !isLoading && (
          <div className="lux-page-audit-footer">
            <CollapsibleAuditPanel
              panelKey={`attendance-employee-${focusEmployee.id}`}
              title={isViewingSelf ? "Your attendance audit" : `${focusEmployee.name}'s attendance audit`}
              subtitle="Marks, edits, approvals, and rejections on attendance records"
              icon="fe-calendar"
              auditProps={{
                scope: AUDIT_SCOPES.ACTOR,
                actorUserId: focusEmployee.id,
                lockedEntityFilter: AUDIT_ENTITY_TYPES.ATTENDANCE,
                showEntityFilters: false,
                onEventDeepLink: this.handleAuditDeepLink,
                emptyState: {
                  eyebrow: "Attendance compliance",
                  title: "No attendance audit events yet",
                  description:
                    "When audit logging is enabled, mark and approval actions will appear here with actor and decision context.",
                  hints: [
                    "Pending approval decisions link back to the attendance record",
                    "Delegate approvals show who acted on whose behalf",
                    "Only attendance-related actions are shown on this page",
                  ],
                },
              }}
            />
          </div>
        )}

        {!hasData && !isLoading && (
          <LuxRegisterEmptyState
            className="lux-register-empty--compact lux-attendance-empty"
            variant="attendance"
            eyebrow="Team roster"
            title="No employees in selected teams"
            description="Select one or more teams in the header to load attendance for this month."
            hints={[
              "Employees must be active members of the selected teams",
              "Clear employee filters to see the full roster",
              "Switch teams if you manage multiple groups",
            ]}
          />
        )}
      </div>
    );
  }
}

const mapStateToProps = (state) => {
  const allEmployees =
    state.employees.teamEmployees &&
    commonUtils.getActiveEmployees(state.employees.teamEmployees);

  return {
    allEmployees,
    employees: commonUtils.filterEmployees(allEmployees, state.employees.filterOptionsA),
    isLoading: state.employees.attendanceLoading,
    items: state.employees.attendanceItems,
    filterOptions: state.employees.filterOptionsA,
    userTeams: commonUtils.getUserTeams(state.employees.userTeamsA),
  };
};

const mapDispatchToProps = () => ({
  getTeamsEmployees: employeeActions.getTeamsEmployees,
  getTeamsAttendance: employeeActions.getTeamsAttendance,
  createAttendance: employeeActions.createAttendance,
  approveAttendance: employeeActions.approveAttendance,
  rejectAttendance: employeeActions.rejectAttendance,
  requestAttendanceRemoval: employeeActions.requestAttendanceRemoval,
  deleteAttendance: employeeActions.deleteAttendance,
});

export default connect(mapStateToProps, mapDispatchToProps)(AttendancePage);
