import React from "react";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { payrollExtractToCsv } from "config/leave-payroll.utils";

export default function LeavePayrollExtractPanel({ extract, loading, onExport }) {
  if (loading) {
    return <div className="lux-leave-subpanel lux-leave-payroll is-loading" aria-busy="true" />;
  }
  if (!extract) {
    return null;
  }

  const handleExport = () => {
    const csv = payrollExtractToCsv(extract);
    if (!csv) return;
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `leave-payroll-extract-${Date.now()}.csv`;
    link.click();
    URL.revokeObjectURL(url);
    if (onExport) onExport();
  };

  return (
    <section className="lux-leave-subpanel lux-leave-payroll" aria-label="Payroll leave extract">
      <header className="lux-leave-subpanel__head">
        <div>
          <span className="lux-leave-subpanel__eyebrow">Payroll</span>
          <h3 className="lux-leave-subpanel__title">Leave extract</h3>
          <p className="lux-leave-subpanel__sub">{extract.periodLabel}</p>
        </div>
        <button type="button" className="lux-leave-hero__cta is-secondary" onClick={handleExport}>
          <i className="fe fe-download" aria-hidden="true" />
          Export CSV
        </button>
      </header>

      <div className="lux-leave-payroll__totals">
        <span>{extract.totals.records} records</span>
        <span>Paid {extract.totals.paidDays} days</span>
        <span className="is-lwp">LWP {extract.totals.lwpDays} days</span>
      </div>

      {extract.rows.length === 0 ? (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact lux-leave-empty"
          icon="fe fe-download"
          title="No payroll rows"
          description="No approved leave in this payroll period."
        />
      ) : (
        <div className="lux-leave-register-wrap">
          <table className="lux-leave-register">
            <thead>
              <tr>
                <th>Employee</th>
                <th>Type</th>
                <th>Dates</th>
                <th>Days</th>
                <th>Payroll</th>
              </tr>
            </thead>
            <tbody>
              {extract.rows.map((row) => (
                <tr key={row.leaveId} className="lux-leave-register__row">
                  <td>{row.employeeName}</td>
                  <td>{row.leaveTypeLabel}</td>
                  <td>{row.dateRange}</td>
                  <td>{row.days}</td>
                  <td>
                    <span className={row.lwp ? "lux-leave-payroll__pill is-lwp" : "lux-leave-payroll__pill is-paid"}>
                      {row.payrollStatus}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </section>
  );
}
