import React, { Component } from "react";
import classNames from "classnames/bind";
import { connect } from "react-redux";
import { AUDIT_CONFIG_CHANGED, isAuditUiEnabled } from "_helpers/audit.config";
import { buildAuditScopeKey } from "_helpers/audit.utils";
import { AUDIT_SCOPES } from "_constants/audit.constants";
import {
  readAuditPanelExpanded,
  writeAuditPanelPrefs,
} from "_helpers/audit.panel.utils";
import AuditTrailSection from "./AuditTrailSection";

class CollapsibleAuditPanel extends Component {
  constructor(props) {
    super(props);
    const { panelKey, defaultExpanded } = props;
    this.state = {
      expanded: readAuditPanelExpanded(panelKey, defaultExpanded === true),
      uiEnabled: isAuditUiEnabled(),
    };
  }

  componentDidMount() {
    this.handleAuditConfigChanged = () => {
      this.setState({ uiEnabled: isAuditUiEnabled() });
    };
    window.addEventListener(AUDIT_CONFIG_CHANGED, this.handleAuditConfigChanged);
  }

  componentDidUpdate(prevProps) {
    if (prevProps.panelKey !== this.props.panelKey) {
      const { panelKey, defaultExpanded } = this.props;
      this.setState({
        expanded: readAuditPanelExpanded(panelKey, defaultExpanded === true),
      });
    }
  }

  componentWillUnmount() {
    window.removeEventListener(AUDIT_CONFIG_CHANGED, this.handleAuditConfigChanged);
  }

  toggleExpanded = () => {
    const { panelKey } = this.props;
    this.setState((prev) => {
      const expanded = !prev.expanded;
      writeAuditPanelPrefs(panelKey, { expanded });
      return { expanded };
    });
  };

  render() {
    const { panelKey, title, subtitle, icon, className, auditProps, children, eventCount, isLoading } =
      this.props;
    const { expanded, uiEnabled } = this.state;

    if (!uiEnabled || !panelKey) {
      return null;
    }

    const toggleIcon = icon || "fe-shield";
    const showCount = typeof eventCount === "number" && eventCount > 0;

    return (
      <section
        className={classNames("lux-audit-collapsible", className, {
          "is-expanded": expanded,
        })}
        data-audit-panel={panelKey}
      >
        <button
          type="button"
          className="lux-audit-collapsible__toggle"
          onClick={this.toggleExpanded}
          aria-expanded={expanded}
          aria-controls={`audit-panel-body-${panelKey}`}
        >
          <span className="lux-audit-collapsible__toggle-main">
            <span className="lux-audit-collapsible__icon" aria-hidden="true">
              <i className={`fe ${toggleIcon}`} />
            </span>
            <span className="lux-audit-collapsible__copy">
              <strong className="lux-audit-collapsible__title">{title}</strong>
              {subtitle && <span className="lux-audit-collapsible__subtitle">{subtitle}</span>}
            </span>
          </span>
          <span className="lux-audit-collapsible__toggle-meta">
            {isLoading && !showCount && (
              <span className="lux-audit-collapsible__status is-loading" aria-hidden="true" />
            )}
            {showCount && (
              <span className="lux-audit-collapsible__count">
                {eventCount} event{eventCount === 1 ? "" : "s"}
              </span>
            )}
            <span className="lux-audit-collapsible__chevron" aria-hidden="true">
              <i className={classNames("fe", expanded ? "fe-chevron-up" : "fe-chevron-down")} />
            </span>
          </span>
        </button>

        <div
          id={`audit-panel-body-${panelKey}`}
          className={classNames("lux-audit-collapsible__body", {
            "is-collapsed": !expanded,
          })}
          aria-hidden={!expanded}
        >
          {auditProps ? (
            <AuditTrailSection
              {...auditProps}
              persistKey={auditProps.persistKey || panelKey}
              hideHeader={auditProps.hideHeader !== false}
            />
          ) : (
            children
          )}
        </div>
      </section>
    );
  }
}

function resolveAuditScopeKey(auditProps) {
  if (!auditProps) return null;
  if (auditProps.scope === AUDIT_SCOPES.ACTOR) {
    return buildAuditScopeKey("actor", { actorUserId: auditProps.actorUserId });
  }
  return buildAuditScopeKey("entity", {
    entityType: auditProps.entityType,
    entityId: auditProps.entityId,
  });
}

const mapStateToProps = (state, ownProps) => {
  const scopeKey = resolveAuditScopeKey(ownProps.auditProps);
  const timeline =
    scopeKey && state.audit && state.audit.timelines && state.audit.timelines[scopeKey];
  return {
    eventCount: timeline && Array.isArray(timeline.items) ? timeline.items.length : null,
    isLoading: !!(timeline && timeline.isLoading),
  };
};

export default connect(mapStateToProps)(CollapsibleAuditPanel);
