import React from "react";
import classNames from "classnames/bind";
import { FEATURE_FLAG_STATUSES } from "config/feature-flag.config";
import { getFeatureFlagModuleMeta } from "config/feature-flag.utils";

function formatUpdatedAt(value) {
  if (!value) return "—";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}

export default function FeatureFlagRegister({ flags, selectedId, onSelect }) {
  return (
    <div className="lux-fflag-register-wrap">
      <table className="lux-fflag-register">
        <colgroup>
          <col className="lux-fflag-register__col--flag" />
          <col className="lux-fflag-register__col--module" />
          <col className="lux-fflag-register__col--adoption" />
          <col className="lux-fflag-register__col--risk" />
          <col className="lux-fflag-register__col--status" />
          <col className="lux-fflag-register__col--updated" />
        </colgroup>
        <thead>
          <tr>
            <th>Flag</th>
            <th>Module</th>
            <th>Adoption</th>
            <th>Risk</th>
            <th>Status</th>
            <th>Updated</th>
          </tr>
        </thead>
        <tbody>
          {flags.map((flag) => {
            const meta = getFeatureFlagModuleMeta(flag.module);
            const adoption = Math.max(0, Math.min(100, Number(flag.adoptionPct) || 0));
            return (
              <tr
                key={flag.id}
                className={classNames("lux-fflag-register__row", {
                  "is-selected": selectedId === flag.id,
                  "is-attention": flag.risk === "high" && flag.enabled,
                })}
                onClick={() => onSelect && onSelect(flag)}
              >
                <td>
                  <div className="lux-fflag-register__primary">
                    <span
                      className={classNames("lux-fflag-register__avatar", meta.tone && `is-${meta.tone}`)}
                      aria-hidden="true"
                    >
                      <i className={meta.icon} />
                    </span>
                    <span className="lux-fflag-register__primary-copy">
                      <strong className="lux-fflag-register__primary-title">{flag.name}</strong>
                      <span className="lux-fflag-register__primary-meta">{flag.key}</span>
                      {flag.description ? (
                        <span className="lux-fflag-register__primary-meta">{flag.description}</span>
                      ) : null}
                    </span>
                  </div>
                </td>
                <td>
                  <span className="lux-fflag-register__chip">{flag.module}</span>
                </td>
                <td>
                  <div className="lux-fflag-register__adoption-cell">
                    <div className="lux-fflag-register__adoption-bar" aria-hidden="true">
                      <span
                        className={classNames("lux-fflag-register__adoption-fill", {
                          "is-on": flag.enabled,
                          "is-off": !flag.enabled,
                        })}
                        style={{ width: `${adoption}%` }}
                      />
                    </div>
                    <span className="lux-fflag-register__adoption">{adoption}%</span>
                  </div>
                </td>
                <td>
                  <span className={classNames("lux-fflag-register__risk", `is-${flag.risk}`)}>
                    {flag.risk}
                  </span>
                </td>
                <td>
                  <span
                    className={classNames("lux-doc-badge", {
                      "is-success": flag.enabled,
                      "is-info": !flag.enabled && flag.status === FEATURE_FLAG_STATUSES.PILOT,
                      "is-muted": !flag.enabled && flag.status !== FEATURE_FLAG_STATUSES.PILOT,
                    })}
                  >
                    {flag.status}
                  </span>
                </td>
                <td>
                  <span className="lux-fflag-register__date">{formatUpdatedAt(flag.updatedAt)}</span>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
