import React, { Component } from "react";
import { ModalManager } from "views/common/plugins/model/Modal";
import { userUtils, accessUtils, brandUtils } from "_helpers";
import { isMockDataEnabled } from "mock/mock.config";
import SparklesIcon from "./fragments/SparklesIcon";
import FamstackAIChatModal from "./FamstackAIChatModal";
import HelpSearchModal from "./HelpSearchModal";
import DeviceRegistrationPopup from "./DeviceRegistrationPopup";
import AgentConsoleAssistModal from "./AgentConsoleAssistModal";
import PagePermissionAssistModal from "./PagePermissionAssistModal";
import AppConfigFlagGuideModal from "./AppConfigFlagGuideModal";
import LuxuryGuidedTour from "./LuxuryGuidedTour";
import {
  clampDockBottom,
  readStoredDockBottom,
  storeDockBottom,
} from "./assistDock.utils";
import "./MobileRegistrationMenu.css";

const DRAG_THRESHOLD_PX = 5;
const HOVER_CLOSE_DELAY_MS = 280;

class LuxuryAssistDock extends Component {
  constructor(props) {
    super(props);
    this.state = {
      menuOpen: false,
      aiOpen: false,
      helpOpen: false,
      consoleOpen: false,
      permissionsOpen: false,
      flagGuideOpen: false,
      mobileOpen: false,
      showMobile: false,
      dockBottom: readStoredDockBottom(),
      isDragging: false,
      tourAvailable: false,
      tourBadge: false,
      tourPopoverOpen: false,
    };
    this.dragState = null;
    this.dockRef = React.createRef();
    this.triggerRef = React.createRef();
    this.tourRef = React.createRef();
    this.hoverCloseTimer = null;
  }

  componentDidMount() {
    this.checkMobileVisibility();
    document.addEventListener("keydown", this.handleKeyDown);
    window.addEventListener("resize", this.handleResize);
  }

  componentWillUnmount() {
    document.removeEventListener("keydown", this.handleKeyDown);
    window.removeEventListener("resize", this.handleResize);
    this.detachDragListeners();
    this.clearHoverCloseTimer();
    document.body.classList.remove("device-registration-popup-open");
  }

  handleResize = () => {
    this.setState((prev) => ({
      dockBottom: clampDockBottom(prev.dockBottom),
    }));
  };

  checkMobileVisibility = () => {
    const permission = accessUtils.getProfileSettingsControl();
    const user = userUtils.getCurrentUser();
    const deviceRegistrationEnabled =
      permission && permission.deviceRegistrationEnabled === true;
    const deviceAppEnabled = user && user.deviceAppEnabled === true;
    this.setState({
      showMobile: deviceRegistrationEnabled && deviceAppEnabled,
    });
  };

  handleKeyDown = (e) => {
    if (e.key === "Escape" && this.state.menuOpen) {
      this.setState({ menuOpen: false });
    }
  };

  clearHoverCloseTimer = () => {
    if (this.hoverCloseTimer) {
      clearTimeout(this.hoverCloseTimer);
      this.hoverCloseTimer = null;
    }
  };

  openMenu = () => {
    this.clearHoverCloseTimer();
    if (!this.state.isDragging) {
      this.setState({ menuOpen: true });
    }
  };

  closeMenu = () => {
    this.clearHoverCloseTimer();
    this.setState({ menuOpen: false });
  };

  scheduleCloseMenu = () => {
    if (this.state.tourPopoverOpen) {
      return;
    }
    this.clearHoverCloseTimer();
    this.hoverCloseTimer = setTimeout(() => {
      this.setState({ menuOpen: false });
    }, HOVER_CLOSE_DELAY_MS);
  };

  handleDockMouseEnter = () => {
    this.openMenu();
  };

  handleDockMouseLeave = () => {
    this.scheduleCloseMenu();
  };

  detachDragListeners = () => {
    document.removeEventListener("pointermove", this.handlePointerMove);
    document.removeEventListener("pointerup", this.handlePointerUp);
    document.removeEventListener("pointercancel", this.handlePointerUp);
  };

  handlePointerDown = (e) => {
    if (e.button !== 0) {
      return;
    }
    this.dragState = {
      startY: e.clientY,
      startBottom: this.state.dockBottom,
      moved: false,
      pointerId: e.pointerId,
    };
    this.setState({ isDragging: false });
    document.addEventListener("pointermove", this.handlePointerMove);
    document.addEventListener("pointerup", this.handlePointerUp);
    document.addEventListener("pointercancel", this.handlePointerUp);
  };

  handlePointerMove = (e) => {
    if (!this.dragState || e.pointerId !== this.dragState.pointerId) {
      return;
    }
    const deltaY = this.dragState.startY - e.clientY;
    if (Math.abs(deltaY) >= DRAG_THRESHOLD_PX) {
      this.dragState.moved = true;
      if (!this.state.isDragging) {
        this.setState({ isDragging: true, menuOpen: false });
      }
    }
    if (this.dragState.moved) {
      e.preventDefault();
      const nextBottom = clampDockBottom(this.dragState.startBottom + deltaY);
      this.setState({ dockBottom: nextBottom });
    }
  };

  handlePointerUp = (e) => {
    if (!this.dragState || e.pointerId !== this.dragState.pointerId) {
      return;
    }
    const wasDrag = this.dragState.moved;
    const bottom = this.state.dockBottom;
    this.detachDragListeners();
    this.dragState = null;

    if (wasDrag) {
      storeDockBottom(bottom);
      this.setState({ isDragging: false });
      return;
    }

    this.setState({ isDragging: false });
    this.openMenu();
  };

  getModalAnchor = () => {
    const el = this.triggerRef.current;
    if (!el || typeof window === "undefined") {
      return { bottom: this.state.dockBottom + 98, right: 0 };
    }
    const rect = el.getBoundingClientRect();
    return {
      bottom: Math.max(48, Math.round(window.innerHeight - rect.top + 6)),
      right: Math.max(0, Math.round(window.innerWidth - rect.right)),
    };
  };

  isAiModuleEnabled = () => {
    const permission = accessUtils.getMenuAccessControl();
    return (
      isMockDataEnabled() ||
      (permission &&
        permission.aiModules &&
        (permission.aiModules.agentsEnabled === true || permission.aiModules.active === true))
    );
  };

  openAiConsole = () => {
    this.clearHoverCloseTimer();
    const dockAnchor = this.getModalAnchor();
    if (this.state.consoleOpen) {
      ModalManager.close();
      this.setState({ consoleOpen: false });
      return;
    }
    ModalManager.open(
      <AgentConsoleAssistModal
        dockAnchor={dockAnchor}
        onRequestClose={() => {
          ModalManager.close();
          this.setState({ consoleOpen: false });
        }}
      />
    );
    this.setState({
      consoleOpen: true,
      aiOpen: false,
      helpOpen: false,
      permissionsOpen: false,
      flagGuideOpen: false,
      menuOpen: false,
    });
  };

  openAI = () => {
    this.clearHoverCloseTimer();
    const dockAnchor = this.getModalAnchor();
    if (this.state.aiOpen) {
      ModalManager.close();
      this.setState({ aiOpen: false });
      return;
    }
    ModalManager.open(
      <FamstackAIChatModal
        dockAnchor={dockAnchor}
        onRequestClose={() => {
          ModalManager.close();
          this.setState({ aiOpen: false });
        }}
      />
    );
    this.setState({
      aiOpen: true,
      helpOpen: false,
      consoleOpen: false,
      permissionsOpen: false,
      flagGuideOpen: false,
      menuOpen: false,
    });
  };

  openHelp = () => {
    this.clearHoverCloseTimer();
    const dockAnchor = this.getModalAnchor();
    if (this.state.helpOpen) {
      ModalManager.close();
      this.setState({ helpOpen: false });
      return;
    }
    ModalManager.open(
      <HelpSearchModal
        dockAnchor={dockAnchor}
        onRequestClose={() => {
          ModalManager.close();
          this.setState({ helpOpen: false });
        }}
      />
    );
    this.setState({
      helpOpen: true,
      aiOpen: false,
      consoleOpen: false,
      permissionsOpen: false,
      flagGuideOpen: false,
      menuOpen: false,
    });
  };

  openFlagGuide = () => {
    this.clearHoverCloseTimer();
    ModalManager.close();
    this.setState({
      flagGuideOpen: true,
      permissionsOpen: false,
      aiOpen: false,
      helpOpen: false,
      consoleOpen: false,
      menuOpen: false,
    });
  };

  closeFlagGuide = () => {
    this.setState({ flagGuideOpen: false });
  };

  openPermissions = () => {
    this.clearHoverCloseTimer();
    const dockAnchor = this.getModalAnchor();
    if (this.state.permissionsOpen) {
      ModalManager.close();
      this.setState({ permissionsOpen: false });
      return;
    }
    ModalManager.open(
      <PagePermissionAssistModal
        dockAnchor={dockAnchor}
        onOpenFlagGuide={this.openFlagGuide}
        onRequestClose={() => {
          ModalManager.close();
          this.setState({ permissionsOpen: false });
        }}
      />
    );
    this.setState({
      permissionsOpen: true,
      flagGuideOpen: false,
      aiOpen: false,
      helpOpen: false,
      consoleOpen: false,
      menuOpen: false,
    });
  };

  openMobile = () => {
    this.clearHoverCloseTimer();
    this.setState({ mobileOpen: true, menuOpen: false });
    document.body.classList.add("device-registration-popup-open");
  };

  closeMobile = (e) => {
    if (e) {
      e.preventDefault();
      e.stopPropagation();
    }
    this.setState({ mobileOpen: false });
    document.body.classList.remove("device-registration-popup-open");
    setTimeout(() => this.checkMobileVisibility(), 0);
  };

  handleTourAvailabilityChange = ({ available, hasBadge }) => {
    this.setState({ tourAvailable: available, tourBadge: hasBadge });
  };

  handleTourPopoverChange = (open) => {
    this.setState({ tourPopoverOpen: open });
    if (open) {
      this.clearHoverCloseTimer();
      this.setState({
        menuOpen: true,
        aiOpen: false,
        helpOpen: false,
        permissionsOpen: false,
        flagGuideOpen: false,
      });
      ModalManager.close();
    }
  };

  openTour = () => {
    this.clearHoverCloseTimer();
    this.setState({
      menuOpen: true,
      aiOpen: false,
      helpOpen: false,
      permissionsOpen: false,
      flagGuideOpen: false,
    });
    ModalManager.close();
    const tour = this.tourRef.current;
    if (tour && typeof tour.openPopover === "function") {
      tour.openPopover();
    }
  };

  render() {
    const {
      menuOpen,
      showMobile,
      mobileOpen,
      dockBottom,
      isDragging,
      tourAvailable,
      tourBadge,
      tourPopoverOpen,
      flagGuideOpen,
    } = this.state;
    const appName = brandUtils.getAppBrandName();

    return (
      <>
        <div
          ref={this.dockRef}
          data-tour="lux-assist-dock"
          className={`lux-assist-dock no-print${menuOpen ? " is-open" : ""}${
            isDragging ? " is-dragging" : ""
          }`}
          style={{ bottom: `${dockBottom}px` }}
          aria-label="Assist menu"
          onMouseEnter={this.handleDockMouseEnter}
          onMouseLeave={this.handleDockMouseLeave}
        >
          <div
            className={`lux-assist-dock__icons${menuOpen ? " is-visible" : ""}`}
            role="menu"
            aria-hidden={!menuOpen}
          >
            <button
              type="button"
              className="lux-assist-dock__icon-btn lux-assist-dock__icon-btn--ai"
              role="menuitem"
              onClick={this.openAI}
              title={`${appName} AI`}
              aria-label={`${appName} AI`}
            >
              <SparklesIcon size={20} />
            </button>

            {this.isAiModuleEnabled() && (
              <button
                type="button"
                className="lux-assist-dock__icon-btn lux-assist-dock__icon-btn--ai-console"
                role="menuitem"
                onClick={this.openAiConsole}
                title="Agent console"
                aria-label="Agent console"
              >
                <i className="fe fe-cpu" aria-hidden="true" />
              </button>
            )}

            <button
              type="button"
              className="lux-assist-dock__icon-btn lux-assist-dock__icon-btn--help"
              role="menuitem"
              onClick={this.openHelp}
              title="Help Center"
              aria-label="Help Center"
            >
              <i className="fa fa-life-ring" aria-hidden="true" />
            </button>

            <button
              type="button"
              className="lux-assist-dock__icon-btn lux-assist-dock__icon-btn--permissions"
              role="menuitem"
              onClick={this.openPermissions}
              title="Page permissions"
              aria-label="Page permissions"
            >
              <i className="fe fe-shield" aria-hidden="true" />
            </button>

            {tourAvailable && (
              <button
                type="button"
                className="lux-assist-dock__icon-btn lux-assist-dock__icon-btn--tour"
                role="menuitem"
                data-tour="lux-tour-launcher"
                onClick={this.openTour}
                title="Guided tour"
                aria-label="Guided tour"
                aria-expanded={tourPopoverOpen}
                aria-haspopup="dialog"
              >
                <i className="fe fe-compass" aria-hidden="true" />
                {tourBadge ? (
                  <span className="lux-assist-dock__icon-badge" aria-hidden="true" />
                ) : null}
              </button>
            )}

            {showMobile && (
              <button
                type="button"
                className="lux-assist-dock__icon-btn lux-assist-dock__icon-btn--mobile"
                role="menuitem"
                onClick={this.openMobile}
                title="Mobile app registration"
                aria-label="Mobile app registration"
              >
                <span className="mobile-registration-icon-container lux-assist-dock__mobile-shell">
                  <span className="mobile-phone-shape">
                    <span className="qr-code-badge">
                      <i className="fa fa-qrcode" />
                    </span>
                    <span className="registration-indicator">REG</span>
                    <i className="fa fa-mobile-alt mobile-phone-icon" />
                    <span className="home-button" />
                  </span>
                </span>
              </button>
            )}
          </div>

          <button
            ref={this.triggerRef}
            type="button"
            className="lux-assist-dock__trigger"
            onPointerDown={this.handlePointerDown}
            aria-expanded={menuOpen}
            aria-haspopup="menu"
            title="Assist menu — hover to open, drag to move"
            aria-label="Assist menu"
          >
            <span className="lux-assist-dock__trigger-glow" aria-hidden="true" />
            <span className="lux-assist-dock__trigger-inner">
              <SparklesIcon size={20} className="lux-assist-dock__trigger-sparkle" />
              <span className="lux-assist-dock__trigger-text">Assist</span>
            </span>
          </button>
        </div>

        {mobileOpen && (
          <DeviceRegistrationPopup
            onClose={this.closeMobile}
            onRegistrationComplete={this.checkMobileVisibility}
          />
        )}

        {flagGuideOpen && (
          <AppConfigFlagGuideModal
            show
            onRequestClose={this.closeFlagGuide}
          />
        )}

        <LuxuryGuidedTour
          ref={this.tourRef}
          embedded
          getDockAnchor={this.getModalAnchor}
          onAvailabilityChange={this.handleTourAvailabilityChange}
          onPopoverChange={this.handleTourPopoverChange}
        />
      </>
    );
  }
}

export default LuxuryAssistDock;
