/**
 * WTG-002 API service. The current user team is always the write/read scope;
 * there is intentionally no mock or environment-flag fallback.
 */
import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import {
  normalizeProjectFeatureOverride,
  normalizeProjectScope,
  normalizeWorkTimeFeature,
} from "config/work-time-governance.config";

const API_BASE = `${urlConfig.APPCONFIG_API_PATH}/work-time-governance`;

export const workTimeGovernanceService = {
  listFeatures,
  getFeatureGate,
  updateFeature,
  listProjectOverrides,
  createProjectOverride,
  updateProjectOverride,
  deleteProjectOverride,
  getObservability,
  getDeadlinePolicy,
  getDeadlinePreview,
  getEstimatePolicy,
  getEstimateVariance,
};

function currentTeamId() {
  const userTeamId = commonUtils.getCurrentUserTeamId();
  if (userTeamId == null || userTeamId === "") {
    throw new Error("A current team is required for work-time governance.");
  }
  return userTeamId;
}

function responsePayload(response) {
  if (
    response &&
    typeof response === "object" &&
    Object.prototype.hasOwnProperty.call(response, "payload")
  ) {
    return response.payload;
  }
  return response;
}

function featurePath(featureKey) {
  if (!featureKey) {
    throw new Error("A work-time feature key is required.");
  }
  return `${API_BASE}/features/${encodeURIComponent(featureKey)}`;
}

function projectOverridesPath(projectId, featureKey) {
  const scope = normalizeProjectScope(projectId);
  if (!scope) {
    throw new Error("A valid project ID is required.");
  }
  const base = `${API_BASE}/projects/${encodeURIComponent(scope)}/overrides`;
  return featureKey ? `${base}/${encodeURIComponent(featureKey)}` : base;
}

function writePath(path) {
  return `${path}?userTeamId=${encodeURIComponent(currentTeamId())}`;
}

async function listFeatures(filters = {}) {
  const query = { userTeamId: currentTeamId() };
  const projectId =
    filters.projectId == null || filters.projectId === ""
      ? null
      : normalizeProjectScope(filters.projectId);
  if (filters.projectId != null && filters.projectId !== "" && !projectId) {
    throw new Error("A valid project ID is required.");
  }
  if (projectId) {
    query.projectId = projectId;
  }
  if (filters.roleId != null && filters.roleId !== "") {
    query.roleId = filters.roleId;
  }

  const response = await axiosUtils.getWithParam(`${API_BASE}/features`, query);
  const rows = responsePayload(response);
  return {
    payload: (Array.isArray(rows) ? rows : []).map(normalizeWorkTimeFeature).filter(Boolean),
    source: "api",
  };
}

async function getFeatureGate(featureKey, filters = {}) {
  if (!featureKey) {
    throw new Error("A work-time feature key is required.");
  }
  const projectId =
    filters.projectId == null || filters.projectId === ""
      ? null
      : normalizeProjectScope(filters.projectId);
  if (filters.projectId != null && filters.projectId !== "" && !projectId) {
    throw new Error("A valid project ID is required.");
  }
  const query = { userTeamId: currentTeamId() };
  if (projectId) {
    query.projectId = projectId;
  }
  const response = await axiosUtils.getWithParam(
    `${API_BASE}/effective/${encodeURIComponent(featureKey)}`,
    query
  );
  const row = responsePayload(response);
  const feature =
    row &&
    typeof row === "object" &&
    !Array.isArray(row) &&
    String(row.id || "") === String(featureKey)
      ? {
          id: String(row.id),
          effectiveEnabled: row.effectiveEnabled === true,
          source: row.source || null,
          blockedByDependencies: Array.isArray(row.blockedByDependencies)
            ? row.blockedByDependencies.filter(Boolean).map(String)
            : [],
        }
      : null;
  return {
    payload: feature,
    enabled: Boolean(feature && feature.effectiveEnabled === true),
    source: "api",
  };
}

async function updateFeature(featureKey, enabled) {
  const response = await axiosUtils.patch(writePath(featurePath(featureKey)), {
    enabled: enabled === true,
  });
  return {
    payload: normalizeWorkTimeFeature(responsePayload(response)),
    source: "api",
  };
}

async function listProjectOverrides(projectId) {
  const response = await axiosUtils.getWithParam(projectOverridesPath(projectId), {
    userTeamId: currentTeamId(),
  });
  const rows = responsePayload(response);
  return {
    payload: (Array.isArray(rows) ? rows : [])
      .map(normalizeProjectFeatureOverride)
      .filter(Boolean),
    source: "api",
  };
}

async function createProjectOverride(projectId, payload) {
  const response = await axiosUtils.post(
    writePath(projectOverridesPath(projectId)),
    payload
  );
  return {
    payload: normalizeProjectFeatureOverride(responsePayload(response)),
    source: "api",
  };
}

async function updateProjectOverride(projectId, featureKey, payload) {
  const response = await axiosUtils.put(
    writePath(projectOverridesPath(projectId, featureKey)),
    payload
  );
  return {
    payload: normalizeProjectFeatureOverride(responsePayload(response)),
    source: "api",
  };
}

async function getObservability() {
  const response = await axiosUtils.getWithParam(`${API_BASE}/observability`, {
    userTeamId: currentTeamId(),
  });
  return {
    payload: responsePayload(response),
    source: "api",
  };
}

async function getDeadlinePolicy(projectId) {
  const query = { userTeamId: currentTeamId() };
  const scope = projectId == null || projectId === "" ? null : normalizeProjectScope(projectId);
  if (scope) {
    query.projectId = scope;
  }
  const response = await axiosUtils.getWithParam(`${API_BASE}/timesheets/deadline-policy`, query);
  return {
    payload: responsePayload(response),
    source: "api",
  };
}

async function getDeadlinePreview({ weekStart, weekEnd, viewerTeamId } = {}) {
  const teamId = currentTeamId();
  const query = {
    userTeamId: teamId,
    viewerTeamId: viewerTeamId == null || viewerTeamId === "" ? teamId : viewerTeamId,
  };
  if (weekStart) {
    query.weekStart = weekStart;
  }
  if (weekEnd) {
    query.weekEnd = weekEnd;
  }
  const response = await axiosUtils.getWithParam(
    `${API_BASE}/timesheets/deadline-preview`,
    query
  );
  return {
    payload: responsePayload(response),
    source: "api",
  };
}

async function getEstimatePolicy(projectId) {
  const query = { userTeamId: currentTeamId() };
  const scope = projectId == null || projectId === "" ? null : normalizeProjectScope(projectId);
  if (scope) {
    query.projectId = scope;
  }
  const response = await axiosUtils.getWithParam(`${API_BASE}/planning/estimate-policy`, query);
  return {
    payload: responsePayload(response),
    source: "api",
  };
}

async function getEstimateVariance(projectId, filters = {}) {
  const scope = normalizeProjectScope(projectId);
  if (!scope) {
    throw new Error("A valid project ID is required.");
  }
  const query = { userTeamId: currentTeamId(), projectId: scope };
  if (filters.from) {
    query.from = filters.from;
  }
  if (filters.to) {
    query.to = filters.to;
  }
  const response = await axiosUtils.getWithParam(`${API_BASE}/planning/variance`, query);
  return {
    payload: responsePayload(response),
    source: "api",
  };
}

async function deleteProjectOverride(projectId, featureKey) {
  const response = await axiosUtils.remove(
    writePath(projectOverridesPath(projectId, featureKey))
  );
  return {
    payload: responsePayload(response),
    source: "api",
  };
}
