import React, { Component } from "react";
import { Link } from "react-router-dom";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { accessUtils } from "_helpers";
import { ADMIN_PAGE_META } from "config/admin-page-meta.config";
import { isAdminInsightsEnabled } from "config/admin-insights.config";
import {
  buildAdminInsightsChartBundle,
  buildAdminInsightsInsights,
  buildAdminInsightsMetrics,
} from "config/admin-insights.utils";
import { adminInsightsService } from "_services/adminInsights.service";
import { recordAuditEvent } from "config/audit-write.service";
import { AUDIT_ACTION_TYPES, AUDIT_ENTITY_TYPES } from "_constants/audit.constants";
import PolicyAnalyticsBarChart from "views/people/components/policy/PolicyAnalyticsBarChart";
import {
  AdminActionButton,
  AdminPanelLink,
  AdminLuxPage,
} from "views/admin/components/AdminLuxShared";
import AdminInsightsSummary from "views/admin/components/AdminInsightsSummary";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import AdminLoadAlert from "views/admin/components/AdminLoadAlert";

const COMMAND_LINKS = [
  {
    to: "/admin/roles",
    icon: "fe fe-lock",
    title: "Roles",
    copy: "Persona access & permissions",
    tone: "indigo",
  },
  {
    to: "/admin/persona-navigation",
    icon: "fe fe-compass",
    title: "Persona navigation",
    copy: "Org-wide offs & page maps",
    tone: "sky",
  },
  {
    to: "/admin/access-requests",
    icon: "fe fe-user-check",
    title: "Access requests",
    copy: "Approve & fulfill queue",
    tone: "amber",
  },
  {
    to: "/admin/delegation",
    icon: "fe fe-git-branch",
    title: "Delegation",
    copy: "Coverage & acting-for",
    tone: "mint",
  },
  {
    to: "/admin/workflows",
    icon: "fe fe-zap",
    title: "Workflows",
    copy: "Automation studio",
    tone: "violet",
  },
  {
    to: "/admin/appconfig",
    icon: "fe fe-settings",
    title: "App config",
    copy: "Org & role settings",
    tone: "slate",
  },
];

class AdminDashboardPage extends Component {
  state = { snapshot: null, loading: true, loadError: null, dataSource: null };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Admin dashboard");
    this.loadDashboard();
    recordAuditEvent({
      actionType: AUDIT_ACTION_TYPES.AUDIT_VIEWED,
      entityType: AUDIT_ENTITY_TYPES.ADMIN_CONFIG,
      entityRef: "Admin dashboard",
      metadata: { route: "/admin/dashboard" },
    });
  }

  loadDashboard = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await adminInsightsService.getDashboard();
      this.setState({ snapshot: result.payload || {}, loading: false, dataSource: result.source });
    } catch (e) {
      this.setState({ loading: false, loadError: "Unable to load admin dashboard.", snapshot: null });
    }
  };

  buildSummaryModel = (snapshot, metrics, pendingAccess) => {
    const insights = buildAdminInsightsInsights(snapshot || {});
    const charts = buildAdminInsightsChartBundle(snapshot || {});
    const auditTotal = Math.max(metrics.auditTotal || 0, 1);
    const denialShare = Math.round((metrics.accessDenials / auditTotal) * 100);
    const readyShare = Math.min(Math.max(metrics.complianceReadinessPct || 0, 0), 100);
    const adoptShare = Math.min(Math.max(metrics.flagAdoptionAvg || 0, 0), 100);

    return {
      kpis: [
        {
          key: "audit",
          label: "Audit events",
          value: metrics.auditTotal,
          hint: `${metrics.auditRecent24h} in 24h`,
          tone: "violet",
          icon: "fe fe-shield",
        },
        {
          key: "denials",
          label: "Access denials",
          value: metrics.accessDenials,
          hint: "Rejected requests",
          tone: metrics.accessDenials ? "rose" : "slate",
          icon: "fe fe-slash",
        },
        {
          key: "access",
          label: "Pending access",
          value: pendingAccess,
          hint: "Needs action",
          tone: pendingAccess ? "amber" : "green",
          icon: "fe fe-user-check",
        },
        {
          key: "compliance",
          label: "Compliance",
          value: metrics.complianceReadinessPct,
          suffix: "%",
          hint: `${metrics.readySections}/${metrics.totalSections} sections`,
          tone: "green",
          icon: "fe fe-check-circle",
        },
        {
          key: "adoption",
          label: "Flag adoption",
          value: metrics.flagAdoptionAvg,
          suffix: "%",
          hint: `${metrics.enabledFlags} enabled`,
          tone: "blue",
          icon: "fe fe-toggle-right",
        },
      ],
      highlights: [
        {
          key: "actors",
          label: "Unique actors",
          value: metrics.uniqueActors,
          hint: "Audit participants",
          tone: "indigo",
          icon: "fe fe-users",
        },
        {
          key: "masking",
          label: "Masking restricted",
          value: `${metrics.maskingRestrictedPct}%`,
          hint: `${metrics.highRiskRules} high-risk open`,
          tone: metrics.highRiskRules ? "amber" : "green",
          icon: "fe fe-eye-off",
        },
      ],
      attention: insights.map((row) => ({
        id: row.id,
        eyebrow: "Signal",
        stat: row.tone === "rose" || row.tone === "amber" ? "Review" : "OK",
        title: row.title,
        copy: row.copy,
        hint: "Open related admin console from Command deck below.",
        icon: row.icon,
        tone: row.tone,
      })),
      mixInsights: [
        {
          key: "governance-mix",
          icon: "fe fe-activity",
          title: "Governance mix",
          subtitle: "Compliance · adoption · denial pressure",
          mix: [
            {
              key: "ready",
              label: "Compliance",
              count: metrics.complianceReadinessPct,
              pct: readyShare,
              tone: "green",
            },
            {
              key: "adopt",
              label: "Adoption",
              count: metrics.flagAdoptionAvg,
              pct: adoptShare,
              tone: "blue",
            },
            {
              key: "denials",
              label: "Denials",
              count: metrics.accessDenials,
              pct: Math.min(Math.max(denialShare, metrics.accessDenials ? 8 : 0), 100),
              tone: "rose",
            },
          ],
          emptyLabel: "No governance mix yet",
        },
        {
          key: "access-queue",
          icon: "fe fe-inbox",
          title: "Access queue",
          subtitle: `${pendingAccess} pending · ${metrics.accessDenials} denied`,
          mix: [
            {
              key: "pending",
              label: "Pending",
              count: pendingAccess,
              pct: Math.round(
                (pendingAccess / Math.max(pendingAccess + metrics.accessDenials, 1)) * 100
              ),
              tone: "amber",
            },
            {
              key: "denied",
              label: "Denied",
              count: metrics.accessDenials,
              pct: Math.round(
                (metrics.accessDenials / Math.max(pendingAccess + metrics.accessDenials, 1)) * 100
              ),
              tone: "rose",
            },
          ],
        },
      ],
      series: [
        {
          id: "audit-volume",
          title: "Audit pulse",
          subtitle: "Last 7 days",
          rows: (charts.auditVolume || []).map((row) => ({
            key: row.id || row.label,
            label: row.label,
            icon: "fe fe-activity",
            tone: row.tone || "violet",
            value: row.value,
            pct: Math.min((row.value || 0) * 18, 100),
            meta: String(row.value),
          })),
        },
      ],
      charts,
    };
  };

  render() {
    const adminModules = accessUtils.getAccessControll("adminModules") || {};
    if (!isAdminInsightsEnabled() || adminModules.dashboardEnabled === false) {
      return (
        <PersonaAccessDenied
          moduleName="Admin dashboard"
          reason="Admin dashboard is not enabled for your organization."
        />
      );
    }

    const { loading, loadError, snapshot, dataSource } = this.state;
    const metrics = buildAdminInsightsMetrics(snapshot || {});
    const accessRequests = (snapshot && snapshot.accessRequests) || [];
    const pendingAccess = accessRequests.filter(
      (row) => row.status === "PENDING" || row.status === "SUBMITTED"
    ).length;
    const summary = loading
      ? null
      : this.buildSummaryModel(snapshot, metrics, pendingAccess);
    const charts = (summary && summary.charts) || {};
    const hasCharts =
      (charts.auditVolume && charts.auditVolume.length > 0) ||
      (charts.accessDenials && charts.accessDenials.length > 0) ||
      (charts.sensitiveFieldAccess && charts.sensitiveFieldAccess.length > 0) ||
      (charts.complianceReadiness && charts.complianceReadiness.length > 0) ||
      (charts.featureAdoption && charts.featureAdoption.length > 0) ||
      (charts.auditActions && charts.auditActions.length > 0);

    return (
      <AdminLuxPage
        pageMeta={ADMIN_PAGE_META.dashboard}
        dataSource={dataSource}
        loading={loading}
        testId="page-admin-dashboard"
        className="lux-admin-page lux-admin-dashboard-page"
        onRefresh={this.loadDashboard}
        refreshLoading={loading}
      >
        <AdminLoadAlert
          error={loadError}
          fallback="Unable to load admin dashboard."
          onDismiss={() => this.setState({ loadError: null })}
        />

        <AdminInsightsSummary
          storageKey="famstack-admin-dashboard-summary-expanded"
          domainClass="lux-admin-summary--dashboard"
          loading={loading}
          eyebrow="Governance intelligence"
          eyebrowIcon="fe-grid"
          title="Admin dashboard insights"
          compactTitle={
            summary
              ? `${metrics.auditTotal} audits · ${pendingAccess} pending · ${metrics.complianceReadinessPct}% ready`
              : "Admin dashboard insights"
          }
          collapsedLine={`${metrics.auditRecent24h} events / 24h · ${metrics.enabledFlags} flags · ${metrics.accessDenials} denials`}
          subtitle="Audit posture, access queue pressure, compliance readiness, and pilot adoption."
          kpis={summary ? summary.kpis : []}
          highlights={summary ? summary.highlights : []}
          attention={summary ? summary.attention : []}
          mixInsights={summary ? summary.mixInsights : []}
          series={summary ? summary.series : []}
          testId="admin-dashboard-insights-summary"
        />

        <section
          className="lux-admin-atelier lux-admin-atelier--dashboard lux-admin-atelier--compact"
          data-testid="admin-dashboard-atelier"
        >
          <header className="lux-admin-atelier__masthead">
            <div className="lux-admin-atelier__masthead-main">
              <span className="lux-admin-atelier__mark" aria-hidden="true">
                <i className="fe fe-command" />
              </span>
              <div className="lux-admin-atelier__masthead-copy">
                <div className="lux-admin-atelier__title-row">
                  <p className="lux-admin-atelier__eyebrow">Command deck</p>
                  <h2 className="lux-admin-atelier__title">Governance workspace</h2>
                </div>
                <p className="lux-admin-atelier__lede">
                  Jump to admin consoles · review charts · keep posture green
                </p>
              </div>
            </div>
            <div className="lux-admin-atelier__masthead-aside">
              <AdminPanelLink to="/admin/setup-checklist">Setup checklist</AdminPanelLink>
              <span className="lux-admin-atelier__count">
                <strong>{pendingAccess}</strong>
                <em>pending</em>
              </span>
            </div>
          </header>

          <div className="lux-admin-atelier__body">
            {loading ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                title="Loading dashboard"
                description="Composing governance KPIs and charts."
              />
            ) : (
              <>
                <div className="lux-admin-dashboard__commands" role="list" aria-label="Admin shortcuts">
                  {COMMAND_LINKS.map((item) => (
                    <Link
                      key={item.to}
                      to={item.to}
                      className={`lux-admin-dashboard__command is-${item.tone}`}
                      role="listitem"
                    >
                      <span className="lux-admin-dashboard__command-icon" aria-hidden="true">
                        <i className={item.icon} />
                      </span>
                      <span className="lux-admin-dashboard__command-copy">
                        <strong>{item.title}</strong>
                        <em>{item.copy}</em>
                      </span>
                      <i className="fe fe-arrow-right lux-admin-dashboard__command-chevron" aria-hidden="true" />
                    </Link>
                  ))}
                </div>

                <div className="lux-admin-atelier__stage-card lux-admin-dashboard__charts">
                  <header className="lux-hrms-dash__panel-head">
                    <div>
                      <h3 className="lux-hrms-dash__panel-title">Governance insights</h3>
                      <p className="lux-hrms-dash__panel-sub">
                        Audit volume, denials, masking, compliance, and adoption
                      </p>
                    </div>
                  </header>
                  {!hasCharts ? (
                    <LuxRegisterEmptyState
                      className="lux-register-empty--compact"
                      title="No chart series yet"
                      description="Audit and governance signals will appear here as activity accumulates."
                    />
                  ) : (
                    <div className="lux-admin-insights-analytics__grid lux-admin-dashboard__chart-grid">
                      {charts.auditVolume && charts.auditVolume.some((row) => row.value > 0) && (
                        <PolicyAnalyticsBarChart
                          title="Audit volume"
                          subtitle="Last 7 days"
                          series={charts.auditVolume}
                        />
                      )}
                      {charts.auditActions && charts.auditActions.length > 0 && (
                        <PolicyAnalyticsBarChart
                          title="Audit actions"
                          subtitle="Top action types"
                          series={charts.auditActions}
                        />
                      )}
                      {charts.accessDenials && charts.accessDenials.length > 0 && (
                        <PolicyAnalyticsBarChart
                          title="Access denials"
                          subtitle="Rejected by domain"
                          series={charts.accessDenials}
                        />
                      )}
                      {charts.sensitiveFieldAccess && charts.sensitiveFieldAccess.length > 0 && (
                        <PolicyAnalyticsBarChart
                          title="Sensitive field access"
                          subtitle="Persona masking posture"
                          series={charts.sensitiveFieldAccess}
                        />
                      )}
                      {charts.complianceReadiness && charts.complianceReadiness.length > 0 && (
                        <PolicyAnalyticsBarChart
                          title="Compliance readiness"
                          subtitle="Pack section posture"
                          series={charts.complianceReadiness}
                        />
                      )}
                      {charts.featureAdoption &&
                        charts.featureAdoption.some((row) => row.value > 0) && (
                          <PolicyAnalyticsBarChart
                            title="Feature adoption"
                            subtitle="Pilot flags"
                            series={charts.featureAdoption}
                          />
                        )}
                    </div>
                  )}
                </div>
              </>
            )}
          </div>
        </section>
      </AdminLuxPage>
    );
  }
}

export default AdminDashboardPage;
