import React from "react";

export default function IssueAgingPanel({ model, loading }) {
  if (loading || !model || !model.openCount) {
    return (
      <div className="lux-gov-issue-aging lux-gov-issue-aging--empty">
        <p>No open issues to age. Log blockers to populate the aging chart.</p>
      </div>
    );
  }

  return (
    <div className="lux-gov-issue-aging">
      <div className="lux-gov-issue-aging__meta">
        <strong>{model.openCount}</strong>
        <span>open issues by age bucket</span>
      </div>
      <div className="lux-gov-issue-aging__bars">
        {model.buckets.map((bucket) => (
          <div key={bucket.id} className="lux-gov-issue-aging__bar-row">
            <span>{bucket.label}</span>
            <div className="lux-gov-issue-aging__track">
              <div
                className="lux-gov-issue-aging__fill"
                style={{ width: `${Math.round((bucket.count / model.maxCount) * 100)}%` }}
              />
            </div>
            <em>{bucket.count}</em>
          </div>
        ))}
      </div>
    </div>
  );
}
