import React from "react";
import classNames from "classnames/bind";
import { buildTimesheetGovernanceBannerModel } from "./timesheetGovernance.utils";
import "./TimesheetGovernanceBanner.css";

export default function TimesheetGovernanceBanner({ governance }) {
  const model = buildTimesheetGovernanceBannerModel(governance);
  if (!model) {
    return null;
  }
  return (
    <section
      className={classNames("lux-ts-lock-banner lux-ts-gov-banner", {
        "is-warning": !model.blocked,
        "is-blocked": model.blocked,
      })}
      data-testid="timesheet-governance-banner"
      aria-label="Timesheet governance"
      role="status"
    >
      <div className="lux-ts-lock-banner__hero">
        <div className="lux-ts-lock-banner__icon" aria-hidden="true">
          <i className={model.blocked ? "fe fe-slash" : "fe fe-shield"} />
        </div>
        <div className="lux-ts-lock-banner__copy">
          <strong>{model.title}</strong>
          {model.chips.length > 0 && (
            <div className="lux-ts-gov-banner__chips">
              {model.chips.map((chip) => (
                <span
                  key={chip.id}
                  className={classNames("lux-doc-badge", {
                    "is-success": chip.tone === "success",
                    "is-warning": chip.tone === "warning",
                    "is-muted": chip.tone === "muted",
                    "is-info": chip.tone === "info",
                    "is-danger": chip.tone === "danger",
                  })}
                >
                  {chip.label}
                </span>
              ))}
            </div>
          )}
          {model.messages.length > 0 && (
            <ul className="lux-ts-gov-banner__list">
              {model.messages.map((message) => (
                <li key={message}>{message}</li>
              ))}
            </ul>
          )}
        </div>
        <span className="lux-ts-lock-banner__count">{model.messages.length || model.chips.length}</span>
      </div>
    </section>
  );
}
