import dateUtils from "_helpers/date.utils";
import moment from "moment";
import { normalizeTimesheetStatus, readAttributeValue } from "./timesheetSummary.utils";

export function isManagerTimesheetApprover(permission) {
  // Role RBAC is the gate for manager lifecycle actions (approve / reopen / lock).
  // Org timesheetApprovalEnabled gates submit/workflow chrome separately — do not
  // hide reopen when a week is already APPROVED (in-flight) and org flag is off/unloaded.
  return !!(permission && permission.enableTimeSheetApproval === true);
}

/**
 * Reopen CTA for APPROVED weeks, or REOPENED weeks that still have other approved
 * submission batches to reopen under partial-week mode:
 * - Normal approve: only {@code approvedBy} may reopen.
 * - Auto-approve-own ({@code approvedBy === employeeId} or authority AUTO):
 *   manager / timesheet approval actor can reopen; employee can only when they
 *   have no reporting manager (solo owner — options.employeeManagerId null).
 */
export function canReopenTimesheetWeek(permission, actingDelegations, options = {}) {
  if (!permission) {
    return false;
  }
  if (permission.timesheetReopenEnabled === false || permission.enableTimeSheetReopen === false) {
    return false;
  }
  const { timeSheetData, currentUserId, viewingOwnWeek, employeeManagerId } = options;
  if (!timeSheetData || currentUserId == null) {
    return false;
  }
  const weekStatus = normalizeTimesheetStatus(readAttributeValue(timeSheetData.status));
  if (weekStatus !== "APPROVED" && weekStatus !== "REOPENED") {
    return false;
  }
  const approvedBy = readAttributeValue(timeSheetData.approvedBy);
  const employeeId = readAttributeValue(timeSheetData.employeeId);
  const authorityType = String(readAttributeValue(timeSheetData.approvalAuthorityType) || "").toUpperCase();

  // Partial-week approvals may leave week.approvedBy unset; match backend reopen
  // authority (reporting manager / delegate) for employee weeks.
  if (!approvedBy) {
    if (viewingOwnWeek === true) {
      return false;
    }
    return isTimesheetApprovalActor(permission, actingDelegations);
  }

  const selfApproved =
    (employeeId != null && String(approvedBy) === String(employeeId)) || authorityType === "AUTO";

  if (selfApproved) {
    const isOwner =
      viewingOwnWeek === true || String(currentUserId) === String(employeeId);
    if (isOwner) {
      return !hasReportingManager(employeeManagerId);
    }
    return isTimesheetApprovalActor(permission, actingDelegations);
  }
  return String(approvedBy) === String(currentUserId);
}

/**
 * Partial-week: reopen an approved submission batch while the week is still DRAFT/PENDING
 * (other day batches remain editable). Managers/delegates only — not the employee owner.
 */
export function canReopenTimesheetSubmissionBatch(permission, actingDelegations, options = {}) {
  if (!permission) {
    return false;
  }
  if (permission.timesheetReopenEnabled === false || permission.enableTimeSheetReopen === false) {
    return false;
  }
  if (permission.partialWeekSubmissionEnabled !== true) {
    return false;
  }
  const { viewingOwnWeek, reopenOptions } = options;
  if (!reopenOptions || !reopenOptions.length) {
    return false;
  }
  if (viewingOwnWeek === true) {
    return false;
  }
  return isTimesheetApprovalActor(permission, actingDelegations);
}

function hasReportingManager(managerId) {
  if (managerId == null || managerId === "") {
    return false;
  }
  return String(managerId) !== "0";
}

export function hasTimesheetDelegationScope(approvalTypes) {
  if (!approvalTypes || !approvalTypes.length) return false;
  return approvalTypes.some((type) => {
    const normalized = String(type).toUpperCase();
    return normalized === "TIMESHEET" || normalized === "BOTH";
  });
}

export function isTimesheetApprovalActor(permission, actingDelegations) {
  if (isManagerTimesheetApprover(permission)) return true;
  if (!permission || permission.approvalDelegationEnabled !== true) return false;
  if (!actingDelegations || !actingDelegations.length) return false;
  return actingDelegations.some(
    (delegation) =>
      delegation &&
      delegation.active !== false &&
      hasTimesheetDelegationScope(delegation.approvalTypes)
  );
}

export function formatTimesheetWeekRange(week) {
  if (!week) return "—";
  if (week.dateFrom || week.dateTo || (week.activityDates && week.activityDates.length)) {
    const start = parseWeekDate(week.dateFrom || (week.activityDates && week.activityDates[0]));
    const end = parseWeekDate(
      week.dateTo ||
        (week.activityDates && week.activityDates[week.activityDates.length - 1])
    );
    if (start && end && start.isValid() && end.isValid()) {
      const weekStart = parseWeekDate(week.weekStartDate);
      const weekEnd = parseWeekDate(week.weekEndDate);
      const rangeLabel = `${start.format("D MMM")} – ${end.format("D MMM")}`;
      if (weekStart && weekEnd && weekStart.isValid() && weekEnd.isValid()) {
        return `${rangeLabel} (week ${weekStart.format("D MMM")}–${weekEnd.format("D MMM")})`;
      }
      return rangeLabel;
    }
  }
  const start = parseWeekDate(week.weekStartDate);
  const end = parseWeekDate(week.weekEndDate);
  if (start && end && start.isValid() && end.isValid()) {
    return `${start.format("D MMM")} – ${end.format("D MMM YYYY")}`;
  }
  if (start && start.isValid()) {
    return `Week of ${start.format("D MMM YYYY")}`;
  }
  return "This week";
}

export function formatSubmittedDate(week) {
  const submitted = parseWeekDate(week && week.submittedDate);
  if (!submitted || !submitted.isValid()) {
    return "—";
  }
  return submitted.format("D MMM YYYY, h:mm a");
}

export function summarizePendingTimesheetWeeks(weeks) {
  const list = weeks || [];
  const employeeIds = new Set(list.map((week) => week.employeeId).filter((id) => id != null));
  return {
    total: list.length,
    employeeCount: employeeIds.size,
  };
}

/** Group pending weeks by employee for the luxury inbox layout (matches leave pending). */
export function groupPendingTimesheetWeeksByEmployee(weeks) {
  const groups = [];
  const byEmployee = new Map();
  (weeks || []).forEach((week) => {
    const employeeId = week && week.employeeId != null ? week.employeeId : "unknown";
    if (!byEmployee.has(employeeId)) {
      const group = {
        employeeId,
        employeeName: (week && week.employeeName) || `Employee #${employeeId}`,
        items: [],
      };
      byEmployee.set(employeeId, group);
      groups.push(group);
    }
    byEmployee.get(employeeId).items.push(week);
  });
  return groups;
}

export function getConflictTypeLabel(conflictType) {
  if (conflictType === "TASK_BOARD_OVERLAP") {
    return "Task board overlap";
  }
  if (conflictType === "DUPLICATE_ENTRY") {
    return "Duplicate entry";
  }
  return conflictType || "Conflict";
}

/** Stable key for pending-card conflict counts (`sub-{id}` or `week-{id}`). */
export function pendingTimesheetConflictKey(week) {
  if (!week || week.id == null) {
    return null;
  }
  if (week.submissionId != null && week.submissionId !== "") {
    return `sub-${week.submissionId}`;
  }
  return `week-${week.id}`;
}

export const CONFLICT_RESOLUTION_OPTIONS = [
  { id: "MERGE", label: "Merge hours", hint: "Sum staged and approved durations" },
  { id: "REPLACE", label: "Replace", hint: "Keep staged hours only" },
  { id: "KEEP_BOTH", label: "Keep both", hint: "Promote staged as a separate entry" },
];

/** Normalize API / grid date keys to ISO yyyy-MM-dd. */
export function toIsoDate(value) {
  if (!value) return null;
  if (typeof value === "string") {
    if (/^\d{4}-\d{2}-\d{2}$/.test(value)) {
      return value;
    }
    const parsed = moment(value, ["YYYY-MMM-DD", "YYYY-MM-DD", moment.ISO_8601], true);
    if (parsed.isValid()) {
      return parsed.format("YYYY-MM-DD");
    }
    const converted = dateUtils.convertDateStringToMoment(value);
    if (converted && converted.isValid()) {
      return converted.format("YYYY-MM-DD");
    }
    return value.length >= 10 ? value.slice(0, 10) : value;
  }
  try {
    const parsed = moment(value);
    return parsed.isValid() ? parsed.format("YYYY-MM-DD") : null;
  } catch (e) {
    return null;
  }
}

/** Context captured when a manager opens a pending approval on the weekly board. */
export function buildApprovalReviewContext(week) {
  if (!week || week.id == null) {
    return null;
  }
  return {
    weekId: week.id,
    submissionId:
      week.submissionId != null && week.submissionId !== "" ? week.submissionId : null,
    activityDates: (week.activityDates || []).map(toIsoDate).filter(Boolean),
    employeeId: week.employeeId,
    weekStartDate: toIsoDate(week.weekStartDate),
    label: formatTimesheetWeekRange(week),
    employeeName: week.employeeName || null,
  };
}

export function isApprovalReviewContextActive(context, options = {}) {
  if (!context) {
    return false;
  }
  const { weekId, employeeId, weekStartDate } = options;
  if (employeeId != null && String(context.employeeId) !== String(employeeId)) {
    return false;
  }
  if (weekId != null && context.weekId != null && String(context.weekId) !== String(weekId)) {
    return false;
  }
  if (weekStartDate) {
    const normalizedWeekStart = toIsoDate(weekStartDate);
    if (
      context.weekStartDate &&
      normalizedWeekStart &&
      context.weekStartDate !== normalizedWeekStart
    ) {
      return false;
    }
  }
  return true;
}

function collectPendingApprovalDatesFromSheet(timeSheetData, submissionId) {
  const dates = new Set();
  if (!timeSheetData) {
    return dates;
  }
  const visitBucket = (bucket) => {
    Object.values(bucket || {}).forEach((group) => {
      (group.tasks || []).forEach((task) => {
        Object.entries(task.timeEntry || {}).forEach(([dateKey, entry]) => {
          if (!entry || entry.isDeleted === true) {
            return;
          }
          const mins = parseInt(entry.timesheetTimeMins || 0, 10);
          if (mins <= 0) {
            return;
          }
          const status = normalizeTimesheetStatus(
            readAttributeValue(entry.status) || readAttributeValue(entry.timesheetStatus)
          );
          if (status !== "PENDING" && status !== "PENDING_APPROVAL") {
            return;
          }
          if (submissionId != null && submissionId !== "") {
            if (
              entry.submissionId == null ||
              String(entry.submissionId) !== String(submissionId)
            ) {
              return;
            }
          }
          const iso = toIsoDate(dateKey);
          if (iso) {
            dates.add(iso);
          }
        });
      });
    });
  };
  visitBucket(timeSheetData.project);
  visitBucket(timeSheetData.nonProject);
  return dates;
}

/** Day columns to highlight when reviewing a pending approval batch. */
export function resolveApprovalReviewHighlightDates(context, timeSheetRequest, weekDates) {
  const highlightDates = new Set();
  if (!context || !weekDates || !weekDates.length) {
    return highlightDates;
  }

  const weekDateSet = new Set(weekDates.map(toIsoDate).filter(Boolean));

  if (context.activityDates && context.activityDates.length) {
    context.activityDates.forEach((iso) => {
      if (weekDateSet.has(iso)) {
        highlightDates.add(iso);
      }
    });
    return highlightDates;
  }

  collectPendingApprovalDatesFromSheet(timeSheetRequest, context.submissionId).forEach((iso) => {
    if (weekDateSet.has(iso)) {
      highlightDates.add(iso);
    }
  });
  return highlightDates;
}

export function isApprovalReviewHighlightEntry(entry, dateKey, context, highlightDates) {
  if (!context || !highlightDates || !highlightDates.size || !entry) {
    return false;
  }
  const iso = toIsoDate(dateKey);
  if (!iso || !highlightDates.has(iso)) {
    return false;
  }
  const mins = parseInt(entry.timesheetTimeMins || 0, 10);
  if (mins <= 0) {
    return false;
  }
  const status = normalizeTimesheetStatus(
    readAttributeValue(entry.status) || readAttributeValue(entry.timesheetStatus)
  );
  if (status !== "PENDING" && status !== "PENDING_APPROVAL") {
    return false;
  }
  if (context.submissionId != null && context.submissionId !== "") {
    if (
      entry.submissionId != null &&
      String(entry.submissionId) !== String(context.submissionId)
    ) {
      return false;
    }
  }
  return true;
}

export function formatApprovalReviewBanner(context) {
  if (!context) {
    return "";
  }
  const parts = ["Reviewing approval batch"];
  if (context.label) {
    parts.push(context.label);
  }
  if (context.submissionId != null) {
    parts.push(`Submission #${context.submissionId}`);
  }
  return parts.join(" · ");
}

function parseWeekDate(value) {
  if (!value) return null;
  if (moment.isMoment(value)) return value;
  if (typeof value === "string") {
    const iso = moment(value);
    if (iso.isValid()) return iso;
    return dateUtils.convertDateToMoment(value);
  }
  return dateUtils.convertDateToMoment(value);
}
