import React, { Component } from "react";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";
import { listReleaseHistory, getCurrentAppVersion } from "config/app-release-history";
import { writeLastSeenWhatsNewVersion } from "views/common/whatsNew/whatsNew.storage";
import ReleaseHistoryList from "views/common/whatsNew/ReleaseHistoryList";

class VersionHistoryPage extends Component {
  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler(this.props.routeProp && this.props.routeProp.name
        ? this.props.routeProp.name
        : "Version history");
    }
    writeLastSeenWhatsNewVersion(getCurrentAppVersion());
  }

  render() {
    const currentVersion = getCurrentAppVersion();
    const releases = listReleaseHistory();

    return (
      <div
        className="lux-register-page lux-version-history-page"
        data-testid="page-version-history"
      >
        <LuxModuleIntro meta={DENSE_PAGE_META.versionHistory} hideHowTo />
        <div className="lux-register-page__body">
          <section className="lux-version-history-page__panel">
            <header className="lux-version-history-page__panel-head">
              <h3 className="lux-version-history-page__panel-title">All releases</h3>
              <p className="lux-version-history-page__panel-sub">
                Current version v{currentVersion}. Earlier versions stay listed so you can
                review every enhancement that shipped.
              </p>
            </header>
            <ReleaseHistoryList releases={releases} currentVersion={currentVersion} />
          </section>
        </div>
      </div>
    );
  }
}

export default VersionHistoryPage;
