import React, { Component } from "react";
import { NavLink, withRouter } from "react-router-dom";
import classNames from "classnames/bind";
import envconfig from "env.config";
import { accessUtils } from "_helpers/access.utils";
import { forceReloadLatestApp } from "_helpers/appUpdate.utils";
import { getCurrentAppVersion } from "config/app-release-history";
import LegalDocumentModal from "views/common/legal/LegalDocumentModal";
import { LEGAL_DOC_TYPES } from "views/common/legal/legalDocuments";
import WhatsNewModal from "views/common/whatsNew/WhatsNewModal";
import { writeLastSeenWhatsNewVersion } from "views/common/whatsNew/whatsNew.storage";
import {
  FOOTER_MODULES,
  getActiveFooterModule,
  getFooterModuleHref,
} from "./pageFooter.utils";

class PageFooter extends Component {
  constructor(props) {
    super(props);
    this.state = {
      permission: accessUtils.getMenuAccessControl(),
      legalDocType: null,
      showWhatsNew: false,
      reloading: false,
    };
  }

  openLegal = (docType) => {
    this.setState({ legalDocType: docType });
  };

  closeLegal = () => {
    this.setState({ legalDocType: null });
  };

  switchLegal = (docType) => {
    this.setState({ legalDocType: docType });
  };

  openWhatsNew = () => {
    this.setState({ showWhatsNew: true });
  };

  closeWhatsNew = () => {
    writeLastSeenWhatsNewVersion(getCurrentAppVersion());
    this.setState({ showWhatsNew: false });
  };

  forceReloadLatest = () => {
    if (this.state.reloading) return;
    this.setState({ reloading: true });
    forceReloadLatestApp().catch(() => {
      this.setState({ reloading: false });
      window.location.reload();
    });
  };

  render() {
    const currentYear = new Date().getFullYear();
    const appName = (envconfig.APP_NAME || "tracopus").toLowerCase();
    const appVersion = getCurrentAppVersion();
    const { permission, legalDocType, showWhatsNew, reloading } = this.state;
    const pathname = this.props.location && this.props.location.pathname;
    const activeModule = getActiveFooterModule(pathname);

    return (
      <>
        <footer className="lux-page-footer page-footer-modern" role="contentinfo">
          <div className="lux-page-footer__bar container-fluid">
            <div className="lux-page-footer__left">
              <span className="lux-page-footer__copy">
                © {currentYear}{" "}
                <a href="https://infleca.com" target="_blank" rel="noopener noreferrer">
                  Infleca Innovation Pvt Ltd
                </a>
              </span>
              <span className="lux-page-footer__sep" aria-hidden="true">·</span>
            </div>

            <nav className="lux-page-footer__context" aria-label="Switch module context">
              {FOOTER_MODULES.map((module) => {
                const href = getFooterModuleHref(module, permission);
                if (!href) return null;
                const isActive = activeModule && activeModule.id === module.id;
                return (
                  <NavLink
                    key={module.id}
                    to={href}
                    className={classNames("lux-page-footer__ctx", { "is-active": isActive })}
                    title={module.description}
                  >
                    <i className={`fe ${module.icon}`} aria-hidden="true" />
                    {module.label}
                  </NavLink>
                );
              })}
            </nav>

            <div className="lux-page-footer__right">
              <a
                href="/documentation/index.html"
                className="lux-page-footer__link"
                target="_blank"
                rel="noopener noreferrer"
              >
                <i className="fe fe-book-open" aria-hidden="true" />
                Docs
              </a>
              <button
                type="button"
                className="lux-page-footer__link"
                data-testid="footer-privacy-link"
                onClick={() => this.openLegal(LEGAL_DOC_TYPES.PRIVACY)}
              >
                Privacy
              </button>
              <button
                type="button"
                className="lux-page-footer__link"
                data-testid="footer-terms-link"
                onClick={() => this.openLegal(LEGAL_DOC_TYPES.TERMS)}
              >
                Terms
              </button>
              <button
                type="button"
                className="lux-page-footer__meta lux-page-footer__meta--version"
                title={`${appName} release — what's new`}
                data-testid="footer-version-whats-new"
                aria-haspopup="dialog"
                aria-expanded={showWhatsNew}
                onClick={this.openWhatsNew}
              >
                v{appVersion}
              </button>
              <button
                type="button"
                className="lux-page-footer__link"
                title="Clear cached shell and load the latest deployed version"
                data-testid="footer-force-reload"
                disabled={reloading}
                onClick={this.forceReloadLatest}
              >
                <i className="fe fe-refresh-cw" aria-hidden="true" />
                {reloading ? "Reloading…" : "Reload latest"}
              </button>
              {envconfig.ENV_NAME && (
                <span className="lux-page-footer__meta is-env">{envconfig.ENV_NAME}</span>
              )}
            </div>
          </div>
        </footer>

        <LegalDocumentModal
          show={!!legalDocType}
          docType={legalDocType || LEGAL_DOC_TYPES.PRIVACY}
          onClose={this.closeLegal}
          onSwitchDoc={this.switchLegal}
        />
        <WhatsNewModal
          show={showWhatsNew}
          onClose={this.closeWhatsNew}
          pathname={pathname}
        />
      </>
    );
  }
}

export default withRouter(PageFooter);
