import React, { Component } from "react";
import { npdService } from "_services/npd/npd.service";
import NpdLuxPage, {
  NpdActionButton,
  NpdLuxPanel,
} from "views/npd/components/NpdLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class NpdLaunchPage extends Component {
  state = {
    loading: true,
    loadError: null,
    ideas: [],
    selectedIdeaRef: "",
    checklist: [],
    title: "Launch docs complete",
    required: true,
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("NPD launch checklist");
    }
    this.loadIdeas();
  }

  loadIdeas = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await npdService.listIdeas();
    if (result.source === "api" && Array.isArray(result.payload)) {
      const ideas = result.payload;
      const selectedIdeaRef = ideas.length ? ideas[0].ideaRef : "";
      this.setState({ loading: false, ideas, selectedIdeaRef }, () => {
        if (selectedIdeaRef) this.loadChecklist(selectedIdeaRef);
      });
    } else {
      this.setState({
        loading: false,
        ideas: [],
        loadError: result.error || new Error("Unable to load ideas"),
      });
    }
  };

  loadChecklist = async (ideaRef) => {
    const result = await npdService.listChecklist(ideaRef);
    if (result.source === "api" && Array.isArray(result.payload)) {
      this.setState({ checklist: result.payload });
    } else {
      this.setState({
        checklist: [],
        loadError: result.error || new Error("Unable to load checklist"),
      });
    }
  };

  onSelectIdea = (e) => {
    const selectedIdeaRef = e.target.value;
    this.setState({ selectedIdeaRef }, () => this.loadChecklist(selectedIdeaRef));
  };

  addItem = async (e) => {
    e.preventDefault();
    const { selectedIdeaRef, title, required } = this.state;
    if (!selectedIdeaRef || !title) return;
    const result = await npdService.addChecklistItem(selectedIdeaRef, { title, required });
    if (result.source === "api") {
      this.setState({ title: "" });
      this.loadChecklist(selectedIdeaRef);
    } else {
      this.setState({ loadError: result.error || new Error("Add failed") });
    }
  };

  complete = async (itemRef) => {
    const result = await npdService.completeChecklistItem(itemRef);
    if (result.source === "api") this.loadChecklist(this.state.selectedIdeaRef);
    else this.setState({ loadError: result.error || new Error("Complete failed") });
  };

  render() {
    const { loading, loadError, ideas, selectedIdeaRef, checklist, title, required } = this.state;
    return (
      <NpdLuxPage
        testId="npd-launch-page"
        dataSource={ideas.length ? "api" : loadError ? "api-error" : loading ? null : "api"}
        pageMeta={{
          tone: "violet",
          icon: "fe fe-rocket",
          eyebrow: "Projects · NPD",
          titleLead: "NPD launch",
          titleAccent: "checklist",
          lede: "Track required launch items before go-live.",
        }}
      >
        {loadError ? (
          <LuxInlineAlert tone="warning" title="Unable to load checklist">
            {String(loadError.message || loadError)}
          </LuxInlineAlert>
        ) : null}
        <NpdLuxPanel title="Select idea" icon="fe fe-lightbulb">
          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading"
              description="Fetching records."
            />
          ) : null}
          {!loading && ideas.length === 0 ? (
            <LuxRegisterEmptyState title="No ideas" description="Create an idea before managing the launch checklist." showCreate={false} />
          ) : (
            <select className="form-control" value={selectedIdeaRef} onChange={this.onSelectIdea}>
              {ideas.map((i) => (
                <option key={i.ideaRef} value={i.ideaRef}>
                  {i.ideaRef} — {i.title} ({i.status})
                </option>
              ))}
            </select>
          )}
        </NpdLuxPanel>
        <NpdLuxPanel title="Add checklist item" icon="fe fe-plus">
          <form className="lux-module-inline-form" onSubmit={this.addItem}>
            <div className="form-row align-items-center">
              <div className="col-md-6">
                <input
                  className="form-control"
                  placeholder="Checklist title"
                  value={title}
                  onChange={(e) => this.setState({ title: e.target.value })}
                />
              </div>
              <div className="col-md-2">
                <label className="mb-0">
                  <input
                    type="checkbox"
                    checked={required}
                    onChange={(e) => this.setState({ required: e.target.checked })}
                  />{" "}
                  Required
                </label>
              </div>
              <div className="col-md-2">
                <NpdActionButton type="submit">Add item</NpdActionButton>
              </div>
            </div>
          </form>
        </NpdLuxPanel>
        <NpdLuxPanel title="Checklist" meta={`${checklist.length} item${checklist.length === 1 ? "" : "s"}`} icon="fe fe-check-square">
          {checklist.length === 0 ? (
            <LuxRegisterEmptyState title="No checklist items" description="Add launch checklist items for the selected idea." showCreate={false} />
          ) : (
            <div className="lux-module-table-wrap">
              <table className="table table-sm mb-0">
                <thead>
                  <tr>
                    <th>Ref</th>
                    <th>Title</th>
                    <th>Required</th>
                    <th>Status</th>
                    <th />
                  </tr>
                </thead>
                <tbody>
                  {checklist.map((c) => (
                    <tr key={c.itemRef}>
                      <td>{c.itemRef}</td>
                      <td>{c.title}</td>
                      <td>{c.required ? "Yes" : "No"}</td>
                      <td>
                        <span className={`lux-expansion-status is-${String(c.status || "open").toLowerCase()}`}>
                          {c.status || "Open"}
                        </span>
                      </td>
                      <td>
                        {c.status === "OPEN" && (
                          <NpdActionButton
                            type="button"
                            variant="secondary"
                            className="lux-onb-action--compact"
                            onClick={() => this.complete(c.itemRef)}
                          >
                            Complete
                          </NpdActionButton>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </NpdLuxPanel>
      </NpdLuxPage>
    );
  }
}

export default NpdLaunchPage;
