async function getHomeDashboardFromApi(activePersona) {
  const response = await axiosUtils.getWithParam(
    `${urlConfig.WORKSPACE_API_PATH}/home`,
    workspaceTeamQuery({ activePersona: activePersona || undefined })
  );
  const raw = (response && response.payload) || response || {};
  if (raw.metrics && raw.insights) {
    return { payload: raw, source: "api" };
  }
  // Incomplete API payload — fail closed rather than inventing client metrics.
  return { payload: null, source: "api-error", reason: "incomplete-home-payload" };
}

async function getHomeDashboard(activePersona) {
  if (envconfig.USE_WORKSPACE_HOME_API !== true) {
    return { payload: null, source: "api-error", reason: "workspace-home-api-disabled" };
  }

  try {
    return await getHomeDashboardFromApi(activePersona);
  } catch (e) {
    return { payload: null, source: "api-error", error: e };
  }
}

async function getDailyBriefingFromApi(activePersona) {
  const response = await axiosUtils.getWithParam(
    `${urlConfig.WORKSPACE_API_PATH}/daily-briefing`,
    workspaceTeamQuery({ activePersona: activePersona || undefined })
  );
  const payload = (response && response.payload) || response || null;
  return { payload, source: "api" };
}

async function getDailyBriefing(activePersona) {

  if (shouldUseWorkspaceHomeApi()) {
    try {
      return await getDailyBriefingFromApi(activePersona);
    } catch (e) {
      // fall through — caller shows Unavailable
    }
  }

  return { payload: null, source: "unavailable" };
}

async function listFavorites() {

  if (shouldUseWorkspaceHomeApi()) {
    try {
      const response = await axiosUtils.getWithParam(
        `${urlConfig.WORKSPACE_API_PATH}/favorites`,
        workspaceTeamQuery()
      );
      const payload = ((response && response.payload) || response || []).map(normalizeFavorite).filter(Boolean);
      return { payload, source: "api" };
    } catch (e) {
      return apiErrorResult([]);
    }
  }
  return apiErrorResult([]);
}

async function addFavorite(entry) {
  if (shouldUseWorkspaceHomeApi()) {
    try {
      const response = await axiosUtils.post(
        `${urlConfig.WORKSPACE_API_PATH}/favorites?${workspaceTeamQueryString()}`,
        entry
      );
      const payload = normalizeFavorite((response && response.payload) || response || entry);
      recordWorkspaceAudit(AUDIT_ACTION_TYPES.CREATED, "Favorite added", entry && entry.path, {
        label: entry && entry.label,
      });
      return { payload, source: "api" };
    } catch (e) {
      return apiErrorResult(null);
    }
  }
  return apiErrorResult(null);
}

async function removeFavorite(path) {
  if (shouldUseWorkspaceHomeApi()) {
    try {
      await axiosUtils.remove(
        `${urlConfig.WORKSPACE_API_PATH}/favorites?${workspaceTeamQueryString({ path })}`
      );
      recordWorkspaceAudit(AUDIT_ACTION_TYPES.DELETED, "Favorite removed", path);
      return { payload: { path }, source: "api" };
    } catch (e) {
      return apiErrorResult({ path });
    }
  }
  return apiErrorResult({ path });
}

async function listSavedViews(surface) {

  if (shouldUseWorkspaceHomeApi()) {
    try {
      const response = await axiosUtils.getWithParam(`${urlConfig.WORKSPACE_API_PATH}/saved-views`, {
        ...workspaceTeamQuery(),
        surface: surface || undefined,
      });
      const payload = ((response && response.payload) || response || [])
        .map(normalizeSavedView)
        .filter(Boolean);
      return { payload, source: "api" };
    } catch (e) {
      return apiErrorResult([]);
    }
  }
  return apiErrorResult([]);
}

async function createSavedView(entry) {
  if (shouldUseWorkspaceHomeApi()) {
    try {
      const response = await axiosUtils.post(
        `${urlConfig.WORKSPACE_API_PATH}/saved-views?${workspaceTeamQueryString()}`,
        entry
      );
      const payload = normalizeSavedView((response && response.payload) || response || entry);
      recordWorkspaceAudit(AUDIT_ACTION_TYPES.CREATED, "Saved view created", payload && payload.id, {
        surface: payload && payload.surface,
        name: payload && payload.name,
      });
      return { payload, source: "api" };
    } catch (e) {
      return apiErrorResult(null);
    }
  }
  return apiErrorResult(null);
}

async function deleteSavedView(viewId) {
  if (shouldUseWorkspaceHomeApi()) {
    try {
      await axiosUtils.remove(
        `${urlConfig.WORKSPACE_API_PATH}/saved-views/${viewId}?${workspaceTeamQueryString()}`
      );
      recordWorkspaceAudit(AUDIT_ACTION_TYPES.DELETED, "Saved view deleted", viewId);
      return { payload: { id: viewId }, source: "api" };
    } catch (e) {
      return apiErrorResult({ id: viewId });
    }
  }
  return apiErrorResult({ id: viewId });
}

function recordWorkspaceAudit(actionType, headline, entityRef, metadata) {
  recordAuditEvent({
    actionType,
    entityType: AUDIT_ENTITY_TYPES.WORKSPACE,
    entityRef: entityRef || headline,
    headline,
    metadata,
  });
}
