import React, { Component } from "react";
import { PersonaContext } from "context/PersonaContextProvider";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { onboardingService } from "_services/onboarding.service";
import { isOffboardingRouteEnabled, OFFBOARDING_STATUSES } from "config/onboarding.config";
import {
  buildOffboardingQueueMetrics,
  filterCasesByDepartment,
  filterCasesByStatus,
} from "config/onboarding.utils";
import LifecycleQueueSummary from "views/people/components/onboarding/LifecycleQueueSummary";
import LifecycleFilterBar from "views/people/components/onboarding/LifecycleFilterBar";
import LifecycleCaseCardGrid from "views/people/components/onboarding/LifecycleCaseCardGrid";
import LifecycleActionLink from "views/people/components/onboarding/LifecycleActionLink";
import CreateOffboardingCasePanel from "views/people/components/onboarding/CreateOffboardingCasePanel";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import { PeopleActionButton } from "views/people/components/PeopleLuxShared";
import { OFFBOARDING_PAGE_META } from "config/people-module-nav.config";

class OffboardingPage extends Component {
  static contextType = PersonaContext;

  state = {
    cases: [],
    loading: true,
    loadError: null,
    statusFilter: "ALL",
    departmentFilter: "ALL",
    createOpen: false,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Offboarding");
    this.loadCases();
  }

  loadCases = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const res = await onboardingService.listOffboardingCases();
      this.setState({ cases: res.payload || [], loading: false });
    } catch (_e) {
      this.setState({ loading: false, loadError: "Unable to load offboarding queue." });
    }
  };

  handleStatusChange = (statusFilter) => {
    this.setState({ statusFilter });
  };

  handleDepartmentChange = (departmentFilter) => {
    this.setState({ departmentFilter });
  };

  getFilteredCases = () => {
    const { cases, statusFilter, departmentFilter } = this.state;
    return filterCasesByDepartment(
      filterCasesByStatus(cases, statusFilter),
      departmentFilter
    );
  };

  getDepartments = () => {
    const { cases } = this.state;
    return [...new Set(cases.map((item) => item.department).filter(Boolean))].sort();
  };

  render() {
    const personaCtx = this.context || {};
    if (!isOffboardingRouteEnabled(personaCtx.menuAccessControl)) {
      return (
        <PersonaAccessDenied
          moduleName="Offboarding"
          reason="Offboarding is not enabled for your organization."
        />
      );
    }

    const { loading, loadError, statusFilter, departmentFilter } = this.state;
    const filtered = this.getFilteredCases();
    const metrics = buildOffboardingQueueMetrics(this.state.cases);

    return (
      <div className="lux-onb-page lux-register-page lux-people-page" data-testid="page-offboarding">
        <PageDataSourceReporter dataSource="api" />
        <LuxModuleIntro
                  meta={OFFBOARDING_PAGE_META}
                  actions={
                    <>
                      <PeopleActionButton to="/people/offboarding/templates" variant="ghost" icon="fe fe-layers">
                        Templates
                      </PeopleActionButton>
                      <PeopleActionButton variant="primary" icon="fe fe-user-x" onClick={() => this.setState({ createOpen: true })}>
                        Start exit case
                      </PeopleActionButton>
                    </>
                  }
                />

        <div className="lux-register-page__body">
        <LifecycleQueueSummary
          lifecycle="offboarding"
          metrics={metrics}
          loading={loading}
          cases={filtered}
        />

        {loadError && (
          <div className="lux-onb-page__error" role="alert">{loadError}</div>
        )}

        <LifecycleFilterBar
          statusFilter={statusFilter}
          departmentFilter={departmentFilter}
          statusOptions={OFFBOARDING_STATUSES}
          departments={this.getDepartments()}
          onStatusChange={this.handleStatusChange}
          onDepartmentChange={this.handleDepartmentChange}
          resultCount={filtered.length}
        />

        <section className="lux-hrms-dash__panel lux-onb-queue-panel">
          <header className="lux-hrms-dash__panel-head">
            <div>
              <h2 className="lux-hrms-dash__panel-title">Exit cases</h2>
              <p className="lux-hrms-dash__panel-sub">
                Review settlement blockers, access revocation, and asset returns.
              </p>
            </div>
            <div className="lux-hrms-dash__panel-actions">
              <LifecycleActionLink
                to="/people/offboarding/templates"
                variant="ghost"
                icon="fe-layers"
              >
                Exit templates
              </LifecycleActionLink>
              <LifecycleActionLink
                variant="primary"
                icon="fe-user-x"
                onClick={() => this.setState({ createOpen: true })}
              >
                Start exit case
              </LifecycleActionLink>
            </div>
          </header>
          <div className="lux-hrms-dash__panel-body">
            <LifecycleCaseCardGrid cases={filtered} loading={loading} lifecycle="offboarding" />
            {!loading && !filtered.length && !loadError && (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact lux-onb-empty"
                icon="fe fe-user-x"
                title="No offboarding cases"
                description="Create an exit checklist when an employee separation is confirmed."
              />
            )}
          </div>
        </section>

        <CreateOffboardingCasePanel
          open={this.state.createOpen}
          onClose={() => this.setState({ createOpen: false })}
          onCreated={this.loadCases}
        />
        </div>
      </div>
    );
  }
}

export default OffboardingPage;
