/**
 * Feature enablement is always Application Config (org) + role RBAC.
 * REACT_APP_* pilot flags are ignored — they must not OR-enable over org/role.
 */
export function isDevEnvPilotEnabled(_envFlag) {
  return false;
}

/** Always org Application Config; env pilots do not OR-enable. */
export function resolveDevEnvOrOrg(_envFlag, orgEnabled) {
  return orgEnabled === true;
}
