import React from "react";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

function formatUsd(value) {
  return `$${Number(value || 0).toLocaleString()}`;
}

function ExpenseAnalyticsPanel({ categoryBreakdown = [], agingSeries = [], loading }) {
  if (loading) {
    return <div className="lux-expense-analytics__skeleton" aria-busy="true" />;
  }

  const totalSpend = categoryBreakdown.reduce((sum, row) => sum + (row.amountUsd || 0), 0);
  const totalAging = agingSeries.reduce((sum, bucket) => sum + (bucket.count || 0), 0);
  const hasData = categoryBreakdown.length > 0 || agingSeries.length > 0;

  if (!hasData) {
    return (
      <LuxRegisterEmptyState
        className="lux-register-empty--compact"
        title="No expense analytics"
        description="Category spend and approval aging will appear once claims enter the finance queue."
      />
    );
  }

  return (
    <div className="lux-expense-analytics">
      <div className="lux-expense-analytics__grid">
        <section className="lux-expense-analytics__card">
          <header className="lux-expense-analytics__card-head">
            <span className="lux-expense-analytics__card-icon is-green" aria-hidden="true">
              <i className="fe fe-pie-chart" />
            </span>
            <div>
              <h3>Spend by category</h3>
              <p>{formatUsd(totalSpend)} total in scope</p>
            </div>
          </header>
          <ul className="lux-expense-analytics__list">
            {categoryBreakdown.map((row) => {
              const pct = totalSpend ? Math.round(((row.amountUsd || 0) / totalSpend) * 100) : 0;
              return (
                <li key={row.category}>
                  <div className="lux-expense-analytics__list-copy">
                    <span>{row.category}</span>
                    <div className="lux-expense-analytics__bar">
                      <span style={{ width: `${pct}%` }} />
                    </div>
                  </div>
                  <strong>{formatUsd(row.amountUsd)}</strong>
                </li>
              );
            })}
          </ul>
        </section>
        <section className="lux-expense-analytics__card">
          <header className="lux-expense-analytics__card-head">
            <span className="lux-expense-analytics__card-icon is-amber" aria-hidden="true">
              <i className="fe fe-clock" />
            </span>
            <div>
              <h3>Approval aging</h3>
              <p>{totalAging} claim{totalAging === 1 ? "" : "s"} awaiting action</p>
            </div>
          </header>
          <ul className="lux-expense-analytics__bars">
            {agingSeries.map((bucket) => (
              <li key={bucket.label}>
                <span>{bucket.label}</span>
                <div className="lux-expense-analytics__bar">
                  <span style={{ width: `${Math.min(100, bucket.count * 20)}%` }} />
                </div>
                <strong>{bucket.count}</strong>
              </li>
            ))}
          </ul>
        </section>
      </div>
    </div>
  );
}

export default ExpenseAnalyticsPanel;
