import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import dateUtils from "_helpers/date.utils";
import moment from "moment";

const PRESETS = [
  { key: "today", label: "Today" },
  { key: "week", label: "This week" },
  { key: "last7", label: "Last 7 days" },
  { key: "deliverable", label: "Deliverable range" },
  { key: "month", label: "This month" },
];

function rangeForPreset(key, taskInfo) {
  const now = dateUtils.getCurrentTime();
  switch (key) {
    case "today":
      return { startDateMoment: now.clone().startOf("day"), endDateMoment: now.clone().endOf("day") };
    case "week":
      return {
        startDateMoment: now.clone().startOf("week"),
        endDateMoment: now.clone().endOf("week"),
      };
    case "last7":
      return {
        startDateMoment: now.clone().subtract(6, "days").startOf("day"),
        endDateMoment: now.clone().endOf("day"),
      };
    case "month":
      return {
        startDateMoment: now.clone().startOf("month"),
        endDateMoment: now.clone().endOf("month"),
      };
    case "deliverable":
      if (taskInfo) {
        return {
          startDateMoment: taskInfo.estStartTime
            ? dateUtils.convertDateStringToMoment(taskInfo.estStartTime)
            : now.clone().subtract(30, "days"),
          endDateMoment: taskInfo.estCompletionTime
            ? dateUtils.convertDateStringToMoment(taskInfo.estCompletionTime)
            : now.clone().add(30, "days"),
        };
      }
      return rangeForPreset("last7", null);
    default:
      return rangeForPreset("week", null);
  }
}

export default class LuxWorkItemDateToolbar extends PureComponent {
  getActivePreset = () => {
    const { dateRange, activePreset } = this.props;
    if (activePreset) return activePreset;
    if (!dateRange || !dateRange.startDateMoment || !dateRange.endDateMoment) return "week";
    return "custom";
  };

  formatRangeLabel = () => {
    const { dateRange } = this.props;
    if (!dateRange || !dateRange.startDateMoment || !dateRange.endDateMoment) {
      return "Select a date range";
    }
    const start = moment(dateRange.startDateMoment).format("MMM D, YYYY");
    const end = moment(dateRange.endDateMoment).format("MMM D, YYYY");
    if (start === end) return start;
    return `${start} – ${end}`;
  };

  applyPreset = (key) => {
    const range = rangeForPreset(key, this.props.taskInfo);
    if (this.props.onRangeChange) {
      this.props.onRangeChange(range, key);
    }
  };

  render() {
    const active = this.getActivePreset();

    return (
      <section className="lux-workitem-date-toolbar" aria-label="Work item date range">
        <div className="lux-workitem-date-toolbar__main">
          <span className="lux-workitem-date-toolbar__icon" aria-hidden="true">
            <i className="fe fe-calendar" />
          </span>
          <div className="lux-workitem-date-toolbar__copy">
            <span className="lux-workitem-date-toolbar__eyebrow">Date range</span>
            <strong className="lux-workitem-date-toolbar__value">{this.formatRangeLabel()}</strong>
          </div>
        </div>
        <div className="lux-workitem-date-toolbar__presets" role="group" aria-label="Quick ranges">
          {PRESETS.map((preset) => (
            <button
              key={preset.key}
              type="button"
              className={classNames("lux-workitem-date-toolbar__chip", {
                "is-active": active === preset.key,
              })}
              onClick={() => this.applyPreset(preset.key)}
            >
              {preset.label}
            </button>
          ))}
        </div>
      </section>
    );
  }
}

export { rangeForPreset };
