import React, { Component } from "react";
import ProjectDetailsTabShell from "views/project/components/ProjectDetailsTabShell";
import AuditTrailSection from "views/common/fragments/AuditTrailSection";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxSegmentNav from "views/common/fragments/LuxSegmentNav";
import { AUDIT_ENTITY_TYPES, AUDIT_SCOPES } from "_constants/audit.constants";
import { commonUtils } from "_helpers";
import { taskService } from "_services/task.service";
import { isAuditUiEnabled } from "_helpers/audit.config";

const PANEL_VIEWS = {
  NOTES: "notes",
  AUDIT: "audit",
};

function formatNoteWhen(note) {
  if (!note) {
    return "—";
  }
  return note.when || note.createdAt || note.updatedAt || "—";
}

export default class Employee360ActivityTab extends Component {
  state = {
    activePanel: PANEL_VIEWS.NOTES,
    personalNotes: [],
    notesLoading: false,
    notesError: null,
  };

  componentDidMount() {
    this.loadPersonalNotesIfSelf();
  }

  componentDidUpdate(prevProps) {
    if (prevProps.employee && prevProps.employee.id !== (this.props.employee && this.props.employee.id)) {
      this.loadPersonalNotesIfSelf();
    }
  }

  isSelfView = () => {
    const employeeId = this.props.employee && this.props.employee.id;
    const viewerId = commonUtils.getCurrentUserId();
    return employeeId && viewerId && String(employeeId) === String(viewerId);
  };

  loadPersonalNotesIfSelf = async () => {
    if (!this.isSelfView()) {
      this.setState({ personalNotes: [], notesLoading: false, notesError: null });
      return;
    }

    const employeeId = this.props.employee.id;
    const end = new Date();
    const start = new Date();
    start.setDate(start.getDate() - 90);

    const formatApiDate = (date) =>
      `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}T00:00:00`;

    this.setState({ notesLoading: true, notesError: null });
    try {
      const response = await taskService.listNotes({
        employeeId,
        currentEmployeeId: employeeId,
        startDate: formatApiDate(start),
        endDate: formatApiDate(end),
      });
      const payload = response && response.payload ? response.payload : response;
      const items = Array.isArray(payload) ? payload : (payload && payload.items) || [];
      this.setState({ personalNotes: items.slice(0, 20), notesLoading: false });
    } catch (e) {
      this.setState({
        notesLoading: false,
        notesError: "Unable to load personal notes.",
        personalNotes: [],
      });
    }
  };

  setPanel = (activePanel) => {
    this.setState({ activePanel });
  };

  renderPanelTabs = () => {
    const { activePanel } = this.state;
    return (
      <LuxSegmentNav
        items={[
          { id: PANEL_VIEWS.NOTES, label: "Notes", icon: "fe fe-edit-3" },
          { id: PANEL_VIEWS.AUDIT, label: "Audit trail", icon: "fe fe-shield" },
        ]}
        activeId={activePanel}
        onChange={this.setPanel}
        ariaLabel="Employee activity views"
        tabList
        testId="employee-360-activity-nav"
      />
    );
  };

  renderNotesList = () => {
    const { summary } = this.props;
    const { personalNotes, notesLoading, notesError } = this.state;
    const hrNotes = (summary && summary.recentNotes) || [];
    const notes = this.isSelfView()
      ? [...hrNotes, ...personalNotes]
      : hrNotes;

    if (notesLoading) {
      return (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact"
          icon="fe fe-loader"
          title="Loading notes"
          description="Fetching recent notes for this employee."
        />
      );
    }

    if (notesError && notes.length === 0) {
      return (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact"
          icon="fe fe-alert-circle"
          title="Notes unavailable"
          description={notesError}
        />
      );
    }

    if (notes.length === 0) {
      return (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact lux-employee-360__activity-empty"
          icon="fe fe-edit-3"
          title="No notes yet"
          description={
            this.isSelfView()
              ? "Personal workspace notes and HR notes will appear here when available."
              : "Notes and HR activity for this employee will appear here when recorded."
          }
        />
      );
    }

    return (
      <ul className="lux-employee-360__notes-list">
        {notes.map((note) => (
          <li key={note.id || `${note.title}-${formatNoteWhen(note)}`} className="lux-employee-360__note">
            <div className="lux-employee-360__note-head">
              <strong>{note.title || note.subject || "Note"}</strong>
              <span>{formatNoteWhen(note)}</span>
            </div>
            {(note.body || note.description || note.text) && (
              <p>{note.body || note.description || note.text}</p>
            )}
            {note.author && <span className="lux-employee-360__note-author">{note.author}</span>}
          </li>
        ))}
      </ul>
    );
  };

  render() {
    const { employee } = this.props;
    const { activePanel } = this.state;
    if (!employee || !employee.id) {
      return null;
    }

    const auditEnabled = isAuditUiEnabled();

    return (
      <ProjectDetailsTabShell
        icon="fe fe-activity"
        eyebrow="Activity"
        title="Notes & audit timeline"
        subtitle="HR notes, personal reminders (self view), and compliance audit events for this employee."
        stats={[
          {
            key: "employee",
            label: "Employee",
            value: employee.empCode || employee.id,
          },
          {
            key: "audit",
            label: "Audit UI",
            value: auditEnabled ? "Enabled" : "Off",
          },
        ]}
      >
        <div className="lux-pd-tab__panel">
          {this.renderPanelTabs()}

          {activePanel === PANEL_VIEWS.NOTES && this.renderNotesList()}

          {activePanel === PANEL_VIEWS.AUDIT && (
            <AuditTrailSection
              scope={AUDIT_SCOPES.ENTITY}
              entityType={AUDIT_ENTITY_TYPES.EMPLOYEE}
              entityId={employee.id}
              eyebrow="Compliance"
              title="Employee audit trail"
              subtitle="Profile changes, approvals, and HR actions recorded for this employee."
              showEntityFilters={false}
              emptyState={{
                eyebrow: "Employee audit",
                title: "No audit events for this employee",
                description:
                  "Profile updates, leave actions, and approval events will appear here when audit logging is active.",
                hints: [
                  "Events are grouped by day with actor metadata",
                  "Sensitive fields are redacted per persona policy",
                  "Export is available from admin audit views",
                ],
              }}
            />
          )}
        </div>
      </ProjectDetailsTabShell>
    );
  }
}
