import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";

/**
 * Luxury pill segment nav — shared masthead and in-panel tab strip.
 * Uses lux-admin-hub-tabs styling (matches developer/workflow hub tabs).
 */
export default function LuxSegmentNav({
  items = [],
  activeId,
  onChange,
  ariaLabel = "Section",
  className,
  testId,
  tabList = false,
}) {
  if (!items.length) {
    return null;
  }

  const navProps = {
    className: classNames("lux-admin-hub-tabs", className),
    "aria-label": ariaLabel,
    "data-testid": testId || undefined,
  };
  if (tabList) {
    navProps.role = "tablist";
  }

  return (
    <nav {...navProps}>
      {items.map((item) => {
        const key = item.id || item.path || item.label;
        const active = activeId === (item.id || item.path);
        const badge = item.badge != null ? item.badge : item.count;
        const showBadge = badge != null && (item.showZeroBadge || Number(badge) > 0);
        const content = (
          <>
            {item.icon ? <i className={item.icon} aria-hidden="true" /> : null}
            <span>{item.label}</span>
            {showBadge ? (
              <span className="lux-segment-nav__badge">{badge}</span>
            ) : null}
          </>
        );

        if (onChange) {
          const buttonProps = {
            key,
            type: "button",
            className: classNames("lux-admin-hub-tabs__tab", { "is-active": active }),
            onClick: () => onChange(item.id),
          };
          if (tabList) {
            buttonProps.role = "tab";
            buttonProps["aria-selected"] = active;
          } else if (active) {
            buttonProps["aria-current"] = "page";
          }
          return (
            <button {...buttonProps}>
              {content}
            </button>
          );
        }

        if (!item.path) {
          return null;
        }

        return (
          <Link
            key={key}
            to={item.path}
            className={classNames("lux-admin-hub-tabs__tab", { "is-active": active })}
            aria-current={active ? "page" : undefined}
          >
            {content}
          </Link>
        );
      })}
    </nav>
  );
}
