import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import {
  readSummaryExpanded,
  writeSummaryExpanded,
  getSummaryToggleLabel,
} from "_helpers/summaryExpandedStorage";
import LifecycleCaseHero from "./LifecycleCaseHero";
import LifecycleInsightStrip from "./LifecycleInsightStrip";

function getStorageKey(lifecycle) {
  return lifecycle === "offboarding"
    ? "famstack-offboarding-case-summary-expanded"
    : "famstack-onboarding-case-summary-expanded";
}

function buildCollapsedLine(caseData, progress, lifecycle) {
  if (!caseData) return "";
  const name = lifecycle === "offboarding" ? caseData.employeeName : caseData.candidateName;
  const pct = caseData.readinessPct || 0;
  const taskLine = progress
    ? `${progress.completed}/${progress.total} tasks complete`
    : "tasks pending";
  return `${name} · ${pct}% ready · ${taskLine}`;
}

class LifecycleCaseSummary extends PureComponent {
  constructor(props) {
    super(props);
    const lifecycle = props.lifecycle || "onboarding";
    this.state = {
      expanded: readSummaryExpanded(getStorageKey(lifecycle)),
    };
  }

  toggleExpanded = () => {
    const lifecycle = this.props.lifecycle || "onboarding";
    this.setState(
      (prev) => ({ expanded: !prev.expanded }),
      () => writeSummaryExpanded(getStorageKey(lifecycle), this.state.expanded)
    );
  };

  render() {
    const { caseData, loading, lifecycle = "onboarding", progress } = this.props;
    const { expanded } = this.state;
    const isOffboarding = lifecycle === "offboarding";
    const collapsedLine = buildCollapsedLine(caseData, progress, lifecycle);

    return (
      <section
        className={classNames("lux-onb-summary lux-onb-summary--case", { "is-collapsed": !expanded })}
        aria-label={isOffboarding ? "Offboarding case summary" : "Onboarding case summary"}
      >
        <div className="lux-onb-summary__header-bar">
          <div className="lux-onb-summary__header-main">
            <LuxSummaryEyebrow
              variant={isOffboarding ? "offboarding" : "onboarding"}
              className="lux-onb-summary__eyebrow"
            >
              {isOffboarding ? "Exit case intelligence" : "Onboarding case intelligence"}
            </LuxSummaryEyebrow>
            {!expanded ? (
              <h2 className="lux-onb-summary__title lux-onb-summary__title--compact">
                {loading ? (
                  "Loading…"
                ) : (
                  <>
                    <span>
                      {lifecycle === "offboarding" ? caseData.employeeName : caseData.candidateName}
                    </span>
                    <span> · {caseData.readinessPct || 0}% ready</span>
                  </>
                )}
              </h2>
            ) : (
              <h2 className="lux-onb-summary__title lux-onb-summary__title--bar">
                {isOffboarding ? "Exit checklist overview" : "Onboarding checklist overview"}
              </h2>
            )}
          </div>
          <button
            type="button"
            className="lux-onb-summary__toggle"
            onClick={this.toggleExpanded}
            aria-expanded={expanded}
            aria-controls="lux-onb-case-summary-body"
            title={expanded ? "Collapse summary" : "Insights"}
          >
            <span>{getSummaryToggleLabel(expanded)}</span>
            <i className={classNames("fe", expanded ? "fe-chevron-up" : "fe-chevron-down")} aria-hidden="true" />
          </button>
        </div>

        {!expanded && !loading && collapsedLine && (
          <div className="lux-onb-summary__collapsed-strip">
            <p className="lux-onb-summary__collapsed-line">{collapsedLine}</p>
          </div>
        )}

        <div
          id="lux-onb-case-summary-body"
          className="lux-onb-summary__body"
          aria-hidden={!expanded}
        >
          {this.props.includeHero !== false && (
            <LifecycleCaseHero caseData={caseData} loading={loading} lifecycle={lifecycle} />
          )}
          <LifecycleInsightStrip progress={progress} caseData={caseData} />
        </div>
      </section>
    );
  }
}

export default LifecycleCaseSummary;
