import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import { recordAuditEvent } from "config/audit-write.service";
import { AUDIT_ACTION_TYPES, AUDIT_ENTITY_TYPES } from "_constants/audit.constants";

export default function AnalyticsAiInsightPanel({ insight, source, onFeedback }) {
  if (!insight) return null;

  const confidence = Math.round((insight.confidence || 0) * 100);
  const sourceReferences = insight.sourceReferences || insight.sourceLinks || [];
  const drillPath = insight.drillPath;
  const insightSource = source || insight.source || null;

  const handleFeedback = (helpful) => {
    recordAuditEvent({
      actionType: AUDIT_ACTION_TYPES.AUDIT_UPDATED,
      entityType: AUDIT_ENTITY_TYPES.ADMIN_CONFIG,
      entityRef: `analytics-ai-insight-${insight.domain || "unknown"}`,
      metadata: { helpful, domain: insight.domain },
    });
    if (onFeedback) {
      onFeedback(helpful);
    }
  };

  let badge = null;
  if (insight.personaMaskingApplied) {
    badge = <span className="lux-analytics-ai__badge is-masked">Masked</span>;
  } else if (insightSource === "api") {
    badge = <span className="lux-analytics-ai__badge is-live">Live</span>;
  } else if (insightSource === "mock") {
    badge = <span className="lux-analytics-ai__badge">Demo</span>;
  } else {
    badge = <span className="lux-analytics-ai__badge">Unavailable</span>;
  }

  return (
    <section className="lux-analytics-ai">
      <header className="lux-analytics-ai__head">
        <div>
          <span className="lux-analytics-ai__kicker">
            <i className="fe fe-zap" aria-hidden="true" />
            AI analytics insight
          </span>
          <h4>{insight.summary}</h4>
        </div>
        {badge}
      </header>

      {insight.recommendation ? <p className="lux-analytics-ai__rec">{insight.recommendation}</p> : null}

      {insight.evidence && insight.evidence.length ? (
        <ul className="lux-analytics-ai__evidence">
          {insight.evidence.map((row) => (
            <li key={row}>{row}</li>
          ))}
        </ul>
      ) : null}

      {sourceReferences.length > 0 && (
        <div className="lux-analytics-ai__sources">
          <h5>Source references</h5>
          <ul>
            {sourceReferences.map((ref, index) => (
              <li key={`${ref.sourceEntityType}-${ref.sourceEntityId}-${index}`}>
                <code>{ref.sourceEntityType || "SOURCE"}</code>
                {ref.sourceEntityId ? ` #${ref.sourceEntityId}` : null}
                {ref.canonicalSource ? ` · ${ref.canonicalSource}` : null}
                {ref.owningEpic ? ` (${ref.owningEpic})` : null}
              </li>
            ))}
          </ul>
        </div>
      )}

      <div className="lux-analytics-ai__meta">
        <span
          className={classNames("lux-analytics-ai__confidence", {
            "is-high": confidence >= 75,
            "is-medium": confidence >= 50 && confidence < 75,
          })}
        >
          Confidence {confidence}%
        </span>
        {drillPath ? (
          <Link to={drillPath} className="lux-analytics-ai__drill">
            Drill into source dashboard
          </Link>
        ) : null}
      </div>

      <div className="lux-analytics-ai__feedback">
        <span>Was this helpful?</span>
        <button type="button" className="lux-onb-action lux-onb-action--success lux-onb-action--sm" onClick={() => handleFeedback(true)}>
          Yes
        </button>
        <button type="button" className="lux-onb-action lux-onb-action--ghost lux-onb-action--sm" onClick={() => handleFeedback(false)}>
          No
        </button>
      </div>

      {insight.disclaimer ? (
        <p className="lux-analytics-ai__disclaimer">{insight.disclaimer}</p>
      ) : null}
    </section>
  );
}
