import React from "react";
import { NavLink } from "react-router-dom";
import classNames from "classnames/bind";
import LuxBackNav from "views/common/fragments/LuxBackNav";
import { getDeliverableStatusMeta } from "./deliverableList.utils";

export default function DeliverableProjectContext({ projectInfo, isLoading }) {
  if (isLoading && !projectInfo) {
    return (
      <section className="lux-deliverable-context is-loading" aria-busy="true">
        <div className="lux-deliverable-context__skeleton" />
      </section>
    );
  }

  if (!projectInfo) return null;

  const statusMeta = getDeliverableStatusMeta(projectInfo.status);
  const ref = projectInfo.itemIdUserTeamPrefix || projectInfo.id;
  const projectDetailsPath = `/project/details/${ref}`;

  return (
    <section className="lux-deliverable-context" aria-label="Project context">
      <LuxBackNav
        component={NavLink}
        to={projectDetailsPath}
        destinationLabel="Project"
        currentLabel="Deliverables"
        navClassName="lux-deliverable-context__nav"
        aria-label="Breadcrumb"
      />

      <div className="lux-deliverable-context__body">
        <div className="lux-deliverable-context__icon" aria-hidden="true">
          <i className="fe fe-briefcase" />
        </div>
        <div className="lux-deliverable-context__copy">
          <span className="lux-deliverable-context__eyebrow">Project</span>
          <NavLink to={projectDetailsPath} className="lux-deliverable-context__title" title={projectInfo.name}>
            {projectInfo.name || ref}
            <i className="fe fe-arrow-up-right" aria-hidden="true" />
          </NavLink>
          <p className="lux-deliverable-context__meta">
            {projectInfo.teamName && <span>{projectInfo.teamName}</span>}
            {projectInfo.accountName && (
              <>
                {projectInfo.teamName && <span className="lux-deliverable-context__dot">·</span>}
                <span>{projectInfo.accountName}</span>
              </>
            )}
          </p>
        </div>
        <div className="lux-deliverable-context__aside">
          <span className={classNames("lux-deliverable-context__status", `is-${statusMeta.tone}`)}>
            {statusMeta.label}
          </span>
        </div>
      </div>
    </section>
  );
}
