import { axiosUtils } from "../_helpers";
import { commonUtils } from "../_helpers/common.utils";
import urlConfig from "url.config";
import {
  normalizeApprovalPolicy,
  normalizeApprovalPolicySimulation,
  normalizeStoredApprovalPolicy,
} from "config/approval-policy.config";

import { apiErrorResult } from "config/mock-fallback.utils";

export const approvalPolicyService = {
  listPolicies,
  savePolicy,
  updatePolicy,
  listStoredPolicies,
  simulateStoredDraft,
};

const STORED_POLICY_API_BASE = `${urlConfig.APPCONFIG_API_PATH}/work-time-governance/approval-policies`;

async function listPoliciesFromApi() {
  const response = await axiosUtils.getWithParam(`${urlConfig.APPROVALS_API_PATH}/policies`, {
    userTeamId: commonUtils.getCurrentUserTeamId(),
  });
  const rows = (response && response.payload) || response || [];
  const list = Array.isArray(rows) ? rows : [];
  return {
    payload: list.map((row) => normalizeApprovalPolicy(row)).filter(Boolean),
    source: "api",
  };
}

async function listPolicies() {
  try {
    return await listPoliciesFromApi();
  } catch (e) {
    return apiErrorResult([]);
  }
}

async function savePolicy(payload) {
  const userTeamId = commonUtils.getCurrentUserTeamId();
  const actorId = commonUtils.getCurrentUserId();
  const response = await axiosUtils.post(
    `${urlConfig.APPROVALS_API_PATH}/policies?userTeamId=${userTeamId}&actorId=${actorId}&adminPersona=true`,
    payload || {}
  );
  const row = (response && response.payload) || response;
  return {
    payload: normalizeApprovalPolicy(row),
    source: "api",
  };
}

async function updatePolicy(policyId, payload) {
  const userTeamId = commonUtils.getCurrentUserTeamId();
  const actorId = commonUtils.getCurrentUserId();
  const response = await axiosUtils.patch(
    `${urlConfig.APPROVALS_API_PATH}/policies/${encodeURIComponent(policyId)}?userTeamId=${userTeamId}&actorId=${actorId}&adminPersona=true`,
    payload || {}
  );
  const row = (response && response.payload) || response;
  return {
    payload: normalizeApprovalPolicy(row),
    source: "api",
  };
}

async function listStoredPolicies(filters = {}) {
  const query = { userTeamId: commonUtils.getCurrentUserTeamId() };
  if (filters.domain) {
    query.domain = filters.domain;
  }
  const response = await axiosUtils.getWithParam(STORED_POLICY_API_BASE, query);
  const rows = (response && response.payload) || response || [];
  return {
    payload: (Array.isArray(rows) ? rows : [])
      .map(normalizeStoredApprovalPolicy)
      .filter(Boolean),
    source: "api",
  };
}

async function simulateStoredDraft(storedDraftId, matchContext) {
  const draftId = Number(storedDraftId);
  const userTeamId = commonUtils.getCurrentUserTeamId();
  if (!Number.isSafeInteger(draftId) || draftId <= 0) {
    throw new Error("A valid stored draft is required for simulation.");
  }
  if (!matchContext || typeof matchContext !== "object" || Array.isArray(matchContext)) {
    throw new Error("A valid match context is required for simulation.");
  }
  if (String(matchContext.userTeamId) !== String(userTeamId)) {
    throw new Error("Simulation match context must use the current team.");
  }
  const response = await axiosUtils.post(
    `${STORED_POLICY_API_BASE}/simulate?userTeamId=${encodeURIComponent(userTeamId)}`,
    {
      storedDraftId: draftId,
      matchContext,
    }
  );
  const row = (response && response.payload) || response;
  return {
    payload: normalizeApprovalPolicySimulation(row),
    source: "api",
  };
}
