/**
 * F08-T10 — Payroll persona masking, export guards, and audit metadata helpers.
 */
import { resolveMaskedFieldValue, isFieldVisible } from "config/employee360-field.utils";
import { canExportField } from "config/persona-export.utils";
import { redactAuditMetadata } from "config/audit-write.utils";
import { formatPayrollCurrency } from "config/payroll.utils";

export const PAYROLL_SENSITIVE_FIELD_KEYS = {
  SALARY: "salary",
  BANK_ACCOUNT: "bankAccount",
  TAX_ID: "taxId",
  PAYROLL_LINES: "payrollLines",
  PAYROLL_GROUP: "payrollGroup",
  NET_PAY: "netPay",
  GROSS_PAY: "grossPay",
};

export const PAYROLL_ADMIN_PERSONAS = [
  "PAYROLL_MANAGER",
  "FINANCE_MANAGER",
  "HR_ADMIN",
  "ADMIN",
];

export function maskPayrollAmount(value, maskingPolicy, fieldKey) {
  if (value == null) {
    return "—";
  }
  const formatted = formatPayrollCurrency(value);
  const resolvedKey = fieldKey || PAYROLL_SENSITIVE_FIELD_KEYS.PAYROLL_LINES;
  return resolveMaskedFieldValue(resolvedKey, formatted, maskingPolicy);
}

export function maskPayrollLineRow(line, maskingPolicy) {
  if (!line) {
    return null;
  }
  const fieldKey = PAYROLL_SENSITIVE_FIELD_KEYS.PAYROLL_LINES;
  return {
    ...line,
    gross: maskPayrollAmount(line.gross, maskingPolicy, fieldKey),
    net: maskPayrollAmount(line.net, maskingPolicy, fieldKey),
    deductions:
      line.deductions != null ? maskPayrollAmount(line.deductions, maskingPolicy, fieldKey) : line.deductions,
  };
}

export function maskPayrollLines(lines, maskingPolicy) {
  return (lines || []).map((row) => maskPayrollLineRow(row, maskingPolicy));
}

export function maskSalaryStructureRow(row, maskingPolicy) {
  if (!row) {
    return null;
  }
  if (!isFieldVisible(PAYROLL_SENSITIVE_FIELD_KEYS.SALARY, maskingPolicy)) {
    return { ...row, baseSalary: "Restricted", annualCost: "Restricted" };
  }
  return {
    ...row,
    baseSalary: resolveMaskedFieldValue(
      PAYROLL_SENSITIVE_FIELD_KEYS.SALARY,
      row.baseSalary,
      maskingPolicy
    ),
    annualCost: resolveMaskedFieldValue(
      PAYROLL_SENSITIVE_FIELD_KEYS.SALARY,
      row.annualCost,
      maskingPolicy
    ),
  };
}

export function canExportPayrollField(activePersona, maskingPolicy, fieldKey) {
  return canExportField(activePersona, maskingPolicy, fieldKey);
}

export function filterPayrollExportColumns(activePersona, maskingPolicy, columns) {
  if (!Array.isArray(columns)) {
    return [];
  }
  return columns.filter((column) =>
    canExportPayrollField(activePersona, maskingPolicy, column.fieldKey || column.key)
  );
}

export function buildPayrollRunAuditMetadata(run, extras) {
  const base = {
    runId: run && run.id,
    runName: run && run.name,
    status: run && run.status,
    groupId: run && run.groupId,
    employeeCount: run && run.employeeCount,
    readinessScore: run && run.readinessScore,
  };
  return redactAuditMetadata(Object.assign(base, extras || {}));
}

export function sanitizePayrollExportRows(rows, maskingPolicy, activePersona) {
  return (rows || []).map((row) => {
    const sanitized = { ...row };
    Object.keys(PAYROLL_SENSITIVE_FIELD_KEYS).forEach((keyName) => {
      const fieldKey = PAYROLL_SENSITIVE_FIELD_KEYS[keyName];
      if (!canExportPayrollField(activePersona, maskingPolicy, fieldKey)) {
        if (sanitized[fieldKey] != null) {
          sanitized[fieldKey] = "[RESTRICTED]";
        }
        if (fieldKey === PAYROLL_SENSITIVE_FIELD_KEYS.PAYROLL_LINES) {
          sanitized.gross = "[RESTRICTED]";
          sanitized.net = "[RESTRICTED]";
          sanitized.deductions = "[RESTRICTED]";
        }
      }
    });
    return sanitized;
  });
}
