export function teamLabel(allTeams, userTeamId) {
  const t =
    allTeams &&
    allTeams.find((x) => String(x.id) === String(userTeamId) || x.id === userTeamId);
  return (t && t.name) || `Team ${userTeamId || "—"}`;
}

export function parseJoinMoment(val) {
  if (!val) return null;
  let m = moment(val, moment.ISO_8601, true);
  if (m.isValid()) return m;
  m = moment(val, dateUtils.CLIENT_DATE_FORMAT, true);
  if (m.isValid()) return m;
  m = moment(val);
  return m.isValid() ? m : null;
}

function countByTeam(activeEmployees, allTeams) {
  const map = {};
  activeEmployees.forEach((e) => {
    const key = e.userTeamId != null ? String(e.userTeamId) : "_none";
    map[key] = (map[key] || 0) + 1;
  });
  return Object.entries(map)
    .sort((a, b) => b[1] - a[1])
    .map(([id, count]) => ({
      id: id === "_none" ? null : id,
      label: id === "_none" ? "Unassigned" : teamLabel(allTeams, id),
      count,
    }));
}

export function buildTeamwiseStackSeries(activeEmployees, allTeams) {
  if (!activeEmployees.length) {
    return {
      categories: ["—"],
      series: [{ name: "Employees", data: [0] }],
      subtitle: "No employees loaded for this view",
    };
  }

  const months = [];
  for (let i = 5; i >= 0; i -= 1) {
    const mm = moment().subtract(i, "months").startOf("month");
    months.push({ label: mm.format("MMM YY"), y: mm.year(), m: mm.month() });
  }

  const ranked = countByTeam(activeEmployees, allTeams);
  const top = ranked.slice(0, 4).map((r) => r.id);
  const topSet = new Set(top.map((id) => (id != null ? String(id) : "")));

  function bucketTeam(uid) {
    const k = uid != null ? String(uid) : "";
    if (topSet.has(k)) return k;
    return "__other__";
  }

  const seriesKeys = [...top.filter((id) => id != null), "__other__"];
  const seriesNames = seriesKeys.map((key) =>
    key === "__other__" ? "Other" : teamLabel(allTeams, key)
  );

  let hireTotal = 0;
  const series = seriesKeys.map((teamKey, idx) => ({
    name: seriesNames[idx],
    data: months.map(({ y, m }) => {
      const n = activeEmployees.filter((e) => {
        const dj = parseJoinMoment(e.dateOfJoin);
        if (!dj) return false;
        return dj.year() === y && dj.month() === m && bucketTeam(e.userTeamId) === teamKey;
      }).length;
      hireTotal += n;
      return n;
    }),
  }));

  if (hireTotal === 0) {
    const head = ranked.slice(0, 6);
    const sumOther = ranked.slice(6).reduce((s, r) => s + r.count, 0);
    let stackSeries =
      sumOther > 0
        ? [
            ...head.map((r) => ({ name: r.label, data: [r.count] })),
            { name: "Other", data: [sumOther] },
          ]
        : head.map((r) => ({ name: r.label, data: [r.count] }));
    if (!stackSeries.length) stackSeries = [{ name: "Employees", data: [0] }];
    return {
      categories: ["Active employees"],
      series: stackSeries,
      subtitle: "Headcount by team (no hires in the last 6 months)",
    };
  }

  return {
    categories: months.map((x) => x.label),
    series,
    subtitle: "New hires by team (join date in month)",
  };
}

export function buildDonutLocation(activeEmployees, allTeams) {
  if (!activeEmployees.length) return { labels: ["No employees"], series: [1] };

  const ranked = countByTeam(activeEmployees, allTeams).slice(0, 6);
  const taken = ranked.reduce((s, r) => s + r.count, 0);
  const other = Math.max(0, activeEmployees.length - taken);
  const labels = ranked.map((r) => r.label);
  const series = ranked.map((r) => r.count);
  if (other > 0) {
    labels.push("Other teams");
    series.push(other);
  }
  return { labels, series };
}

export function buildPieEmpTypes(activeEmployees) {
  if (!activeEmployees.length) return { labels: ["—"], series: [1] };

  const types = {};
  activeEmployees.forEach((e) => {
    const t = e.empType || "Other";
    types[t] = (types[t] || 0) + 1;
  });
  const entries = Object.entries(types).sort((a, b) => b[1] - a[1]);
  return { labels: entries.map(([k]) => k), series: entries.map(([, v]) => v) };
}

export function buildGenderByTeam(activeEmployees, allTeams) {
  if (!activeEmployees.length) {
    return {
      series: [
        { name: "Male", data: [0] },
        { name: "Female", data: [0] },
        { name: "Other / undeclared", data: [0] },
      ],
      categories: ["—"],
    };
  }

  const ranked = countByTeam(activeEmployees, allTeams).slice(0, 10);
  const matchesTeam = (e, teamId) => {
    const eu = e.userTeamId;
    if (teamId == null || teamId === "") return eu == null || eu === "";
    return String(eu) === String(teamId);
  };

  const male = ranked.map((r) =>
    activeEmployees.filter(
      (e) => matchesTeam(e, r.id) && (e.gender || "").toLowerCase() === "male"
    ).length
  );
  const female = ranked.map((r) =>
    activeEmployees.filter(
      (e) => matchesTeam(e, r.id) && (e.gender || "").toLowerCase() === "female"
    ).length
  );
  const other = ranked.map((r, i) => Math.max(0, r.count - male[i] - female[i]));

  return {
    series: [
      { name: "Male", data: male },
      { name: "Female", data: female },
      { name: "Other / undeclared", data: other },
    ],
    categories: ranked.map((r) => r.label),
  };
}

export function buildDivisionDesignations(activeEmployees, limit = 6) {
  const map = {};
  activeEmployees.forEach((e) => {
    const d = (e.designation && String(e.designation).trim()) || "Unassigned";
    map[d] = (map[d] || 0) + 1;
  });
  const total = activeEmployees.length || 1;
  return Object.entries(map)
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit)
    .map(([name, count]) => ({
      name,
      count,
      pct: Math.round((count / total) * 100),
    }));
}

export function buildRecentJoiners(employees, limit = 6) {
  return [...employees]
    .filter((e) => e.active && parseJoinMoment(e.dateOfJoin))
    .sort((a, b) => parseJoinMoment(b.dateOfJoin) - parseJoinMoment(a.dateOfJoin))
    .slice(0, limit)
    .map((e) => ({
      id: e.id,
      name: e.name,
      designation: e.designation || "—",
      teamId: e.userTeamId,
      joinDate: parseJoinMoment(e.dateOfJoin).format("DD MMM YYYY"),
      empType: e.empType || "—",
    }));
}

export function buildWorkforceAlerts(allEmployees, activeEmployees) {
  const alerts = [];
  const inactive = allEmployees.length - activeEmployees.length;
  if (inactive > 0) {
    alerts.push({
      tone: "amber",
      icon: "fe-user-x",
      title: `${inactive} inactive profile${inactive === 1 ? "" : "s"}`,
      detail: "Review deactivated accounts and exit records.",
    });
  }

  const missingDesignation = activeEmployees.filter((e) => !e.designation).length;
  if (missingDesignation > 0) {
    alerts.push({
      tone: "blue",
      icon: "fe-briefcase",
      title: `${missingDesignation} missing designation`,
      detail: "Complete job titles for accurate org reporting.",
    });
  }

  const missingGender = activeEmployees.filter((e) => !e.gender).length;
  if (missingGender > 0) {
    alerts.push({
      tone: "slate",
      icon: "fe-users",
      title: `${missingGender} incomplete diversity fields`,
      detail: "Gender data helps diversity and compliance reporting.",
    });
  }

  const cutoff90 = moment().subtract(90, "days");
  const probation = activeEmployees.filter((e) => {
    const join = parseJoinMoment(e.dateOfJoin);
    return join && join.isAfter(cutoff90);
  }).length;
  if (probation > 0) {
    alerts.push({
      tone: "green",
      icon: "fe-flag",
      title: `${probation} in first 90 days`,
      detail: "New hires may need onboarding or probation review.",
    });
  }

  if (!alerts.length) {
    alerts.push({
      tone: "green",
      icon: "fe-check-circle",
      title: "Workforce data looks healthy",
      detail: "No critical profile gaps detected in the current roster.",
    });
  }

  return alerts;
}

