function countByField(employees, getKey, limit = 8) {
  const map = {};
  employees.forEach((e) => {
    const raw = getKey(e);
    const key =
      raw == null || String(raw).trim() === "" ? "Unspecified" : String(raw).trim();
    map[key] = (map[key] || 0) + 1;
  });
  const total = employees.length || 1;
  return Object.entries(map)
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit)
    .map(([label, count]) => ({
      label,
      count,
      pct: Math.round((count / total) * 100),
    }));
}

export function buildSkillDistribution(activeEmployees, limit = 10) {
  return countByField(activeEmployees, (e) => e.primarySkill, limit);
}

export function buildDepartmentDistribution(activeEmployees, allTeams, limit = 10) {
  return countByField(
    activeEmployees,
    (e) =>
      e.department && String(e.department).trim()
        ? e.department
        : teamLabel(allTeams, e.userTeamId),
    limit
  );
}

export function buildBandDistribution(activeEmployees, limit = 8) {
  return countByField(activeEmployees, (e) => e.band, limit);
}

export function buildLocationDistribution(activeEmployees, limit = 8) {
  return countByField(activeEmployees, (e) => e.location, limit);
}

export function buildEmpTypeDetailed(activeEmployees) {
  return countByField(activeEmployees, (e) => e.empType || "Other", 8);
}

export function buildGenderDistribution(activeEmployees) {
  const male = activeEmployees.filter((e) => (e.gender || "").toLowerCase() === "male").length;
  const female = activeEmployees.filter((e) => (e.gender || "").toLowerCase() === "female").length;
  const other = Math.max(0, activeEmployees.length - male - female);
  const labels = [];
  const series = [];
  if (male) {
    labels.push("Male");
    series.push(male);
  }
  if (female) {
    labels.push("Female");
    series.push(female);
  }
  if (other) {
    labels.push("Other / undeclared");
    series.push(other);
  }
  if (!labels.length) return { labels: ["—"], series: [0] };
  return { labels, series };
}

export function buildTenureBuckets(activeEmployees) {
  const buckets = [
    { label: "< 1 yr", min: 0, max: 12, count: 0 },
    { label: "1–3 yrs", min: 12, max: 36, count: 0 },
    { label: "3–5 yrs", min: 36, max: 60, count: 0 },
    { label: "5+ yrs", min: 60, max: Infinity, count: 0 },
  ];
  const now = moment();
  activeEmployees.forEach((e) => {
    const join = parseJoinMoment(e.dateOfJoin);
    if (!join) return;
    const months = now.diff(join, "months");
    const bucket = buckets.find((b) => months >= b.min && months < b.max);
    if (bucket) bucket.count += 1;
  });
  return buckets.map(({ label, count }) => ({ label, count }));
}

export function buildJoinExitTrend(allEmployees, monthsBack = 12) {
  const months = [];
  for (let i = monthsBack - 1; i >= 0; i -= 1) {
    months.push(moment().subtract(i, "months").startOf("month"));
  }

  const joins = months.map((m) =>
    allEmployees.filter((e) => {
      const join = parseJoinMoment(e.dateOfJoin);
      return join && join.year() === m.year() && join.month() === m.month();
    }).length
  );

  const exits = months.map((m) =>
    allEmployees.filter((e) => {
      const exit = parseJoinMoment(e.exitDate);
      return exit && exit.year() === m.year() && exit.month() === m.month();
    }).length
  );

  return {
    categories: months.map((m) => m.format("MMM YY")),
    joins,
    exits,
  };
}

export function buildHeadcountTrend(allEmployees, monthsBack = 12) {
  const months = [];
  for (let i = monthsBack - 1; i >= 0; i -= 1) {
    months.push(moment().subtract(i, "months").endOf("month"));
  }

  const data = months.map((m) =>
    allEmployees.filter((e) => {
      const join = parseJoinMoment(e.dateOfJoin);
      if (!join || join.isAfter(m, "day")) return false;
      const exit = parseJoinMoment(e.exitDate);
      if (exit && exit.isBefore(m, "day")) return false;
      if (!e.active && !exit) return false;
      return true;
    }).length
  );

  return {
    categories: months.map((m) => m.format("MMM YY")),
    data,
  };
}

export function buildRetentionSummary(allEmployees, activeEmployees) {
  const now = moment();
  const twelveMonthsAgo = moment().subtract(12, "months").startOf("month");

  const withJoin = activeEmployees.filter((e) => parseJoinMoment(e.dateOfJoin));
  const avgTenureMonths = withJoin.length
    ? Math.round(
        withJoin.reduce(
          (sum, e) => sum + now.diff(parseJoinMoment(e.dateOfJoin), "months"),
          0
        ) / withJoin.length
      )
    : 0;

  const exits12m = allEmployees.filter((e) => {
    const exit = parseJoinMoment(e.exitDate);
    return exit && exit.isSameOrAfter(twelveMonthsAgo);
  }).length;

  const hires12m = allEmployees.filter((e) => {
    const join = parseJoinMoment(e.dateOfJoin);
    return join && join.isSameOrAfter(twelveMonthsAgo);
  }).length;

  const retentionRate =
    allEmployees.length > 0
      ? Math.round((activeEmployees.length / allEmployees.length) * 100)
      : 100;

  const earlyExits = allEmployees.filter((e) => {
    const join = parseJoinMoment(e.dateOfJoin);
    const exit = parseJoinMoment(e.exitDate);
    if (!join || !exit) return false;
    return exit.diff(join, "months") <= 12;
  }).length;

  const longTenure = activeEmployees.filter((e) => {
    const join = parseJoinMoment(e.dateOfJoin);
    return join && now.diff(join, "years") >= 5;
  }).length;

  const probation = activeEmployees.filter((e) => {
    const join = parseJoinMoment(e.dateOfJoin);
    return join && now.diff(join, "days") <= 90;
  }).length;

  return {
    avgTenureMonths,
    exits12m,
    hires12m,
    retentionRate,
    earlyExits,
    netGrowth: hires12m - exits12m,
    longTenure,
    probation,
  };
}

export function buildEmpTypeByDepartment(activeEmployees, allTeams, limit = 5) {
  const depts = buildDepartmentDistribution(activeEmployees, allTeams, limit);
  const types = [...new Set(activeEmployees.map((e) => e.empType || "Other"))];

  const series = types.map((type) => ({
    name: type,
    data: depts.map((d) =>
      activeEmployees.filter((e) => {
        const dept =
          e.department && String(e.department).trim()
            ? e.department
            : teamLabel(allTeams, e.userTeamId);
        return dept === d.label && (e.empType || "Other") === type;
      }).length
    ),
  }));

  return {
    categories: depts.map((d) => d.label),
    series: series.filter((s) => s.data.some((n) => n > 0)),
  };
}

export function buildSkillByEmpType(activeEmployees, limit = 6) {
  const skills = buildSkillDistribution(activeEmployees, limit);
  const types = [...new Set(activeEmployees.map((e) => e.empType || "Other"))].slice(0, 4);

  const series = types.map((type) => ({
    name: type,
    data: skills.map((s) =>
      activeEmployees.filter(
        (e) => (e.primarySkill || "Unspecified") === s.label && (e.empType || "Other") === type
      ).length
    ),
  }));

  return {
    categories: skills.map((s) => s.label),
    series: series.filter((s) => s.data.some((n) => n > 0)),
  };
}

export function buildRetentionRiskList(activeEmployees, limit = 5) {
  const now = moment();
  return [...activeEmployees]
    .filter((e) => parseJoinMoment(e.dateOfJoin))
    .map((e) => {
      const join = parseJoinMoment(e.dateOfJoin);
      const months = now.diff(join, "months");
      let risk = "stable";
      let label = "Established";
      if (months <= 3) {
        risk = "watch";
        label = "New hire · onboarding";
      } else if (months <= 12) {
        risk = "watch";
        label = "First year · retention watch";
      } else if (months >= 60) {
        risk = "champion";
        label = "Long tenure · culture anchor";
      }
      return {
        id: e.id,
        name: e.name,
        designation: e.designation || "—",
        tenureMonths: months,
        risk,
        label,
      };
    })
    .sort((a, b) => {
      const order = { watch: 0, stable: 1, champion: 2 };
      const aOrder = order[a.risk] !== undefined ? order[a.risk] : 1;
      const bOrder = order[b.risk] !== undefined ? order[b.risk] : 1;
      return aOrder - bOrder || a.tenureMonths - b.tenureMonths;
    })
    .slice(0, limit);
}

/** Live health summary mapper — masked counts from feedback health-summary API. */
export function mapFeedbackHealthSummary(apiPayload, activeEmployees, allTeams) {
  if (!isEmployeeHealthSectionVisible()) {
    return null;
  }
  const teamCount = countByTeam(activeEmployees || [], allTeams || []).length;
  const hasData = Boolean(apiPayload && (apiPayload.hasData || apiPayload.requestedCount > 0));
  if (!apiPayload || !hasData) {
    return {
      status: "unavailable",
      message: "Unavailable — no employee feedback surveys in the selected lookback window.",
      plannedMetrics: [],
      sentimentBands: [],
      rosterSize: (activeEmployees || []).length,
      teamsMonitored: teamCount,
      lastSurvey: null,
      participationRate: null,
      requestedCount: 0,
      receivedCount: 0,
      hasData: false,
    };
  }
  return {
    status: "live",
    message: "Aggregated from EMPLOYEE feedback requests (masked counts only).",
    plannedMetrics: [
      { key: "requested", label: "Surveys requested", icon: "fe-send", tone: "blue", value: apiPayload.requestedCount },
      { key: "received", label: "Responses received", icon: "fe-check-circle", tone: "green", value: apiPayload.receivedCount },
      {
        key: "participation",
        label: "Participation rate",
        icon: "fe-percent",
        tone: "violet",
        value: `${apiPayload.participationRate != null ? apiPayload.participationRate : 0}%`,
      },
      {
        key: "last",
        label: "Last survey",
        icon: "fe-calendar",
        tone: "slate",
        value: apiPayload.lastSurveyAt
          ? new Date(apiPayload.lastSurveyAt).toLocaleDateString()
          : "—",
      },
    ],
    sentimentBands: [],
    rosterSize: (activeEmployees || []).length,
    teamsMonitored: teamCount,
    lastSurvey: apiPayload.lastSurveyAt || null,
    participationRate: apiPayload.participationRate,
    requestedCount: apiPayload.requestedCount || 0,
    receivedCount: apiPayload.receivedCount || 0,
    hasData: true,
  };
}

