import React from "react";
import ProfilePersonalView from "views/hrms/components/profile/ProfilePersonalView";
import ProjectDetailsTabShell from "views/project/components/ProjectDetailsTabShell";

export default function Employee360ProfileTab({ employee }) {
  if (!employee) {
    return null;
  }

  return (
    <ProjectDetailsTabShell
      title="Profile"
      description="Personal and contact details from the employee record."
      stats={[]}
    >
      <ProfilePersonalView employee={employee} />
    </ProjectDetailsTabShell>
  );
}
