import React from "react";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import { getOrgUnitTypeMeta, getEmployeeInitials, resolveOrgUnitEmployeeId } from "config/org-structure.utils";
import OrgManagerReassignForm from "views/admin/components/OrgManagerReassignForm";

export default function OrgUnitDetailPanel({
  unit,
  employees,
  tree,
  reassignManagerId,
  onReassignChange,
  onReassignSave,
  reassignSaving,
  reassignError,
  reassignSuccess,
}) {
  if (!unit) {
    return (
      <aside className="lux-org-structure-detail lux-org-structure-detail--empty" aria-label="Selected org unit">
        <span className="lux-org-structure-detail__empty-icon" aria-hidden="true">
          <i className="fe fe-git-branch" />
        </span>
        <strong>Select a hierarchy node</strong>
        <p>Inspect span, location, and reassign the reporting line on EmployeeModel.</p>
      </aside>
    );
  }

  const typeMeta = getOrgUnitTypeMeta(unit.type);
  const employeeId = resolveOrgUnitEmployeeId(unit);

  return (
    <aside className="lux-org-structure-detail" aria-label="Selected org unit">
      <header className="lux-org-structure-detail__head">
        <div className="lux-org-structure-detail__identity">
          <span className={classNames("lux-org-structure-detail__avatar", typeMeta.tone && `is-${typeMeta.tone}`)}>
            {unit.headEmployeeName ? getEmployeeInitials(unit.headEmployeeName) : <i className={typeMeta.icon} />}
          </span>
          <div>
            <h3>{unit.name}</h3>
            <p>
              {typeMeta.label}
              {unit.department ? ` · ${unit.department}` : ""}
            </p>
          </div>
        </div>
        <span className={classNames("lux-doc-badge", unit.status === "Active" ? "is-primary" : "is-slate")}>
          {unit.status}
        </span>
      </header>
      <dl className="lux-org-structure-detail__grid">
        <div>
          <dt>Head</dt>
          <dd>{unit.headEmployeeName || "Vacant"}</dd>
        </div>
        <div>
          <dt>Direct reports</dt>
          <dd>{unit.childCount != null ? unit.childCount : "—"}</dd>
        </div>
        <div>
          <dt>Headcount</dt>
          <dd>{unit.headcount != null ? unit.headcount : "—"}</dd>
        </div>
        <div>
          <dt>Location</dt>
          <dd>{unit.location || "—"}</dd>
        </div>
        <div>
          <dt>Cost center</dt>
          <dd>{unit.costCenter || "—"}</dd>
        </div>
        <div>
          <dt>Source</dt>
          <dd>{unit.catalogSource || unit.sourceEntityType || "EmployeeModel"}</dd>
        </div>
      </dl>
      {employeeId ? (
        <>
          <div className="lux-org-chart__detail-actions">
            <Link to={`/people/employees/${employeeId}/360`} className="lux-org-chart__detail-link">
              <i className="fe fe-user" aria-hidden="true" />
              Employee 360
            </Link>
          </div>
          <OrgManagerReassignForm
            employeeId={employeeId}
            employees={employees}
            tree={tree}
            value={reassignManagerId}
            onChange={onReassignChange}
            onSave={onReassignSave}
            saving={reassignSaving}
            error={reassignError}
            success={reassignSuccess}
          />
        </>
      ) : (
        <p className="lux-org-structure-detail__hint">This node is not tied to an employee, so reporting cannot be reassigned here.</p>
      )}
    </aside>
  );
}
