import React, { Component } from "react";
import classNames from "classnames/bind";
import Select from "react-select";

function getTypeLabel(typeOptions, value) {
  const match = (typeOptions || []).find((type) => type.value === value);
  return (match && (match.label || match.value)) || value || "—";
}

function isMultiType(typeOptions, value) {
  return Boolean(
    (typeOptions || []).find((type) => type.value === value && type.multi === true)
  );
}

class QuestionaireTable extends Component {
  onQuestionChange = (index, question) => {
    const list = [...(this.props.questionDataList || [])];
    list[index] = question;
    this.props.onChange("questionDataList", list);
  };

  onRemoveQuestion = (questionId) => {
    let questionDataList =
      (this.props.questionDataList || []).filter(
        (question) => question.id !== questionId
      ) || [];
    questionDataList = questionDataList.map((question, index) => ({
      ...question,
      index,
    }));
    this.props.onChange("questionDataList", questionDataList);
  };

  onMoveUp = (index) => {
    const questionDataList = [...(this.props.questionDataList || [])];
    if (index <= 0) return;
    questionDataList[index] = { ...questionDataList[index], index: index - 1 };
    questionDataList[index - 1] = {
      ...questionDataList[index - 1],
      index,
    };
    this.props.onChange("questionDataList", questionDataList);
  };

  onMoveDown = (index) => {
    const questionDataList = [...(this.props.questionDataList || [])];
    if (index >= questionDataList.length - 1) return;
    questionDataList[index + 1] = {
      ...questionDataList[index + 1],
      index,
    };
    questionDataList[index] = { ...questionDataList[index], index: index + 1 };
    this.props.onChange("questionDataList", questionDataList);
  };

  renderEmpty = () => (
    <div className="lux-qt-empty">
      <div className="lux-qt-empty__icon" aria-hidden="true">
        <i className="fe fe-check-square" />
      </div>
      <strong>No questions yet</strong>
      <p>Add your first checklist question to define what teams must complete.</p>
    </div>
  );

  render() {
    const list = this.props.questionDataList || [];
    const sorted = [...list].sort((a, b) => (a.index || 0) - (b.index || 0));

    if (!sorted.length) {
      return <div className="lux-qt">{this.renderEmpty()}</div>;
    }

    return (
      <div className="lux-qt" role="list" aria-label="Checklist questions">
        {sorted.map((question, index) => (
          <Question
            key={question.id != null ? String(question.id) : `qt-${index}`}
            typeOptions={this.props.typeOptions}
            index={index}
            size={sorted.length}
            readOnly={this.props.readOnly}
            dragMode={this.props.dragMode}
            editMode={this.props.editMode}
            questionConfigureMode={this.props.questionConfigureMode}
            question={question}
            onQuestionChange={this.onQuestionChange}
            onRemoveQuestion={this.onRemoveQuestion}
            onMoveUp={this.onMoveUp}
            onMoveDown={this.onMoveDown}
          />
        ))}
      </div>
    );
  }
}

class Question extends Component {
  onQuestionChange = (name, value) => {
    let next = { ...this.props.question, [name]: value };
    if (name === "type") {
      const multi = isMultiType(this.props.typeOptions, value);
      if (!multi) {
        next = { ...next, questionOptions: null };
      }
    }
    this.props.onQuestionChange(this.props.index, next);
  };

  renderConfigure = () => {
    const { question, typeOptions, editMode, dragMode, index, size } = this.props;
    const selectedType =
      (typeOptions || []).find((type) => type.value === question.type) || null;
    const multi = isMultiType(typeOptions, question.type);

    return (
      <article
        className={classNames("lux-qt-card", "lux-qt-card--configure", {
          "is-required": !!question.mandatory,
        })}
        role="listitem"
      >
        <div className="lux-qt-card__rail">
          <span className="lux-qt-card__index">{index + 1}</span>
          {dragMode && editMode && (
            <div className="lux-qt-card__reorder">
              <button
                type="button"
                className="lux-qt-card__reorder-btn"
                disabled={index === 0}
                onClick={() => this.props.onMoveUp(question.index)}
                title="Move up"
                aria-label="Move question up"
              >
                <i className="fe fe-chevron-up" aria-hidden="true" />
              </button>
              <button
                type="button"
                className="lux-qt-card__reorder-btn"
                disabled={index === size - 1}
                onClick={() => this.props.onMoveDown(question.index)}
                title="Move down"
                aria-label="Move question down"
              >
                <i className="fe fe-chevron-down" aria-hidden="true" />
              </button>
            </div>
          )}
        </div>

        <div className="lux-qt-card__content">
          <div className="lux-qt-card__field lux-qt-card__field--primary">
            <label className="lux-qt-card__label">Question</label>
            <input
              type="text"
              className="lux-qt-card__input"
              value={question.question || ""}
              placeholder="What should the team confirm?"
              disabled={!editMode}
              onChange={(event) =>
                this.onQuestionChange("question", event.target.value)
              }
            />
          </div>

          <div className="lux-qt-card__toolbar">
            <div className="lux-qt-card__type">
              <label className="lux-qt-card__label">Answer type</label>
              <Select
                isSearchable
                isClearable={false}
                isDisabled={!editMode}
                placeholder="Select type"
                classNamePrefix="custom-select"
                isMulti={false}
                menuPlacement="auto"
                value={selectedType}
                onChange={(selectedOption) => {
                  this.onQuestionChange("type", selectedOption.value);
                }}
                options={typeOptions}
              />
            </div>

            <div className="lux-qt-card__toggles">
              <label
                className={classNames("lux-qt-toggle", {
                  "is-on": !!question.mandatory,
                })}
              >
                <input
                  type="checkbox"
                  checked={!!question.mandatory}
                  disabled={!editMode}
                  onChange={(event) =>
                    this.onQuestionChange("mandatory", event.target.checked)
                  }
                />
                <i className="fe fe-alert-circle" aria-hidden="true" />
                Required
              </label>
              <label
                className={classNames("lux-qt-toggle", {
                  "is-on": !!question.hasComments,
                })}
              >
                <input
                  type="checkbox"
                  checked={!!question.hasComments}
                  disabled={!editMode}
                  onChange={(event) =>
                    this.onQuestionChange("hasComments", event.target.checked)
                  }
                />
                <i className="fe fe-message-circle" aria-hidden="true" />
                Comments
              </label>
            </div>

            {editMode && (
              <button
                type="button"
                className="lux-qt-card__remove"
                onClick={() => this.props.onRemoveQuestion(question.id)}
                title="Remove question"
                aria-label="Remove question"
              >
                <i className="fe fe-trash-2" aria-hidden="true" />
              </button>
            )}
          </div>

          {multi && (
            <div className="lux-qt-card__field">
              <label className="lux-qt-card__label">Options (comma separated)</label>
              <input
                type="text"
                className="lux-qt-card__input"
                value={question.questionOptions || ""}
                placeholder="Option A, Option B, Option C"
                disabled={!editMode}
                onChange={(event) =>
                  this.onQuestionChange("questionOptions", event.target.value)
                }
              />
            </div>
          )}
        </div>
      </article>
    );
  };

  renderPreview = () => {
    const { question, typeOptions, index } = this.props;
    const typeLabel = getTypeLabel(typeOptions, question.type);

    return (
      <article
        className={classNames("lux-qt-card", "lux-qt-card--preview", {
          "is-required": !!question.mandatory,
        })}
        role="listitem"
      >
        <div className="lux-qt-card__rail">
          <span className="lux-qt-card__index">{index + 1}</span>
        </div>
        <div className="lux-qt-card__content">
          <div className="lux-qt-card__preview-head">
            <strong className="lux-qt-card__preview-title">
              {question.question || "Untitled question"}
              {question.mandatory ? (
                <span className="lux-qt-card__required" title="Required">
                  *
                </span>
              ) : null}
            </strong>
            <div className="lux-qt-card__preview-meta">
              <span className="lux-qt-meta-chip">
                <i className="fe fe-layers" aria-hidden="true" />
                {typeLabel}
              </span>
              {question.hasComments ? (
                <span className="lux-qt-meta-chip">
                  <i className="fe fe-message-circle" aria-hidden="true" />
                  Comments
                </span>
              ) : null}
            </div>
          </div>
        </div>
      </article>
    );
  };

  renderAnswer = () => {
    const { question, readOnly, index, typeOptions } = this.props;
    const typeLabel = getTypeLabel(typeOptions, question.type);
    const radioName = `lux-qt-answer-${question.id || index}`;

    if (readOnly) {
      const answerText =
        question.type === "boolean"
          ? question.answer === false || question.answer === "false"
            ? "No"
            : question.answer === true || question.answer === "true"
              ? "Yes"
              : "—"
          : question.answer || "—";

      return (
        <article
          className={classNames("lux-qt-card", "lux-qt-card--answer", "is-readonly", {
            "is-required": !!question.mandatory,
            "is-answered":
              question.answer !== undefined &&
              question.answer !== null &&
              question.answer !== "",
          })}
          role="listitem"
        >
          <div className="lux-qt-card__rail">
            <span className="lux-qt-card__index">{index + 1}</span>
          </div>
          <div className="lux-qt-card__content">
            <div className="lux-qt-card__preview-head">
              <strong className="lux-qt-card__preview-title">
                {question.question || "Untitled question"}
                {question.mandatory ? (
                  <span className="lux-qt-card__required">*</span>
                ) : null}
              </strong>
              <span className="lux-qt-meta-chip">{typeLabel}</span>
            </div>
            <div className="lux-qt-answer lux-qt-answer--readonly">
              <span className="lux-qt-answer__value">{answerText}</span>
              {question.comments ? (
                <span className="lux-qt-answer__comments">{question.comments}</span>
              ) : null}
            </div>
          </div>
        </article>
      );
    }

    return (
      <article
        className={classNames("lux-qt-card", "lux-qt-card--answer", {
          "is-required": !!question.mandatory,
          "is-answered":
            question.answer !== undefined &&
            question.answer !== null &&
            question.answer !== "",
        })}
        role="listitem"
      >
        <div className="lux-qt-card__rail">
          <span className="lux-qt-card__index">{index + 1}</span>
        </div>
        <div className="lux-qt-card__content">
          <div className="lux-qt-card__preview-head">
            <strong className="lux-qt-card__preview-title">
              {question.question || "Untitled question"}
              {question.mandatory ? (
                <span className="lux-qt-card__required">*</span>
              ) : null}
            </strong>
            <span className="lux-qt-meta-chip">{typeLabel}</span>
          </div>

          <div className="lux-qt-answer">
            {question.type === "string" && (
              <input
                type="text"
                className="lux-qt-card__input"
                value={question.answer || ""}
                placeholder="Enter answer"
                onChange={(event) =>
                  this.onQuestionChange("answer", event.target.value)
                }
              />
            )}
            {question.type === "number" && (
              <input
                type="number"
                className="lux-qt-card__input"
                value={question.answer || ""}
                placeholder="Enter number"
                onChange={(event) =>
                  this.onQuestionChange("answer", event.target.value)
                }
              />
            )}
            {question.type === "boolean" && (
              <div className="lux-qt-bool" role="radiogroup" aria-label="Yes or No">
                <label
                  className={classNames("lux-qt-bool__option", {
                    "is-selected": question.answer === true || question.answer === "true",
                  })}
                >
                  <input
                    type="radio"
                    name={radioName}
                    checked={question.answer === true || question.answer === "true"}
                    onChange={() => this.onQuestionChange("answer", true)}
                  />
                  <i className="fe fe-check" aria-hidden="true" />
                  Yes
                </label>
                <label
                  className={classNames("lux-qt-bool__option", {
                    "is-selected":
                      question.answer === false || question.answer === "false",
                  })}
                >
                  <input
                    type="radio"
                    name={radioName}
                    checked={
                      question.answer === false || question.answer === "false"
                    }
                    onChange={() => this.onQuestionChange("answer", false)}
                  />
                  <i className="fe fe-x" aria-hidden="true" />
                  No
                </label>
              </div>
            )}
            {question.type !== "string" &&
              question.type !== "number" &&
              question.type !== "boolean" && (
                <input
                  type="text"
                  className="lux-qt-card__input"
                  value={question.answer || ""}
                  placeholder="Enter answer"
                  onChange={(event) =>
                    this.onQuestionChange("answer", event.target.value)
                  }
                />
              )}
            {question.hasComments && (
              <input
                type="text"
                className="lux-qt-card__input lux-qt-card__input--comments"
                value={question.comments || ""}
                placeholder="Optional comments"
                onChange={(event) =>
                  this.onQuestionChange("comments", event.target.value)
                }
              />
            )}
          </div>
        </div>
      </article>
    );
  };

  render() {
    // Template editor configure fields
    if (this.props.questionConfigureMode) {
      return this.renderConfigure();
    }
    // Template editor read/preview list (sidebar config view)
    if (this.props.dragMode) {
      return this.renderPreview();
    }
    // Work-item fill / answer mode
    return this.renderAnswer();
  }
}

export default QuestionaireTable;
