import React from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import { INTEGRATION_CENTER_ROUTES } from "config/integration-center.config";
import {
  IntegrationActionButton,
  IntegrationStatusBadge,
  IntegrationTrustBadge,
} from "views/integrations/components/IntegrationsLuxShared";

function getConnectorDrawerAccent(connector) {
  if (connector.status === "failed") {
    return "danger";
  }
  if (connector.status === "degraded") {
    return "warning";
  }
  if (connector.status === "paused") {
    return "neutral";
  }
  const tone = connector.tone || "blue";
  if (tone === "indigo" || tone === "violet") {
    return "indigo";
  }
  if (tone === "amber") {
    return "amber";
  }
  if (tone === "slate") {
    return "neutral";
  }
  if (tone === "emerald" || tone === "green") {
    return "success";
  }
  return "blue";
}

function formatConnectorDirection(direction) {
  const value = String(direction || "").toLowerCase();
  if (value === "bidirectional") {
    return "Bidirectional sync";
  }
  if (value === "inbound") {
    return "Inbound only";
  }
  if (value === "outbound") {
    return "Outbound only";
  }
  return direction || "—";
}

export default function ConnectorRegister({ connectors = [], loading, onSelect, selectedId }) {
  if (loading) {
    return <div className="lux-integ-register__skeleton" aria-busy="true" />;
  }
  if (!connectors.length) {
    return (
      <div className="lux-integ-register__empty">
        <i className="fe fe-link lux-integ-register__empty-icon" aria-hidden="true" />
        <strong>No live connectors</strong>
        <p>Salesforce, ZingHR, and Email appear after Integration Center bootstrap. Demo connectors are hidden.</p>
      </div>
    );
  }

  return (
    <div className="lux-integ-connector-grid">
      {connectors.map((row) => (
        <article
          key={row.id}
          className={classNames(
            "lux-integ-connector-card",
            row.status && `is-${row.status}`,
            row.tone && `is-tone-${row.tone}`,
            { "is-selected": selectedId === row.id }
          )}
        >
          <header className="lux-integ-connector-card__head">
            <span className="lux-integ-connector-card__icon" aria-hidden="true">
              <i className={row.icon || "fe fe-link"} />
            </span>
            <div className="lux-integ-connector-card__title">
              <strong>{row.name}</strong>
              <small>{row.type}</small>
            </div>
            <IntegrationStatusBadge status={row.status} />
          </header>
          <p className="lux-integ-connector-card__lede">
            {row.lastError || row.description}
          </p>
          <div className="lux-integ-connector-card__metric-grid">
            <article>
              <span>Records</span>
              <strong>{row.recordsSynced}</strong>
            </article>
            <article>
              <span>{row.healthSource ? "Signal" : "Latency"}</span>
              <strong>
                {row.healthSource
                  ? String(row.healthSource)
                  : `${row.avgLatencyMs}ms`}
              </strong>
            </article>
            <article>
              <span>Error rate</span>
              <strong>{row.errorRatePct}%</strong>
            </article>
          </div>
          <div className="lux-integ-connector-card__footer">
            <IntegrationTrustBadge score={row.trustScore} />
            <span className="lux-integ-connector-card__sync">
              <i className="fe fe-clock" aria-hidden="true" />
              {row.lastSync}
            </span>
          </div>
          {onSelect ? (
            <button type="button" className="lux-integ-connector-card__select" onClick={() => onSelect(row)}>
              <span>View details</span>
              <i className="fe fe-arrow-right" aria-hidden="true" />
            </button>
          ) : null}
        </article>
      ))}
    </div>
  );
}

export function ConnectorDetailDrawer({ connector, onClose }) {
  if (!connector) {
    return null;
  }

  const accent = getConnectorDrawerAccent(connector);
  const showDegradedBanner = connector.status === "degraded" || connector.status === "failed";
  const bannerCopy =
    connector.status === "failed"
      ? "Connector sync is failing — inspect integration logs and retry pending jobs."
      : `Elevated error rate (${connector.errorRatePct}%) — review sync monitor before the next window.`;

  return createPortal(
    <div className="lux-integ-drawer-backdrop" role="presentation" onClick={onClose}>
      <aside
        className={classNames("lux-integ-drawer", `lux-integ-drawer--${accent}`, connector.status && `is-${connector.status}`)}
        role="dialog"
        aria-modal="true"
        aria-labelledby="lux-integ-drawer-title"
        onClick={(e) => e.stopPropagation()}
      >
        <span className="lux-integ-drawer__accent" aria-hidden="true" />

        <header className="lux-integ-drawer__head">
          <div className="lux-integ-drawer__head-main">
            <span className="lux-integ-drawer__category-icon" aria-hidden="true">
              <i className={connector.icon || "fe fe-link"} />
            </span>
            <div className="lux-integ-drawer__head-copy">
              <span className="lux-integ-drawer__eyebrow">Connector · {connector.type}</span>
              <h2 id="lux-integ-drawer-title">{connector.name}</h2>
              <div className="lux-integ-drawer__badges">
                <IntegrationStatusBadge status={connector.status} />
                <IntegrationTrustBadge score={connector.trustScore} />
              </div>
            </div>
          </div>
          <button type="button" className="lux-integ-drawer__close" onClick={onClose} aria-label="Close">
            <i className="fe fe-x" aria-hidden="true" />
          </button>
        </header>

        <div className="lux-integ-drawer__body">
          {showDegradedBanner ? (
            <div className="lux-integ-drawer__banner is-alert">
              <span className="lux-integ-drawer__banner-icon" aria-hidden="true">
                <i className="fe fe-alert-triangle" />
              </span>
              <div>
                <strong>Attention required</strong>
                <p>{bannerCopy}</p>
              </div>
            </div>
          ) : (
            <div className="lux-integ-drawer__banner is-success">
              <span className="lux-integ-drawer__banner-icon" aria-hidden="true">
                <i className="fe fe-check-circle" />
              </span>
              <div>
                <strong>Sync posture healthy</strong>
                <p>Trust score {connector.trustScore}% with {connector.errorRatePct}% error rate over the last window.</p>
              </div>
            </div>
          )}

          <div className="lux-integ-drawer__metrics">
            <article className="lux-integ-drawer__metric is-blue">
              <span>Records synced</span>
              <strong>{connector.recordsSynced}</strong>
            </article>
            <article className="lux-integ-drawer__metric is-indigo">
              <span>Avg latency</span>
              <strong>{connector.avgLatencyMs}ms</strong>
            </article>
            <article
              className={classNames(
                "lux-integ-drawer__metric",
                connector.errorRatePct >= 3 ? "is-rose" : "is-green"
              )}
            >
              <span>Error rate</span>
              <strong>{connector.errorRatePct}%</strong>
            </article>
          </div>

          <section className="lux-integ-drawer__section">
            <h3>Adapter profile</h3>
            <div className="lux-integ-drawer__facts">
              <article className="lux-integ-drawer__fact">
                <span className="lux-integ-drawer__fact-icon" aria-hidden="true">
                  <i className="fe fe-shield" />
                </span>
                <div>
                  <span className="lux-integ-drawer__fact-label">Authentication</span>
                  <span className="lux-integ-drawer__fact-value">{connector.authType}</span>
                </div>
              </article>
              <article className="lux-integ-drawer__fact">
                <span className="lux-integ-drawer__fact-icon" aria-hidden="true">
                  <i className="fe fe-repeat" />
                </span>
                <div>
                  <span className="lux-integ-drawer__fact-label">Direction</span>
                  <span className="lux-integ-drawer__fact-value">{formatConnectorDirection(connector.direction)}</span>
                </div>
              </article>
              <article className="lux-integ-drawer__fact">
                <span className="lux-integ-drawer__fact-icon" aria-hidden="true">
                  <i className="fe fe-clock" />
                </span>
                <div>
                  <span className="lux-integ-drawer__fact-label">Last sync</span>
                  <span className="lux-integ-drawer__fact-value">{connector.lastSync}</span>
                </div>
              </article>
              <article className="lux-integ-drawer__fact">
                <span className="lux-integ-drawer__fact-icon" aria-hidden="true">
                  <i className="fe fe-hash" />
                </span>
                <div>
                  <span className="lux-integ-drawer__fact-label">Connector ID</span>
                  <span className="lux-integ-drawer__fact-value">{connector.id}</span>
                </div>
              </article>
            </div>
          </section>

          <section className="lux-integ-drawer__notes-card">
            <header>
              <i className="fe fe-align-left" aria-hidden="true" />
              <span>Sync scope</span>
            </header>
            <p>{connector.description}</p>
          </section>
        </div>

        <footer className="lux-integ-drawer__footer">
          <IntegrationActionButton icon="fe fe-file-text" variant="ghost" to={INTEGRATION_CENTER_ROUTES.LOGS}>
            View logs
          </IntegrationActionButton>
          <IntegrationActionButton icon="fe fe-activity" to={INTEGRATION_CENTER_ROUTES.SYNC_HEALTH}>
            Sync monitor
          </IntegrationActionButton>
        </footer>
      </aside>
    </div>,
    document.body
  );
}
