import { PAYROLL_EXCEPTION_SEVERITIES, PAYROLL_RUN_STATUSES } from "config/payroll.config";

const DEFAULT_SUGGESTIONS = [
  {
    id: "timesheets",
    title: "Verify timesheet approval",
    detail: "Confirm all employee timesheets are approved for the pay period.",
    priority: "HIGH",
  },
  {
    id: "leave",
    title: "Review leave without pay",
    detail: "Ensure unpaid leave entries are reflected before calculation.",
    priority: "MEDIUM",
  },
  {
    id: "new-hires",
    title: "Check new hire pro-rata",
    detail: "Validate salary components for employees who joined mid-period.",
    priority: "MEDIUM",
  },
];

const FIX_HINTS = {
  Timesheet: "Open the employee timesheet and approve or reject pending hours.",
  Leave: "Review leave transactions and unpaid leave entries for the period.",
  Compensation: "Update salary structure or employee compensation before recalculating.",
  General: "Resolve the exception in the payroll exception queue, then recalculate.",
};

export function resolvePayrollExceptionFixHint(exception) {
  if (!exception) {
    return FIX_HINTS.General;
  }
  const category = exception.category || "General";
  return FIX_HINTS[category] || FIX_HINTS.General;
}

export function mapPayrollExceptionInsight(exception) {
  if (!exception) {
    return null;
  }
  return {
    id: exception.id || exception.code || "exception",
    message: exception.message || "Payroll exception",
    code: exception.code || "",
    category: exception.category || "General",
    employeeName: exception.employeeName || "",
    fixHint: resolvePayrollExceptionFixHint(exception),
  };
}

export function computePayrollReadinessConfidence(run, blockers, warnings) {
  let score = 0.88;
  if (run && run.readinessScore != null && run.readinessScore >= 0) {
    score = Math.min(0.95, 0.55 + run.readinessScore / 200);
  }
  score -= (blockers.length * 0.12);
  score -= (warnings.length * 0.04);
  if (run && run.status === PAYROLL_RUN_STATUSES.DRAFT) {
    score -= 0.08;
  }
  return Math.max(0.35, Math.min(0.95, Math.round(score * 100) / 100));
}

export function buildPayrollReadinessNextAction(run, blockers, warnings) {
  if (!run) {
    return "Select a payroll run to review readiness.";
  }
  if (blockers.length > 0) {
    return "Resolve blockers in the exception queue, then recalculate the run.";
  }
  if (warnings.length > 0) {
    return "Review warnings with payroll admin before submitting for approval.";
  }
  if (run.status === PAYROLL_RUN_STATUSES.DRAFT) {
    return "Calculate the run to refresh lines and readiness score.";
  }
  if (run.status === PAYROLL_RUN_STATUSES.CALCULATED) {
    return "Submit the run for approval when totals look correct.";
  }
  if (run.status === PAYROLL_RUN_STATUSES.PENDING_APPROVAL) {
    return "Complete approval workflow before finalize.";
  }
  return "Run is on track — proceed with the next lifecycle step.";
}

export function buildPayrollReadinessEvidence(run, blockers, warnings) {
  const evidence = [];
  if (run) {
    if (run.readinessScore != null) {
      evidence.push(`Readiness score ${run.readinessScore}%`);
    }
    if (run.employeeCount != null) {
      evidence.push(`${run.employeeCount} employee(s) in run`);
    }
    if (run.exceptionCount != null) {
      evidence.push(`${run.exceptionCount} open exception(s)`);
    }
    if (run.status) {
      evidence.push(`Status ${run.status}`);
    }
  }
  if (blockers.length > 0) {
    evidence.push(`${blockers.length} blocker(s) unresolved`);
  }
  if (warnings.length > 0) {
    evidence.push(`${warnings.length} warning(s) open`);
  }
  return evidence.slice(0, 5);
}

export function buildPayrollReadinessAiBrief(run, exceptions, options) {
  const opts = options || {};
  const rows = exceptions || [];
  const blockers = rows
    .filter((row) => !row.resolved && row.severity === PAYROLL_EXCEPTION_SEVERITIES.BLOCKER)
    .map(mapPayrollExceptionInsight)
    .filter(Boolean);
  const warnings = rows
    .filter((row) => !row.resolved && row.severity === PAYROLL_EXCEPTION_SEVERITIES.WARNING)
    .map(mapPayrollExceptionInsight)
    .filter(Boolean);

  const headline = blockers.length
    ? `${blockers.length} blocker(s) must be resolved before finalize`
    : warnings.length
      ? `${warnings.length} warning(s) — review before approval`
      : run && run.status === PAYROLL_RUN_STATUSES.DRAFT
        ? "Calculate the run to generate readiness signals"
        : "Run is ready for the next lifecycle step";

  const summary = blockers.length
    ? `Payroll readiness is blocked by ${blockers.length} exception(s). Address timesheet, leave, and compensation gaps before approval.`
    : warnings.length
      ? `No blockers detected, but ${warnings.length} warning(s) need payroll admin review.`
      : "Exception queue is clear for this run. Continue with standard payroll checks before approval.";

  const confidence = computePayrollReadinessConfidence(run, blockers, warnings);

  return {
    headline,
    summary,
    blockers: blockers.slice(0, 5),
    warnings: warnings.slice(0, 5),
    suggestions: DEFAULT_SUGGESTIONS,
    confidence,
    nextBestAction: buildPayrollReadinessNextAction(run, blockers, warnings),
    evidence: buildPayrollReadinessEvidence(run, blockers, warnings),
    disclaimer:
      "Draft — readiness insights are rule-based today. Live AI integration will enrich summaries without auto-approving payroll.",
    source: opts.source || "client",
  };
}

/** @deprecated Use buildPayrollReadinessAiBrief — kept for payroll.utils re-export */
export function buildPayrollReadinessDraft(run, exceptions) {
  const brief = buildPayrollReadinessAiBrief(run, exceptions);
  return {
    headline: brief.headline,
    blockers: brief.blockers.map((row) => row.message),
    suggestions: brief.suggestions.map((row) => row.title),
  };
}

export function normalizePayrollReadinessBrief(row) {
  if (!row) {
    return null;
  }
  return {
    headline: row.headline || "",
    summary: row.summary || "",
    blockers: (row.blockers || []).map((item) => ({
      id: item.id || item.code || "blocker",
      message: item.message || "",
      code: item.code || "",
      category: item.category || "General",
      employeeName: item.employeeName || "",
      fixHint: item.fixHint || FIX_HINTS.General,
    })),
    warnings: (row.warnings || []).map((item) => ({
      id: item.id || item.code || "warning",
      message: item.message || "",
      code: item.code || "",
      category: item.category || "General",
      employeeName: item.employeeName || "",
      fixHint: item.fixHint || FIX_HINTS.General,
    })),
    suggestions: (row.suggestions || DEFAULT_SUGGESTIONS).map((item, index) => ({
      id: item.id || `suggestion-${index}`,
      title: item.title || item.detail || "Suggested check",
      detail: item.detail || item.title || "",
      priority: item.priority || "MEDIUM",
    })),
    confidence: row.confidence != null ? row.confidence : 0.5,
    nextBestAction: row.nextBestAction || "",
    evidence: row.evidence || [],
    disclaimer: row.disclaimer || "",
    source: row.source || "api",
  };
}
