import React, { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import "./UniversalApprovalWorkflow.css";

function itemLabel(item) {
  if (!item) {
    return "Approval item";
  }
  return item.subject || item.domainLabel || String(item.sourceId || "Approval item");
}

export function UniversalApprovalBulkResults({ result, items = [] }) {
  if (!result) {
    return null;
  }
  return (
    <div className="lux-appr-bulk-results" data-testid="approval-bulk-results">
      <div className="lux-appr-bulk-results__summary" role="status">
        <span className="is-success">
          <i className="fe fe-check-circle" aria-hidden="true" />
          {result.successCount || 0} succeeded
        </span>
        <span className={result.failureCount ? "is-danger" : "is-muted"}>
          <i className="fe fe-alert-circle" aria-hidden="true" />
          {result.failureCount || 0} failed
        </span>
        {result.stoppedEarly ? <em>Stopped early</em> : null}
      </div>
      <ul className="lux-appr-bulk-results__list">
        {(result.results || []).map((row, resultIndex) => {
          const source = items[row.index != null ? row.index : resultIndex];
          return (
            <li
              key={`${row.index != null ? row.index : resultIndex}-${row.domain}-${row.sourceId}`}
              className={classNames({
                "is-success": row.success,
                "is-danger": !row.success,
              })}
            >
              <i
                className={row.success ? "fe fe-check" : "fe fe-x"}
                aria-hidden="true"
              />
              <span>
                <strong>{itemLabel(source)}</strong>
                <em>
                  {row.success
                    ? row.idempotent
                      ? "Already completed"
                      : row.outcome || "Completed"
                    : row.message || row.errorType || "Action failed"}
                </em>
              </span>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

export default function UniversalApprovalBulkActionDialog({
  open,
  action,
  items = [],
  summary,
  acting,
  error,
  result,
  onConfirm,
  onClose,
}) {
  const [comment, setComment] = useState("");
  const [localError, setLocalError] = useState(null);

  useEffect(() => {
    if (open) {
      setComment("");
      setLocalError(null);
    }
  }, [open, action]);

  if (!open || typeof document === "undefined") {
    return null;
  }

  const rejecting = action === "REJECT";
  const verb = rejecting ? "Reject" : "Approve";
  const handleConfirm = () => {
    if (rejecting && !comment.trim()) {
      setLocalError("A rejection reason is required.");
      return;
    }
    setLocalError(null);
    onConfirm(comment.trim() || null);
  };

  return createPortal(
    <div
      className="lux-appr-bulk-backdrop"
      role="presentation"
      onClick={acting ? undefined : onClose}
    >
      <section
        className="lux-appr-bulk-dialog"
        role="dialog"
        aria-modal="true"
        aria-labelledby="approval-bulk-dialog-title"
        onClick={(event) => event.stopPropagation()}
        data-testid="approval-bulk-dialog"
      >
        <header className="lux-appr-bulk-dialog__head">
          <span className={rejecting ? "is-danger" : "is-success"} aria-hidden="true">
            <i className={rejecting ? "fe fe-x-circle" : "fe fe-check-circle"} />
          </span>
          <div>
            <p>Bulk approval</p>
            <h2 id="approval-bulk-dialog-title">
              {result ? "Bulk action results" : `${verb} selected requests?`}
            </h2>
            <small>
              {items.length} selected
              {summary && summary.hours != null ? ` · ${summary.hours}h available` : ""}
            </small>
          </div>
          <button
            type="button"
            className="lux-appr-bulk-dialog__close"
            aria-label="Close bulk approval dialog"
            onClick={onClose}
            disabled={acting}
          >
            <i className="fe fe-x" aria-hidden="true" />
          </button>
        </header>

        <div className="lux-appr-bulk-dialog__body">
          {result ? (
            <UniversalApprovalBulkResults result={result} items={items} />
          ) : (
            <>
              <p className="lux-appr-bulk-dialog__confirm">
                This sends one governed request to the approval engine. Each item is processed
                independently so mixed outcomes can be reviewed here.
              </p>
              <label className="lux-appr-bulk-dialog__field">
                <span>{rejecting ? "Rejection reason" : "Approval comment (optional)"}</span>
                <textarea
                  rows={4}
                  value={comment}
                  onChange={(event) => setComment(event.target.value)}
                  placeholder={
                    rejecting
                      ? "Explain why these requests are being rejected…"
                      : "Add a note for the selected requests…"
                  }
                  disabled={acting}
                  data-testid="approval-bulk-comment"
                />
              </label>
            </>
          )}
          {(localError || error) && (
            <p className="lux-appr-bulk-dialog__error" role="alert">
              {localError || error}
            </p>
          )}
        </div>

        <footer className="lux-appr-bulk-dialog__foot">
          <button
            type="button"
            className="lux-appr-bulk-dialog__btn is-ghost"
            onClick={onClose}
            disabled={acting}
          >
            {result ? "Close" : "Cancel"}
          </button>
          {!result && (
            <button
              type="button"
              className={classNames("lux-appr-bulk-dialog__btn", {
                "is-danger": rejecting,
                "is-success": !rejecting,
              })}
              onClick={handleConfirm}
              disabled={acting || !items.length}
              data-testid="approval-bulk-confirm"
            >
              {acting ? `${verb}ing…` : `Confirm ${verb.toLowerCase()}`}
            </button>
          )}
        </footer>
      </section>
    </div>,
    document.body
  );
}
