import React, { useState } from "react";
import PropTypes from "prop-types";
import { useMsal } from "@azure/msal-react";
import { loginRequest, msalConfig } from "_helpers/microsoftAuthConfig";
import { userActions } from "_actions";
import { store } from "_helpers";
import { applyRememberMePreference, authSetItem } from "_helpers/authStorage.utils";

/**
 * Renders Microsoft SSO sign-in. Applies the same Remember me preference as email login.
 */
export const MicrosoftSignInButton = ({ rememberMe, emailHint, disabled }) => {
    const { instance } = useMsal();
    const [busy, setBusy] = useState(false);
    const [errorMessage, setErrorMessage] = useState("");

    function callbackFunction(_response, token) {
        authSetItem('loginType', "MS");
        authSetItem('authToken', JSON.stringify(token));
        authSetItem('authRefreshToken', JSON.stringify(token));
    }

    function getLoginToken(account) {
        setBusy(true);
        setErrorMessage("");
        instance.acquireTokenSilent({
            scopes: [msalConfig.auth.clientId + "/.default"],
            account: account
        }).then((res) => {
            const email = (account && account.username) || emailHint || "";
            applyRememberMePreference(rememberMe, email);
            store.dispatch(userActions.login(account.username, res.accessToken, "MS", (response) => callbackFunction(response, res.accessToken)));
            setBusy(false);
        }).catch((e) => {
            console.error(e);
            setBusy(false);
            setErrorMessage("Microsoft sign-in could not get a token. Try again or use email.");
        });
    }

    const handleLogin = () => {
        if (disabled || busy) return;
        setBusy(true);
        setErrorMessage("");
        instance.loginPopup(loginRequest)
            .then(response => {
                getLoginToken(response.account);
            })
            .catch(e => {
                console.error(e);
                setBusy(false);
                const cancelled = e && (e.errorCode === "user_cancelled" || e.errorCode === "popup_window_error");
                setErrorMessage(cancelled
                    ? "Microsoft sign-in was cancelled."
                    : "Microsoft sign-in failed. Try again or use email.");
            });
    }

    return (
        <div className="auth-login__ms">
            <button
                type="button"
                className="microsoftlogin"
                onClick={handleLogin}
                disabled={disabled || busy}
                aria-busy={busy}
                data-ga-action="login_microsoft"
                data-ga-category="auth"
                data-ga-label="Microsoft Sign in"
            >
                {busy ? (
                    <span className="auth-login__ms-busy">
                        <span className="spinner-border spinner-border-sm mr-2" aria-hidden="true" />
                        Signing in with Microsoft…
                    </span>
                ) : (
                    <img src="/assets/images/microsoftlogin.svg" alt="Sign in with Microsoft" width="215" height="41" />
                )}
            </button>
            {errorMessage && (
                <div className="invalid-feedback d-block auth-login__ms-error" role="alert" aria-live="polite">
                    {errorMessage}
                </div>
            )}
        </div>
    )
}

MicrosoftSignInButton.propTypes = {
  rememberMe: PropTypes.bool,
  emailHint: PropTypes.string,
  disabled: PropTypes.bool,
};

MicrosoftSignInButton.defaultProps = {
  rememberMe: true,
  emailHint: "",
  disabled: false,
};
