import React, { Component } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import { industryTemplateService } from "_services/industryTemplates/industryTemplates.service";
import { commonUtils } from "_helpers";
import {
  AdminActionButton,
  AdminInsightStrip,
  AdminLuxPage,
  AdminPanelHead,
} from "views/admin/components/AdminLuxShared";
import AdminLoadAlert from "views/admin/components/AdminLoadAlert";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

const STEPS = [
  { id: "select", label: "Select" },
  { id: "preview", label: "Preview" },
  { id: "draft", label: "Draft" },
  { id: "committed", label: "Commit" },
];

function stepIndex(step) {
  if (step === "cancelled") return 0;
  const idx = STEPS.findIndex((s) => s.id === step);
  return idx >= 0 ? idx : 0;
}

class IndustryTemplateApplyPage extends Component {
  state = {
    catalogs: [],
    loading: true,
    loadError: null,
    templateRef: "",
    overwriteApproved: false,
    step: "select",
    apply: null,
    busy: false,
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Apply industry template");
    }
    this.loadCatalog();
  }

  queryTemplateRef = () => {
    const search =
      (this.props.location && this.props.location.search) ||
      (typeof window !== "undefined" ? window.location.search : "");
    try {
      return new URLSearchParams(search).get("templateRef") || "";
    } catch (e) {
      return "";
    }
  };

  loadCatalog = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await industryTemplateService.listCatalog();
    if (result.source === "api" && Array.isArray(result.payload)) {
      const fromQuery = this.queryTemplateRef();
      const preferred =
        fromQuery && result.payload.some((c) => c.templateRef === fromQuery)
          ? fromQuery
          : result.payload[0]
            ? result.payload[0].templateRef
            : "";
      this.setState({
        loading: false,
        catalogs: result.payload,
        templateRef: preferred,
      });
    } else {
      this.setState({
        loading: false,
        loadError: result.error || new Error("Unable to load catalog"),
      });
    }
  };

  runPreview = async () => {
    const { templateRef } = this.state;
    if (!templateRef) return;
    this.setState({ busy: true, loadError: null });
    const result = await industryTemplateService.preview({
      templateRef,
      targetTeamId: commonUtils.getCurrentUserTeamId(),
    });
    this.setState({ busy: false });
    if (result.source === "api" && result.payload) {
      this.setState({ apply: result.payload, step: "preview" });
    } else {
      this.setState({ loadError: result.error || new Error("Preview failed") });
    }
  };

  runDraft = async () => {
    const { templateRef, overwriteApproved } = this.state;
    this.setState({ busy: true, loadError: null });
    const result = await industryTemplateService.applyDraft({
      templateRef,
      targetTeamId: commonUtils.getCurrentUserTeamId(),
      overwriteApproved,
    });
    this.setState({ busy: false });
    if (result.source === "api" && result.payload) {
      this.setState({ apply: result.payload, step: "draft" });
    } else {
      this.setState({ loadError: result.error || new Error("Draft failed") });
    }
  };

  runCommit = async () => {
    const { apply, overwriteApproved } = this.state;
    if (!apply || !apply.applyRef) return;
    this.setState({ busy: true, loadError: null });
    const result = await industryTemplateService.commit(apply.applyRef, {
      overwriteApproved,
      targetTeamId: commonUtils.getCurrentUserTeamId(),
    });
    this.setState({ busy: false });
    if (result.source === "api" && result.payload) {
      this.setState({ apply: result.payload, step: "committed" });
    } else {
      this.setState({
        loadError: result.error || new Error("Commit failed — check overwrite conflicts"),
      });
    }
  };

  runCancel = async () => {
    const { apply } = this.state;
    if (!apply || !apply.applyRef) return;
    this.setState({ busy: true, loadError: null });
    const result = await industryTemplateService.cancel(apply.applyRef, {});
    this.setState({ busy: false });
    if (result.source === "api" && result.payload) {
      this.setState({ apply: result.payload, step: "cancelled" });
    } else {
      this.setState({ loadError: result.error || new Error("Cancel failed") });
    }
  };

  parseDiff() {
    const { apply } = this.state;
    if (!apply || !apply.previewDiffJson) return null;
    try {
      return typeof apply.previewDiffJson === "string"
        ? JSON.parse(apply.previewDiffJson)
        : apply.previewDiffJson;
    } catch (e) {
      return null;
    }
  }

  renderStepper = () => {
    const active = stepIndex(this.state.step);
    return (
      <ol className="lux-itpl-steps" aria-label="Apply steps">
        {STEPS.map((step, index) => (
          <li
            key={step.id}
            className={classNames("lux-itpl-steps__item", {
              "is-active": index === active,
              "is-done": index < active || this.state.step === "committed",
            })}
          >
            <span className="lux-itpl-steps__index">{index + 1}</span>
            <span className="lux-itpl-steps__label">{step.label}</span>
          </li>
        ))}
      </ol>
    );
  };

  renderDiffSummary = (diff, conflicts) => {
    const changes =
      (diff && (diff.changes || diff.proposedChanges || diff.keys || diff.appConfigKeys)) || [];
    const changeList = Array.isArray(changes)
      ? changes
      : changes && typeof changes === "object"
        ? Object.keys(changes)
        : [];

    return (
      <div className="lux-itpl-diff">
        <div className="lux-itpl-diff__kpis">
          <article className="lux-itpl-diff__kpi is-blue">
            <strong>{changeList.length || (diff ? "—" : 0)}</strong>
            <span>Proposed keys</span>
          </article>
          <article className={classNames("lux-itpl-diff__kpi", conflicts.length ? "is-amber" : "is-green")}>
            <strong>{conflicts.length}</strong>
            <span>Conflicts</span>
          </article>
          <article className="lux-itpl-diff__kpi is-indigo">
            <strong>{(this.state.apply && this.state.apply.status) || "—"}</strong>
            <span>Apply status</span>
          </article>
        </div>

        {conflicts.length > 0 ? (
          <div className="lux-itpl-conflict-list">
            <h4>Overwrite conflicts</h4>
            <ul>
              {conflicts.slice(0, 12).map((item, index) => (
                <li key={index}>
                  {typeof item === "string" ? item : JSON.stringify(item)}
                </li>
              ))}
            </ul>
          </div>
        ) : (
          <p className="lux-itpl-muted">No overwrite conflicts detected for this preview.</p>
        )}

        {changeList.length > 0 ? (
          <div className="lux-itpl-change-list">
            <h4>Keys in scope</h4>
            <ul className="lux-itpl-chip-list">
              {changeList.slice(0, 30).map((item) => {
                const label =
                  typeof item === "string"
                    ? item
                    : item && (item.key || item.name || item.path)
                      ? String(item.key || item.name || item.path)
                      : JSON.stringify(item);
                return (
                  <li key={label} className="lux-itpl-chip">
                    {label}
                  </li>
                );
              })}
            </ul>
          </div>
        ) : null}

        {diff ? (
          <details className="lux-itpl-raw-details">
            <summary>Raw preview diff</summary>
            <pre className="lux-itpl-raw">{JSON.stringify(diff, null, 2)}</pre>
          </details>
        ) : null}
      </div>
    );
  };

  render() {
    const {
      loading,
      loadError,
      catalogs,
      templateRef,
      overwriteApproved,
      step,
      apply,
      busy,
    } = this.state;
    const diff = this.parseDiff();
    const conflicts =
      (diff && diff.conflicts) ||
      (apply && apply.overwriteConflictsJson
        ? (() => {
            try {
              return JSON.parse(apply.overwriteConflictsJson);
            } catch (e) {
              return [];
            }
          })()
        : []);
    const conflictCount = Array.isArray(conflicts) ? conflicts.length : 0;
    const selected = catalogs.find((c) => c.templateRef === templateRef);

    const kpiCards = [
      {
        id: "team",
        label: "Target team",
        value: commonUtils.getCurrentUserTeamId() || "—",
        hint: "Active user team",
        tone: "indigo",
        icon: "fe fe-users",
      },
      {
        id: "pack",
        label: "Selected pack",
        value: selected ? selected.industryPack || "—" : "—",
        hint: selected ? selected.name : "Choose a template",
        tone: "blue",
        icon: "fe fe-package",
      },
      {
        id: "step",
        label: "Wizard step",
        value: String(step).toUpperCase(),
        hint: apply && apply.applyRef ? apply.applyRef : "No apply yet",
        tone: "amber",
        icon: "fe fe-git-commit",
      },
      {
        id: "conflicts",
        label: "Conflicts",
        value: conflictCount,
        hint: overwriteApproved ? "Overwrite approved" : "Guard active",
        tone: conflictCount ? "rose" : "green",
        icon: "fe fe-alert-triangle",
      },
    ];

    const insights = [
      {
        id: "flow",
        tone: "indigo",
        icon: "fe fe-shuffle",
        title: "Preview → draft → commit",
        copy: "Nothing writes App Config until you commit a draft.",
      },
      {
        id: "guard",
        tone: "amber",
        icon: "fe fe-shield",
        title: "ITPL-009 overwrite guard",
        copy: "Approve overwrite explicitly when conflicts exist.",
      },
      {
        id: "catalog",
        tone: "blue",
        icon: "fe fe-package",
        title: "Browse catalog",
        copy: "Inspect pack payloads before applying.",
        path: "/admin/industry-templates",
      },
    ];

    return (
      <AdminLuxPage
        testId="industry-template-apply-page"
        className="lux-register-page lux-itpl-page"
        pageMeta={{
          tone: "indigo",
          icon: "fe fe-package",
          eyebrow: "Admin · Industry templates",
          titleLead: "Apply industry",
          titleAccent: "template",
          lede: "Preview → draft → commit. Conflicts require overwrite approval before App Config write.",
        }}
        dataSource="api"
        loading={loading}
        kpiCards={kpiCards}
        heroActions={
          <AdminActionButton to="/admin/industry-templates" variant="ghost" icon="fe fe-arrow-left">
            Catalog
          </AdminActionButton>
        }
      >
        {loading ? (
          <LuxRegisterEmptyState
            className="lux-register-empty--compact"
            title="Loading catalog"
            description="Fetching industry template packs for apply."
          />
        ) : null}
        <AdminLoadAlert
          error={loadError}
          fallback="Unable to load catalog."
          onDismiss={() => this.setState({ loadError: null })}
        />

        <AdminInsightStrip insights={insights} className="lux-itpl-insights" />
        {this.renderStepper()}

        {(step === "select" || step === "preview" || step === "draft") && (
          <section className="lux-hrms-dash__panel lux-itpl-wizard">
            <AdminPanelHead
              title="Apply controls"
              subtitle="Choose a published pack, then advance through preview and draft before writing App Config."
            />
            <div className="lux-itpl-wizard__body">
              <div className="lux-itpl-field">
                <label htmlFor="templateRef">Template pack</label>
                <select
                  id="templateRef"
                  className="lux-itpl-select"
                  value={templateRef}
                  disabled={busy || step !== "select"}
                  onChange={(e) => this.setState({ templateRef: e.target.value })}
                >
                  {catalogs.map((c) => (
                    <option key={c.templateRef} value={c.templateRef}>
                      {c.industryPack} — {c.name}
                    </option>
                  ))}
                </select>
              </div>

              <label className="lux-itpl-check">
                <input
                  id="overwriteApproved"
                  type="checkbox"
                  checked={overwriteApproved}
                  onChange={(e) => this.setState({ overwriteApproved: e.target.checked })}
                />
                <span>
                  Approve overwrite of existing App Config customizations
                  <small>Required when conflicts are present (ITPL-009)</small>
                </span>
              </label>

              <div className="lux-itpl-wizard__actions">
                {step === "select" && (
                  <AdminActionButton
                    type="button"
                    variant="primary"
                    icon="fe fe-eye"
                    disabled={busy || !templateRef}
                    onClick={this.runPreview}
                  >
                    {busy ? "Working…" : "Preview"}
                  </AdminActionButton>
                )}
                {step === "preview" && (
                  <>
                    <AdminActionButton
                      type="button"
                      variant="secondary"
                      icon="fe fe-file-plus"
                      disabled={busy}
                      onClick={this.runDraft}
                    >
                      Create draft
                    </AdminActionButton>
                    <AdminActionButton
                      type="button"
                      variant="ghost"
                      disabled={busy}
                      onClick={this.runCancel}
                    >
                      Cancel
                    </AdminActionButton>
                  </>
                )}
                {step === "draft" && (
                  <>
                    <AdminActionButton
                      type="button"
                      variant="primary"
                      icon="fe fe-check"
                      disabled={busy}
                      onClick={this.runCommit}
                    >
                      Commit to App Config
                    </AdminActionButton>
                    <AdminActionButton
                      type="button"
                      variant="ghost"
                      disabled={busy}
                      onClick={this.runCancel}
                    >
                      Cancel draft
                    </AdminActionButton>
                  </>
                )}
              </div>
            </div>
          </section>
        )}

        {apply && (
          <section className="lux-hrms-dash__panel lux-itpl-result">
            <AdminPanelHead
              title={`Apply ${apply.applyRef}`}
              subtitle={`Status ${apply.status}. Review conflicts before commit.`}
            />
            {conflictCount > 0 && (
              <LuxInlineAlert
                tone="warning"
                message={`${conflictCount} overwrite conflict(s). Check the overwrite box before commit.`}
              />
            )}
            {this.renderDiffSummary(diff, Array.isArray(conflicts) ? conflicts : [])}
          </section>
        )}

        {(step === "committed" || step === "cancelled") && apply && (
          <section className="lux-hrms-dash__panel">
            <AdminPanelHead
              title={step === "committed" ? "Committed" : "Cancelled"}
              subtitle={`Apply ${apply.applyRef} is now ${apply.status}.`}
            />
            <div className="lux-itpl-wizard__actions">
              <AdminActionButton to="/admin/industry-templates" variant="primary" icon="fe fe-package">
                Back to catalog
              </AdminActionButton>
              <AdminActionButton
                type="button"
                variant="ghost"
                onClick={() =>
                  this.setState({
                    step: "select",
                    apply: null,
                    overwriteApproved: false,
                  })
                }
              >
                Start another apply
              </AdminActionButton>
              <Link className="lux-admin-panel-link" to="/admin/appconfig">
                Open application config
                <i className="fe fe-arrow-right" aria-hidden="true" />
              </Link>
            </div>
          </section>
        )}
      </AdminLuxPage>
    );
  }
}

export default IndustryTemplateApplyPage;
