/**
 * Production deploy freshness — force reload + remote version check.
 * /version.json is written by release.sh and must not be long-cached.
 */
import envconfig from "env.config";

export const VERSION_JSON_PATH = `${process.env.PUBLIC_URL || ""}/version.json`;

export function getEmbeddedAppVersion() {
  return String((envconfig && envconfig.APP_VERSION) || "").trim();
}

export function normalizeVersion(raw) {
  const text = String(raw || "").trim();
  if (!text) return "";
  const match = text.match(/^(\d+\.\d+\.\d+)/);
  return match ? match[1] : text;
}

export function isRemoteVersionNewer(localVersion, remoteVersion) {
  const local = normalizeVersion(localVersion);
  const remote = normalizeVersion(remoteVersion);
  if (!local || !remote || local === remote) return false;

  const toParts = (v) =>
    v.split(".").map((part) => {
      const n = Number(part);
      return Number.isFinite(n) ? n : 0;
    });

  const a = toParts(local);
  const b = toParts(remote);
  const len = Math.max(a.length, b.length);
  for (let i = 0; i < len; i += 1) {
    const left = a[i] || 0;
    const right = b[i] || 0;
    if (right > left) return true;
    if (right < left) return false;
  }
  return false;
}

export async function fetchRemoteAppVersion({ fetchImpl = fetch, path = VERSION_JSON_PATH } = {}) {
  const response = await fetchImpl(`${path}?_=${Date.now()}`, {
    cache: "no-store",
    headers: { Accept: "application/json" },
  });
  if (!response || !response.ok) {
    throw new Error(`version.json HTTP ${response && response.status}`);
  }
  const payload = await response.json();
  return normalizeVersion(payload && payload.version);
}

export async function checkForAppUpdate(options = {}) {
  const localVersion = normalizeVersion(options.localVersion || getEmbeddedAppVersion());
  const remoteVersion = await fetchRemoteAppVersion(options);
  return {
    localVersion,
    remoteVersion,
    updateAvailable: isRemoteVersionNewer(localVersion, remoteVersion),
  };
}

export async function clearAppCaches() {
  if (typeof caches !== "undefined" && caches.keys) {
    const keys = await caches.keys();
    await Promise.all(keys.map((key) => caches.delete(key)));
  }
}

export async function unregisterServiceWorkers() {
  if (typeof navigator === "undefined" || !navigator.serviceWorker) {
    return;
  }
  const registrations = await navigator.serviceWorker.getRegistrations();
  await Promise.all(registrations.map((registration) => registration.unregister()));
}

/**
 * Hard refresh path for stale shells after production deploy.
 */
export async function forceReloadLatestApp({ locationRef = window.location } = {}) {
  try {
    await unregisterServiceWorkers();
  } catch (_err) {
    // continue — reload still helps
  }
  try {
    await clearAppCaches();
  } catch (_err) {
    // continue
  }
  const url = new URL(locationRef.href);
  url.searchParams.set("_reload", String(Date.now()));
  locationRef.replace(url.toString());
}

export function startAppUpdateWatcher({
  intervalMs = 5 * 60 * 1000,
  onUpdateAvailable,
  checkFn = checkForAppUpdate,
} = {}) {
  if (typeof onUpdateAvailable !== "function") {
    return () => {};
  }

  let cancelled = false;
  let timerId = null;

  const run = async () => {
    try {
      const result = await checkFn();
      if (!cancelled && result && result.updateAvailable) {
        onUpdateAvailable(result);
      }
    } catch (_err) {
      // Fail closed — offline / missing version.json must not break the app.
    }
  };

  run();
  if (intervalMs > 0) {
    timerId = setInterval(run, intervalMs);
  }

  const onFocus = () => {
    run();
  };
  if (typeof window !== "undefined") {
    window.addEventListener("focus", onFocus);
  }

  return () => {
    cancelled = true;
    if (timerId) clearInterval(timerId);
    if (typeof window !== "undefined") {
      window.removeEventListener("focus", onFocus);
    }
  };
}
