import React from "react";
import classNames from "classnames/bind";
import { PerformanceStatusBadge } from "views/performance/components/PerformanceLuxShared";

export default function GrowthPlanRegister({ plans, loading }) {
  if (loading) {
    return <div className="lux-perf-skeleton lux-perf-skeleton--panel" />;
  }
  if (!plans || !plans.length) {
    return (
      <div className="lux-perf-empty">
        <i className="fe fe-trending-up" aria-hidden="true" />
        <p>No growth plans yet.</p>
      </div>
    );
  }
  return (
    <div className="lux-perf-register">
      {plans.map((plan, index) => (
        <article key={plan.id} className="lux-perf-register__row">
          <span className="lux-perf-register__index">{index + 1}</span>
          <span className={classNames("lux-perf-register__rail", plan.tone && `is-${plan.tone}`)}>
            <i className="fe fe-trending-up" aria-hidden="true" />
          </span>
          <div className="lux-perf-register__main">
            <span className="lux-perf-register__eyebrow">{plan.employeeName}</span>
            <h3>{plan.title}</h3>
            <p>Mentor: {plan.mentorName || "—"}</p>
            <div className="lux-perf-register__meta">
              <PerformanceStatusBadge status={plan.status} />
              <span>{plan.progress}% complete</span>
              {plan.competencies && plan.competencies.length ? (
                <span>{plan.competencies.join(", ")}</span>
              ) : null}
            </div>
          </div>
        </article>
      ))}
    </div>
  );
}
