import { IntegrationSnapshotStrip } from "views/integrations/components/IntegrationRegisters";

export { IntegrationSnapshotStrip };

export function buildAdapterSnapshotMetrics(adapters) {
  const rows = adapters || [];
  const passed = rows.filter((row) => row.testStatus === "passed").length;
  const api = rows.filter((row) => row.transport === "api").length;
  const fileTransports = rows.filter((row) => row.transport === "file" || row.transport === "sftp").length;
  const avgSuccess = rows.length
    ? Math.round(rows.reduce((sum, row) => sum + (Number(row.successRatePct) || 0), 0) / rows.length)
    : 0;
  return [
    { id: "wrappers", label: "Wrappers", value: rows.length, tone: "violet" },
    { id: "passed", label: "Tests passed", value: passed, tone: "green" },
    { id: "api", label: "API adapters", value: api, tone: "blue" },
    { id: "success", label: "Avg success", value: `${avgSuccess}%`, tone: "indigo" },
  ];
}
