export const WORK_TIME_GOVERNANCE_FEATURE_KEYS = Object.freeze({
  APPROVAL_BULK_ACTIONS: "approval.bulk-actions",
  ADMIN_POLICY_MANAGEMENT: "admin.policy-management",
  OBSERVABILITY: "admin.observability",
  TIMESHEET_VALIDATION: "timesheet.validation",
  TIMESHEET_LATE_WORKFLOW: "timesheet.late-workflow",
  PROJECT_IMPORT: "integration.project-import",
  TIMESHEET_EXPORT: "integration.timesheet-export",
  SWIPE_INGEST: "attendance.swipe-ingest",
});

function titleCase(value) {
  return String(value || "")
    .replace(/[._-]+/g, " ")
    .replace(/\b\w/g, (letter) => letter.toUpperCase())
    .trim();
}

export function formatWorkTimeFeatureName(featureId) {
  const parts = String(featureId || "").split(".");
  return titleCase(parts[parts.length - 1]) || "Work-time feature";
}

export function getWorkTimeFamilyMeta(family) {
  const familyKey = String(family || "admin").toLowerCase();
  return (
    WORK_TIME_GOVERNANCE_FAMILY_META[familyKey] || {
      label: titleCase(familyKey),
      icon: "fe fe-grid",
      tone: "slate",
    }
  );
}

export function getWorkTimeSourceLabel(source) {
  return WORK_TIME_GOVERNANCE_SOURCE_LABELS[source] || titleCase(source) || "Catalog default";
}

function normalizeRoleGate(roleGate) {
  if (!roleGate || typeof roleGate !== "object") {
    return null;
  }
  return {
    module: roleGate.module || "",
    group: roleGate.group || "",
    key: roleGate.key || "",
  };
}

export function normalizeProjectFeatureOverride(row) {
  if (!row || typeof row !== "object") {
    return null;
  }
  return {
    id: row.id != null ? row.id : null,
    userTeamId: row.userTeamId != null ? row.userTeamId : null,
    projectId: row.projectId != null ? row.projectId : null,
    featureKey: row.featureKey || "",
    enabled: row.enabled === true,
    config: row.config && typeof row.config === "object" ? row.config : null,
    effectiveFrom: row.effectiveFrom || null,
    effectiveTo: row.effectiveTo || null,
    version: row.version != null ? row.version : null,
    createdBy: row.createdBy != null ? row.createdBy : null,
    createdDate: row.createdDate || null,
    modifiedBy: row.modifiedBy != null ? row.modifiedBy : null,
    lastModifiedDate: row.lastModifiedDate || null,
  };
}

export function normalizeWorkTimeFeature(row) {
  if (!row || typeof row !== "object" || !row.id) {
    return null;
  }

  const dependencyStatus =
    row.dependencyStatus && typeof row.dependencyStatus === "object"
      ? Object.keys(row.dependencyStatus).reduce((result, key) => {
          result[key] = row.dependencyStatus[key] === true;
          return result;
        }, {})
      : {};
  const blockedByDependencies = Array.isArray(row.blockedByDependencies)
    ? row.blockedByDependencies.filter(Boolean)
    : Object.keys(dependencyStatus).filter((key) => dependencyStatus[key] !== true);
  const source = WORK_TIME_GOVERNANCE_SOURCE_LABELS[row.source]
    ? row.source
    : "CATALOG_DEFAULT";

  return {
    id: row.id,
    featureKey: row.id,
    name: row.name || formatWorkTimeFeatureName(row.id),
    family: String(row.family || "admin").toLowerCase(),
    module: row.module || "",
    group: row.group || "",
    key: row.key || "",
    applicationConfigPath: [row.module, row.group, row.key].filter(Boolean).join("."),
    defaultEnabled: row.defaultEnabled === true,
    projectOverrideAllowed: row.projectOverrideAllowed === true,
    dependencies: Array.isArray(row.dependencies) ? row.dependencies.filter(Boolean) : [],
    dependencyStatus,
    blockedByDependencies,
    roleGate: normalizeRoleGate(row.roleGate),
    roleAllowed:
      row.roleAllowed === true ? true : row.roleAllowed === false ? false : null,
    inherited: row.inherited === true,
    inheritedEnabled: row.inheritedEnabled === true,
    effectiveEnabled: row.effectiveEnabled === true,
    source,
    sourceLabel: getWorkTimeSourceLabel(source),
    effectiveConfig:
      row.effectiveConfig && typeof row.effectiveConfig === "object"
        ? row.effectiveConfig
        : null,
    projectOverride: normalizeProjectFeatureOverride(row.projectOverride),
  };
}

export function findEffectiveWorkTimeFeature(features, featureKey) {
  if (!featureKey) {
    return null;
  }
  return (
    (Array.isArray(features) ? features : []).find(
      (feature) => feature && feature.id === featureKey
    ) || null
  );
}

export function isWorkTimeFeatureEnabled(features, featureKey) {
  const feature = findEffectiveWorkTimeFeature(features, featureKey);
  return Boolean(feature && feature.effectiveEnabled === true);
}

export function mergeProjectFeatureOverrides(features, overrides) {
  const byFeatureKey = (Array.isArray(overrides) ? overrides : [])
    .map(normalizeProjectFeatureOverride)
    .filter((row) => row && row.featureKey)
    .reduce((result, row) => {
      result[row.featureKey] = row;
      return result;
    }, {});

  return (Array.isArray(features) ? features : []).map((feature) => {
    const projectOverride = byFeatureKey[feature.id] || feature.projectOverride || null;
    return {
      ...feature,
      projectOverride,
      hasProjectOverride: Boolean(projectOverride),
    };
  });
}

export function groupWorkTimeFeatures(features) {
  const grouped = (Array.isArray(features) ? features : []).reduce((result, feature) => {
    const family = feature.family || "admin";
    if (!result[family]) {
      result[family] = [];
    }
    result[family].push(feature);
    return result;
  }, {});

  return Object.keys(grouped)
    .sort((left, right) => {
      const leftIndex = WORK_TIME_GOVERNANCE_FAMILY_ORDER.indexOf(left);
      const rightIndex = WORK_TIME_GOVERNANCE_FAMILY_ORDER.indexOf(right);
      const safeLeft = leftIndex === -1 ? Number.MAX_SAFE_INTEGER : leftIndex;
      const safeRight = rightIndex === -1 ? Number.MAX_SAFE_INTEGER : rightIndex;
      return safeLeft - safeRight || left.localeCompare(right);
    })
    .map((family) => ({
      id: family,
      ...getWorkTimeFamilyMeta(family),
      features: grouped[family].slice().sort((left, right) => left.name.localeCompare(right.name)),
    }));
}

export function buildProjectFeatureOverridePayload(feature, enabled) {
  const payload = {
    featureKey: feature.id,
    enabled: enabled === true,
  };
  const existing = feature.projectOverride;

  if (existing) {
    if (existing.config != null) {
      payload.config = existing.config;
    }
    if (existing.effectiveFrom) {
      payload.effectiveFrom = existing.effectiveFrom;
    }
    if (existing.effectiveTo) {
      payload.effectiveTo = existing.effectiveTo;
    }
    if (existing.version != null) {
      payload.version = existing.version;
    }
  }

  return payload;
}

export function normalizeProjectScope(value) {
  const normalized = String(value == null ? "" : value).trim();
  return /^[1-9]\d*$/.test(normalized) ? normalized : null;
}
