import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isIntegrationCenterEnabled } from "config/integration-center.config";
import { INTEGRATION_LOGS_PAGE_META } from "config/integration-center-nav.config";
import { buildLogsKpis } from "config/integration-center.utils";
import { integrationCenterService } from "_services/integrationCenter.service";
import IntegrationsLuxPage, {
  IntegrationLuxPanel,
} from "views/integrations/components/IntegrationsLuxShared";
import {
  IntegrationLevelFilter,
  IntegrationLogsRegister,
  IntegrationSnapshotStrip,
  buildLogsSnapshotMetrics,
} from "views/integrations/components/IntegrationRegisters";

class IntegrationLogsPage extends Component {
  state = { loading: true, loadError: null, dataSource: null, logs: [], levelFilter: "ALL", kpiCards: [] };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    const { levelFilter } = this.state;
    this.setState({ loading: true, loadError: null });
    try {
      const filters = {};
      if (levelFilter !== "ALL") {
        filters.level = levelFilter;
      }
      const result = await integrationCenterService.listIntegrationLogs(filters);
      const logs = result.payload || [];
      this.setState({
        loading: false,
        dataSource: result.source,
        logs,
        kpiCards: buildLogsKpis(logs),
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load integration logs.",
      });
    }
  };

  handleLevelChange = (levelFilter) => {
    this.setState({ levelFilter }, this.loadData);
  };

  render() {
    if (!isIntegrationCenterEnabled()) {
      return <PersonaAccessDenied title="Integration logs" message="Integration center is not enabled for this organization." />;
    }

    const { loading, loadError, dataSource, logs, levelFilter, kpiCards } = this.state;

    return (
      <IntegrationsLuxPage
        pageMeta={INTEGRATION_LOGS_PAGE_META}
        pageId="logs"
        shellTitle="Integration logs"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        onRefresh={this.loadData}
        refreshLoading={loading}
      >
        {loadError ? <p className="lux-integ-error">{loadError}</p> : null}
        <IntegrationSnapshotStrip
          loading={loading}
          badgeIcon="fe fe-file-text"
          badgeLabel="Event telemetry"
          metrics={buildLogsSnapshotMetrics(logs)}
        />
        <IntegrationLuxPanel
          title="Event log"
          meta="Structured connector events with correlation IDs"
          icon="fe fe-file-text"
          accent="slate"
          featured
          actions={<IntegrationLevelFilter value={levelFilter} onChange={this.handleLevelChange} />}
        >
          <IntegrationLogsRegister logs={logs} loading={loading} />
        </IntegrationLuxPanel>
      </IntegrationsLuxPage>
    );
  }
}

export default IntegrationLogsPage;
