import dateUtils from "_helpers/date.utils";
import { getDayCapacityMinutesForEmployee } from "./plannerCapacity.utils";
import { isEmployeeOnLeave, isPlannerLeaveOrHolidayItem } from "./plannerLeave.utils";

export const PLANNER_DAY_CAPACITY_MINUTES = 8 * 60;

export const PLANNER_STATUS_COLORS = {
  ASSIGNED: "#3b82f6",
  INPROGRESS: "#f59e0b",
  COMPLETED: "#10b981",
  CLOSED: "#475569",
  NEW: "#0ea5e9",
  ONGOING: "#8b5cf6",
  PAUSED: "#ea580c",
  DEFAULT: "#64748b",
};

export const PLANNER_STATUS_FILTER_OPTIONS = {
  SHOW: {
    options: [
      { name: "ALL", label: "All" },
      { name: "ASSIGNED", label: "Assigned" },
      { name: "INPROGRESS", label: "In progress" },
      { name: "COMPLETED", label: "Completed" },
      { name: "CLOSED", label: "Closed" },
    ],
    selected: "ALL",
  },
  filterText: "",
};

export function employeeIdsMatch(workItemEmployeeId, selectedId) {
  if (workItemEmployeeId == null || selectedId == null) return false;
  const a = Number(workItemEmployeeId);
  const b = Number(selectedId);
  if (!Number.isNaN(a) && !Number.isNaN(b)) return a === b;
  return String(workItemEmployeeId).trim() === String(selectedId).trim();
}

export function normalizeWorkItemStatus(status) {
  return String(status || "").trim().toUpperCase();
}

export function getWorkItemStatusColor(status) {
  return PLANNER_STATUS_COLORS[normalizeWorkItemStatus(status)] || PLANNER_STATUS_COLORS.DEFAULT;
}

export function getWorkItemEmployeeId(item) {
  if (!item) return null;
  if (item.employeeId != null && item.employeeId !== "") return item.employeeId;
  if (item.assignedEmployeeId != null && item.assignedEmployeeId !== "") return item.assignedEmployeeId;
  if (item.resourceEmployeeId != null && item.resourceEmployeeId !== "") return item.resourceEmployeeId;
  if (item.employee && item.employee.id != null) return item.employee.id;
  return null;
}

export function getItemStartDate(item) {
  const st = normalizeWorkItemStatus(item.status);
  const startValue =
    item.actualStartTime && (st === "COMPLETED" || st === "CLOSED")
      ? item.actualStartTime
      : item.estStartTime || item.estimatedStartTime;
  return startValue ? new Date(startValue) : null;
}

export function getItemEndDate(item, startDate) {
  const st = normalizeWorkItemStatus(item.status);
  const endValue =
    item.actualEndTime && (st === "COMPLETED" || st === "CLOSED")
      ? item.actualEndTime
      : item.estCompletionTime || item.estimatedEndTime || item.actualCompletionTime;
  if (endValue) return new Date(endValue);
  const duration = item.estDurationInMins || item.durationInMinutes || 60;
  return new Date(startDate.getTime() + duration * 60 * 1000);
}

export function formatPlannerHours(minutes) {
  const mins = Math.max(0, Math.round(minutes || 0));
  const hours = Math.floor(mins / 60);
  const rem = mins % 60;
  return `${hours}h ${String(rem).padStart(2, "0")}m`;
}

export function getPlannerDays(startMoment, horizonWeeks) {
  const totalDays = Math.max(1, horizonWeeks) * 7;
  return [...Array(totalDays)].map((_, idx) => startMoment.clone().add(idx, "days"));
}

export function isWeekendDay(dayMoment) {
  const iw = dayMoment.isoWeekday();
  return iw === 6 || iw === 7;
}

export function getPlannerRosterEmployees(employees) {
  return (employees || []).filter((e) => e != null && e.deleted !== true && e.active !== false);
}

export function getOverlappedMinutes(startDate, endDate, dayMoment) {
  if (!startDate || !endDate) return 0;
  const dayStart = dayMoment.clone().startOf("day");
  const dayEnd = dayMoment.clone().endOf("day");
  const itemStart = dateUtils.convertDateToMoment(startDate);
  const itemEnd = dateUtils.convertDateToMoment(endDate);
  const overlappedStart = itemStart.isAfter(dayStart) ? itemStart : dayStart;
  const overlappedEnd = itemEnd.isBefore(dayEnd) ? itemEnd : dayEnd;
  if (overlappedEnd.diff(overlappedStart, "minutes") <= 0) return 0;
  return overlappedEnd.diff(overlappedStart, "minutes");
}

export function getHolidayDateKeys(holidayItems) {
  const keys = new Set();
  (holidayItems || []).forEach((h) => {
    if (!h || !h.holidayDate) return;
    const m = dateUtils.convertDateStringToMoment(h.holidayDate);
    if (m && m.isValid()) keys.add(m.format("YYYY-MM-DD"));
  });
  return keys;
}

export function getLeaveActivityKeys(workItems) {
  const keys = new Set();
  (workItems || []).forEach((item) => {
    const type = String(item.taskType || "").toUpperCase();
    if (type !== "LEAVE" && type !== "HOLIDAY") return;
    const start = getItemStartDate(item);
    if (!start) return;
    keys.add(dateUtils.convertDateToMoment(start).format("YYYY-MM-DD"));
  });
  return keys;
}

/** Billable / non-billable / leave-holiday bucket for planner charts. */
export function classifyPlannerWorkItemType(item) {
  if (!item) return "nonBillable";
  if (isPlannerLeaveOrHolidayItem(item)) {
    return "leaveHoliday";
  }
  const type = String(item.taskType || "").toUpperCase().replace(/-/g, "_");
  if (type === "NON_PROJECT" || type === "NONPROJECT") {
    return "nonBillable";
  }
  if (type === "PROJECT" || (item.projectId != null && item.projectId !== "")) {
    return "billable";
  }
  return "nonBillable";
}

/** Capacity days in horizon — all calendar days; optional holiday reduction. */
export function getCapacityDayMoments(startMoment, horizonWeeks, holidayKeys, reduceForHolidays) {
  const days = getPlannerDays(startMoment.clone(), horizonWeeks);
  if (!reduceForHolidays || !holidayKeys || holidayKeys.size === 0) return days;
  return days.filter((d) => !holidayKeys.has(d.format("YYYY-MM-DD")));
}

export function getDayCapacityMinutes(dayMoment, reduceForHolidays, holidayKeys) {
  if (reduceForHolidays && holidayKeys && holidayKeys.has(dayMoment.format("YYYY-MM-DD"))) {
    return 0;
  }
  return PLANNER_DAY_CAPACITY_MINUTES;
}

export function getPlannerFocusEmployeeName(employees, selectedEmployeeId) {
  if (selectedEmployeeId == null) return null;
  const match = (employees || []).find((e) => employeeIdsMatch(e.id, selectedEmployeeId));
  return match ? match.name : `Employee ${selectedEmployeeId}`;
}

/** Empty-state copy for Timeline / Gantt lane lists */
export function getPlannerScheduleEmptyState({
  workItems,
  filterOptions,
  selectedEmployeeId,
  employees,
  laneFilterText,
  visibleLaneCount,
}) {
  const allItems = filterPlannerWorkItems(workItems, filterOptions, null);
  const scopedItems = filterPlannerWorkItems(workItems, filterOptions, selectedEmployeeId);
  const search = (laneFilterText || "").trim().toLowerCase();

  if (visibleLaneCount > 0) return null;

  if (allItems.length === 0) {
    return {
      title: "No scheduled work in this horizon",
      detail: "Adjust status filters, widen the date range, or assign work from Team roster.",
    };
  }

  if (selectedEmployeeId != null && scopedItems.length === 0) {
    const name = getPlannerFocusEmployeeName(employees, selectedEmployeeId);
    return {
      title: `No work assigned to ${name}`,
      detail: "Use the employee menu and choose All team, or select someone who has work in this range.",
    };
  }

  if (search.length >= 2) {
    return {
      title: "No lanes match your search",
      detail: "Clear the lane filter or try a different keyword.",
    };
  }

  return {
    title: "No lanes to show",
    detail: "Work items may be missing start dates. Try All team or change the view mode (Tasks / Projects).",
  };
}

export function filterPlannerWorkItems(items, filterOptions, employeeId) {
  const status = filterOptions.SHOW && filterOptions.SHOW.selected;
  const statusFilter = normalizeWorkItemStatus(status);
  const text = (filterOptions.filterText || "").trim().toLowerCase();
  return (items || []).filter((item) => {
    const itemStatus = normalizeWorkItemStatus(item.status);
    const matchesStatus = status === "ALL" || itemStatus === statusFilter;
    const haystack = `${item.name || ""} ${item.projectName || ""} ${item.taskName || ""} ${item.taskActCategory || ""}`.toLowerCase();
    const matchesText = text.length < 3 || haystack.includes(text);
    const matchesEmployee = !employeeId || employeeIdsMatch(getWorkItemEmployeeId(item), employeeId);
    return matchesStatus && matchesText && matchesEmployee;
  });
}

export function resolvePlannerRowKeyAndTitle(item, viewMode) {
  if (viewMode === "WORK_ITEMS") {
    return {
      key: String(item.id),
      title: item.name || item.taskName || item.taskActCategory || "Work item",
    };
  }
  if (viewMode === "PROJECTS") {
    return {
      key: String(item.projectId != null ? item.projectId : item.id),
      title: item.projectName || item.name || "Untitled",
    };
  }
  return {
    key: String(item.taskId != null ? item.taskId : item.id),
    title: item.taskName || item.name || "Untitled",
  };
}

export function buildUtilizationByResource({
  employees,
  workItems,
  startMoment,
  horizonWeeks,
  holidayKeys,
  reduceForHolidays,
  leaveMap,
  capacityOverrides,
}) {
  const roster = getPlannerRosterEmployees(employees);
  const days = getPlannerDays(startMoment.clone(), horizonWeeks);

  const capacityPerEmployee = (employee) =>
    days.reduce((sum, dayMoment) => {
      const dayKey = dayMoment.format("YYYY-MM-DD");
      if (isEmployeeOnLeave(leaveMap, employee.id, dayKey)) return sum;
      return (
        sum +
        getDayCapacityMinutesForEmployee(employee, dayMoment, {
          holidayKeys,
          reduceForHolidays,
          leaveKeys: null,
          capacityOverrides,
        })
      );
    }, 0) || PLANNER_DAY_CAPACITY_MINUTES;

  const minutesForEmployee = (employeeId) =>
    (workItems || [])
      .filter((item) => !isPlannerLeaveOrHolidayItem(item))
      .filter((item) => employeeIdsMatch(getWorkItemEmployeeId(item), employeeId))
      .reduce((sum, item) => {
        const itemStart = getItemStartDate(item);
        if (!itemStart) return sum;
        const itemEnd = getItemEndDate(item, itemStart);
        const itemMinutes = days.reduce(
          (daySum, dayMoment) => daySum + getOverlappedMinutes(itemStart, itemEnd, dayMoment),
          0
        );
        return sum + itemMinutes;
      }, 0);

  const rows = roster.map((employee) => {
    const cap = capacityPerEmployee(employee);
    const minutes = minutesForEmployee(employee.id);
    const utilization = Math.round((minutes / Math.max(cap, 1)) * 100);
    return {
      id: employee.id,
      name: employee.name,
      minutes,
      utilization,
      freeMinutes: Math.max(0, cap - minutes),
      dailyCapacityMins: getDayCapacityMinutesForEmployee(employee, days[0] || startMoment, {
        holidayKeys,
        reduceForHolidays,
        capacityOverrides,
      }),
    };
  });

  return { rows, capacityPerEmployee: roster.length ? capacityPerEmployee(roster[0]) : PLANNER_DAY_CAPACITY_MINUTES };
}

export function buildPlannerRange(weekStartMoment, horizonWeeks) {
  return {
    startDateMoment: weekStartMoment.clone(),
    endDateMoment: weekStartMoment
      .clone()
      .add(horizonWeeks * 7 - 1, "days")
      .endOf("day"),
  };
}

/** Map project id → project row (for details URL prefixes). */
export function buildProjectDetailsLookup(projects) {
  const map = new Map();
  (projects || []).forEach((project) => {
    if (project != null && project.id != null) {
      map.set(String(project.id), project);
    }
  });
  return map;
}

/** Route segment for `/project/details/…` — matches project list NavLinks. */
export function resolveProjectDetailsPath(projectId, projectLookup) {
  if (projectId == null || projectId === "" || projectId === "none") {
    return null;
  }
  const key = String(projectId);
  const project = projectLookup && projectLookup.get(key);
  if (project && project.itemIdUserTeamPrefix) {
    return project.itemIdUserTeamPrefix;
  }
  return key;
}
