import React from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";

const TYPE_ICONS = {
  AL: "fe-sun",
  SL: "fe-thermometer",
  CL: "fe-heart",
  PL: "fe-user",
  ML: "fe-smile",
  default: "fe-calendar",
};

function getTypeIcon(code) {
  return TYPE_ICONS[String(code || "").toUpperCase()] || TYPE_ICONS.default;
}

function LeaveBalanceCards({ cards, loading, onApplyClick }) {
  if (loading) {
    return (
      <section className="lux-leave-balance lux-hrms-dash__panel" aria-busy="true">
        <div className="lux-leave-balance__skeleton-grid">
          {[1, 2, 3].map((k) => (
            <div key={k} className="lux-leave-balance__card lux-leave-balance__card--skeleton" />
          ))}
        </div>
      </section>
    );
  }

  const list = cards || [];

  return (
    <section className="lux-leave-balance lux-hrms-dash__panel" aria-label="Leave balances">
      <header className="lux-hrms-dash__panel-head lux-leave-balance__head">
        <div>
          <span className="lux-leave-panel__eyebrow">Balances</span>
          <h2 className="lux-hrms-dash__panel-title">Leave balances</h2>
          <p className="lux-hrms-dash__panel-sub">
            Entitlement and usage by type · policies under Admin → Leave policies
          </p>
        </div>
        {typeof onApplyClick === "function" ? (
          <button
            type="button"
            className="lux-leave-hero__cta"
            title="Apply leave"
            onClick={onApplyClick}
          >
            <i className="fe fe-plus" aria-hidden="true" />
            Apply leave
          </button>
        ) : null}
      </header>

      <div className="lux-hrms-dash__panel-body">
        {list.length === 0 ? (
          <div className="lux-leave-balance__empty">
            <span className="lux-leave-balance__empty-icon" aria-hidden="true">
              <i className="fe fe-calendar" />
            </span>
            <strong>No leave usage yet</strong>
            <p>Apply for leave or sync from HR to see balances and usage here.</p>
          </div>
        ) : (
          <div className="lux-leave-balance__grid">
            {list.map((card) => (
              <article
                key={card.code}
                className={classNames("lux-leave-balance__card", `is-${String(card.code).toLowerCase()}`)}
              >
                <span className="lux-leave-balance__type-icon" aria-hidden="true">
                  <i className={`fe ${getTypeIcon(card.code)}`} />
                </span>
                <span className="lux-leave-balance__type">{card.label}</span>
                <div className="lux-leave-balance__metric">
                  {card.hasEntitlement ? (
                    <>
                      <CountUp
                        end={card.available != null ? card.available : card.balance != null ? card.balance : 0}
                        decimals={
                          ((card.available != null ? card.available : card.balance) || 0) % 1 ? 1 : 0
                        }
                        duration={0.8}
                      />
                      <span className="lux-leave-balance__unit">days available</span>
                    </>
                  ) : (
                    <>
                      <CountUp end={card.usedDays} decimals={card.usedDays % 1 ? 1 : 0} duration={0.8} />
                      <span className="lux-leave-balance__unit">days used</span>
                    </>
                  )}
                </div>
                <p className="lux-leave-balance__meta">
                  {card.hasEntitlement
                    ? `${card.usedDays} used · ${card.entitlement} entitled`
                    : card.requests != null
                      ? `${card.requests} request${card.requests === 1 ? "" : "s"}`
                      : "Usage from approved leave"}
                </p>
                <p className="lux-leave-balance__policy-hint">{card.remainingLabel}</p>
              </article>
            ))}
          </div>
        )}
      </div>
    </section>
  );
}

export default LeaveBalanceCards;
