import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import { sanitizeUiCopy } from "_helpers/ui-copy.utils";
import { useReportPageDataSource } from "views/common/PageChromeContext";
import LuxKpiStrip from "views/common/fragments/LuxKpiStrip";

export const MY_WORK_QUICK_LINKS = [
  { path: "/workspace/approvals", label: "Approvals", icon: "fe fe-inbox", desc: "Leave, timesheet, and attendance sign-off", tone: "blue" },
  { path: "/people/timesheet", label: "Timesheet", icon: "fe fe-clock", desc: "Submit and review your hours", tone: "amber" },
  { path: "/people/attendance", label: "Attendance", icon: "fe fe-calendar", desc: "Regularize punches and exceptions", tone: "violet" },
  { path: "/people/onboarding/my-tasks", label: "Onboarding", icon: "fe fe-user-plus", desc: "Complete assigned lifecycle tasks", tone: "green" },
];

export function WorkspaceHeroActions({ dataSource, demoLabel, children }) {
  useReportPageDataSource(dataSource);
  return (
    <div className="lux-workspace-home-hero__actions">
      <div className="lux-workspace-home-hero__buttons">{children}</div>
    </div>
  );
}

export function WorkspaceActionButton({
  to,
  onClick,
  children,
  icon,
  variant = "primary",
  type = "button",
  disabled = false,
  className,
  title,
}) {
  const content = icon ? (
    <>
      <i className={icon} aria-hidden="true" />
      <span>{children}</span>
    </>
  ) : (
    children
  );

  if (to) {
    return (
      <Link
        to={to}
        className={classNames("lux-module-hero__text-link", className)}
      >
        {content}
      </Link>
    );
  }

  const classes = classNames("lux-onb-action lux-my-work-action", `lux-onb-action--${variant}`, className);
  return (
    <button type={type} className={classes} onClick={onClick} disabled={disabled} title={title}>
      {content}
    </button>
  );
}

export function WorkspaceKpiStrip({ cards, loading, className }) {
  return (
    <LuxKpiStrip
      cards={cards}
      loading={loading}
      className={classNames("lux-workspace-home-kpi-strip", className)}
    />
  );
}

/** Rich 3-column insight cards for workspace home */
export function WorkspaceInsightStrip({ insights, className }) {
  if (!insights || insights.length === 0) {
    return null;
  }

  return (
    <div className={classNames("lux-workspace-home-insights", className)} role="list">
      {insights.map((insight) => {
        const tone = insight.tone === "mint" ? "green" : insight.tone;
        const body = (
          <>
            <span className="lux-workspace-home-insight__icon" aria-hidden="true">
              <i className={insight.icon} />
            </span>
            <div className="lux-workspace-home-insight__copy">
              <strong>{insight.title}</strong>
              <p>{insight.copy}</p>
            </div>
            {insight.path && <i className="fe fe-chevron-right lux-workspace-home-insight__chevron" aria-hidden="true" />}
          </>
        );
        const cardClass = classNames("lux-workspace-home-insight", tone && `is-${tone}`);

        if (insight.path) {
          return (
            <Link key={insight.id} to={insight.path} className={cardClass} role="listitem">
              {body}
            </Link>
          );
        }

        return (
          <article key={insight.id} className={cardClass} role="listitem">
            {body}
          </article>
        );
      })}
    </div>
  );
}

export function WorkspaceQuickNav({ links = MY_WORK_QUICK_LINKS, eyebrow = "Navigate", title = "Operating shortcuts" }) {
  if (!links || links.length === 0) {
    return null;
  }

  return (
    <section className="lux-workspace-home-quick-nav" aria-label={title}>
      <header className="lux-admin-quick-nav__head">
        <div>
          {eyebrow && <span className="lux-hrms-dash__section-eyebrow">{sanitizeUiCopy(eyebrow)}</span>}
          {title && <h2 className="lux-hrms-dash__section-title">{title}</h2>}
        </div>
      </header>
      <div className="lux-admin-quick-nav__grid">
        {links.map((item) => (
          <Link
            key={item.path}
            to={item.path}
            className={classNames("lux-admin-quick-card lux-workspace-home-quick-card", item.tone && `is-${item.tone}`)}
          >
            <span className="lux-admin-quick-card__icon" aria-hidden="true">
              <i className={item.icon} />
            </span>
            <span className="lux-admin-quick-card__copy">
              <strong>{item.label}</strong>
              <small>{item.desc}</small>
            </span>
            <i className="fe fe-arrow-right lux-admin-quick-card__chevron" aria-hidden="true" />
          </Link>
        ))}
      </div>
    </section>
  );
}

export function WorkspacePanelHead({ title, subtitle, actions }) {
  return (
    <header className={classNames("lux-hrms-dash__panel-head", { "lux-hrms-dash__panel-head--stack": subtitle })}>
      <div>
        <h2 className="lux-hrms-dash__panel-title">{title}</h2>
        {subtitle && <p className="lux-hrms-dash__panel-sub">{sanitizeUiCopy(subtitle)}</p>}
      </div>
      {actions && <div className="lux-hrms-dash__panel-actions">{actions}</div>}
    </header>
  );
}
