import React from "react";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import {
  formatEventTimeRange,
  getCalendarEventStatusMeta,
  getEventDetailHref,
} from "./userCalendar.utils";

export default function LuxUserCalendarEventPanel({ event, viewModeLabel, onClose }) {
  if (!event) return null;

  const meta = getCalendarEventStatusMeta(event.status);
  const href = getEventDetailHref(event);
  const item = event.resource || {};

  const facts = [
    { label: "Type", value: viewModeLabel },
    { label: "Status", value: meta.label },
    { label: "Schedule", value: formatEventTimeRange(event) },
  ];

  if (event.viewMode === "WORKITEMS") {
    if (item.projectName) facts.push({ label: "Project", value: item.projectName });
    if (item.taskName) facts.push({ label: "Deliverable", value: item.taskName });
    if (item.taskActCategory) facts.push({ label: "Category", value: item.taskActCategory });
    if (item.itemIdUserTeamPrefix) facts.push({ label: "Reference", value: item.itemIdUserTeamPrefix });
  } else if (event.viewMode === "PROJECT") {
    if (item.projectcode) facts.push({ label: "Code", value: item.projectcode });
    if (item.projectCategory) facts.push({ label: "Category", value: item.projectCategory });
  } else if (item.taskActCategory) {
    facts.push({ label: "Category", value: item.taskActCategory });
  }

  return (
    <section className={classNames("lux-user-calendar-panel", `is-${meta.tone}`)} aria-label="Event details">
      <header className="lux-user-calendar-panel__head">
        <div>
          <span className={classNames("lux-user-calendar-panel__badge", `is-${meta.tone}`)}>{meta.label}</span>
          <h3 className="lux-user-calendar-panel__title">{event.title}</h3>
          {event.desc && <p className="lux-user-calendar-panel__subtitle">{event.desc}</p>}
        </div>
        <button type="button" className="lux-user-calendar-panel__close" onClick={onClose} aria-label="Close details">
          <i className="fe fe-x" aria-hidden="true" />
        </button>
      </header>

      <dl className="lux-user-calendar-panel__facts">
        {facts.map((fact) => (
          <div key={fact.label} className="lux-user-calendar-panel__fact">
            <dt>{fact.label}</dt>
            <dd>{fact.value}</dd>
          </div>
        ))}
      </dl>

      <div className="lux-user-calendar-panel__actions">
        {href && (
          <Link to={href} className="lux-user-calendar-panel__btn lux-user-calendar-panel__btn--primary">
            <i className="fe fe-external-link" aria-hidden="true" />
            Open record
          </Link>
        )}
        <button type="button" className="lux-user-calendar-panel__btn" onClick={onClose}>
          Close
        </button>
      </div>
    </section>
  );
}
