import React, { Component } from "react";
import classNames from "classnames/bind";
import { SCHEDULE_FREQUENCIES, SCHEDULE_STATUSES } from "config/analytics-platform.config";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { AnalyticsActionButton } from "views/analytics/components/AnalyticsLuxShared";

const STATUS_TONE = {
  [SCHEDULE_STATUSES.ACTIVE]: "green",
  [SCHEDULE_STATUSES.PAUSED]: "amber",
  [SCHEDULE_STATUSES.FAILED]: "rose",
};

const JOB_TONE = {
  QUEUED: "slate",
  RUNNING: "blue",
  COMPLETE: "green",
  FAILED: "rose",
};

const EMPTY_FORM = {
  reportId: "",
  reportName: "",
  frequency: SCHEDULE_FREQUENCIES.WEEKLY,
  recipients: "",
};

function formatTimestamp(value) {
  if (!value) return "—";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleString();
}

export default class ScheduledReportsPanel extends Component {
  state = {
    selectedScheduleId: null,
    form: { ...EMPTY_FORM },
    saving: false,
    queueing: false,
    saveError: null,
  };

  componentDidUpdate(prevProps) {
    const schedules = this.props.schedules || [];
    if (!this.state.selectedScheduleId && schedules.length) {
      this.selectSchedule(schedules[0]);
    }
  }

  selectSchedule = (schedule) => {
    if (!schedule) return;
    this.setState({
      selectedScheduleId: schedule.id,
      form: {
        reportId: schedule.reportId || "",
        reportName: schedule.reportName || "",
        frequency: schedule.frequency || SCHEDULE_FREQUENCIES.WEEKLY,
        recipients: (schedule.recipients || []).join(", "),
      },
      saveError: null,
    });
  };

  handleFormChange = (field) => (event) => {
    this.setState((prev) => ({
      form: { ...prev.form, [field]: event.target.value },
    }));
  };

  handleSave = async (event) => {
    event.preventDefault();
    const { form } = this.state;
    const { onSaveSchedule } = this.props;
    if (!onSaveSchedule) return;

    this.setState({ saving: true, saveError: null });
    try {
      await onSaveSchedule({
        id: this.state.selectedScheduleId || undefined,
        reportId: form.reportId || null,
        reportName: form.reportName,
        frequency: form.frequency,
        recipients: form.recipients
          .split(",")
          .map((row) => row.trim())
          .filter(Boolean),
        status: SCHEDULE_STATUSES.ACTIVE,
      });
      this.setState({ saving: false });
    } catch (error) {
      this.setState({
        saving: false,
        saveError: (error && error.message) || "Unable to save schedule.",
      });
    }
  };

  handleQueueExport = async (schedule) => {
    const { onQueueExport } = this.props;
    if (!onQueueExport || !schedule) return;
    this.setState({ queueing: true });
    try {
      await onQueueExport({
        reportId: schedule.reportId,
        reportName: schedule.reportName,
        outputFormat: schedule.outputFormat,
      });
    } finally {
      this.setState({ queueing: false });
    }
  };

  renderJobs() {
    const { exportJobs = [] } = this.props;
    if (!exportJobs.length) {
      return (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact"
          title="No export jobs"
          description="Queue an export from a saved schedule to see job status here."
        />
      );
    }

    return (
      <table className="lux-scheduled-reports__jobs-table">
        <thead>
          <tr>
            <th>Report</th>
            <th>Status</th>
            <th>Rows</th>
            <th>Requested</th>
          </tr>
        </thead>
        <tbody>
          {exportJobs.map((row) => (
            <tr key={row.id}>
              <td>
                <strong>{row.reportName}</strong>
                <small>{row.outputFormat}</small>
              </td>
              <td>
                <span className={classNames("lux-scheduled-reports__badge", `is-${JOB_TONE[row.status] || "slate"}`)}>
                  {row.status}
                </span>
              </td>
              <td>{row.rowCount != null ? row.rowCount : "—"}</td>
              <td>{formatTimestamp(row.requestedAt)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    );
  }

  render() {
    const { schedules = [], savedReports = [], exportJobs = [], loading } = this.props;
    const { selectedScheduleId, form, saving, queueing, saveError } = this.state;

    if (loading) {
      return <div className="lux-scheduled-reports__skeleton" aria-busy="true" />;
    }

    return (
      <div className="lux-scheduled-reports">
        <div className="lux-scheduled-reports__sidebar">
          <span className="lux-scheduled-reports__label">Schedules</span>
          <div className="lux-scheduled-reports__list">
            {!schedules.length ? (
              <LuxRegisterEmptyState
                className="lux-register-empty--compact"
                title="No schedules yet"
                description="Create a schedule linked to a saved report or enter a custom report name."
              />
            ) : null}
            {schedules.map((row) => (
              <button
                key={row.id}
                type="button"
                className={classNames("lux-scheduled-reports__card", selectedScheduleId === row.id && "is-active")}
                onClick={() => this.selectSchedule(row)}
              >
                <strong>{row.reportName}</strong>
                <small>{row.frequency} · {row.recipients.length} recipients</small>
                <span className={classNames("lux-scheduled-reports__badge", `is-${STATUS_TONE[row.status] || "slate"}`)}>
                  {row.status}
                </span>
              </button>
            ))}
          </div>
        </div>

        <div className="lux-scheduled-reports__main">
          <form className="lux-scheduled-reports__form" onSubmit={this.handleSave}>
            <div className="lux-scheduled-reports__form-grid">
              <label>
                Linked report
                <select value={form.reportId} onChange={this.handleFormChange("reportId")}>
                  <option value="">Custom / manual name</option>
                  {savedReports.map((row) => (
                    <option key={row.id} value={row.id}>
                      {row.name}
                    </option>
                  ))}
                </select>
              </label>
              <label>
                Report name
                <input type="text" value={form.reportName} onChange={this.handleFormChange("reportName")} required />
              </label>
              <label>
                Frequency
                <select value={form.frequency} onChange={this.handleFormChange("frequency")}>
                  {Object.values(SCHEDULE_FREQUENCIES).map((value) => (
                    <option key={value} value={value}>
                      {value}
                    </option>
                  ))}
                </select>
              </label>
              <label className="is-wide">
                Recipients (comma-separated)
                <input type="text" value={form.recipients} onChange={this.handleFormChange("recipients")} />
              </label>
            </div>

            {saveError ? <p className="lux-scheduled-reports__error">{saveError}</p> : null}

            <div className="lux-scheduled-reports__actions">
              <AnalyticsActionButton icon="fe fe-save" variant="primary" buttonType="submit" disabled={saving}>
                {saving ? "Saving…" : "Save schedule"}
              </AnalyticsActionButton>
              {selectedScheduleId ? (
                <AnalyticsActionButton
                  icon="fe fe-upload-cloud"
                  variant="ghost"
                  disabled={queueing}
                  onClick={() => {
                    const schedule = schedules.find((row) => row.id === selectedScheduleId);
                    this.handleQueueExport(schedule);
                  }}
                >
                  {queueing ? "Queueing…" : "Queue export now"}
                </AnalyticsActionButton>
              ) : null}
            </div>
          </form>

          <div className="lux-scheduled-reports__jobs">
            <span className="lux-scheduled-reports__label">Export jobs ({exportJobs.length})</span>
            {this.renderJobs()}
          </div>
        </div>
      </div>
    );
  }
}
