/**
 * F01-T7: Module-level empty state when a module has no visible sidebar items.
 */

import {
  SIDEBAR_GROUPS,
  isSidebarGroupVisible,
  pathMatchesSidebarGroup,
} from "config/sidebar-menu.config";
import { isVersionHistoryPath } from "config/version-history.routes";

export function resolveSidebarGroupForPath(pathname) {
  const path = (pathname || "").split("?")[0];
  let bestGroup = null;
  let bestPrefixLen = -1;

  for (const group of SIDEBAR_GROUPS) {
    if (!pathMatchesSidebarGroup(path, group)) {
      continue;
    }
    for (const prefix of group.pathPrefixes || []) {
      if (path === prefix || path.startsWith(`${prefix}/`)) {
        if (prefix.length > bestPrefixLen) {
          bestPrefixLen = prefix.length;
          bestGroup = group;
        }
      }
    }
  }

  return bestGroup;
}

export function getModuleEmptyReason(pathname, menuAccessControl, activePersona) {
  if (isVersionHistoryPath(pathname)) {
    return null;
  }
  const group = resolveSidebarGroupForPath(pathname);
  if (!group || !menuAccessControl) {
    return null;
  }
  if (isSidebarGroupVisible(group, menuAccessControl, activePersona)) {
    return null;
  }
  return {
    moduleId: group.id,
    moduleName: group.menuName,
    pathname: (pathname || "").split("?")[0],
  };
}
