import React from "react";
import classNames from "classnames/bind";
import PageInnerHeaderTeamsSelectionMenu from "views/common/fragments/PageInnerHeaderTeamsSelectionMenu";
import { store } from "_helpers";
import { commonUtils } from "_helpers";
import { workItemConstants } from "_constants";
import { CALENDAR_STATUS_FILTERS } from "./userCalendar.utils";

const VIEW_MODES = [
  { key: "PROJECT", label: "Projects", icon: "fe fe-layers" },
  { key: "DELIVERABLES", label: "Deliverables", icon: "fe fe-check-square" },
  { key: "WORKITEMS", label: "Work items", icon: "fe fe-list" },
];

const CALENDAR_VIEWS = [
  { key: "month", label: "Month", icon: "fe fe-grid" },
  { key: "week", label: "Week", icon: "fe fe-columns" },
  { key: "day", label: "Day", icon: "fe fe-align-left" },
  { key: "agenda", label: "Agenda", icon: "fe fe-list" },
];

export default function LuxUserCalendarToolbar({
  date,
  view,
  periodLabel,
  onNavigate,
  onView,
  onLoadRange,
  viewMode: viewModeProp,
  isLoading,
  statusFilter,
  onStatusFilterChange,
  searchQuery,
  onSearchChange,
  userTeams,
}) {
  if (!date) return null;

  const viewMode = viewModeProp || store.getState().workItem.viewMode || "WORKITEMS";

  const handleNavigate = (action) => (event) => {
    event.preventDefault();
    event.stopPropagation();
    if (onNavigate) onNavigate(action);
  };

  const handleViewChange = (viewName) => (event) => {
    event.preventDefault();
    event.stopPropagation();
    if (onView) onView(viewName);
  };

  const changeViewMode = (mode) => {
    if (viewMode === mode) return;
    const teams = commonUtils.getUserTeams(userTeams || store.getState().workItem.userTeamsFC);
    store.dispatch({
      type: workItemConstants.INITIALIZE_WORK_ITEMS_FULLCALENDAR,
      userTeams: teams,
      viewMode: mode,
    });
    if (onLoadRange) onLoadRange(date, view);
  };

  const onChangeTeam = (currentUserTeams) => {
    store.dispatch({
      type: workItemConstants.INITIALIZE_WORK_ITEMS_FULLCALENDAR,
      userTeams: currentUserTeams,
      viewMode,
    });
    if (onLoadRange) onLoadRange(date, view, currentUserTeams);
  };

  return (
    <div className="lux-user-calendar-toolbar">
      <div className="lux-user-calendar-toolbar__row lux-user-calendar-toolbar__row--primary">
        <div className="lux-user-calendar-toolbar__left">
          <PageInnerHeaderTeamsSelectionMenu
            userTeams={commonUtils.getUserTeams(userTeams || store.getState().workItem.userTeamsFC)}
            handleUserTeamsSelection={onChangeTeam}
            isLoading={isLoading}
            enabled
          />
          <div className="lux-user-calendar-toolbar__modes" role="group" aria-label="Data mode">
            {VIEW_MODES.map((mode) => (
              <button
                key={mode.key}
                type="button"
                className={classNames("lux-user-calendar-toolbar__chip", {
                  "is-active": viewMode === mode.key,
                })}
                onClick={() => changeViewMode(mode.key)}
              >
                <i className={mode.icon} aria-hidden="true" />
                <span>{mode.label}</span>
              </button>
            ))}
          </div>
        </div>

        <div className="lux-user-calendar-toolbar__center">
          <div className="lux-user-calendar-toolbar__nav" role="group" aria-label="Calendar navigation">
            <button type="button" className="lux-user-calendar-toolbar__nav-btn" onClick={handleNavigate("PREV")} aria-label="Previous period">
              <i className="fe fe-chevron-left" aria-hidden="true" />
            </button>
            <button type="button" className="lux-user-calendar-toolbar__today" onClick={handleNavigate("TODAY")}>
              Today
            </button>
            <button type="button" className="lux-user-calendar-toolbar__nav-btn" onClick={handleNavigate("NEXT")} aria-label="Next period">
              <i className="fe fe-chevron-right" aria-hidden="true" />
            </button>
          </div>
          <h2 className="lux-user-calendar-toolbar__label">{periodLabel}</h2>
          {isLoading && (
            <span className="lux-user-calendar-toolbar__loading" aria-live="polite">
              <i className="fe fe-loader" aria-hidden="true" /> Syncing…
            </span>
          )}
        </div>

        <div className="lux-user-calendar-toolbar__views" role="group" aria-label="Calendar layout">
          {CALENDAR_VIEWS.map((v) => (
            <button
              key={v.key}
              type="button"
              className={classNames("lux-user-calendar-toolbar__chip", { "is-active": view === v.key })}
              onClick={handleViewChange(v.key)}
              aria-pressed={view === v.key}
            >
              <i className={v.icon} aria-hidden="true" />
              <span>{v.label}</span>
            </button>
          ))}
        </div>
      </div>

      <div className="lux-user-calendar-toolbar__row lux-user-calendar-toolbar__row--filters">
        <label className="lux-user-calendar-toolbar__search">
          <i className="fe fe-search" aria-hidden="true" />
          <input
            type="search"
            value={searchQuery || ""}
            onChange={(e) => onSearchChange && onSearchChange(e.target.value)}
            placeholder="Search events, projects, deliverables…"
            aria-label="Search calendar events"
          />
        </label>
        <div className="lux-user-calendar-toolbar__status-filters" role="group" aria-label="Status filter">
          {CALENDAR_STATUS_FILTERS.map((f) => (
            <button
              key={f.key}
              type="button"
              className={classNames("lux-user-calendar-toolbar__filter-pill", {
                "is-active": statusFilter === f.key,
              })}
              onClick={() => onStatusFilterChange && onStatusFilterChange(f.key)}
            >
              {f.label}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}
