import React from "react";
import classNames from "classnames/bind";

export default function OrgStructureWorkspaceTabs({ items = [], activeId, onChange, testId }) {
  if (!items.length) {
    return null;
  }

  const activate = (id, { focus } = {}) => {
    if (onChange) {
      onChange(id);
    }
    if (!focus || typeof document === "undefined") {
      return;
    }
    window.requestAnimationFrame(() => {
      const next = document.getElementById(`org-structure-tab-${id}`);
      if (next) {
        next.focus();
      }
    });
  };

  const handleKeyDown = (event) => {
    if (event.key !== "ArrowRight" && event.key !== "ArrowLeft" && event.key !== "Home" && event.key !== "End") {
      return;
    }
    event.preventDefault();
    const index = Math.max(0, items.findIndex((item) => item.id === activeId));
    if (event.key === "Home") {
      activate(items[0].id, { focus: true });
      return;
    }
    if (event.key === "End") {
      activate(items[items.length - 1].id, { focus: true });
      return;
    }
    const delta = event.key === "ArrowRight" ? 1 : -1;
    const next = items[(index + delta + items.length) % items.length];
    activate(next.id, { focus: true });
  };

  return (
    <nav
      className="lux-rbac-editor-tabs lux-org-structure-tabs"
      role="tablist"
      aria-label="Org structure sections"
      data-testid={testId || "org-structure-tabs"}
      onKeyDown={handleKeyDown}
    >
      {items.map((item) => {
        const active = activeId === item.id;
        const badge = item.badge != null ? item.badge : item.count;
        const tabId = `org-structure-tab-${item.id}`;
        const panelId = `org-structure-panel-${item.id}`;
        return (
          <button
            key={item.id}
            id={tabId}
            type="button"
            role="tab"
            aria-selected={active}
            aria-controls={panelId}
            tabIndex={active ? 0 : -1}
            className={classNames(
              "lux-rbac-editor-tabs__tab",
              "lux-org-structure-tabs__tab",
              item.tone && `is-${item.tone}`,
              { "is-active": active }
            )}
            onClick={() => activate(item.id)}
          >
            <i className={item.icon} aria-hidden="true" />
            <span className="lux-rbac-editor-tabs__copy lux-org-structure-tabs__copy">
              <strong>{item.label}</strong>
              <em>{item.hint}</em>
            </span>
            {badge != null ? <span className="lux-org-structure-tabs__count">{badge}</span> : null}
          </button>
        );
      })}
    </nav>
  );
}
