/**
 * W17-A — Write-offs FE service. Real API only (no mock fallback path).
 */
import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";

export const writeOffsService = {
  listWriteOffs,
  getWriteOffByRef,
  createWriteOff,
  submitWriteOff,
  approveWriteOff,
  rejectWriteOff,
};

const API_ERROR = { payload: null, source: "api-error" };

function resolveUserTeamId(explicit) {
  if (explicit != null && explicit !== "") {
    return explicit;
  }
  return commonUtils.getCurrentUserTeamId();
}

function resolveActorId() {
  return commonUtils.getCurrentUserId();
}

function financeListTeamQuery(extra) {
  const query = {};
  const explicitIds = extra && extra.userTeamIds;
  const currentIds = commonUtils.getCurrentUserTeamIds() || [];
  const currentId = commonUtils.getCurrentUserTeamId();
  if (Array.isArray(explicitIds) && explicitIds.length) {
    query.userTeamIds = explicitIds;
  } else if (currentIds.length > 0) {
    query.userTeamIds = currentIds;
  } else if (currentId != null && currentId !== "") {
    query.userTeamId = currentId;
  }
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (key === "userTeamId" || key === "userTeamIds") return;
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

async function listWriteOffs(extra = {}) {
  try {
    const response = await axiosUtils.getWithParam(
      urlConfig.WRITE_OFFS_API_PATH,
      financeListTeamQuery(extra)
    );
    const payload = response && response.payload != null ? response.payload : response;
    if (Array.isArray(payload)) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    console.warn("[WriteOffs] list unavailable.", e);
    return { ...API_ERROR, error: e };
  }
}

async function getWriteOffByRef(writeOffRef, userTeamId) {
  try {
    const response = await axiosUtils.getWithParam(
      `${urlConfig.WRITE_OFFS_API_PATH}/by-ref/${encodeURIComponent(writeOffRef)}`,
      { userTeamId: resolveUserTeamId(userTeamId) }
    );
    const payload = response && response.payload != null ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

async function createWriteOff(body = {}) {
  try {
    const response = await axiosUtils.post(urlConfig.WRITE_OFFS_API_PATH, {
      ...body,
      userTeamId: body.userTeamId || resolveUserTeamId(),
      actorId: body.actorId || resolveActorId(),
    });
    const payload = response && response.payload != null ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

async function submitWriteOff(writeOffRef, userTeamId) {
  return transition(writeOffRef, "submit", null, userTeamId);
}

async function approveWriteOff(writeOffRef, userTeamId) {
  return transition(writeOffRef, "approve", null, userTeamId);
}

async function rejectWriteOff(writeOffRef, reason, userTeamId) {
  return transition(writeOffRef, "reject", reason, userTeamId);
}

async function transition(writeOffRef, action, reason, userTeamId) {
  try {
    const params = new URLSearchParams({
      userTeamId: String(resolveUserTeamId(userTeamId)),
      actorId: String(resolveActorId()),
    });
    if (reason) {
      params.set("reason", reason);
    }
    const response = await axiosUtils.post(
      `${urlConfig.WRITE_OFFS_API_PATH}/${encodeURIComponent(writeOffRef)}/${action}?${params.toString()}`,
      null
    );
    const payload = response && response.payload != null ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}
