/**
 * W17-A — Credit notes FE service. Real API only (no mock fallback path).
 */
import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";

export const creditNotesService = {
  listCreditNotes,
  getCreditNoteByRef,
  createCreditNote,
  submitCreditNote,
  approveCreditNote,
  rejectCreditNote,
  getEffectiveOutstanding,
  getProjectAdjustmentSummary,
};

const API_ERROR = { payload: null, source: "api-error" };

function resolveUserTeamId(explicit) {
  if (explicit != null && explicit !== "") {
    return explicit;
  }
  return commonUtils.getCurrentUserTeamId();
}

function resolveActorId() {
  return commonUtils.getCurrentUserId();
}

function financeListTeamQuery(extra) {
  const query = {};
  const explicitIds = extra && extra.userTeamIds;
  const currentIds = commonUtils.getCurrentUserTeamIds() || [];
  const currentId = commonUtils.getCurrentUserTeamId();
  if (Array.isArray(explicitIds) && explicitIds.length) {
    query.userTeamIds = explicitIds;
  } else if (currentIds.length > 0) {
    query.userTeamIds = currentIds;
  } else if (currentId != null && currentId !== "") {
    query.userTeamId = currentId;
  }
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (key === "userTeamId" || key === "userTeamIds") return;
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

async function listCreditNotes(extra = {}) {
  try {
    const response = await axiosUtils.getWithParam(
      urlConfig.CREDIT_NOTES_API_PATH,
      financeListTeamQuery(extra)
    );
    const payload = response && response.payload != null ? response.payload : response;
    if (Array.isArray(payload)) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    console.warn("[CreditNotes] list unavailable.", e);
    return { ...API_ERROR, error: e };
  }
}

async function getCreditNoteByRef(creditNoteRef, userTeamId) {
  try {
    const response = await axiosUtils.getWithParam(
      `${urlConfig.CREDIT_NOTES_API_PATH}/by-ref/${encodeURIComponent(creditNoteRef)}`,
      { userTeamId: resolveUserTeamId(userTeamId) }
    );
    const payload = response && response.payload != null ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

async function createCreditNote(body = {}) {
  try {
    const response = await axiosUtils.post(urlConfig.CREDIT_NOTES_API_PATH, {
      ...body,
      userTeamId: body.userTeamId || resolveUserTeamId(),
      actorId: body.actorId || resolveActorId(),
    });
    const payload = response && response.payload != null ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

async function submitCreditNote(creditNoteRef, userTeamId) {
  return transition(creditNoteRef, "submit", null, userTeamId);
}

async function approveCreditNote(creditNoteRef, userTeamId) {
  return transition(creditNoteRef, "approve", null, userTeamId);
}

async function rejectCreditNote(creditNoteRef, reason, userTeamId) {
  return transition(creditNoteRef, "reject", reason, userTeamId);
}

async function transition(creditNoteRef, action, reason, userTeamId) {
  try {
    const params = new URLSearchParams({
      userTeamId: String(resolveUserTeamId(userTeamId)),
      actorId: String(resolveActorId()),
    });
    if (reason) {
      params.set("reason", reason);
    }
    const response = await axiosUtils.post(
      `${urlConfig.CREDIT_NOTES_API_PATH}/${encodeURIComponent(creditNoteRef)}/${action}?${params.toString()}`,
      null
    );
    const payload = response && response.payload != null ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

async function getEffectiveOutstanding(invoiceId) {
  try {
    const response = await axiosUtils.get(
      `${urlConfig.CREDIT_NOTES_API_PATH}/outstanding/${encodeURIComponent(invoiceId)}`
    );
    const payload = response && response.payload != null ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

async function getProjectAdjustmentSummary(projectId, userTeamId) {
  try {
    const response = await axiosUtils.getWithParam(
      `${urlConfig.CREDIT_NOTES_API_PATH}/project-summary`,
      { userTeamId: resolveUserTeamId(userTeamId), projectId }
    );
    const payload = response && response.payload != null ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

/** Pure util for FE unit tests — mirrors backend effective outstanding. */
export function computeEffectiveOutstanding(totalAmount, paidAmount, approvedCredits, approvedWriteOffs) {
  const raw =
    Number(totalAmount || 0) -
    Number(paidAmount || 0) -
    Number(approvedCredits || 0) -
    Number(approvedWriteOffs || 0);
  return Math.max(0, Math.round(raw * 100) / 100);
}
