import React, { Component } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import {
  SAVED_VIEW_SURFACES,
  isWorkspaceFavoritesEnabled,
} from "config/workspace-personalization.config";
import { summarizeSavedViewFilters } from "config/workspace-personalization.utils";
import { workspaceService } from "_services/workspace.service";
import { WorkspacePanelHead } from "views/workspace/components/WorkspaceLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

export default class WorkspaceSavedViewsPanel extends Component {
  state = {
    savedViews: [],
    loading: true,
    acting: false,
  };

  componentDidMount() {
    if (Array.isArray(this.props.initialSavedViews)) {
      this.setState({ savedViews: this.props.initialSavedViews, loading: false });
    } else {
      this.loadSavedViews();
    }
    this._listener = () => this.loadSavedViews();
    window.addEventListener("famstack-workspace-personalization-changed", this._listener);
  }

  componentDidUpdate(prevProps) {
    if (
      prevProps.initialSavedViews !== this.props.initialSavedViews
      && Array.isArray(this.props.initialSavedViews)
      && !this.state.acting
    ) {
      this.setState({ savedViews: this.props.initialSavedViews, loading: false });
    }
  }

  componentWillUnmount() {
    window.removeEventListener("famstack-workspace-personalization-changed", this._listener);
  }

  loadSavedViews = async () => {
    if (!isWorkspaceFavoritesEnabled()) {
      this.setState({ loading: false, savedViews: [] });
      return;
    }
    this.setState({ loading: true });
    try {
      const result = await workspaceService.listSavedViews();
      this.setState({ savedViews: result.payload || [], loading: false });
    } catch (e) {
      this.setState({ savedViews: [], loading: false });
    }
  };

  handleDelete = async (view) => {
    if (!view || !view.id) {
      return;
    }
    this.setState({ acting: true });
    try {
      await workspaceService.deleteSavedView(view.id);
      await this.loadSavedViews();
      if (this.props.onChange) {
        this.props.onChange();
      }
    } finally {
      this.setState({ acting: false });
    }
  };

  render() {
    if (!isWorkspaceFavoritesEnabled()) {
      return null;
    }

    const { savedViews, loading, acting } = this.state;
    const rows = savedViews || [];

    return (
      <section className="lux-hrms-dash__panel lux-workspace-saved-views" aria-label="Saved views">
        <WorkspacePanelHead
          title="Saved views"
          subtitle="Filter presets across approvals, my work, and notifications"
        />
        <div className="lux-hrms-dash__panel-body">
          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading saved views"
              description="Reading your personalized filter presets."
            />
          ) : rows.length === 0 ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              icon="fe fe-bookmark"
              title="No saved views"
              description="Save a filter preset from approvals, my work, or notifications."
            />
          ) : (
            <ul className="lux-workspace-saved-views__list" role="list">
              {rows.map((view) => {
                const surfaceMeta = SAVED_VIEW_SURFACES[view.surface] || {};
                return (
                  <li key={view.id} className="lux-workspace-saved-views__item" role="listitem">
                    <Link
                      to={surfaceMeta.path || "/workspace/home"}
                      className={classNames("lux-workspace-saved-views__link", surfaceMeta.tone && `is-${surfaceMeta.tone}`)}
                      title="Open surface to apply this view"
                    >
                      <span className="lux-workspace-saved-views__icon" aria-hidden="true">
                        <i className={surfaceMeta.icon || "fe fe-bookmark"} />
                      </span>
                      <span className="lux-workspace-saved-views__copy">
                        <strong>{view.name}</strong>
                        <small>
                          {view.surfaceLabel} · {summarizeSavedViewFilters(view.filters)}
                        </small>
                      </span>
                      {view.isDefault && <span className="lux-badge is-success">Default</span>}
                    </Link>
                    <button
                      type="button"
                      className="lux-workspace-saved-views__delete"
                      onClick={() => this.handleDelete(view)}
                      disabled={acting}
                      aria-label={`Delete saved view ${view.name}`}
                    >
                      <i className="fe fe-trash-2" aria-hidden="true" />
                    </button>
                  </li>
                );
              })}
            </ul>
          )}
        </div>
      </section>
    );
  }
}
