export function filterReviewCycles(rows, filters) {
  const list = (rows || []).map(normalizeReviewCycle).filter(Boolean);
  const f = filters || {};
  return list.filter((row) => {
    if (f.status && f.status !== "ALL" && row.status !== f.status) {
      return false;
    }
    if (f.query) {
      const q = String(f.query).toLowerCase();
      const hay = `${row.name} ${row.templateName}`.toLowerCase();
      if (hay.indexOf(q) === -1) {
        return false;
      }
    }
    return true;
  });
}

