export function formatPerformanceRating(value, maskingPolicy) {
  if (value == null || value === "") {
    return "—";
  }
  const policy = maskingPolicy || {};
  if (policy.performanceReview === "HIDDEN") {
    return "Restricted";
  }
  if (policy.performanceReview === "MASKED") {
    return "••••••";
  }
  return String(value);
}

export function buildEmployeePerformanceSnapshot(employeeName, goals, reviews, feedback, growthPlans) {
  const employeeGoals = filterGoalsByEmployeeName(goals, employeeName);
  const employeeReviews = filterReviewsByEmployeeName(reviews, employeeName);
  const employeeFeedback = filterFeedbackByEmployeeName(feedback, employeeName);
  const employeePlans = filterGrowthPlansByEmployeeName(growthPlans, employeeName);
  const activeReview =
    employeeReviews.find((row) => row.status !== REVIEW_STATUSES.COMPLETED) ||
    employeeReviews[0] ||
    null;
  const avgGoalProgress = employeeGoals.length
    ? Math.round(
        employeeGoals.reduce((sum, row) => sum + (Number(row.progress) || 0), 0) / employeeGoals.length
      )
    : 0;

  return {
    employeeName,
    goals: employeeGoals,
    reviews: employeeReviews,
    feedback: employeeFeedback.slice(0, 5),
    growthPlans: employeePlans,
    activeReview,
    avgGoalProgress,
    openGoals: employeeGoals.filter((row) => row.status !== GOAL_STATUSES.COMPLETED).length,
    praiseCount: employeeFeedback.filter((row) => row.type === FEEDBACK_TYPES.PRAISE).length,
  };
}

