import { getDelegationStatus } from "_helpers/approvalDelegation.utils";
import {
  formatDisplayValue,
  getSortedTeamNames,
  getTenureLabel,
  isAppLoginEnabled,
  parseDisplayValueList,
} from "./profilePage.utils";

export function getProfileEmployeeLabel(employee) {
  if (!employee) return null;
  if (employee.empCode) return `${employee.name} · ${employee.empCode}`;
  return employee.name;
}

export function buildLeaveTabStats(leaves, balances) {
  const list = leaves || [];
  let pending = 0;
  let approved = 0;
  list.forEach((leave) => {
    const status = String((leave.workflowStatus || leave.workflow_status || "")).toUpperCase();
    if (status === "SUBMITTED") pending += 1;
    if (status === "APPROVED" || status === "SYNCED") approved += 1;
  });
  const balanceTotal = (balances || []).reduce((sum, row) => {
    const n = parseFloat(row.balance);
    return sum + (Number.isNaN(n) ? 0 : n);
  }, 0);

  return [
    {
      key: "pending",
      label: "Pending",
      value: pending,
      hint: "Awaiting approval",
      tone: pending ? "amber" : "slate",
    },
    {
      key: "approved",
      label: "Approved",
      value: approved,
      hint: "Including HR sync",
      tone: approved ? "green" : "slate",
    },
    {
      key: "balance",
      label: "Balance",
      value: balanceTotal ? Math.round(balanceTotal * 10) / 10 : "—",
      hint: "Days remaining (all types)",
      tone: "slate",
    },
  ];
}

export function buildPersonalTabStats(employee) {
  if (!employee) return [];
  const teams =
    (employee.additionalUserTeamDetails && employee.additionalUserTeamDetails.length) || 0;
  const serviceLines = parseDisplayValueList(employee.serviceLines).length;
  const loginOn = isAppLoginEnabled(employee);

  return [
    {
      key: "tenure",
      label: "Tenure",
      value: getTenureLabel(employee.dateOfJoin) || "—",
      hint: employee.dateOfJoin ? "Since join date" : "No join date",
      tone: "slate",
    },
    {
      key: "teams",
      label: "Teams",
      value: teams + (employee.defaultUserTeamDetails ? 1 : 0),
      hint: "Default + additional",
      tone: "slate",
    },
    {
      key: "lines",
      label: "Service lines",
      value: serviceLines || "—",
      hint: "Delivery scope",
      tone: serviceLines ? "green" : "slate",
    },
    {
      key: "login",
      label: "App login",
      value: loginOn ? "Enabled" : "Disabled",
      hint: "Platform access",
      tone: loginOn ? "green" : "rose",
    },
  ];
}

export function buildAccessTabStats(employee) {
  if (!employee) return [];
  const role = (employee.userAccessDetails && employee.userAccessDetails.name) || "—";
  return [
    {
      key: "role",
      label: "Role",
      value: role,
      hint: "Assigned access role",
      tone: "slate",
    },
    {
      key: "team",
      label: "Default team",
      value:
        (employee.defaultUserTeamDetails && employee.defaultUserTeamDetails.name) || "—",
      hint: "Primary team scope",
      tone: "slate",
    },
    {
      key: "teams",
      label: "Extra teams",
      value: (getSortedTeamNames(employee.additionalUserTeamDetails) || []).length,
      hint: "Additional team access",
      tone: "slate",
    },
  ];
}

export function buildSecurityTabStats(employee, readOnly) {
  if (!employee) return [];
  const loginOn = isAppLoginEnabled(employee);
  return [
    {
      key: "login",
      label: "App login",
      value: loginOn ? "Enabled" : "Disabled",
      hint: "Password change gate",
      tone: loginOn ? "green" : "rose",
    },
    {
      key: "mode",
      label: "View mode",
      value: readOnly ? "Read-only" : "Self-service",
      hint: readOnly ? "Another employee" : "Your account",
      tone: readOnly ? "slate" : "green",
    },
  ];
}

export function buildDelegationTabStats(delegations) {
  const list = delegations || [];
  const activeCount = list.filter((item) => {
    const status = getDelegationStatus(item);
    return status === "active" || status === "upcoming";
  }).length;
  return [
    {
      key: "active",
      label: "Active",
      value: activeCount || "—",
      hint: "Current and upcoming coverage",
      tone: activeCount ? "green" : "slate",
    },
    {
      key: "total",
      label: "Total",
      value: list.length || "—",
      hint: "Delegations you created",
      tone: "slate",
    },
  ];
}

export function buildSettingsTabStats(employee, readOnly) {
  return [
    {
      key: "scope",
      label: "Scope",
      value: readOnly ? "View only" : "Editable",
      hint: readOnly ? "Another employee" : "Saved on this device",
      tone: readOnly ? "slate" : "green",
    },
    {
      key: "emp",
      label: "Employee",
      value: employee.empCode || employee.name || "—",
      hint: "Profile owner",
      tone: "slate",
    },
  ];
}

export function buildActivityTabStats(employee) {
  return [
    {
      key: "status",
      label: "Audit log",
      value: "Preview",
      hint: "Server sync pending",
      tone: "amber",
    },
    {
      key: "emp",
      label: "Subject",
      value: employee.empCode || "—",
      hint: employee.name,
      tone: "slate",
    },
  ];
}

export function countEnabledLoginFlags(employee) {
  if (!employee) return 0;
  const flags = [
    employee.appLoginDisabled === false || employee.appLoginDisabled === "false",
    employee.deviceAppEnabled === true || employee.deviceAppEnabled === "true",
    employee.extLeaveSyncEnabled === true || employee.extLeaveSyncEnabled === "true",
  ];
  return flags.filter(Boolean).length;
}

export function formatAsideMetaValue(val) {
  return formatDisplayValue(val) || "—";
}
