import React from "react";
import classNames from "classnames/bind";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

function ExpenseLeakageAgentPanel({ flags = [], loading }) {
  if (loading) {
    return <div className="lux-expense-leakage__skeleton" aria-busy="true" />;
  }
  if (!flags.length) {
    return (
      <LuxRegisterEmptyState
        className="lux-register-empty--compact"
        title="No expense leakage flags"
        description="Duplicate, out-of-policy, and unbilled billable detections will surface here when the agent finds risk."
      />
    );
  }

  return (
    <div className="lux-expense-leakage">
      {flags.map((flag) => (
        <article
          key={flag.id}
          className={classNames("lux-expense-leakage__card", flag.severity && `is-${flag.severity.toLowerCase()}`)}
        >
          <div className="lux-expense-leakage__top">
            <span className="lux-expense-chip is-violet">{flag.leakageType.replace(/_/g, " ")}</span>
            <span className="lux-expense-chip is-rose">{flag.severity}</span>
          </div>
          <h3>{flag.employeeName}</h3>
          {flag.claimTitle ? <p className="lux-expense-leakage__claim">{flag.claimTitle}</p> : null}
          <p>{flag.recommendation}</p>
          <div className="lux-expense-leakage__meta">
            <span>Est. ${Number(flag.estimatedUsd || 0).toLocaleString()}</span>
            <span>{flag.flaggedAt}</span>
          </div>
        </article>
      ))}
    </div>
  );
}

export default ExpenseLeakageAgentPanel;
