import React from "react";
import classNames from "classnames/bind";
import PlannerHorizonTasksEmptyIllustration from "./PlannerHorizonTasksEmptyIllustration";

const COPY = {
  "select-member": {
    eyebrow: "Tasks in horizon",
    title: "Select a team member",
    description:
      "Choose someone in the form to see existing assignments, daily load, and capacity for this planning range.",
    hints: [
      "Summary charts update for the selected person",
      "Assign billable or non-billable work from the form",
    ],
  },
  "no-tasks": {
    eyebrow: "Open horizon",
    title: "No tasks scheduled yet",
    description: (employeeName) =>
      employeeName
        ? `${employeeName} has no assignments in this range — a good window to plan new work.`
        : "No assignments in this range — capacity is open for new work.",
    hints: (ctx) => {
      const hints = ["Use the form on the left to assign tasks for these dates"];
      if (ctx && ctx.freeLabel) {
        hints.unshift(`${ctx.freeLabel} capacity available in this horizon`);
      }
      if (ctx && ctx.horizonUtilization != null) {
        hints.push(`${ctx.horizonUtilization}% utilized across the horizon`);
      }
      return hints;
    },
  },
};

export default function PlannerAssignHorizonEmptyState({ variant = "no-tasks", context }) {
  const config = COPY[variant] || COPY["no-tasks"];
  const employeeName = context && context.employee && context.employee.name;
  const description =
    typeof config.description === "function"
      ? config.description(employeeName)
      : config.description;
  const hints =
    typeof config.hints === "function" ? config.hints(context) : config.hints;

  return (
    <div
      className={classNames("lux-planner-assign-alloc-empty", `is-${variant}`)}
      role="status"
    >
      <div className="lux-planner-assign-alloc-empty__glow" aria-hidden="true" />
      <div className="lux-planner-assign-alloc-empty__art">
        <PlannerHorizonTasksEmptyIllustration />
      </div>
      <div className="lux-planner-assign-alloc-empty__copy">
        <span className="lux-planner-assign-alloc-empty__eyebrow">{config.eyebrow}</span>
        <h4 className="lux-planner-assign-alloc-empty__title">{config.title}</h4>
        <p className="lux-planner-assign-alloc-empty__text">{description}</p>
        {hints && hints.length > 0 && (
          <ul className="lux-planner-assign-alloc-empty__hints">
            {hints.map((hint) => (
              <li key={hint}>
                <i className="fe fe-check-circle" aria-hidden="true" />
                {hint}
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}
