import dateUtils from "_helpers/date.utils";

export function getMonthRangeOptions(estStartTime, estCompletionTime) {
    return dateUtils.getMonthYearArray(estStartTime, estCompletionTime)
        .map((monthYear) => ({ value: monthYear, label: monthYear }));
}

export function formatHours(value) {
    if (value == null || value === "") return "—";
    const num = parseFloat(value);
    if (Number.isNaN(num)) return String(value);
    if (Number.isInteger(num)) return String(num);
    return num.toFixed(2).replace(/\.?0+$/, "");
}

export function formatHoursLabel(value) {
    const formatted = formatHours(value);
    return formatted === "—" ? formatted : `${formatted}h`;
}

export function getEstimateTotal(teamEstimate, estimateType, estimateHourType, monthOptions) {
    let total = 0;
    if (!teamEstimate || !teamEstimate.estimates) return "0.00";
    monthOptions.forEach(({ value: monthYear }) => {
        const monthData = teamEstimate.estimates[monthYear];
        if (monthData && monthData[estimateType]) {
            Object.keys(monthData[estimateType]).forEach((estimateName) => {
                total += parseFloat(monthData[estimateType][estimateName][estimateHourType] || 0);
            });
        }
    });
    return total.toFixed(2);
}

export function getTeamGrandTotal(teamEstimate, hourType, monthOptions) {
    const types = teamEstimate.estimateTypes || [];
    let total = 0;
    types.forEach((estimateType) => {
        total += parseFloat(getEstimateTotal(teamEstimate, estimateType, hourType, monthOptions));
    });
    return total.toFixed(2);
}

export function getAllTeamsGrandTotal(projectEstimateRequest, hourType, monthOptions) {
    if (!projectEstimateRequest) return "0.00";
    let total = 0;
    Object.keys(projectEstimateRequest).forEach((teamId) => {
        total += parseFloat(getTeamGrandTotal(projectEstimateRequest[teamId], hourType, monthOptions));
    });
    return total.toFixed(2);
}

export function getSharePct(part, whole) {
    const p = parseFloat(part);
    const w = parseFloat(whole);
    if (!w || Number.isNaN(p) || Number.isNaN(w)) return 0;
    return Math.max(0, Math.min(100, Math.round((p / w) * 100)));
}

export function countTeamMonths(teamEstimate) {
    if (!teamEstimate || !teamEstimate.estimates) return 0;
    return Object.keys(teamEstimate.estimates).length;
}

export function countTeamLines(teamEstimate) {
    if (!teamEstimate || !teamEstimate.estimates) return 0;
    let count = 0;
    Object.values(teamEstimate.estimates).forEach((monthData) => {
        Object.values(monthData).forEach((typeData) => {
            count += Object.keys(typeData).length;
        });
    });
    return count;
}

export function countAllTeams(projectEstimateRequest) {
    return projectEstimateRequest ? Object.keys(projectEstimateRequest).length : 0;
}

export function countAllLines(projectEstimateRequest) {
    if (!projectEstimateRequest) return 0;
    return Object.values(projectEstimateRequest).reduce(
        (sum, team) => sum + countTeamLines(team),
        0
    );
}

export function getMonthSubtotal(teamEstimate, monthYear, hourType) {
    if (!teamEstimate || !teamEstimate.estimates || !teamEstimate.estimates[monthYear]) {
        return "0.00";
    }
    let total = 0;
    const monthData = teamEstimate.estimates[monthYear];
    Object.values(monthData).forEach((typeData) => {
        Object.values(typeData).forEach((hours) => {
            total += parseFloat((hours && hours[hourType]) || 0);
        });
    });
    return total.toFixed(2);
}

/** Flat rows — kept for compatibility. */
export function buildTeamDetailRows(teamEstimate, monthOptions) {
    if (!teamEstimate || !teamEstimate.estimates) return [];
    const types = teamEstimate.estimateTypes || [];
    const rows = [];
    monthOptions.forEach(({ value: monthYear }) => {
        const monthData = teamEstimate.estimates[monthYear];
        if (!monthData) return;
        types.forEach((estimateType) => {
            const typeData = monthData[estimateType];
            if (!typeData) return;
            Object.keys(typeData).forEach((estimateName) => {
                const hours = typeData[estimateName] || {};
                rows.push({
                    monthYear,
                    estimateType,
                    estimateName,
                    estimate: hours.estimate || "0",
                    estimateAutomation: hours.estimateAutomation,
                    estimateRevised: hours.estimateRevised,
                });
            });
        });
    });
    return rows;
}

/**
 * Grouped structure for scannable summary:
 * [{ monthYear, monthTotal, types: [{ estimateType, typeTotal, lines: [...] }] }]
 */
export function buildTeamGroupedDetails(teamEstimate, monthOptions) {
    if (!teamEstimate || !teamEstimate.estimates) return [];
    const types = teamEstimate.estimateTypes || [];
    const groups = [];

    monthOptions.forEach(({ value: monthYear }) => {
        const monthData = teamEstimate.estimates[monthYear];
        if (!monthData) return;

        const typeGroups = [];
        let monthTotal = 0;

        types.forEach((estimateType) => {
            const typeData = monthData[estimateType];
            if (!typeData) return;
            const lines = Object.keys(typeData).map((estimateName) => {
                const hours = typeData[estimateName] || {};
                const estimate = parseFloat(hours.estimate || 0);
                monthTotal += estimate;
                return {
                    estimateName,
                    displayName: formatEstimateName(estimateName),
                    estimate: hours.estimate || "0",
                    estimateAutomation: hours.estimateAutomation,
                    estimateRevised: hours.estimateRevised,
                };
            });
            if (!lines.length) return;
            const typeTotal = lines.reduce(
                (sum, line) => sum + parseFloat(line.estimate || 0),
                0
            );
            typeGroups.push({
                estimateType,
                typeTotal: typeTotal.toFixed(2),
                lines,
            });
        });

        if (typeGroups.length) {
            groups.push({
                monthYear,
                monthTotal: monthTotal.toFixed(2),
                types: typeGroups,
            });
        }
    });

    return groups;
}

export function formatEstimateName(estimateName) {
    if (!estimateName) return "—";
    if (String(estimateName).includes("#")) {
        const [primary, secondary] = String(estimateName).split("#");
        return secondary ? `${primary} · ${secondary}` : primary;
    }
    return estimateName;
}

export function getHourColumnCount(projectItem) {
    let count = 1;
    if (projectItem && projectItem.automationEnabled) count += 1;
    if (projectItem && projectItem.revisedEstEnabled) count += 1;
    return count;
}

export function getTypeTotals(teamEstimate, monthOptions) {
    const types = (teamEstimate && teamEstimate.estimateTypes) || [];
    return types.map((estimateType) => ({
        estimateType,
        total: getEstimateTotal(teamEstimate, estimateType, "estimate", monthOptions),
    }));
}
