import React, { Component } from "react";
import Skeleton from "react-loading-skeleton";
import classNames from "classnames/bind";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxCustomCalendarMonth from "./LuxCustomCalendarMonth";
import LuxCustomCalendarTimeGrid from "./LuxCustomCalendarTimeGrid";
import LuxCustomCalendarAgenda from "./LuxCustomCalendarAgenda";
import { getDayMeta, getWeekDays } from "./customCalendar.utils";

class LuxUserCalendarView extends Component {
  handleDayClick = (dayDate, event) => {
    if (event) {
      event.preventDefault();
      event.stopPropagation();
    }
    if (this.props.onOpenDay) {
      this.props.onOpenDay(dayDate);
      return;
    }
    const { onView, onDateChange } = this.props;
    if (onDateChange) onDateChange(dayDate);
    if (onView) onView("day");
  };

  handleSurfaceClick = (event) => {
    if (event.target !== event.currentTarget) return;
    if (this.props.onSelectSlot) this.props.onSelectSlot(event);
  };

  renderBody() {
    const { events, date, view, selectedEvent, onSelectEvent } = this.props;

    switch (view) {
      case "month":
        return (
          <LuxCustomCalendarMonth
            date={date}
            events={events}
            selectedEvent={selectedEvent}
            onSelectEvent={onSelectEvent}
            onDayClick={this.handleDayClick}
          />
        );
      case "day":
        return (
          <LuxCustomCalendarTimeGrid
            days={[getDayMeta(date)]}
            events={events}
            selectedEvent={selectedEvent}
            onSelectEvent={onSelectEvent}
            singleDay
          />
        );
      case "agenda":
        return (
          <LuxCustomCalendarAgenda
            date={date}
            events={events}
            selectedEvent={selectedEvent}
            onSelectEvent={onSelectEvent}
          />
        );
      case "week":
      default:
        return (
          <LuxCustomCalendarTimeGrid
            days={getWeekDays(date)}
            events={events}
            selectedEvent={selectedEvent}
            onSelectEvent={onSelectEvent}
          />
        );
    }
  }

  render() {
    const {
      events,
      date,
      view,
      onSelectEvent,
      isLoading,
      selectedEvent,
      className,
    } = this.props;

    const showEmpty = !isLoading && (!events || events.length === 0);

    return (
      <div
        className={classNames("lux-user-calendar-grid", className, `is-view-${view}`, {
          "is-loading": isLoading,
          "is-empty": showEmpty,
        })}
      >
        <div
          className="lux-user-calendar-grid__surface"
          onClick={this.handleSurfaceClick}
          role="presentation"
        >
          <div key={`${view}-${date && date.getTime ? date.getTime() : date}`} className="lux-user-calendar-grid__body">
            {this.renderBody()}
          </div>

          {showEmpty && (
            <div className="lux-user-calendar-grid__empty">
              <LuxRegisterEmptyState
                variant="holidays"
                eyebrow="Clear schedule"
                title="No events in this period"
                description="Adjust filters or navigate to another week. Events appear when team data is loaded for the selected range."
                hints={["Switch to Month for overview", "Clear status filters", "Change data mode above"]}
                className="lux-user-calendar-grid__empty-card"
              />
            </div>
          )}
        </div>

        {isLoading && (
          <div className="lux-user-calendar-grid__loader" aria-live="polite" aria-busy="true" aria-label="Updating schedule">
            <Skeleton height={48} borderRadius={12} style={{ width: "min(280px, 90%)" }} />
          </div>
        )}
      </div>
    );
  }
}

export default LuxUserCalendarView;
