import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import classNames from "classnames/bind";
import {
  buildDeliveryGanttModel,
  getMilestoneStatusTone,
  shiftMilestoneSchedule,
} from "config/project-governance.utils";

const SIDEBAR_WIDTH = 240;
const ROW_HEIGHT = 52;
const MIN_PX_PER_DAY = 18;

export default function DeliveryGanttChart({
  milestones,
  dependencies,
  projectFilter,
  canEdit,
  onReschedule,
  onSelectMilestone,
}) {
  const frameRef = useRef(null);
  const [dragState, setDragState] = useState(null);
  const [trackWidth, setTrackWidth] = useState(900);
  const [selectedId, setSelectedId] = useState(null);

  const model = useMemo(
    () =>
      buildDeliveryGanttModel(milestones, dependencies, {
        projectId: projectFilter,
      }),
    [milestones, dependencies, projectFilter]
  );

  const pxPerDay = Math.max(MIN_PX_PER_DAY, trackWidth / Math.max(model.totalDays, 1));
  const canvasWidth = model.totalDays * pxPerDay;
  const todayLeft = model.todayOffset != null ? model.todayOffset * pxPerDay : null;

  useEffect(() => {
    const el = frameRef.current;
    if (!el || typeof ResizeObserver === "undefined") {
      return undefined;
    }

    const measure = () => {
      const scrollEl = el.querySelector(".lux-delivery-gantt__tracks-scroll");
      const w = scrollEl ? scrollEl.clientWidth : el.clientWidth - SIDEBAR_WIDTH;
      const minWidth = model.totalDays * MIN_PX_PER_DAY;
      setTrackWidth(Math.max(w, minWidth));
    };

    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    window.addEventListener("resize", measure);
    return () => {
      ro.disconnect();
      window.removeEventListener("resize", measure);
    };
  }, [model.totalDays]);

  const onBarPointerDown = (e, row) => {
    if (!canEdit) {
      return;
    }
    e.preventDefault();
    e.stopPropagation();
    setDragState({ milestone: row.milestone, startX: e.clientX, deltaDays: 0 });
  };

  const onMouseMove = useCallback(
    (e) => {
      if (!dragState) {
        return;
      }
      const deltaDays = Math.round((e.clientX - dragState.startX) / pxPerDay);
      setDragState((prev) => (prev ? { ...prev, deltaDays } : null));
    },
    [dragState, pxPerDay]
  );

  const onMouseUp = useCallback(async () => {
    if (!dragState) {
      return;
    }
    if (dragState.deltaDays !== 0 && onReschedule) {
      const shifted = shiftMilestoneSchedule(dragState.milestone, dragState.deltaDays);
      await onReschedule(dragState.milestone.id, shifted);
    }
    setDragState(null);
  }, [dragState, onReschedule]);

  if (!model.rows.length) {
    return (
      <div className="lux-delivery-gantt lux-delivery-gantt--empty">
        <p>No milestones in this view. Adjust the project filter or add milestones to build a delivery Gantt.</p>
      </div>
    );
  }

  return (
    <div
      className="lux-delivery-gantt"
      ref={frameRef}
      onMouseMove={onMouseMove}
      onMouseUp={onMouseUp}
      onMouseLeave={onMouseUp}
    >
      <div className="lux-delivery-gantt__legend">
        <span>
          <i className="is-green" /> Complete
        </span>
        <span>
          <i className="is-blue" /> In progress
        </span>
        <span>
          <i className="is-amber" /> At risk
        </span>
        <span>
          <i className="is-rose" /> Critical path
        </span>
        {model.hasDependencyCycle ? (
          <span className="lux-delivery-gantt__legend-warn">Dependency loop — critical path paused</span>
        ) : null}
        <span className="lux-delivery-gantt__legend-note">
          {canEdit ? "Drag bars to shift planned dates · click for details" : "View-only schedule"}
        </span>
      </div>

      <div className="lux-delivery-gantt__frame">
        <div className="lux-delivery-gantt__sidebar-head" style={{ width: SIDEBAR_WIDTH }}>
          Milestone
        </div>
        <div className="lux-delivery-gantt__timeline-head">
          <div className="lux-delivery-gantt__timeline-inner" style={{ width: canvasWidth }}>
            {model.slots.map((slot) => (
              <div
                key={slot.id}
                className="lux-delivery-gantt__month"
                style={{ left: slot.startOffset * pxPerDay, width: slot.span * pxPerDay }}
              >
                {slot.label}
              </div>
            ))}
          </div>
        </div>

        <div className="lux-delivery-gantt__body">
          <div className="lux-delivery-gantt__sidebar" style={{ width: SIDEBAR_WIDTH }}>
            {model.rows.map((row) => (
              <button
                key={row.milestone.id}
                type="button"
                className={classNames("lux-delivery-gantt__lane", {
                  "is-selected": selectedId === row.milestone.id,
                  "is-critical": row.milestone.onCriticalPath,
                })}
                style={{ height: ROW_HEIGHT }}
                onClick={() => {
                  setSelectedId(row.milestone.id);
                  onSelectMilestone && onSelectMilestone(row.milestone);
                }}
              >
                <strong>{row.milestone.name}</strong>
                <span>{row.milestone.projectCode || row.milestone.projectName}</span>
              </button>
            ))}
          </div>

          <div className="lux-delivery-gantt__tracks-scroll">
            <div className="lux-delivery-gantt__tracks" style={{ width: canvasWidth }}>
              {todayLeft != null ? (
                <div className="lux-delivery-gantt__today" style={{ left: todayLeft }} aria-hidden="true" />
              ) : null}

              <svg className="lux-delivery-gantt__links" width={canvasWidth} height={model.rows.length * ROW_HEIGHT}>
                {model.links.map((link) => {
                  const y1 = link.from.rowIndex * ROW_HEIGHT + ROW_HEIGHT / 2;
                  const y2 = link.to.rowIndex * ROW_HEIGHT + ROW_HEIGHT / 2;
                  const x1 = link.from.x * pxPerDay;
                  const x2 = link.to.x * pxPerDay;
                  const midX = x1 + (x2 - x1) / 2;
                  return (
                    <path
                      key={link.id}
                      d={`M ${x1} ${y1} C ${midX} ${y1}, ${midX} ${y2}, ${x2} ${y2}`}
                      className={classNames("lux-delivery-gantt__link-path", {
                        "is-critical": link.isCritical,
                      })}
                    />
                  );
                })}
              </svg>

              {model.rows.map((row) => {
                const isDragging = dragState && dragState.milestone.id === row.milestone.id;
                const dragOffsetDays = isDragging ? dragState.deltaDays : 0;
                const previewSchedule = isDragging
                  ? shiftMilestoneSchedule(row.milestone, dragOffsetDays)
                  : null;
                const tone = getMilestoneStatusTone(row.milestone.status);

                return (
                  <div key={row.milestone.id} className="lux-delivery-gantt__track-row" style={{ height: ROW_HEIGHT }}>
                    <button
                      type="button"
                      className={classNames("lux-delivery-gantt__bar", `is-${tone}`, {
                        "is-dragging": isDragging,
                        "is-critical": row.milestone.onCriticalPath,
                        "is-selected": selectedId === row.milestone.id,
                      })}
                      style={{
                        left: (row.bar.left + dragOffsetDays) * pxPerDay,
                        width: Math.max(row.bar.width * pxPerDay, 12),
                      }}
                      onPointerDown={(e) => onBarPointerDown(e, row)}
                      onClick={() => {
                        setSelectedId(row.milestone.id);
                        onSelectMilestone && onSelectMilestone(row.milestone);
                      }}
                      title={`${row.milestone.name} · ${
                        previewSchedule
                          ? `${previewSchedule.plannedStart} → ${previewSchedule.plannedEnd}`
                          : `${row.milestone.plannedStart} → ${row.milestone.plannedEnd}`
                      }`}
                    >
                      <span
                        className="lux-delivery-gantt__bar-progress"
                        style={{ width: `${Math.min(100, row.milestone.percentComplete || 0)}%` }}
                      />
                      <span className="lux-delivery-gantt__bar-label">{row.milestone.name}</span>
                    </button>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
