export const RECRUITING_PIPELINE_STAGES = [
  "APPLIED",
  "SCREENING",
  "INTERVIEW",
  "OFFER",
  "HIRED",
  "REJECTED",
  "WITHDRAWN",
];

export function formatRecruitingStage(stage) {
  const key = String(stage || "").toUpperCase();
  if (!key) return "Unknown";
  return key.charAt(0) + key.slice(1).toLowerCase();
}

export function buildRecruitingKpiCards(summary) {
  if (!summary) return [];

  const approved = summary.approvedRequisitionCount != null ? summary.approvedRequisitionCount : 0;
  const openInterviews = summary.openInterviewCount != null ? summary.openInterviewCount : 0;
  const accepted = summary.acceptedOfferCount != null ? summary.acceptedOfferCount : 0;

  return [
    {
      id: "req",
      label: "Requisitions",
      value: summary.requisitionCount != null ? summary.requisitionCount : 0,
      hint: `${approved} approved`,
      tone: "primary",
      icon: "fe fe-file-text",
    },
    {
      id: "cand",
      label: "Candidates",
      value: summary.candidateCount != null ? summary.candidateCount : 0,
      hint: "Active pipeline",
      tone: "violet",
      icon: "fe fe-users",
    },
    {
      id: "int",
      label: "Interviews",
      value: summary.interviewCount != null ? summary.interviewCount : 0,
      hint: `${openInterviews} open`,
      tone: "blue",
      icon: "fe fe-calendar",
    },
    {
      id: "off",
      label: "Offers",
      value: summary.offerCount != null ? summary.offerCount : 0,
      hint: `${accepted} accepted`,
      tone: "amber",
      icon: "fe fe-award",
    },
    {
      id: "post",
      label: "Open postings",
      value: summary.openPostingCount != null ? summary.openPostingCount : 0,
      hint: "Published roles",
      tone: "green",
      icon: "fe fe-radio",
    },
  ];
}

export function buildRecruitingPipelineStages(summary) {
  if (!summary) return [];
  const byStage = summary.candidatesByStage || {};
  const total = Number(summary.candidateCount) || 0;

  return RECRUITING_PIPELINE_STAGES.map((stage) => {
    const count = Number(byStage[stage]) || 0;
    return {
      stage,
      label: formatRecruitingStage(stage),
      count,
      pct: total > 0 ? Math.round((count / total) * 100) : 0,
    };
  });
}

export function buildRecruitingInsights(summary, snapshots = {}) {
  if (!summary) return [];

  const insights = [];
  const pendingReqs = (snapshots.requisitions || []).filter(
    (row) => String(row.status || "").toUpperCase() === "SUBMITTED"
  ).length;
  const openInterviews = Number(summary.openInterviewCount) || 0;
  const interviewStage = Number((summary.candidatesByStage || {}).INTERVIEW) || 0;
  const offerStage = Number((summary.candidatesByStage || {}).OFFER) || 0;
  const accepted = Number(summary.acceptedOfferCount) || 0;

  if (pendingReqs > 0) {
    insights.push({
      id: "pending-req",
      tone: "amber",
      icon: "fe fe-clock",
      title: `${pendingReqs} requisition${pendingReqs === 1 ? "" : "s"} awaiting approval`,
      copy: "Review submitted headcount before posting roles to candidates.",
      path: "/recruiting/requisitions",
    });
  }

  if (openInterviews > 0) {
    insights.push({
      id: "open-interviews",
      tone: "blue",
      icon: "fe fe-calendar",
      title: `${openInterviews} interview round${openInterviews === 1 ? "" : "s"} open`,
      copy: "Capture feedback to advance candidates toward offer.",
      path: "/recruiting/interviews",
    });
  }

  if (interviewStage > 0) {
    insights.push({
      id: "interview-stage",
      tone: "violet",
      icon: "fe fe-users",
      title: `${interviewStage} candidate${interviewStage === 1 ? "" : "s"} in interview`,
      copy: "Keep the pipeline moving with timely panel decisions.",
      path: "/recruiting/candidates",
    });
  }

  if (offerStage > 0) {
    insights.push({
      id: "offer-stage",
      tone: "green",
      icon: "fe fe-award",
      title: `${offerStage} candidate${offerStage === 1 ? "" : "s"} at offer`,
      copy: "Finalize compensation and route offers for approval.",
      path: "/recruiting/offers",
    });
  }

  if (accepted > 0) {
    insights.push({
      id: "accepted-offers",
      tone: "green",
      icon: "fe fe-check-circle",
      title: `${accepted} accepted offer${accepted === 1 ? "" : "s"}`,
      copy: "Accepted offers create onboarding cases — Employee converts later via HR-ONB.",
      path: "/recruiting/offers",
    });
  }

  if (insights.length === 0) {
    insights.push({
      id: "empty-pipeline",
      tone: "indigo",
      icon: "fe fe-user-check",
      title: "Start the hiring pipeline",
      copy: "Create a requisition, add candidates, and schedule interviews to populate ATS metrics.",
      path: "/recruiting/requisitions",
    });
  }

  return insights.slice(0, 3);
}

export function pickRecruitingActionRows(rows, limit = 5) {
  return (rows || []).slice(0, limit);
}

export function filterPendingRequisitions(rows) {
  return (rows || []).filter((row) => {
    const status = String(row.status || "").toUpperCase();
    return status === "SUBMITTED" || status === "DRAFT" || status === "OPEN";
  });
}

export function filterActiveCandidates(rows) {
  return (rows || []).filter((row) => {
    const stage = String(row.stage || "").toUpperCase();
    return stage && !["HIRED", "REJECTED", "WITHDRAWN"].includes(stage);
  });
}

export function filterOpenInterviews(rows) {
  return (rows || []).filter((row) => String(row.status || "").toUpperCase() !== "COMPLETED");
}

export function filterPendingOffers(rows) {
  return (rows || []).filter((row) => {
    const status = String(row.status || "").toUpperCase();
    return status && !["ACCEPTED", "DECLINED"].includes(status);
  });
}
