import React, { Component } from "react";
import { PersonaContext } from "context/PersonaContextProvider";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import { onboardingService } from "_services/onboarding.service";
import {
  isOnboardingRouteEnabled,
  isOffboardingRouteEnabled,
  ONBOARDING_TASK_CATEGORIES,
  OFFBOARDING_TASK_CATEGORIES,
} from "config/onboarding.config";
import {
  buildLifecycleCaseMetrics,
  canConvertOnboardingCase,
  computeCaseProgress,
  groupTasksByCategory,
} from "config/onboarding.utils";
import ConvertToEmployeePanel from "views/people/components/onboarding/ConvertToEmployeePanel";
import OffboardingSettlementStrip from "views/people/components/onboarding/OffboardingSettlementStrip";
import LifecycleCaseAuditStrip from "views/people/components/onboarding/LifecycleCaseAuditStrip";
import LifecycleBackNav from "views/people/components/onboarding/LifecycleBackNav";
import LifecycleCaseSummary from "views/people/components/onboarding/LifecycleCaseSummary";
import LifecycleCaseHero from "views/people/components/onboarding/LifecycleCaseHero";
import LifecycleCaseKpiStrip from "views/people/components/onboarding/LifecycleCaseKpiStrip";
import LifecycleActionLink from "views/people/components/onboarding/LifecycleActionLink";
import LifecycleChecklistHeader from "views/people/components/onboarding/LifecycleChecklistHeader";
import OnboardingChecklistPanel from "views/people/components/onboarding/OnboardingChecklistPanel";
import OnboardingTaskDrawer from "views/people/components/onboarding/OnboardingTaskDrawer";

class LifecycleCaseDetailsPage extends Component {
  static contextType = PersonaContext;

  state = {
    caseData: null,
    loading: true,
    loadError: null,
    selectedTask: null,
    drawerOpen: false,
    completing: false,
    rejecting: false,
    actionError: null,
    convertPanelOpen: false,
  };

  componentDidMount() {
    this.loadCase();
  }

  componentDidUpdate(prevProps) {
    const prevId = prevProps.match && prevProps.match.params && prevProps.match.params.caseId;
    const nextId = this.props.match && this.props.match.params && this.props.match.params.caseId;
    if (prevId !== nextId) {
      this.loadCase();
    }
  }

  getLifecycle = () => (this.props.lifecycle === "offboarding" ? "offboarding" : "onboarding");

  isRouteEnabled = (menuAccessControl) => {
    return this.getLifecycle() === "offboarding"
      ? isOffboardingRouteEnabled(menuAccessControl)
      : isOnboardingRouteEnabled(menuAccessControl);
  };

  loadCase = async () => {
    const caseId = this.props.match && this.props.match.params && this.props.match.params.caseId;
    if (!caseId) {
      this.setState({ loading: false, loadError: "Case not found." });
      return;
    }

    this.setState({ loading: true, loadError: null });
    try {
      const res =
        this.getLifecycle() === "offboarding"
          ? await onboardingService.getOffboardingCase(caseId)
          : await onboardingService.getOnboardingCase(caseId);
      const pageTitle =
        this.getLifecycle() === "offboarding"
          ? (res.payload && res.payload.employeeName) || "Offboarding case"
          : (res.payload && res.payload.candidateName) || "Onboarding case";
      this.props.pageHeaderNameChangeHandler(pageTitle);
      this.setState({
        caseData: res.payload,
        loading: false,
        loadError: res.payload ? null : "Case not found.",
      });
    } catch (_e) {
      this.setState({ loading: false, loadError: "Unable to load case details." });
    }
  };

  handleTaskSelect = (task) => {
    this.setState({ selectedTask: task, drawerOpen: true });
  };

  handleDrawerClose = () => {
    this.setState({ drawerOpen: false, selectedTask: null });
  };

  handleOpenConvertPanel = (event) => {
    if (event && event.preventDefault) {
      event.preventDefault();
    }
    this.setState({ convertPanelOpen: true, drawerOpen: false, selectedTask: null });
  };

  handleCloseConvertPanel = () => {
    this.setState({ convertPanelOpen: false });
  };

  handleConverted = async () => {
    await this.loadCase();
  };

  handleCompleteTask = async (task) => {
    const { caseData } = this.state;
    if (!caseData || !task || this.state.completing || this.state.rejecting) {
      return;
    }
    this.setState({ completing: true, actionError: null });
    try {
      if (this.getLifecycle() === "offboarding") {
        await onboardingService.completeOffboardingTask(caseData.id, task.id);
      } else {
        await onboardingService.completeOnboardingTask(caseData.id, task.id);
      }
      await this.loadCase();
      this.setState({ drawerOpen: false, selectedTask: null, completing: false });
    } catch (e) {
      this.setState({
        completing: false,
        actionError: (e && e.message) || "Unable to complete task.",
      });
    }
  };

  handleRejectTask = async (task, comment) => {
    const { caseData } = this.state;
    if (!caseData || !task || this.state.completing || this.state.rejecting) {
      return;
    }
    const reason = String(comment || "").trim();
    if (!reason) {
      this.setState({ actionError: "A reject reason is required." });
      return;
    }
    this.setState({ rejecting: true, actionError: null });
    try {
      await onboardingService.rejectLifecycleApprovalTask(
        caseData.id,
        task.id,
        this.getLifecycle(),
        reason
      );
      await this.loadCase();
      this.setState({ drawerOpen: false, selectedTask: null, rejecting: false });
    } catch (e) {
      this.setState({
        rejecting: false,
        actionError: (e && e.message) || "Unable to reject task.",
      });
    }
  };

  render() {
    const personaCtx = this.context || {};
    if (!this.isRouteEnabled(personaCtx.menuAccessControl)) {
      return (
        <PersonaAccessDenied
          moduleName={this.getLifecycle() === "offboarding" ? "Offboarding" : "Onboarding"}
          reason="This lifecycle module is not enabled for your organization."
        />
      );
    }

    const {
      caseData,
      loading,
      loadError,
      selectedTask,
      drawerOpen,
      completing,
      rejecting,
      actionError,
      convertPanelOpen,
    } = this.state;
    const lifecycle = this.getLifecycle();
    const showConvertCta =
      lifecycle === "onboarding" &&
      caseData &&
      !caseData.employeeId &&
      caseData.status !== "completed" &&
      caseData.status !== "cancelled" &&
      (canConvertOnboardingCase(caseData) || caseData.status === "ready");
    const categories =
      lifecycle === "offboarding" ? OFFBOARDING_TASK_CATEGORIES : ONBOARDING_TASK_CATEGORIES;
    const groups = caseData ? groupTasksByCategory(caseData.tasks, categories) : [];
    const progress = caseData ? computeCaseProgress(caseData.tasks) : null;
    const displayName = caseData
      ? (lifecycle === "offboarding" ? caseData.employeeName : caseData.candidateName)
      : null;
    const caseMetrics = caseData
      ? buildLifecycleCaseMetrics(caseData, progress, lifecycle)
      : null;

    return (
      <div
        className="lux-onb-page lux-onb-detail lux-hrms-dash pd-page"
        data-testid="page-lifecycle-case"
        data-lifecycle={lifecycle}
      >
        <LifecycleBackNav lifecycle={lifecycle} label={displayName} />

        {loadError && !loading && (
          <LuxRegisterEmptyState
            className="lux-register-empty--compact lux-onb-empty"
            icon="fe fe-alert-circle"
            title="Case unavailable"
            description={loadError}
          />
        )}

        {(loading || caseData) && !loadError && (
          <div className="lux-onb-detail__shell">
            <LifecycleCaseHero
              caseData={caseData || {}}
              loading={loading}
              lifecycle={lifecycle}
            />
            <LifecycleCaseKpiStrip
              metrics={caseMetrics}
              lifecycle={lifecycle}
              loading={loading}
            />
          </div>
        )}

        {caseData && (
          <>
            <LifecycleCaseSummary
              caseData={caseData}
              loading={loading}
              lifecycle={lifecycle}
              progress={progress}
              includeHero={false}
            />

            {lifecycle === "offboarding" && (
              <OffboardingSettlementStrip
                caseData={caseData}
                onTaskSelect={this.handleTaskSelect}
              />
            )}

            {showConvertCta && (
              <div className="lux-onb-detail__cta">
                <LifecycleActionLink
                  variant="primary"
                  icon="fe-user-plus"
                  onClick={this.handleOpenConvertPanel}
                >
                  Convert to employee
                </LifecycleActionLink>
                <span className="lux-onb-detail__cta-hint">
                  All required tasks are complete — create the employee record in HRIS.
                </span>
              </div>
            )}

            {caseData && caseData.employeeId && lifecycle === "onboarding" && (
              <div className="lux-onb-detail__cta lux-onb-detail__cta--done">
                <i className="fe fe-check-circle" aria-hidden />
                <span>Employee record linked — case completed.</span>
                <LifecycleActionLink to="/people/employees" variant="ghost" icon="fe-users">
                  View employees
                </LifecycleActionLink>
              </div>
            )}

            <LifecycleCaseAuditStrip caseId={caseData.id} lifecycle={lifecycle} />

            {actionError && (
              <LuxInlineAlert
                tone="danger"
                title="Task action failed"
                className="lux-onb-page__error"
                testId="lifecycle-task-action-error"
              >
                {actionError}
              </LuxInlineAlert>
            )}

            <section className="lux-hrms-dash__panel lux-onb-checklist-section">
              <LifecycleChecklistHeader progress={progress} lifecycle={lifecycle} />
              <div className="lux-hrms-dash__panel-body">
                <OnboardingChecklistPanel
                  groups={groups}
                  lifecycle={lifecycle}
                  onTaskSelect={this.handleTaskSelect}
                />
              </div>
            </section>
          </>
        )}

        <OnboardingTaskDrawer
          task={selectedTask}
          caseData={caseData}
          open={drawerOpen}
          completing={completing}
          rejecting={rejecting}
          lifecycle={lifecycle}
          onClose={this.handleDrawerClose}
          onComplete={this.handleCompleteTask}
          onReject={this.handleRejectTask}
        />

        <ConvertToEmployeePanel
          caseData={caseData}
          open={convertPanelOpen}
          onClose={this.handleCloseConvertPanel}
          onConverted={this.handleConverted}
        />
      </div>
    );
  }
}

export default LifecycleCaseDetailsPage;
