import React from "react";
import { PerformanceLuxPanel } from "views/performance/components/PerformanceLuxShared";

function isMockAiEvidence(evidence) {
  const source = String((evidence && evidence.source) || "").toLowerCase();
  return source.includes("mock") || source.includes("demo") || source.includes("seed") || source.includes("pilot");
}

export default function PerformanceAiEvidencePanel({ evidence, loading }) {
  if (loading) {
    return <div className="lux-perf-skeleton lux-perf-skeleton--panel" />;
  }
  if (!evidence || isMockAiEvidence(evidence)) {
    return null;
  }
  const sourceLabel = evidence.source === "api" ? "rules-based brief" : String(evidence.source || "live");
  return (
    <PerformanceLuxPanel
      title="AI evidence brief"
      meta={`Confidence ${Math.round((evidence.confidence || 0) * 100)}% · ${sourceLabel}`}
      icon="fe fe-zap"
      accent="rose"
      featured
    >
      <p className="lux-perf-ai__headline">{evidence.headline}</p>
      <ul className="lux-perf-ai__bullets">
        {(evidence.bullets || []).map((item) => (
          <li key={item}>{item}</li>
        ))}
      </ul>
    </PerformanceLuxPanel>
  );
}
