import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isPerformanceManagementEnabled } from "config/performance-management.config";
import { REVIEW_CYCLES_PAGE_META } from "config/performance-management-nav.config";
import { performanceManagementService } from "_services/performanceManagement.service";
import PerformanceLuxPage, { PerformanceActionButton, PerformanceLuxPanel } from "views/performance/components/PerformanceLuxShared";
import ReviewCycleRegister from "views/performance/components/ReviewCycleRegister";
import { ReviewCycleCreateDrawer } from "views/performance/components/PerformanceCreateDrawers";

class ReviewCyclesPage extends Component {
  state = { loading: true, cycles: [], kpiCards: [], dataSource: null, createOpen: false, busy: false };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true });
    try {
      const [overview, cyclesResult] = await Promise.all([
        performanceManagementService.getOverview({}),
        performanceManagementService.listReviewCycles({}),
      ]);
      this.setState({
        loading: false,
        dataSource: cyclesResult.source,
        cycles: cyclesResult.payload || [],
        kpiCards: (overview.payload && overview.payload.kpiCards) || [],
      });
    } catch (error) {
      this.setState({ loading: false, cycles: [] });
    }
  };

  handleCreate = async (payload) => {
    this.setState({ busy: true });
    try {
      await performanceManagementService.createReviewCycle(payload);
      this.setState({ createOpen: false, busy: false });
      await this.loadData();
    } catch (error) {
      this.setState({ busy: false });
    }
  };

  render() {
    if (!isPerformanceManagementEnabled()) {
      return <PersonaAccessDenied featureLabel="Review cycles" />;
    }

    const { loading, cycles, kpiCards, dataSource, createOpen, busy } = this.state;

    return (
      <PerformanceLuxPage
        pageMeta={REVIEW_CYCLES_PAGE_META}
        pageId="review-cycles"
        shellTitle="Review cycles"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        onRefresh={this.loadData}
        refreshLoading={loading}
        heroActions={<><PerformanceActionButton variant="primary" icon="fe fe-plus" onClick={() => this.setState({ createOpen: true })}>
              Launch cycle
            </PerformanceActionButton>
          </>}
      >
        <PerformanceLuxPanel title="Cycle register" meta="Templates, participants, and completion" icon="fe fe-calendar" accent="violet" featured>
          <ReviewCycleRegister cycles={cycles} loading={loading} />
        </PerformanceLuxPanel>
        <ReviewCycleCreateDrawer open={createOpen} onClose={() => this.setState({ createOpen: false })} onCreate={this.handleCreate} busy={busy} />
      </PerformanceLuxPage>
    );
  }
}

export default ReviewCyclesPage;
