import React, { Component } from "react";
import classNames from "classnames/bind";
import WorkItemTimer from "views/common/plugins/WorkItemTimer";
import dateUtils from "_helpers/date.utils";
import { accessUtils } from "_helpers";
import {
  TASKBOARD_COLUMNS,
  filterItemsByStage,
  getTaskBoardCardMeta,
} from "./taskboard.utils";

let columns = TASKBOARD_COLUMNS.map((c) => ({ ...c, canDrop: false }));

class TaskBoardGrid extends Component {
  constructor(props) {
    super(props);
    this.state = { draggedOverCol: 0 };
    this.state.permission = accessUtils.getTaskBoardAccessControl();
  }

  handleOnDragEnter = (stageValue) => {
    this.setState({ draggedOverCol: stageValue });
  };

  handleOnDragStart = (workItem) => {
    workItem.dragging = true;
    columns = columns.map((column) => {
      column.canDrop = column.stage > workItem.stage;
      return column;
    });
  };

  handleOnDragEnd = (workItem) => {
    workItem.dragging = false;
    columns = columns.map((column) => {
      column.canDrop = false;
      return column;
    });
    let draggedOverCol = this.state.draggedOverCol;
    if (this.state.draggedOverCol < workItem.stage) {
      draggedOverCol = workItem.stage;
    }
    if (workItem.stage === 1 && this.state.draggedOverCol === 2) {
      if (this.props.updateWorkItemStatus) {
        this.props.updateWorkItemStatus(workItem.id, "READY_TO_START");
      }
    } else if (
      ((workItem.stage === 1 || workItem.stage === 2) && this.state.draggedOverCol === 3) ||
      ((workItem.stage === 1 || workItem.stage === 2 || workItem.stage === 3) && this.state.draggedOverCol === 4)
    ) {
      this.props.showTaskStatusUpdateModel(
        workItem,
        draggedOverCol === 4 ? "COMPLETED" : "INPROGRESS",
        false,
        () => {}
      );
    } else {
      this.setState({ draggedOverCol: 0 });
    }
  };

  handlePlayWorkItem = (workItem, callbackFunction) => {
    this.props.showTaskStatusUpdateModel(workItem, "COMPLETED", true, callbackFunction);
  };

  render() {
    return (
      <div className="lux-taskboard-kanban" role="region" aria-label="Task kanban board">
        {columns.map((column) => {
          const items = filterItemsByStage(this.props.workItems, column);
          return (
            <KanbanColumn
              key={column.stage}
              column={column}
              items={items}
              onDragEnter={this.handleOnDragEnter}
              onDragStart={this.handleOnDragStart}
              onDragEnd={this.handleOnDragEnd}
              onPause={this.props.onPause}
              onPlay={this.handlePlayWorkItem}
              onViewProject={this.props.onViewProject}
              onViewTask={this.props.onViewTask}
              permission={this.state.permission}
            />
          );
        })}
      </div>
    );
  }
}

class KanbanColumn extends React.Component {
  constructor(props) {
    super(props);
    this.state = { mouseIsHovering: false };
  }

  componentWillReceiveProps() {
    this.setState({ mouseIsHovering: false });
  }

  render() {
    const { column, items } = this.props;
    const colMeta = TASKBOARD_COLUMNS.find((c) => c.stage === column.stage) || column;

    return (
      <div
        className={classNames("lux-taskboard-col", `is-${colMeta.key}`, {
          "is-droppable": column.canDrop && this.state.mouseIsHovering,
        })}
        onDragEnter={() => {
          this.setState({ mouseIsHovering: true });
          this.props.onDragEnter(column.stage);
        }}
        onDragLeave={() => this.setState({ mouseIsHovering: false })}
      >
        <header className="lux-taskboard-col__head">
          <div className="lux-taskboard-col__head-top">
            <h3 className="lux-taskboard-col__title">
              <i className={`fe ${colMeta.icon}`} aria-hidden />
              {colMeta.name}
            </h3>
            <span className="lux-taskboard-col__count">{items ? items.length : 0}</span>
          </div>
          <p className="lux-taskboard-col__hint">{colMeta.hint}</p>
        </header>
        <div className="lux-taskboard-col__body">
          {column.canDrop && (
            <div className="lux-taskboard-col__drop" role="status">
              Drop here to advance
            </div>
          )}
          <ul className="list-unstyled mb-0 p-0">
            {items &&
              items.map((workItem) => (
                <KanbanCard
                  key={workItem.id}
                  workItem={workItem}
                  onDragStart={this.props.onDragStart}
                  onDragEnd={this.props.onDragEnd}
                  onPause={this.props.onPause}
                  onPlay={this.props.onPlay}
                  onViewProject={this.props.onViewProject}
                  onViewTask={this.props.onViewTask}
                  permission={this.props.permission}
                />
              ))}
          </ul>
        </div>
      </div>
    );
  }
}

class KanbanCard extends React.Component {
  render() {
    const { workItem, permission } = this.props;
    const meta = getTaskBoardCardMeta(workItem, permission);
    const isDragging = workItem.dragging === true;
    return (
      <li
        className={classNames("lux-taskboard-card", `is-stage-${meta.column.key}`, {
          "is-dragging": isDragging,
          "is-overdue": meta.isOverdue,
          "is-paused": meta.isPaused,
        })}
      >
        <div
          className="lux-taskboard-card__shell"
          draggable={!isDragging}
          onDragStart={() => this.props.onDragStart(workItem)}
          onDragEnd={() => this.props.onDragEnd(workItem)}
        >
          <div className="lux-taskboard-card__accent" aria-hidden />
          <header className="lux-taskboard-card__head">
            <span className="lux-taskboard-card__drag" aria-hidden="true" title="Drag to move">
              <i className="fe fe-menu" />
            </span>
            <div className="lux-taskboard-card__badges">
              <span className={classNames("lux-taskboard-card__status", `is-${meta.statusMeta.tone}`)}>
                {meta.statusMeta.label}
              </span>
              <span className={classNames("lux-taskboard-card__stage", `is-${meta.column.tone}`)}>
                {meta.column.name}
              </span>
            </div>
            {meta.itemRef && <span className="lux-taskboard-card__ref">{meta.itemRef}</span>}
          </header>

          <div className="lux-taskboard-card__main">
            <strong className="lux-taskboard-card__title">{workItem.name}</strong>
            {workItem.description && (
              <p className="lux-taskboard-card__desc">{workItem.description}</p>
            )}
            {meta.isProject && meta.projectName && (
              <p className="lux-taskboard-card__line">
                <i className="fe fe-briefcase" aria-hidden="true" />
                <span>{meta.projectName}</span>
                {meta.projectCode && <em>{meta.projectCode}</em>}
              </p>
            )}
            {meta.taskName && (
              <p className="lux-taskboard-card__line is-deliverable">
                <i className="fe fe-layers" aria-hidden="true" />
                <span>{meta.taskName}</span>
              </p>
            )}
            <div className="lux-taskboard-card__meta">
              <div className="lux-taskboard-card__meta-item">
                <span>Start</span>
                <strong>{meta.scheduleLabel}</strong>
              </div>
              <div className={classNames("lux-taskboard-card__meta-item", { "is-warn": meta.isOverdue })}>
                <span>Due</span>
                <strong>{meta.dueLabel || "—"}</strong>
              </div>
              {meta.durationLabel && (
                <div className="lux-taskboard-card__meta-item">
                  <span>{meta.stage === 4 ? "Logged" : "Est."}</span>
                  <strong>{meta.durationLabel}</strong>
                </div>
              )}
              {meta.assignee && (
                <div className="lux-taskboard-card__meta-item is-assignee">
                  <span>Owner</span>
                  <strong>{meta.assignee}</strong>
                </div>
              )}
            </div>
            <div className="lux-taskboard-card__chips">
              {workItem.taskActCategory && (
                <span className="lux-taskboard-card__chip is-category">{workItem.taskActCategory}</span>
              )}
              {meta.isProject ? (
                <span className="lux-taskboard-card__chip is-billable">Billable</span>
              ) : (
                <span className="lux-taskboard-card__chip">Non-project</span>
              )}
              {meta.isPaused && <span className="lux-taskboard-card__chip is-paused">Paused</span>}
              {meta.isOverdue && <span className="lux-taskboard-card__chip is-overdue">Overdue</span>}
            </div>
          </div>

          <footer className="lux-taskboard-card__foot">
            {meta.stage === 3 ? (
              <div className="lux-taskboard-card__timer">
                <WorkItemTimer
                  workItem={workItem}
                  onPause={this.props.onPause}
                  onPlay={this.props.onPlay}
                  startTime={dateUtils.convertDateStringToDate(workItem.actualStartTime)}
                  pausedTime={
                    workItem.status === "PAUSED"
                      ? dateUtils.convertDateStringToDate(workItem.taskPausedTime)
                      : null
                  }
                  workItemPausedTime={
                    workItem.status === "PAUSED"
                      ? dateUtils.convertDateStringToDate(workItem.taskActivityPausedTime)
                      : null
                  }
                />
              </div>
            ) : (
              <span className="lux-taskboard-card__foot-hint">
                <i className="fe fe-move" aria-hidden="true" />
                Drag to advance
              </span>
            )}
            {meta.isProject && (
              <div className="lux-taskboard-card__actions">
                <button
                  type="button"
                  className="lux-taskboard-card__action"
                  title="View project"
                  onClick={(e) => {
                    e.stopPropagation();
                    this.props.onViewProject(workItem.projectId);
                  }}
                >
                  <i className="fe fe-briefcase" />
                </button>
                <button
                  type="button"
                  className="lux-taskboard-card__action"
                  title="View deliverable"
                  onClick={(e) => {
                    e.stopPropagation();
                    this.props.onViewTask(workItem.taskId, workItem.projectId);
                  }}
                >
                  <i className="fe fe-layers" />
                </button>
              </div>
            )}
          </footer>
        </div>
      </li>
    );
  }
}

export default TaskBoardGrid;
