import React from 'react';
import { connect } from 'react-redux';
import { withRouter } from 'react-router-dom';
import { leavePhase2Service as api } from '_services/leavePhase2.service';
import { getApiErrorMessage } from '_helpers/apiError.utils';
import { AdminActionButton } from 'views/admin/components/AdminLuxShared';
import {
  LeavePhase2AdminBase,
  LeavePhase2Panel,
  LeavePhase2Register,
  LEAVE_PHASE2_EMPTY_DESCRIPTION,
  mapLeavePhase2State,
  renderLeavePhase2Nav,
  cell,
} from './leavePhase2.shared';
import '../leaveLuxForms.css';

const NAV = [
  { path: '/admin/leave/bidding', label: 'Bidding', icon: 'fe fe-award', exact: true },
  { path: '/admin/leave/roster-planning', label: 'Roster', icon: 'fe fe-grid' },
  { path: '/admin/leave/coverage-optimizer', label: 'Optimizer', icon: 'fe fe-sliders' },
];

const EMPTY_BID = { windowId: '', employeeId: '', startDate: '', endDate: '' };

function sectionFromPath(pathname) {
  if (pathname.includes('roster-planning')) return 'roster';
  if (pathname.includes('coverage-optimizer')) return 'optimizer';
  return 'bidding';
}

class LeaveWorkforcePlanningPage extends LeavePhase2AdminBase {
  state = {
    ...this.state,
    windows: [],
    bids: [],
    coverageRules: [],
    coveragePreview: null,
    saving: false,
    bidForm: { ...EMPTY_BID },
  };

  fetchSectionData = async (teamId) => {
    const section = sectionFromPath(this.props.location.pathname);
    const windows = (await api.listQuotaWindows(teamId)) || [];
    const windowList = Array.isArray(windows) ? windows : [];
    this.setState({ windows: windowList });

    if (section === 'bidding') {
      const windowId = windowList.length ? windowList[0].id : null;
      const bids = windowId ? await api.listLeaveBids(teamId, windowId) : [];
      this.setState({
        bids: Array.isArray(bids) ? bids : [],
        bidForm: {
          ...EMPTY_BID,
          windowId: windowId ? String(windowId) : '',
        },
      });
      return;
    }
    if (section === 'roster') {
      const coverageRules = (await api.listCoverageRules(teamId)) || [];
      this.setState({ coverageRules: Array.isArray(coverageRules) ? coverageRules : [] });
      return;
    }
    let coveragePreview = null;
    if (windowList.length && windowList[0].id) {
      coveragePreview = await api.previewCoverage(teamId, windowList[0].id).catch(() => null);
    }
    this.setState({ coveragePreview });
  };

  submitBid = (event) => {
    event.preventDefault();
    const { bidForm } = this.state;
    const windowId = Number(bidForm.windowId);
    const employeeId = Number(bidForm.employeeId);
    if (!windowId || !employeeId) {
      this.setState({ error: 'Window and employee ID are required.' });
      return;
    }
    const teamId = this.teamId();
    if (!teamId) {
      this.setState({ error: 'Select a team first.' });
      return;
    }
    this.setState({ saving: true, error: null, notice: null });
    api
      .submitLeaveBid({
        userTeamId: teamId,
        actorId: this.actorId(),
        windowId,
        employeeId,
        startDate: bidForm.startDate || null,
        endDate: bidForm.endDate || null,
      })
      .then(() => {
        this.setState({
          saving: false,
          notice: 'Leave bid submitted.',
          bidForm: { ...EMPTY_BID, windowId: String(windowId) },
        });
        return this.loadAll();
      })
      .catch((e) => {
        this.setState({
          saving: false,
          error: getApiErrorMessage(e, 'Could not submit bid.'),
        });
      });
  };

  render() {
    const { loading, windows, bids, coverageRules, coveragePreview, bidForm, saving } = this.state;
    const section = sectionFromPath(this.props.location.pathname);
    const previewRows = coveragePreview && typeof coveragePreview === 'object' ? [coveragePreview] : [];
    const kpiCards = [
      { id: 'win', label: 'Quota windows', value: windows.length, tone: 'primary', icon: 'fe fe-calendar' },
      { id: 'bid', label: 'Bids', value: bids.length, tone: 'blue', icon: 'fe fe-award' },
      { id: 'cov', label: 'Coverage rules', value: coverageRules.length, tone: 'green', icon: 'fe fe-grid' },
    ];

    return this.renderChrome({
      testId: 'page-leave-workforce-planning',
      kpiCards,
      pageMeta: {
        tone: 'emerald',
        icon: 'fe fe-award',
        eyebrow: 'Admin · Leave',
        titleLead: 'Workforce',
        titleAccent: 'planning',
        lede: windows.length
          ? 'Submit bids against seeded quota windows; roster/optimizer remain preview registers.'
          : 'Quota windows must be seeded via API before bidding. Roster/optimizer are preview registers.',
      },
      heroNav: renderLeavePhase2Nav(NAV, this.props.location.pathname),
      children: (
        <>
          {section === 'bidding' && (
            <>
              {windows.length ? (
                <LeavePhase2Panel title="Submit leave bid" subtitle="Requires an existing quota window.">
                  <form className="lux-glp-form" onSubmit={this.submitBid} data-testid="glp24-submit-bid-form">
                    <label>
                      Window
                      <select
                        required
                        value={bidForm.windowId}
                        onChange={(e) =>
                          this.setState({ bidForm: { ...bidForm, windowId: e.target.value } })
                        }
                      >
                        {windows.map((w) => (
                          <option key={w.id} value={w.id}>
                            {w.name || w.windowRef || w.id}
                          </option>
                        ))}
                      </select>
                    </label>
                    <label>
                      Employee ID
                      <input
                        required
                        value={bidForm.employeeId}
                        onChange={(e) =>
                          this.setState({ bidForm: { ...bidForm, employeeId: e.target.value } })
                        }
                      />
                    </label>
                    <label>
                      Start
                      <input
                        type="date"
                        value={bidForm.startDate}
                        onChange={(e) =>
                          this.setState({ bidForm: { ...bidForm, startDate: e.target.value } })
                        }
                      />
                    </label>
                    <label>
                      End
                      <input
                        type="date"
                        value={bidForm.endDate}
                        onChange={(e) =>
                          this.setState({ bidForm: { ...bidForm, endDate: e.target.value } })
                        }
                      />
                    </label>
                    <div className="lux-glp-form__actions">
                      <AdminActionButton type="submit" icon="fe fe-plus" disabled={saving || loading}>
                        Submit bid
                      </AdminActionButton>
                    </div>
                  </form>
                </LeavePhase2Panel>
              ) : null}
              <LeavePhase2Panel title="Leave bidding" subtitle="Quota windows and employee bids with fairness priority.">
                <LeavePhase2Register
                  loading={loading}
                  rows={bids}
                  testId="glp24-bids-register"
                  emptyTitle="No leave bids"
                  emptyDescription={
                    windows.length
                      ? LEAVE_PHASE2_EMPTY_DESCRIPTION
                      : 'No quota windows yet — seed windows via API, then submit bids here.'
                  }
                  columns={[
                    { key: 'id', label: 'Bid' },
                    { key: 'employeeId', label: 'Employee' },
                    { key: 'windowId', label: 'Window' },
                    { key: 'requestedDates', label: 'Dates', render: (r) => cell(r.requestedDates || r.startDate) },
                    { key: 'status', label: 'Status' },
                    { key: 'priorityScore', label: 'Priority' },
                  ]}
                />
              </LeavePhase2Panel>
            </>
          )}
          {section === 'roster' && (
            <LeavePhase2Panel title="Roster coverage rules" subtitle="Minimum staffing and roster-aware approval thresholds.">
              <LeavePhase2Register
                loading={loading}
                rows={coverageRules}
                testId="glp24-roster-register"
                emptyTitle="No coverage rules"
                emptyDescription={LEAVE_PHASE2_EMPTY_DESCRIPTION}
                columns={[
                  { key: 'id', label: 'Rule' },
                  { key: 'name', label: 'Name' },
                  { key: 'minCoverage', label: 'Min coverage' },
                  { key: 'rosterScope', label: 'Scope' },
                  { key: 'active', label: 'Active' },
                ]}
              />
            </LeavePhase2Panel>
          )}
          {section === 'optimizer' && (
            <LeavePhase2Panel title="Coverage optimizer preview" subtitle="Alternate dates and staffing suggestions for the active window.">
              <LeavePhase2Register
                loading={loading}
                rows={previewRows}
                testId="glp24-optimizer-register"
                emptyTitle="No optimizer preview"
                emptyDescription={LEAVE_PHASE2_EMPTY_DESCRIPTION}
                columns={[
                  { key: 'windowId', label: 'Window' },
                  { key: 'suggestedAllocations', label: 'Suggestions' },
                  { key: 'coverageGap', label: 'Gap' },
                  { key: 'summary', label: 'Summary' },
                ]}
              />
            </LeavePhase2Panel>
          )}
        </>
      ),
    });
  }
}

export default connect(mapLeavePhase2State)(withRouter(LeaveWorkforcePlanningPage));
