import React from "react";
import classNames from "classnames/bind";
import moment from "moment";

function formatBatchDateLabel(dateKey) {
  const parsed = moment(dateKey, ["YYYY-MM-DD", moment.ISO_8601], true);
  if (!parsed.isValid()) {
    return dateKey;
  }
  return parsed.format("ddd D MMM");
}

function formatBatchDateRange(activityDates) {
  if (!activityDates || !activityDates.length) {
    return "Approved batch";
  }
  const start = formatBatchDateLabel(activityDates[0]);
  const end = formatBatchDateLabel(activityDates[activityDates.length - 1]);
  if (activityDates.length === 1) {
    return start;
  }
  return `${start} – ${end}`;
}

function summarizeBatchDays(activityDates) {
  const count = (activityDates && activityDates.length) || 0;
  if (count === 0) {
    return "Approved";
  }
  return count === 1 ? "1 day" : `${count} days`;
}

export function summarizeBatchReopenOption(option) {
  if (!option) {
    return "Approved batch";
  }
  return formatBatchDateRange(option.activityDates || []);
}

export function summarizeBatchDaysForOption(option) {
  return summarizeBatchDays(option && option.activityDates);
}

function TimesheetBatchReopenPicker({
  options,
  selectedSubmissionId,
  onSelect,
  disabled,
  title = "Choose batch to reopen",
  onReopen,
  reopenLabel = "Reopen selected batch",
  showReopenAction = false,
}) {
  const list = Array.isArray(options) ? options : [];
  if (!list.length) {
    return null;
  }

  const selectedId = String(
    selectedSubmissionId != null && selectedSubmissionId !== ""
      ? selectedSubmissionId
      : list[0].submissionId
  );

  return (
    <div
      className="lux-ts-batch-reopen"
      role="radiogroup"
      aria-label={title}
      data-testid="timesheet-reopen-batch-picker"
    >
      <div className="lux-ts-batch-reopen__head">
        <span className="lux-ts-batch-reopen__eyebrow">Submission batches</span>
        <strong className="lux-ts-batch-reopen__title">{title}</strong>
        <p className="lux-ts-batch-reopen__hint">
          Select an approved batch to unlock those days for correction. Other days stay unchanged.
        </p>
      </div>
      <div className="lux-ts-batch-reopen__grid">
        {list.map((option, index) => {
          const id = String(option.submissionId);
          const isSelected = id === selectedId;
          const activityDates = option.activityDates || [];
          const rangeLabel = formatBatchDateRange(activityDates);
          const daySummary = summarizeBatchDays(activityDates);

          return (
            <button
              key={option.submissionId}
              type="button"
              role="radio"
              aria-checked={isSelected}
              disabled={disabled}
              className={classNames("lux-ts-batch-reopen__card", {
                "is-selected": isSelected,
              })}
              onClick={() => onSelect && onSelect(option.submissionId)}
              data-testid={`timesheet-reopen-batch-card-${option.submissionId}`}
            >
              <span className="lux-ts-batch-reopen__card-index" aria-hidden="true">
                {String(index + 1).padStart(2, "0")}
              </span>
              <span className="lux-ts-batch-reopen__card-body">
                <span className="lux-ts-batch-reopen__card-range">{rangeLabel}</span>
                <span className="lux-ts-batch-reopen__card-meta">
                  <span className="lux-ts-batch-reopen__pill is-days">{daySummary}</span>
                  <span className="lux-ts-batch-reopen__pill is-id">#{option.submissionId}</span>
                  <span className="lux-ts-batch-reopen__pill is-approved">
                    <i className="fe fe-check-circle" aria-hidden="true" />
                    Approved
                  </span>
                </span>
                {activityDates.length > 1 ? (
                  <span className="lux-ts-batch-reopen__card-days" aria-hidden="true">
                    {activityDates.map((dateKey) => (
                      <span key={dateKey} className="lux-ts-batch-reopen__day-dot">
                        {formatBatchDateLabel(dateKey).replace(/^[A-Za-z]+\s/, "")}
                      </span>
                    ))}
                  </span>
                ) : null}
              </span>
              <span className="lux-ts-batch-reopen__card-check" aria-hidden="true">
                <i className={`fe ${isSelected ? "fe-check-circle" : "fe-circle"}`} />
              </span>
            </button>
          );
        })}
      </div>
      {showReopenAction && onReopen ? (
        <div className="lux-ts-batch-reopen__actions">
          <button
            type="button"
            className={classNames("lux-ts-batch-reopen__btn", { "is-loading": disabled })}
            disabled={disabled}
            onClick={onReopen}
            data-testid="timesheet-reopen-week"
          >
            <i className="fe fe-rotate-ccw" aria-hidden="true" />
            {reopenLabel}
          </button>
        </div>
      ) : null}
    </div>
  );
}

export default TimesheetBatchReopenPicker;
