import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isWorkflowAutomationEnabled } from "config/workflow-automation.config";
import { AUTOMATION_RULES_PAGE_META } from "config/workflow-automation-nav.config";
import { workflowAutomationService } from "_services/workflowAutomation.service";
import WorkflowLuxPage, {
  WorkflowActionButton,
  WorkflowInsightPanel,
} from "views/automation/components/WorkflowLuxShared";
import RuleBuilderPanel from "views/automation/components/RuleBuilderPanel";
import TriggerConfigPanel from "views/automation/components/TriggerConfigPanel";
import WorkflowRunHistoryPanel from "views/automation/components/WorkflowRunHistoryPanel";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

function getRuleIdFromQuery(search) {
  const params = new URLSearchParams(search || "");
  return params.get("rule");
}

class AutomationRulesPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    triggers: [],
    actions: [],
    rule: null,
    runs: [],
    insights: [],
    kpiCards: [],
    selectedTrigger: null,
    selectedRunId: null,
    busy: false,
  };

  componentDidMount() {
    this.loadData();
  }

  componentDidUpdate(prevProps) {
    const prevRule = getRuleIdFromQuery(prevProps.location && prevProps.location.search);
    const nextRule = getRuleIdFromQuery(this.props.location && this.props.location.search);
    if (prevRule !== nextRule) {
      this.loadData();
    }
  }

  loadData = async () => {
    const ruleId = getRuleIdFromQuery(this.props.location && this.props.location.search);
    this.setState({ loading: true, loadError: null });
    try {
      const overview = await workflowAutomationService.getOverview({});
      const payload = overview.payload || {};
      let rule = null;
      if (ruleId) {
        const ruleResult = await workflowAutomationService.getRule(ruleId);
        rule = ruleResult.payload;
      } else if ((payload.rules || []).length) {
        rule = payload.rules[0];
      }
      const runsResult = await workflowAutomationService.listRuns(rule ? { ruleId: rule.id } : {});
      this.setState({
        loading: false,
        dataSource: overview.source,
        triggers: payload.triggers || [],
        actions: payload.actions || [],
        rule: rule,
        runs: runsResult.payload || [],
        insights: payload.insights || [],
        kpiCards: payload.kpiCards || [],
        selectedTrigger: rule ? rule.triggerType : null,
        selectedRunId: (runsResult.payload && runsResult.payload[0] && runsResult.payload[0].id) || null,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load automation rules.",
      });
    }
  };

  handleFieldChange = (field, value) => {
    this.setState((prev) => ({
      rule: { ...(prev.rule || {}), [field]: value },
    }));
  };

  handleTriggerSelect = (trigger) => {
    this.setState((prev) => ({
      selectedTrigger: trigger.id,
      rule: {
        ...(prev.rule || {}),
        triggerType: trigger.id,
        triggerLabel: trigger.label,
      },
    }));
  };

  handleSave = async () => {
    const { rule } = this.state;
    if (!rule) {
      return;
    }
    this.setState({ busy: true });
    try {
      await workflowAutomationService.saveRule(rule);
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to save rule." });
    } finally {
      this.setState({ busy: false });
    }
  };

  handlePublish = async () => {
    const { rule } = this.state;
    if (!rule || !rule.id) {
      return;
    }
    this.setState({ busy: true });
    try {
      await workflowAutomationService.publishRule(rule.id);
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to publish rule." });
    } finally {
      this.setState({ busy: false });
    }
  };

  handleTestTrigger = async () => {
    const { rule } = this.state;
    if (!rule || !rule.id) {
      return;
    }
    this.setState({ busy: true, loadError: null });
    try {
      const result = await workflowAutomationService.testTrigger(rule.id, {
        triggerEventType: rule.triggerType || "manual.test",
        triggerEntityType: "WORKFLOW_RULE",
        triggerEntityId: rule.id,
        source: "test-trigger",
      });
      if (result && result.source === "api-error") {
        this.setState({ loadError: "Workflow automation API is disabled or unavailable." });
        return;
      }
      await this.loadData();
      if (result && result.payload && result.payload.id) {
        this.setState({ selectedRunId: result.payload.id });
      }
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to fire test trigger." });
    } finally {
      this.setState({ busy: false });
    }
  };

  render() {
    if (!isWorkflowAutomationEnabled()) {
      return <PersonaAccessDenied featureLabel="Automation rules" />;
    }

    const {
      loading,
      loadError,
      dataSource,
      triggers,
      actions,
      rule,
      runs,
      insights,
      kpiCards,
      selectedTrigger,
      selectedRunId,
      busy,
    } = this.state;

    return (
      <WorkflowLuxPage
        pageMeta={AUTOMATION_RULES_PAGE_META}
        testId="page-admin-automation-rules"
        shellTitle="Automation rules"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        heroActions={
          <>
            <WorkflowActionButton to="/admin/workflows" icon="fe fe-git-branch">
              Studio
            </WorkflowActionButton>
            <WorkflowActionButton icon="fe fe-save" onClick={this.handleSave} disabled={busy || !rule}>
              Save draft
            </WorkflowActionButton>
            <WorkflowActionButton variant="primary" icon="fe fe-check-circle" onClick={this.handlePublish} disabled={busy || !rule}>
              Publish
            </WorkflowActionButton>
            <WorkflowActionButton
              icon="fe fe-zap"
              onClick={this.handleTestTrigger}
              disabled={busy || !rule || !rule.id}
              data-testid="workflow-test-trigger"
            >
              Test trigger
            </WorkflowActionButton>
          </>
        }
      >
        {loadError ? <LuxInlineAlert message={loadError} /> : null}
        <WorkflowInsightPanel insights={insights} loading={loading} />

        <div className="lux-wf-page-grid">
          <div className="lux-wf-page-main">
            <RuleBuilderPanel rule={rule} actions={actions} onFieldChange={this.handleFieldChange} loading={loading} />
          </div>
          <div className="lux-wf-page-side">
            <TriggerConfigPanel
              triggers={triggers}
              selectedTrigger={selectedTrigger}
              onSelect={this.handleTriggerSelect}
              loading={loading}
            />
            <WorkflowRunHistoryPanel
              runs={runs}
              loading={loading}
              selectedRunId={selectedRunId}
              onSelect={(run) => this.setState({ selectedRunId: run.id })}
            />
          </div>
        </div>
      </WorkflowLuxPage>
    );
  }
}

export default AutomationRulesPage;
