/**
 * EH16 — Derived delivery sprints FE service. Fail closed when flag on.
 */
import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import { shouldUseDeliverySprintsApi } from "config/delivery-sprints.config";

export const deliverySprintsService = {
  listSprints,
  assignSprint,
};

const API_ERROR = { payload: null, source: "api-error" };

async function listSprints() {
  if (!shouldUseDeliverySprintsApi()) {
    return { ...API_ERROR, reason: "flag-off" };
  }
  try {
    const response = await axiosUtils.getWithParam(`${urlConfig.DELIVERY_API_PATH}/sprints`, {
      userTeamId: commonUtils.getCurrentUserTeamId(),
    });
    const payload = response && response.payload ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    console.warn("[DeliverySprints] API unavailable.", e);
    return { ...API_ERROR, error: e };
  }
}

async function assignSprint(taskId, sprintBucket) {
  if (!shouldUseDeliverySprintsApi()) {
    return { ...API_ERROR, reason: "flag-off" };
  }
  if (taskId == null || !sprintBucket) {
    return { ...API_ERROR, reason: "invalid-args" };
  }
  try {
    const response = await axiosUtils.post(
      `${urlConfig.DELIVERY_API_PATH}/sprints/assign?userTeamId=${commonUtils.getCurrentUserTeamId()}`,
      {
        taskId,
        sprintBucket,
        sprintId: sprintBucket,
      }
    );
    const payload = response && response.payload ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    console.warn("[DeliverySprints] assign unavailable.", e);
    return { ...API_ERROR, error: e };
  }
}
