import React, { PureComponent } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import moment from "moment";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import { buildNoteSavePayload, parseNoteDateTime } from "../notes.utils";
import { commonUtils } from "_helpers";
import LuxNoteEditorFooter from "./LuxNoteEditorFooter";

const STATUS_OPTIONS = [
  { value: "IN_PROGRESS", label: "Open", icon: "fe-edit-3" },
  { value: "COMPLETED", label: "Done", icon: "fe-check-circle" },
];

class LuxNoteEditorPanel extends PureComponent {
  constructor(props) {
    super(props);
    this.state = this.emptyForm();
  }

  emptyForm = () => ({
    name: "",
    description: "",
    noteDateTimeLocal: moment().format("YYYY-MM-DDTHH:mm"),
    remindMe: false,
    status: "IN_PROGRESS",
  });

  componentDidUpdate(prevProps) {
    if (this.props.show && !prevProps.show) {
      this.hydrate();
    }
    if (!this.props.show && prevProps.show) {
      this.setState(this.emptyForm());
    }
  }

  hydrate = () => {
    const { note } = this.props;
    if (!note) {
      this.setState(this.emptyForm());
      return;
    }
    const dt = parseNoteDateTime(note.noteDateTime) || moment();
    this.setState({
      name: note.name || "",
      description: note.description || "",
      noteDateTimeLocal: dt.format("YYYY-MM-DDTHH:mm"),
      remindMe: !!note.remindMe,
      status: note.status === "COMPLETED" ? "COMPLETED" : "IN_PROGRESS",
    });
  };

  onChange = (e) => {
    const { name, type, checked, value } = e.target;
    this.setState({ [name]: type === "checkbox" ? checked : value });
  };

  setStatus = (status) => {
    if (!this.props.isSaving) {
      this.setState({ status });
    }
  };

  toggleRemind = () => {
    if (!this.props.isSaving) {
      this.setState((prev) => ({ remindMe: !prev.remindMe }));
    }
  };

  buildPayload = () => {
    const name = (this.state.name || "").trim();
    if (!name) return null;
    return buildNoteSavePayload({
      name,
      description: this.state.description,
      noteDateTimeLocal: this.state.noteDateTimeLocal,
      note: this.props.note,
      employeeId: commonUtils.getCurrentUserId(),
      remindMe: this.state.remindMe,
      status: this.state.status,
    });
  };

  handleSubmit = (e) => {
    if (e) e.preventDefault();
    const payload = this.buildPayload();
    if (payload) this.props.onSave(payload);
  };

  renderPreview = () => {
    const { name, description, noteDateTimeLocal, remindMe, status } = this.state;
    const title = (name || "").trim() || "Untitled note";
    const pending = status !== "COMPLETED";
    const m = noteDateTimeLocal ? moment(noteDateTimeLocal) : null;
    const previewDate = m && m.isValid() ? m.format("ddd, D MMM YYYY · HH:mm") : "—";

    return (
      <article className={classNames("lux-note-editor-preview", { "is-done": !pending })}>
        <span className="lux-note-editor-preview__pin" aria-hidden="true" />
        <header className="lux-note-editor-preview__head">
          <h3 className="lux-note-editor-preview__title">{title}</h3>
          <div className="lux-note-editor-preview__badges">
            {remindMe && (
              <span className="lux-note-editor-preview__remind" title="Reminder on">
                <i className="fe fe-bell" aria-hidden="true" />
              </span>
            )}
            <span className={classNames("lux-note-editor-preview__status", pending ? "is-open" : "is-done")}>
              {pending ? "Open" : "Done"}
            </span>
          </div>
        </header>
        <p className="lux-note-editor-preview__body">
          {(description || "").trim() ? description : "Add details below — they appear here live."}
        </p>
        <footer className="lux-note-editor-preview__foot">
          <i className="fe fe-calendar" aria-hidden="true" />
          <span>{previewDate}</span>
        </footer>
      </article>
    );
  };

  render() {
    const { show, onClose, isSaving, note } = this.props;
    if (!show) return null;

    const isEdit = !!(note && note.id);
    const canSubmit = !!(this.state.name || "").trim();
    const titleId = "lux-note-editor-modal-title";

    const modal = (
      <>
        <button
          type="button"
          className="lux-note-editor-modal__backdrop"
          aria-label="Close note editor"
          onClick={onClose}
        />
        <div
          className="lux-note-editor-modal"
          role="dialog"
          aria-modal="true"
          aria-labelledby={titleId}
        >
          <div className="lux-note-editor-modal__glow" aria-hidden="true" />

          <header className="lux-note-editor-modal__hero">
            <div className="lux-note-editor-modal__hero-top">
              <div className="lux-note-editor-modal__hero-brand">
                <span className="lux-note-editor-modal__icon" aria-hidden="true">
                  <i className="fe fe-book-open" />
                </span>
                <div className="lux-note-editor-modal__hero-copy">
                  <LuxSummaryEyebrow variant="notes" className="lux-note-editor-modal__eyebrow">
                    Personal notes
                  </LuxSummaryEyebrow>
                  <h2 id={titleId}>{isEdit ? "Edit note" : "New note"}</h2>
                  <p className="lux-note-editor-modal__subtitle">
                    Title, details, date &amp; time, status, and optional reminder.
                  </p>
                </div>
              </div>
              <button
                type="button"
                className="lux-note-editor-modal__close"
                onClick={onClose}
                aria-label="Close"
                disabled={isSaving}
              >
                <i className="fe fe-x" aria-hidden="true" />
              </button>
            </div>
          </header>

          <div className="lux-note-editor-modal__body">
            {this.renderPreview()}

            <form
              id="lux-note-editor-form"
              className="lux-create-panel__form-grid lux-create-form lux-note-editor-form"
              onSubmit={this.handleSubmit}
            >
              <section className="lux-create-field-group">
                <header className="lux-create-field-group__head">
                  <h3 className="lux-create-field-group__title">Note content</h3>
                  <p className="lux-create-field-group__desc">What you want to remember and any supporting detail.</p>
                </header>
                <div className="lux-create-field-group__grid lux-create-field-group__grid--1">
                  <div className="lux-create-field lux-create-field--span-full">
                    <div className="lux-create-field__inner">
                      <div className="form-group">
                        <label className="form-label" htmlFor="lux-note-name">
                          Title <span className="text-danger">*</span>
                        </label>
                        <input
                          id="lux-note-name"
                          type="text"
                          name="name"
                          className="form-control"
                          value={this.state.name}
                          onChange={this.onChange}
                          placeholder="e.g. Follow up with design on deliverable X"
                          maxLength={500}
                          required
                          disabled={isSaving}
                          autoFocus
                        />
                      </div>
                    </div>
                  </div>
                  <div className="lux-create-field lux-create-field--span-full">
                    <div className="lux-create-field__inner">
                      <div className="form-group">
                        <label className="form-label" htmlFor="lux-note-desc">
                          Details
                        </label>
                        <textarea
                          id="lux-note-desc"
                          name="description"
                          className="form-control"
                          rows={4}
                          value={this.state.description}
                          onChange={this.onChange}
                          placeholder="Context, links, bullet points, or next steps…"
                          disabled={isSaving}
                        />
                      </div>
                    </div>
                  </div>
                </div>
              </section>

              <section className="lux-create-field-group">
                <header className="lux-create-field-group__head">
                  <h3 className="lux-create-field-group__title">Schedule &amp; status</h3>
                  <p className="lux-create-field-group__desc">When the note applies and whether it stays open or is archived.</p>
                </header>
                <div className="lux-create-field-group__grid lux-create-field-group__grid--1">
                  <div className="lux-create-field lux-create-field--span-full">
                    <div className="lux-create-field__inner">
                      <div className="form-group">
                        <label className="form-label" htmlFor="lux-note-datetime">
                          Date &amp; time
                        </label>
                        <input
                          id="lux-note-datetime"
                          type="datetime-local"
                          name="noteDateTimeLocal"
                          className="form-control"
                          value={this.state.noteDateTimeLocal}
                          onChange={this.onChange}
                          disabled={isSaving}
                        />
                      </div>
                    </div>
                  </div>
                  <div className="lux-create-field lux-create-field--span-full">
                    <div className="lux-create-field__inner">
                      <span className="form-label d-block">Status</span>
                      <div className="lux-create-mode lux-note-editor-status" role="group" aria-label="Note status">
                        {STATUS_OPTIONS.map((opt) => (
                          <button
                            key={opt.value}
                            type="button"
                            className={classNames("lux-create-mode__pill", {
                              "is-active": this.state.status === opt.value,
                            })}
                            onClick={() => this.setStatus(opt.value)}
                            disabled={isSaving}
                          >
                            <i className={classNames("fe", opt.icon)} aria-hidden="true" />
                            {opt.label}
                          </button>
                        ))}
                      </div>
                    </div>
                  </div>
                  <div className="lux-create-field lux-create-field--span-full">
                    <button
                      type="button"
                      className={classNames("lux-note-editor-option", {
                        "is-active": this.state.remindMe,
                      })}
                      onClick={this.toggleRemind}
                      disabled={isSaving}
                      aria-pressed={this.state.remindMe}
                    >
                      <span className="lux-note-editor-option__icon" aria-hidden="true">
                        <i className="fe fe-bell" />
                      </span>
                      <span className="lux-note-editor-option__copy">
                        <strong>Remind me</strong>
                        <span>Flag this note for follow-up notifications</span>
                      </span>
                      <span className={classNames("lux-note-editor-option__switch", { "is-on": this.state.remindMe })}>
                        <span className="lux-note-editor-option__knob" />
                      </span>
                    </button>
                  </div>
                </div>
              </section>
            </form>
          </div>

          <LuxNoteEditorFooter
            isEdit={isEdit}
            isSaving={isSaving}
            canSubmit={canSubmit}
            onClose={onClose}
            onSubmit={this.handleSubmit}
          />
        </div>
      </>
    );

    if (typeof document !== "undefined") {
      return createPortal(modal, document.body);
    }
    return modal;
  }
}

export default LuxNoteEditorPanel;
