import React from "react";
import { createPortal } from "react-dom";
import LuxCreatePanelShell from "views/common/create/LuxCreatePanelShell";
import WorkItemCreateContextInsight from "./WorkItemCreateContextInsight";

export default function LuxWorkItemCreatePanel({
  show,
  editMode,
  onClose,
  taskInfo,
  children,
}) {
  const deliverableName = taskInfo && taskInfo.name ? taskInfo.name : null;
  const projectName =
    taskInfo && taskInfo.projectInfo && taskInfo.projectInfo.name
      ? taskInfo.projectInfo.name
      : null;
  const subtitleParts = [];
  if (deliverableName) subtitleParts.push(deliverableName);
  if (projectName) subtitleParts.push(projectName);

  const panel = (
    <LuxCreatePanelShell
      show={show === true}
      onClose={onClose}
      panelId="lux-workitem-create-panel"
      className="lux-create-panel--work-item-create lux-create-panel--planner-assign lux-overlay-shell--create"
      kicker="Work item"
      title={editMode ? "Edit work item" : "Create work item"}
      subtitle={
        subtitleParts.length
          ? `${editMode ? "Update activity on" : "Log effort against"} ${subtitleParts.join(" · ")}`
          : "Assignee, schedule, category, and notes for this deliverable."
      }
      size="lg"
    >
      {show === true && (
        <div className="lux-workitem-create-panel">
          <WorkItemCreateContextInsight taskInfo={taskInfo} />
          <div className="lux-workitem-create-panel__form">{children}</div>
        </div>
      )}
    </LuxCreatePanelShell>
  );

  if (typeof document !== "undefined") {
    return createPortal(panel, document.body);
  }
  return panel;
}
