import { axiosUtils } from '../_helpers';
import { leaveTeamQueryParams, listLeaveAcrossTeams } from '_helpers/leave.config';
import urlConfig from 'url.config';

const BASE = urlConfig.GLOBAL_LEAVE_POLICY_API_PATH;

function payload(res) {
  if (res == null) return null;
  if (res.payload !== undefined) return res.payload;
  return res;
}

export const globalLeavePolicyService = {
  listJurisdictions: (userTeamId) =>
    axiosUtils.get(`${BASE}/jurisdictions?userTeamId=${userTeamId}`).then(payload),
  createJurisdiction: (body) => axiosUtils.post(`${BASE}/jurisdictions`, body).then(payload),
  updateJurisdiction: (id, body) => axiosUtils.put(`${BASE}/jurisdictions/${id}`, body).then(payload),

  listRuleSets: (userTeamId) =>
    axiosUtils.get(`${BASE}/rule-sets?userTeamId=${userTeamId}`).then(payload),
  createRuleSet: (body) => axiosUtils.post(`${BASE}/rule-sets`, body).then(payload),

  listTemplates: () => axiosUtils.get(`${BASE}/templates`).then(payload),
  createTemplate: (body) => axiosUtils.post(`${BASE}/templates`, body).then(payload),
  applyTemplate: (templateId, body) =>
    axiosUtils.post(`${BASE}/templates/${templateId}/apply`, body).then(payload),

  listPolicies: (userTeamId) =>
    axiosUtils.get(`${BASE}/policies?userTeamId=${userTeamId}`).then(payload),
  getPolicy: (id) => axiosUtils.get(`${BASE}/policies/${id}`).then(payload),
  createPolicy: (body) => axiosUtils.post(`${BASE}/policies`, body).then(payload),
  updatePolicy: (id, body) => axiosUtils.put(`${BASE}/policies/${id}`, body).then(payload),

  listVersions: (policyId) => axiosUtils.get(`${BASE}/policies/${policyId}/versions`).then(payload),
  createDraftVersion: (policyId, body) =>
    axiosUtils.post(`${BASE}/policies/${policyId}/versions`, body).then(payload),
  updateVersion: (versionId, body) =>
    axiosUtils.put(`${BASE}/versions/${versionId}`, body).then(payload),
  publishVersion: (versionId, body) =>
    axiosUtils.post(`${BASE}/versions/${versionId}/publish`, body || {}).then(payload),
  retireVersion: (versionId, body) =>
    axiosUtils.post(`${BASE}/versions/${versionId}/retire`, body || {}).then(payload),
  diffVersions: (leftId, rightId) =>
    axiosUtils.get(`${BASE}/versions/diff?leftId=${leftId}&rightId=${rightId}`).then(payload),
  listTypeDefinitions: (versionId) =>
    axiosUtils.get(`${BASE}/versions/${versionId}/type-definitions`).then(payload),
  upsertSpecialLeave: (versionId, body) =>
    axiosUtils.post(`${BASE}/versions/${versionId}/special-leave`, body).then(payload),

  resolve: (userTeamId, employeeId, context = {}) => {
    const params = new URLSearchParams({ userTeamId: String(userTeamId) });
    if (employeeId) params.set('employeeId', String(employeeId));
    Object.entries(context).forEach(([k, v]) => {
      if (v != null && v !== '') params.set(k, String(v));
    });
    return axiosUtils.get(`${BASE}/resolve?${params.toString()}`).then(payload);
  },
  simulate: (body) => axiosUtils.post(`${BASE}/simulate`, body).then(payload),
  employeePreview: (body) => axiosUtils.post(`${BASE}/employee-preview`, body).then(payload),
  listSimulations: (userTeamId) =>
    axiosUtils.get(`${BASE}/simulations?userTeamId=${userTeamId}`).then(payload),

  listHolidayAssignments: (userTeamId) =>
    axiosUtils.get(`${BASE}/holiday-calendars?userTeamId=${userTeamId}`).then(payload),
  listHolidayCalendarCatalog: (userTeamId) =>
    axiosUtils.get(`${BASE}/holiday-calendars/catalog?userTeamId=${userTeamId}`).then(payload),
  previewHolidayCalendar: (userTeamId, holidayCalendarKey) =>
    axiosUtils
      .get(
        `${BASE}/holiday-calendars/preview?userTeamId=${userTeamId}&holidayCalendarKey=${encodeURIComponent(
          holidayCalendarKey
        )}`
      )
      .then(payload),
  createHolidayAssignment: (body) =>
    axiosUtils.post(`${BASE}/holiday-calendars`, body).then(payload),
  deactivateHolidayAssignment: (id) =>
    axiosUtils.post(`${BASE}/holiday-calendars/${id}/deactivate`, {}).then(payload),

  listOvertimePolicies: (userTeamId) =>
    axiosUtils.get(`${BASE}/overtime/policies?userTeamId=${userTeamId}`).then(payload),
  createOvertimePolicy: (body) =>
    axiosUtils.post(`${BASE}/overtime/policies`, body).then(payload),
  updateOvertimePolicy: (id, body) =>
    axiosUtils.put(`${BASE}/overtime/policies/${id}`, body).then(payload),
  publishOvertimePolicy: (id) =>
    axiosUtils.post(`${BASE}/overtime/policies/${id}/publish`, {}).then(payload),
  listOvertimeRequests: (userTeamId) =>
    axiosUtils.get(`${BASE}/overtime/requests?userTeamId=${userTeamId}`).then(payload),
  createOvertimeRequest: (body) =>
    axiosUtils.post(`${BASE}/overtime/requests`, body).then(payload),
  approveOvertime: (requestId, body) =>
    axiosUtils.post(`${BASE}/overtime/requests/${requestId}/approve`, body || {}).then(payload),

  listCompOffPolicies: (userTeamId) =>
    axiosUtils.get(`${BASE}/comp-off/policies?userTeamId=${userTeamId}`).then(payload),
  createCompOffPolicy: (body) =>
    axiosUtils.post(`${BASE}/comp-off/policies`, body).then(payload),
  listCompOffLedger: (userTeamId, employeeId) => {
    let url = `${BASE}/comp-off/ledger?userTeamId=${userTeamId}`;
    if (employeeId) url += `&employeeId=${employeeId}`;
    return axiosUtils.get(url).then(payload);
  },
  consumeCompOff: (body) => axiosUtils.post(`${BASE}/comp-off/consume`, body).then(payload),
  /** CFA-LEAVE-W3 — attendance ≥6h weekend / >15h weekday → manager credit request */
  createCompOffCreditRequest: (body) =>
    axiosUtils.post(`${BASE}/comp-off/credit-requests`, body).then(payload),
  /** CFA-LEAVE-W3 — expire unused bank → payroll encash staging */
  expireCompOffRun: (body) =>
    axiosUtils.post(`${BASE}/comp-off/expire/run`, body).then(payload),

  listComplianceReports: (userTeamId) =>
    axiosUtils.get(`${BASE}/compliance-reports?userTeamId=${userTeamId}`).then(payload),
  runComplianceReport: (body) =>
    axiosUtils.post(`${BASE}/compliance-reports`, body).then(payload),

  listAudit: (userTeamId, policyId) => {
    let url = `${BASE}/audit?userTeamId=${userTeamId}`;
    if (policyId) url += `&policyId=${policyId}`;
    return axiosUtils.get(url).then(payload);
  },

  /** Published global vs classic — what drives monthly LEAVE_ACCRUAL for the team. */
  accrualSource: (userTeamId) =>
    axiosUtils.get(`${BASE}/accrual-source?userTeamId=${userTeamId}`).then(payload),

  /** Per-employee leave balance / accrual data-quality scan (one or many teams). */
  leaveDataQuality: (userTeamIds) =>
    axiosUtils.getWithParam(`${BASE}/ops/data-quality`, leaveTeamQueryParams(userTeamIds)).then(payload),
  runLeaveDataQuality: (userTeamIds) => {
    const q = leaveTeamQueryParams(userTeamIds);
    const params = new URLSearchParams();
    if (Array.isArray(q.userTeamIds)) {
      q.userTeamIds.forEach((id) => params.append('userTeamIds', String(id)));
    } else if (q.userTeamId != null) {
      params.set('userTeamId', String(q.userTeamId));
    }
    return axiosUtils.post(`${BASE}/ops/data-quality/run?${params.toString()}`, {}).then(payload);
  },

  /** Fan-out helper for single-team list endpoints across selected teams. */
  listAcrossTeams: (userTeamIds, listOne) => listLeaveAcrossTeams(userTeamIds, listOne),
};
