import React from "react";
import classNames from "classnames/bind";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { formatFinancePct, formatFinanceUsd } from "config/finance-intelligence.utils";

const SEVERITY_TONE = {
  HIGH: "rose",
  MEDIUM: "amber",
  LOW: "slate",
};

export default function RevenueLeakageRegister({ rows = [], loading }) {
  if (loading) {
    return <div className="lux-finance-register__skeleton" aria-busy="true" />;
  }
  if (!rows.length) {
    return (
      <LuxRegisterEmptyState
        className="lux-register-empty--compact"
        title="No revenue leakage flags"
        description="Open leakage flags from the Revenue Leakage Agent will appear here."
      />
    );
  }

  return (
    <div className="lux-finance-register-wrap">
      <table className="lux-portfolio-register lux-finance-register">
        <thead>
          <tr>
            <th>Project</th>
            <th>Type</th>
            <th>Severity</th>
            <th>Leakage</th>
            <th>Estimated</th>
            <th>Weeks open</th>
            <th>Status</th>
            <th>Recommendation</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => (
            <tr key={row.id} className="lux-portfolio-register__row">
              <td>
                <div className="lux-portfolio-register__primary">
                  <strong>{row.projectName}</strong>
                  <small>{row.projectCode}</small>
                </div>
              </td>
              <td>{row.leakageType.replace(/_/g, " ")}</td>
              <td>
                <span className={classNames("lux-portfolio-badge", `is-${SEVERITY_TONE[row.severity] || "slate"}`)}>
                  {row.severity}
                </span>
              </td>
              <td>{formatFinancePct(row.leakagePct)}</td>
              <td>{formatFinanceUsd(row.estimatedUsd)}</td>
              <td>{row.weeksOpen != null ? row.weeksOpen : "—"}</td>
              <td>{row.status}</td>
              <td>{row.recommendation}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
