/**
 * F20-T3 — Role permission administration service.
 */
import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import { isRbacAdminEnabled, normalizeRolePermissionProfile } from "config/role-permission.config";
import { recordAuditEvent } from "config/audit-write.service";
import { AUDIT_ENTITY_TYPES } from "_constants/audit.constants";

import { apiErrorResult } from "config/mock-fallback.utils";

export const rolePermissionService = {
  listRoles,
  getRole,
  updatePermission,
  updatePersonaModules,
  setRoleStatus,
};

const APPCONFIG_BASE = urlConfig.APPCONFIG_API_PATH || urlConfig.APPCONFIG_PATH;
const API_BASE = `${APPCONFIG_BASE}/role-permissions`;

function teamQuery(extra) {
  const query = { userTeamId: commonUtils.getCurrentUserTeamId() };
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

function canUseRbacAdminApi() {
  return isRbacAdminEnabled() === true;
}

async function listRoles() {
  if (!canUseRbacAdminApi()) {
    return apiErrorResult(null);
  }
  try {
    const response = await axiosUtils.getWithParam(API_BASE, teamQuery());
    const rows = (response && response.payload) || response || [];
    return {
      payload: (Array.isArray(rows) ? rows : []).map(normalizeRolePermissionProfile).filter(Boolean),
      source: "api",
    };
  } catch (e) {
    return { ...apiErrorResult(null), error: e };
  }
}

async function getRole(roleId) {
  if (!canUseRbacAdminApi()) {
    return apiErrorResult(null);
  }
  try {
    const response = await axiosUtils.getWithParam(`${API_BASE}/${roleId}`, teamQuery());
    const row = (response && response.payload) || response;
    return { payload: normalizeRolePermissionProfile(row), source: "api" };
  } catch (e) {
    return { ...apiErrorResult(null), error: e };
  }
}

async function updatePermission(roleId, moduleKey, flagKey, enabled) {
  if (!canUseRbacAdminApi()) {
    throw new Error("Unable to complete action via API.");
  }
  try {
    const response = await axiosUtils.patch(
      `${API_BASE}/${roleId}?userTeamId=${commonUtils.getCurrentUserTeamId()}`,
      { moduleKey, flagKey, enabled }
    );
    const row = (response && response.payload) || response;
    const result = { payload: normalizeRolePermissionProfile(row), source: "api" };
    recordAuditEvent({
      actionType: enabled ? "UPDATED" : "STATUS_CHANGED",
      entityType: AUDIT_ENTITY_TYPES.ADMIN_CONFIG,
      entityRef: `${result.payload && result.payload.name} · ${moduleKey}.${flagKey}`,
      metadata: { roleId, moduleKey, flagKey, enabled },
    });
    return result;
  } catch (e) {
    throw e;
  }
}

async function updatePersonaModules(roleId, payload) {
  if (!canUseRbacAdminApi()) {
    throw new Error("Unable to complete action via API.");
  }
  const body = {
    allowedPersonas: (payload && payload.allowedPersonas) || [],
    defaultPersona: payload && payload.defaultPersona,
    personaSwitchEnabled: payload ? payload.personaSwitchEnabled !== false : true,
  };
  try {
    const response = await axiosUtils.patch(
      `${API_BASE}/${roleId}?userTeamId=${commonUtils.getCurrentUserTeamId()}`,
      body
    );
    const row = (response && response.payload) || response;
    const result = { payload: normalizeRolePermissionProfile(row), source: "api" };
    recordAuditEvent({
      actionType: "UPDATED",
      entityType: AUDIT_ENTITY_TYPES.ADMIN_CONFIG,
      entityRef: `${result.payload && result.payload.name} · personaModules`,
      metadata: { roleId, ...body },
    });
    return result;
  } catch (e) {
    throw e;
  }
}

async function setRoleStatus(roleId, status) {
  if (!canUseRbacAdminApi()) {
    throw new Error("Unable to complete action via API.");
  }
  try {
    const response = await axiosUtils.patch(
      `${API_BASE}/${roleId}/status?userTeamId=${commonUtils.getCurrentUserTeamId()}`,
      { status }
    );
    const row = (response && response.payload) || response;
    const result = { payload: normalizeRolePermissionProfile(row), source: "api" };
    recordAuditEvent({
      actionType: "STATUS_CHANGED",
      entityType: AUDIT_ENTITY_TYPES.ADMIN_CONFIG,
      entityRef: result.payload && result.payload.name,
      metadata: { roleId, status },
    });
    return result;
  } catch (e) {
    throw e;
  }
}
