import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import { PROGRAM_STATUSES } from "config/portfolio-control-tower.config";

const STATUS_TONE = {
  [PROGRAM_STATUSES.ON_TRACK]: "green",
  [PROGRAM_STATUSES.AT_RISK]: "amber",
  [PROGRAM_STATUSES.OFF_TRACK]: "rose",
  [PROGRAM_STATUSES.COMPLETE]: "slate",
};

export default function PortfolioProgramRegister({ programs = [], loading }) {
  if (loading) {
    return <div className="lux-portfolio-register__loading">Loading program roll-ups…</div>;
  }

  if (!programs.length) {
    return <div className="lux-portfolio-register__empty">No programs linked to this portfolio yet.</div>;
  }

  return (
    <div className="lux-portfolio-register-wrap">
      <table className="lux-portfolio-register">
        <thead>
          <tr>
            <th>Program</th>
            <th>Status</th>
            <th>Health</th>
            <th>Projects</th>
            <th>Risks</th>
            <th>Slippage</th>
            <th>Phase</th>
          </tr>
        </thead>
        <tbody>
          {programs.map((program) => (
            <tr key={program.id} className="lux-portfolio-register__row">
              <td>
                <div className="lux-portfolio-register__primary">
                  <strong>{program.name}</strong>
                  <small>{program.code}</small>
                  <span>{program.sponsorName ? `Sponsor · ${program.sponsorName}` : ""}</span>
                </div>
              </td>
              <td>
                <span className={classNames("lux-portfolio-badge", `is-${STATUS_TONE[program.status] || "slate"}`)}>
                  {program.status ? program.status.replace(/_/g, " ") : "—"}
                </span>
              </td>
              <td>
                <strong>{program.healthScore != null ? `${program.healthScore}%` : "—"}</strong>
              </td>
              <td>{program.projectCount != null ? program.projectCount : (program.projectIds || []).length}</td>
              <td>{program.openRisks != null ? program.openRisks : "—"}</td>
              <td>{program.avgSlippageDays != null ? `${program.avgSlippageDays}d` : "—"}</td>
              <td>{program.roadmapPhase || "—"}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <p className="lux-portfolio-register__foot">
        Drill into delivery modules from the{" "}
        <Link to="/project/governance">governance hub</Link> or{" "}
        <Link to="/project/timeline">timeline</Link>.
      </p>
    </div>
  );
}
