import React from "react";
import classNames from "classnames/bind";
import { CREATE_ENTRY_MODES } from "./createPanel.utils";

/** Compact segmented control — minimal vertical footprint. */
function LuxCreateModeSwitch({ mode, onChange, disabled }) {
  return (
    <div className="lux-create-mode lux-create-mode--compact" role="tablist" aria-label="Form layout">
      <button
        type="button"
        role="tab"
        aria-selected={mode === CREATE_ENTRY_MODES.WIZARD}
        disabled={disabled}
        className={classNames("lux-create-mode__pill", {
          "is-active": mode === CREATE_ENTRY_MODES.WIZARD,
        })}
        onClick={() => onChange(CREATE_ENTRY_MODES.WIZARD)}
        title="Move through focused steps with progress tracking"
      >
        <i className="fe fe-git-merge" aria-hidden="true" />
        Guided
      </button>
      <button
        type="button"
        role="tab"
        aria-selected={mode === CREATE_ENTRY_MODES.FULL}
        disabled={disabled}
        className={classNames("lux-create-mode__pill", {
          "is-active": mode === CREATE_ENTRY_MODES.FULL,
        })}
        onClick={() => onChange(CREATE_ENTRY_MODES.FULL)}
        title="View and edit all sections on one scrollable page"
      >
        <i className="fe fe-layout" aria-hidden="true" />
        Full form
      </button>
    </div>
  );
}

export default LuxCreateModeSwitch;
