import React, { Component } from "react";
import { REVENUE_RECOGNITION_PERIOD_CLOSE_META } from "config/finance-intelligence-nav.config";
import { formatFinanceUsd } from "config/finance-intelligence.utils";
import { revenueRecognitionService } from "_services/revenueRecognition.service";
import FinanceLuxPage, {
  FinanceActionButton,
  FinanceField,
  FinanceFormGrid,
  FinanceInsightPanel,
  FinanceLuxPanel,
  FinanceMetricTiles,
  FinanceQuickNav,
  FinanceRevRecSectionTabs,
  FinanceStatusBadge,
  REV_REC_QUICK_LINKS,
} from "views/finance/components/FinanceLuxShared";
import FinanceLoadAlert from "views/finance/components/FinanceLoadAlert";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

class RevenueRecognitionPeriodClosePage extends Component {
  state = {
    loading: false,
    loadError: null,
    periodKey: "2026-07",
    period: null,
    locking: false,
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Period close");
    }
  }

  loadPeriod = async () => {
    const { periodKey } = this.state;
    if (!periodKey) {
      return;
    }
    this.setState({ loading: true, loadError: null });
    const result = await revenueRecognitionService.getPeriod(periodKey);
    if (result.source === "api" && result.payload) {
      this.setState({ loading: false, period: result.payload, loadError: null });
    } else {
      this.setState({
        loading: false,
        period: null,
        loadError: result.error || new Error("Unable to load period"),
      });
    }
  };

  handleLock = async () => {
    const { periodKey } = this.state;
    this.setState({ locking: true });
    const result = await revenueRecognitionService.lockPeriod(periodKey, "Period close");
    this.setState({ locking: false });
    if (result.source === "api") {
      this.loadPeriod();
    } else {
      this.setState({ loadError: result.error || new Error("Lock failed") });
    }
  };

  render() {
    const { loading, loadError, periodKey, period, locking } = this.state;
    const locked = period && period.locked;
    const kpiCards = [
      {
        id: "period",
        label: "Period",
        value: periodKey || "—",
        hint: "YYYY-MM key",
        tone: "rose",
        icon: "fe fe-calendar",
      },
      {
        id: "status",
        label: "Status",
        value: period ? (locked ? "Locked" : "Open") : "—",
        hint: period ? "Period state" : "Load a period",
        tone: locked ? "rose" : "green",
        icon: locked ? "fe fe-lock" : "fe fe-unlock",
      },
      {
        id: "entries",
        label: "Entries",
        value: period && period.entryCount != null ? period.entryCount : "—",
        hint: "In this period",
        tone: "indigo",
        icon: "fe fe-list",
      },
      {
        id: "recognized",
        label: "Approved $",
        value:
          period && period.approvedRecognizedUsd != null
            ? formatFinanceUsd(period.approvedRecognizedUsd)
            : "—",
        hint: "Recognized total",
        tone: "violet",
        icon: "fe fe-trending-up",
      },
    ];

    const tiles = period
      ? [
          {
            id: "locked",
            label: "Locked",
            value: period.locked ? "Yes" : "No",
            hint: period.locked ? "Edits blocked" : "Entries still editable",
            tone: period.locked ? "rose" : "green",
          },
          {
            id: "count",
            label: "Entry count",
            value: period.entryCount != null ? period.entryCount : "—",
            hint: "All statuses",
            tone: "indigo",
          },
          {
            id: "approved",
            label: "Approved recognized",
            value: formatFinanceUsd(period.approvedRecognizedUsd),
            hint: "Posted recognition",
            tone: "violet",
          },
        ]
      : [];

    return (
      <FinanceLuxPage
        testId="rev-rec-period-close-page"
        pageMeta={REVENUE_RECOGNITION_PERIOD_CLOSE_META}
        dataSource={period ? "api" : loadError ? "api-error" : null}
        demoLabel={null}
        loading={loading}
        kpiCards={kpiCards}
        heroActions={
          <>
            <FinanceActionButton
              to="/finance/revenue-recognition/entries"
              icon="fe fe-check-square"
              variant="ghost"
            >
              Entries
            </FinanceActionButton>
            <FinanceActionButton
              type="button"
              icon="fe fe-search"
              variant="ghost"
              onClick={this.loadPeriod}
              disabled={loading || !periodKey}
            >
              {loading ? "Loading…" : "Load period"}
            </FinanceActionButton>
            <FinanceActionButton
              type="button"
              icon="fe fe-lock"
              variant="primary"
              disabled={locking || !periodKey || locked}
              onClick={this.handleLock}
            >
              {locking ? "Locking…" : locked ? "Already locked" : "Lock period"}
            </FinanceActionButton>
          </>
        }
      >
        <FinanceRevRecSectionTabs active="/finance/revenue-recognition/period-close" />
        <FinanceQuickNav
          links={REV_REC_QUICK_LINKS}
          eyebrow="Recognition workflow"
          title="Lock only after entries are approved"
        />
        <FinanceInsightPanel
          insights={[
            {
              id: "review",
              tone: "amber",
              icon: "fe fe-check-square",
              title: "Review entries first",
              copy: "Approve or reverse outstanding drafts before locking.",
              path: "/finance/revenue-recognition/entries",
            },
            {
              id: "lock",
              tone: "rose",
              icon: "fe fe-lock",
              title: "Lock is final for the period",
              copy: "A locked period blocks recognition entry edits for that YYYY-MM key.",
            },
            {
              id: "hub",
              tone: "indigo",
              icon: "fe fe-trending-up",
              title: "Check recognized vs billed",
              copy: "Confirm hub totals after close so finance sees the final gap.",
              path: "/finance/revenue-recognition",
            },
          ]}
        />
        <FinanceLoadAlert
          error={loadError}
          fallback="Unable to load period."
          onDismiss={() => this.setState({ loadError: null })}
        />

        <FinanceLuxPanel
          title="Select period"
          meta="Load period status, then lock when ready"
          icon="fe fe-calendar"
          accent="rose"
        >
          <div className="lux-finance-form">
            <FinanceFormGrid columns={3}>
              <FinanceField label="Period key" hint="Format YYYY-MM">
                <input
                  className="form-control"
                  value={periodKey}
                  onChange={(e) => this.setState({ periodKey: e.target.value })}
                  data-testid="rrp-period-key"
                />
              </FinanceField>
              <FinanceField label="Actions">
                <div className="lux-finance-form__inline-actions">
                  <FinanceActionButton type="button" variant="ghost" icon="fe fe-search" onClick={this.loadPeriod}>
                    Load
                  </FinanceActionButton>
                  <FinanceActionButton
                    type="button"
                    variant="primary"
                    icon="fe fe-lock"
                    disabled={locking || locked}
                    onClick={this.handleLock}
                  >
                    {locking ? "Locking…" : "Lock period"}
                  </FinanceActionButton>
                </div>
              </FinanceField>
            </FinanceFormGrid>
          </div>
        </FinanceLuxPanel>

        <FinanceLuxPanel
          title="Period detail"
          meta={period ? `Period ${periodKey}` : "Load a period to view status"}
          icon="fe fe-shield"
          accent="indigo"
          actions={
            period ? (
              <FinanceStatusBadge
                status={period.locked ? "LOCKED" : "OPEN"}
                label={period.locked ? "Locked" : "Open"}
              />
            ) : null
          }
        >
          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading period"
              description="Fetching period lock state and totals."
            />
          ) : period ? (
            <FinanceMetricTiles tiles={tiles} testId="rev-rec-period-detail" />
          ) : (
            <LuxRegisterEmptyState
              title="No period loaded"
              description="Enter a YYYY-MM period key and load status before locking."
              showCreate={false}
            />
          )}
        </FinanceLuxPanel>
      </FinanceLuxPage>
    );
  }
}

export default RevenueRecognitionPeriodClosePage;
