import React from "react";
import classNames from "classnames/bind";

export default function PlannerConflictModal({ pending, onCancel, onConfirm }) {
  if (!pending) return null;

  const { workItem, employee, dayMoment, hour, conflict } = pending;
  const dayLabel = dayMoment && dayMoment.format("ddd DD MMM YYYY");
  const hourLabel = hour != null ? ` · ${String(hour).padStart(2, "0")}:00` : "";

  return (
    <div className="lux-planner-conflict" role="dialog" aria-modal="true" aria-labelledby="planner-conflict-title">
      <div className="lux-planner-conflict__backdrop" onClick={onCancel} role="presentation" />
      <div className="lux-planner-conflict__sheet">
        <h2 id="planner-conflict-title">Review assignment</h2>
        <p className="lux-planner-conflict__sub">
          Assign <strong>{workItem.name || workItem.taskName || "work item"}</strong> to{" "}
          <strong>{employee.name}</strong>
          {dayLabel && (
            <>
              {" "}
              on {dayLabel}
              {hourLabel}
            </>
          )}
        </p>

        {(conflict.errors || []).map((err) => (
          <div key={err.code} className="lux-planner-conflict__msg is-error">
            <i className="fe fe-alert-circle" />
            {err.message}
          </div>
        ))}
        {(conflict.warnings || []).map((warn) => (
          <div key={warn.code} className="lux-planner-conflict__msg is-warn">
            <i className="fe fe-alert-triangle" />
            {warn.message}
          </div>
        ))}

        <div className="lux-planner-conflict__actions">
          <button type="button" className="lux-planner-btn lux-planner-btn--ghost" onClick={onCancel}>
            Cancel
          </button>
          <button
            type="button"
            className={classNames("lux-planner-btn", {
              "lux-planner-btn--primary": conflict.canAssign,
              "lux-planner-btn--danger": !conflict.canAssign,
            })}
            onClick={onConfirm}
          >
            {conflict.canAssign ? "Assign anyway" : "Force assign"}
          </button>
        </div>
      </div>
    </div>
  );
}
