import { appConfigService } from '../_services';
import { commonUtils } from './common.utils';
import envconfig from '../env.config';
import { isDevEnvPilotEnabled, resolveDevEnvOrOrg } from './featurePilot.utils';

export const APPROVAL_DELEGATION_CONFIG_KEY = 'approvalDelegation';
export const APPROVAL_DELEGATION_ENABLED_KEY = 'approvalDelegationEnabled';
export const APPROVAL_REMINDER_ENABLED_KEY = 'approvalReminderEnabled';
export const SLA_FIRST_REMINDER_DAYS_KEY = 'slaFirstReminderDays';
export const SLA_REPEAT_REMINDER_DAYS_KEY = 'slaRepeatReminderDays';
export const EMPLOYEE_MANUAL_REMINDER_COOLDOWN_HOURS_KEY = 'employeeManualReminderCooldownHours';
export const APPROVAL_DELEGATION_CONFIG_CHANGED = 'famstack-approval-delegation-config-changed';

const HRMS_MODULE = 'HRMS';

const DEFAULT_SLA_FIRST_REMINDER_DAYS = 2;
const DEFAULT_SLA_REPEAT_REMINDER_DAYS = 2;
const DEFAULT_EMPLOYEE_MANUAL_REMINDER_COOLDOWN_HOURS = 24;

let orgApprovalDelegationEnabled = false;
let orgApprovalReminderEnabled = true;
let slaFirstReminderDays = DEFAULT_SLA_FIRST_REMINDER_DAYS;
let slaRepeatReminderDays = DEFAULT_SLA_REPEAT_REMINDER_DAYS;
let employeeManualReminderCooldownHours = DEFAULT_EMPLOYEE_MANUAL_REMINDER_COOLDOWN_HOURS;
let configLoaded = false;
let loadPromise = null;

function readIntFlag(group, flagKey, defaultValue) {
  if (!group || typeof group !== 'object') {
    return defaultValue;
  }
  const value = group[flagKey];
  if (typeof value === 'number' && !Number.isNaN(value)) {
    return value;
  }
  return defaultValue;
}

export function readApprovalDelegationFlag(configList, flagKey) {
  const group = commonUtils.getAppConfigValue(configList, APPROVAL_DELEGATION_CONFIG_KEY);
  if (!group || typeof group !== 'object') {
    return false;
  }
  return group[flagKey] === true;
}

export function isApprovalDelegationEnabledFromConfig(configList) {
  return readApprovalDelegationFlag(configList, APPROVAL_DELEGATION_ENABLED_KEY);
}

export function isApprovalReminderEnabledFromConfig(configList) {
  const group = commonUtils.getAppConfigValue(configList, APPROVAL_DELEGATION_CONFIG_KEY);
  if (!group || typeof group !== 'object') {
    return true;
  }
  if (group[APPROVAL_REMINDER_ENABLED_KEY] === false) {
    return false;
  }
  return true;
}

export function applyApprovalDelegationConfig(configList) {
  const group = commonUtils.getAppConfigValue(configList, APPROVAL_DELEGATION_CONFIG_KEY);
  orgApprovalDelegationEnabled = isApprovalDelegationEnabledFromConfig(configList);
  orgApprovalReminderEnabled = isApprovalReminderEnabledFromConfig(configList);
  slaFirstReminderDays = readIntFlag(group, SLA_FIRST_REMINDER_DAYS_KEY, DEFAULT_SLA_FIRST_REMINDER_DAYS);
  slaRepeatReminderDays = readIntFlag(group, SLA_REPEAT_REMINDER_DAYS_KEY, DEFAULT_SLA_REPEAT_REMINDER_DAYS);
  employeeManualReminderCooldownHours = readIntFlag(
    group,
    EMPLOYEE_MANUAL_REMINDER_COOLDOWN_HOURS_KEY,
    DEFAULT_EMPLOYEE_MANUAL_REMINDER_COOLDOWN_HOURS
  );
  configLoaded = true;
  return orgApprovalDelegationEnabled;
}

export function isApprovalDelegationOrgEnabled() {
  return orgApprovalDelegationEnabled;
}

export function isApprovalReminderOrgEnabled() {
  return orgApprovalReminderEnabled;
}

export function getSlaFirstReminderDays() {
  return slaFirstReminderDays;
}

export function getSlaRepeatReminderDays() {
  return slaRepeatReminderDays;
}

export function getEmployeeManualReminderCooldownHours() {
  return employeeManualReminderCooldownHours;
}

export function isApprovalDelegationConfigLoaded() {
  return configLoaded;
}

export function notifyApprovalDelegationConfigChanged() {
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent(APPROVAL_DELEGATION_CONFIG_CHANGED));
  }
}

export function loadApprovalDelegationConfig(force, teamIdOverride) {
  if (!force && configLoaded) {
    return Promise.resolve(orgApprovalDelegationEnabled);
  }
  if (!force && loadPromise) {
    return loadPromise;
  }

  const teamId = teamIdOverride || commonUtils.getCurrentUserTeamId();
  if (!teamId) {
    orgApprovalDelegationEnabled = false;
    orgApprovalReminderEnabled = true;
    slaFirstReminderDays = DEFAULT_SLA_FIRST_REMINDER_DAYS;
    slaRepeatReminderDays = DEFAULT_SLA_REPEAT_REMINDER_DAYS;
    employeeManualReminderCooldownHours = DEFAULT_EMPLOYEE_MANUAL_REMINDER_COOLDOWN_HOURS;
    configLoaded = true;
    return Promise.resolve(false);
  }

  loadPromise = appConfigService
    .getModuleConfig(teamId, HRMS_MODULE)
    .then((response) => {
      const list = response && response.payload;
      applyApprovalDelegationConfig(list);
      notifyApprovalDelegationConfigChanged();
      return orgApprovalDelegationEnabled;
    })
    .catch(() => {
      orgApprovalDelegationEnabled = false;
      orgApprovalReminderEnabled = true;
      slaFirstReminderDays = DEFAULT_SLA_FIRST_REMINDER_DAYS;
      slaRepeatReminderDays = DEFAULT_SLA_REPEAT_REMINDER_DAYS;
      employeeManualReminderCooldownHours = DEFAULT_EMPLOYEE_MANUAL_REMINDER_COOLDOWN_HOURS;
      configLoaded = true;
      return false;
    })
    .finally(() => {
      loadPromise = null;
    });

  return loadPromise;
}

export function refreshApprovalDelegationConfig(teamIdOverride) {
  configLoaded = false;
  return loadApprovalDelegationConfig(true, teamIdOverride);
}

/**
 * Org `approvalDelegation.approvalDelegationEnabled` from Application Config.
 * Admin menu also needs role.json `adminModules.delegationEnabled`.
 */
export function shouldUseApprovalDelegation() {
  return resolveDevEnvOrOrg(envconfig.APPROVAL_DELEGATION_ENABLED, isApprovalDelegationOrgEnabled());
}

export function isEffectiveApprovalReminderEnabled() {
  // Reminder is independent of delegation master switch (matches BE SLA/remind gates).
  // Env pilots are ignored — Application Config only.
  if (isDevEnvPilotEnabled(envconfig.APPROVAL_REMINDER_ENABLED)) {
    return true;
  }
  return isApprovalReminderOrgEnabled();
}
