import React from 'react';
import { createRoot } from 'react-dom/client';
import { Provider } from 'react-redux';

import { store } from './_helpers';

import App from 'App';
import { registerTracopusServiceWorker } from './pwa/registerServiceWorker';

const root = createRoot( document.getElementById('root'));
root.render(
    <Provider store={store}>
        <App />
    </Provider>,
   
);

registerTracopusServiceWorker({
  onUpdate: () => {
    try {
      window.dispatchEvent(new CustomEvent("tracopus:sw-update"));
    } catch (_err) {
      // ignore
    }
  },
});
