import React from "react";
import classNames from "classnames/bind";
import { WorkGraphLuxPanel } from "views/workgraph/components/WorkGraphLuxShared";

export default function GraphAnalyticsPanel({ analytics, loading }) {
  if (loading || !analytics) {
    return (
      <WorkGraphLuxPanel title="Graph analytics" meta="Insights" icon="fe fe-bar-chart-2" accent="indigo">
        <div className="lux-wg-skeleton lux-wg-skeleton--panel" />
      </WorkGraphLuxPanel>
    );
  }

  const densityBars = analytics.densityBars || [];
  const bottlenecks = analytics.bottleneckNodes || [];
  const maxScore = densityBars.length ? densityBars[0].score : 1;

  return (
    <div className="lux-wg-analytics-grid">
      <WorkGraphLuxPanel title="Module density" meta="Cross-module" icon="fe fe-layers" accent="indigo">
        <div className="lux-wg-density-bars">
          {densityBars.map((bar) => (
            <div key={bar.label} className="lux-wg-density-row">
              <span className="lux-wg-density-row__label">{bar.label}</span>
              <div className="lux-wg-density-row__track">
                <span
                  className="lux-wg-density-row__fill"
                  style={{ width: `${Math.round((bar.score / maxScore) * 100)}%` }}
                />
              </div>
              <span className="lux-wg-density-row__meta">
                {bar.nodes}n · {bar.edges}e
              </span>
            </div>
          ))}
        </div>
      </WorkGraphLuxPanel>

      <WorkGraphLuxPanel title="Bottleneck nodes" meta="Fan-out" icon="fe fe-alert-circle" accent="amber">
        <ul className="lux-wg-bottleneck-list">
          {bottlenecks.map((row) => (
            <li key={row.id} className={classNames("lux-wg-bottleneck-row", row.tone && `is-${row.tone}`)}>
              <span className="lux-wg-bottleneck-row__label">{row.label}</span>
              <span className="lux-wg-bottleneck-row__degree">{row.degree} links</span>
            </li>
          ))}
        </ul>
        <p className="lux-wg-analytics-foot">
          Risk clusters in graph: <strong>{analytics.riskClusters || 0}</strong>
        </p>
      </WorkGraphLuxPanel>
    </div>
  );
}
