export function getKnowledgeModuleNavActiveId(pathname = "") {
  if (pathname.indexOf(KNOWLEDGE_RCA_ROUTES.RCA) === 0) {
    return "rca";
  }
  if (pathname.indexOf(KNOWLEDGE_RCA_ROUTES.KNOWLEDGE_BASE) === 0) {
    return "knowledge";
  }
  return "lessons";
}