import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import { NavLink } from "react-router-dom";
import EmployeeImage from "views/common/fragments/EmployeeImage";
import AttendanceDayCell from "./AttendanceDayCell";
import { findAttendanceItem, getEmployeeStats } from "./attendance.utils";
import { getEmployeeDetailsPathname } from "views/hrms/profileDetailsNavigation.utils";

class AttendanceMatrixRow extends PureComponent {
  render() {
    const {
      employee,
      monthDays,
      items,
      permission,
      isLoading,
      isCurrentUser,
      currentUserId,
      createAttendance,
      deleteAttendance,
      onRequestMark,
      onRequestViewDetails,
      workdays,
      holidayDates,
    } = this.props;

    const stats = getEmployeeStats(employee.id, items, monthDays);

    return (
      <tr
        className={classNames("lux-att-row", {
          "is-current-user": isCurrentUser,
        })}
      >
        <td className="lux-att-row__employee">
          <div className="lux-att-row__employee-inner">
            <div className="lux-att-row__avatar-wrap">
              <EmployeeImage employee={employee} classes="lux-att-row__avatar" />
              {isCurrentUser && (
                <span className="lux-att-row__you-badge" title="You">
                  You
                </span>
              )}
            </div>
            <div className="lux-att-row__copy">
              <div className="lux-att-row__name">
                {permission && permission.viewEnabled ? (
                  <NavLink to={getEmployeeDetailsPathname(employee.id)}>{employee.name}</NavLink>
                ) : (
                  employee.name
                )}
              </div>
              {employee.designation && (
                <div className="lux-att-row__designation">{employee.designation}</div>
              )}
              {employee.empCode && (
                <div className="lux-att-row__code">{employee.empCode}</div>
              )}
            </div>
            <div className="lux-att-row__stats" title="Days marked this month">
              <strong>{stats.present}</strong>
              <span>{stats.rate}%</span>
            </div>
          </div>
        </td>
        {monthDays.map((dayMonth) => (
          <AttendanceDayCell
            key={`${employee.id}-${dayMonth.format("YYYY-MM-DD")}`}
            item={findAttendanceItem(items, employee.id, dayMonth)}
            employeeId={employee.id}
            employeeName={employee.name}
            dayMonth={dayMonth}
            permission={permission}
            currentUserId={currentUserId}
            isLoading={isLoading}
            createAttendance={createAttendance}
            deleteAttendance={deleteAttendance}
            onRequestMark={onRequestMark}
            onRequestViewDetails={onRequestViewDetails}
            workdays={workdays}
            holidayDates={holidayDates}
          />
        ))}
      </tr>
    );
  }
}

export default AttendanceMatrixRow;
