export const DASHBOARD_PREFS_KEY_PREFIX = "famstack-project-dashboard-prefs";

export function getDashboardPrefsKey(userId) {
  return DASHBOARD_PREFS_KEY_PREFIX + "-" + (userId || "default");
}

export function readDashboardPrefs(userId) {
  try {
    const raw = localStorage.getItem(getDashboardPrefsKey(userId));
    if (!raw) {
      return null;
    }
    return JSON.parse(raw);
  } catch (e) {
    return null;
  }
}

export function writeDashboardPrefs(userId, prefs) {
  try {
    localStorage.setItem(getDashboardPrefsKey(userId), JSON.stringify(prefs));
  } catch (e) {
    /* ignore */
  }
}

export function applyTeamSelectionFromPrefs(baseTeams, selectedTeamIds) {
  if (!baseTeams || !baseTeams.length) {
    return [];
  }
  if (!selectedTeamIds || !selectedTeamIds.length) {
    return baseTeams.map(function (team) {
      return { ...team };
    });
  }
  return baseTeams.map(function (team) {
    return {
      ...team,
      isChecked: selectedTeamIds.indexOf(team.id) > -1,
    };
  });
}
