import React from "react";
import classNames from "classnames/bind";
import { getPromotionStatusMeta, getSourceMeta } from "./leave.utils";

function LeaveSyncStatusBadge({ leave, onRetry, retryInProgress }) {
  const promo = getPromotionStatusMeta(leave);
  const source = getSourceMeta(leave);

  return (
    <div className="lux-leave-sync">
      <span className={classNames("lux-leave-sync__source", `is-${source.tone}`)}>{source.label}</span>
      <span className={classNames("lux-leave-sync__promo", `is-${promo.tone}`)}>{promo.label}</span>
      {promo.hint && (
        <span className="lux-leave-sync__hint" title={promo.hint}>
          <i className="fe fe-info" aria-hidden="true" />
        </span>
      )}
      {promo.canRetry && onRetry && (
        <button
          type="button"
          className="lux-leave-sync__retry"
          disabled={retryInProgress}
          onClick={() => onRetry(leave)}
        >
          {retryInProgress ? "Retrying…" : "Retry sync"}
        </button>
      )}
    </div>
  );
}

export default LeaveSyncStatusBadge;
