import { axiosUtils } from "../_helpers";
import urlConfig from "url.config";
import { isValidPersonaContextPayload } from "config/persona-context.utils";

export const personaService = {
  getPersonaContext,
  switchPersona,
  getLandingExperience,
};

function unwrapPayload(response) {
  return response && response.payload ? response.payload : response;
}

function assertPersonaContextPayload(payload, action) {
  if (!isValidPersonaContextPayload(payload)) {
    throw new Error(`Invalid persona ${action} response`);
  }
  return payload;
}

async function getPersonaContext() {
  const response = await axiosUtils.get(urlConfig.PERSONA_CONTEXT);
  return assertPersonaContextPayload(unwrapPayload(response), "context");
}

async function switchPersona(persona) {
  const response = await axiosUtils.post(urlConfig.PERSONA_SWITCH, { persona });
  if (response === "Network error" || response == null) {
    throw new Error("Persona switch request failed");
  }
  return assertPersonaContextPayload(unwrapPayload(response), "switch");
}

async function getLandingExperience() {
  const response = await axiosUtils.get(urlConfig.PERSONA_LANDING_EXPERIENCE);
  return response && response.payload ? response.payload : response;
}
