import React from "react";

function ReceiptUploader({ receipts = [], onUpload, disabled, claimRef }) {
  const label = claimRef ? "Attach receipt" : "Attach receipt (save claim first)";
  return (
    <div className="lux-expense-receipts">
      <div className="lux-expense-receipts__list">
        {receipts.map((receipt) => (
          <div key={receipt.id} className="lux-expense-receipts__item">
            <i className="fe fe-file-text" aria-hidden="true" />
            <div>
              <strong>{receipt.fileName || receipt.title || receipt.id}</strong>
              <span>{receipt.uploadedAt || "Uploaded"}</span>
            </div>
          </div>
        ))}
        {!receipts.length ? <p className="lux-expense-receipts__empty">No receipts attached yet.</p> : null}
      </div>
      <button
        type="button"
        className="lux-onb-action lux-onb-action--ghost"
        onClick={onUpload}
        disabled={disabled || !claimRef}
      >
        <i className="fe fe-upload" aria-hidden="true" />
        {label}
      </button>
    </div>
  );
}

export default ReceiptUploader;
