/** F17 — AI work intelligence (agent console, recommendations, evidence). */

export function isAiWorkIntelligenceEnabled() {
  return shouldUseAiWorkIntelligence();
}

export function shouldUseAiWorkIntelligenceApi() {
  return envconfig.USE_AI_WORK_INTELLIGENCE_API === true;
}

export function isAiWorkIntelligenceLlmOrgEnabled() {
  return getTracopusPilotOrgFlags().aiWorkIntelligenceLlmEnabled === true;
}

