import React, { Component } from "react";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { AdminActionButton, AdminLuxPage } from "views/admin/components/AdminLuxShared";
import AdminLoadAlert from "views/admin/components/AdminLoadAlert";
import { ADMIN_PAGE_META } from "config/admin-page-meta.config";
import { isVendorsOverviewEnabled } from "config/vendors-overview.config";
import { isVendorMasterEnabled } from "config/vendor-master.config";
import { vendorsOverviewService } from "_services/vendorsOverview.service";
import { vendorMasterService } from "_services/vendorMaster.service";

/**
 * EH17 — Vendor master register + read-only BidRequest/PO overview.
 */
class VendorsPage extends Component {
  state = {
    loading: false,
    loadError: null,
    dataSource: null,
    overview: null,
    masterLoading: false,
    masterError: null,
    masterVendors: [],
    masterSource: null,
    createName: "",
    createCode: "",
    createVendorRef: "",
    createNotes: "",
    creating: false,
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Vendors");
    }
    this.loadOverview();
    this.loadMaster();
  }

  loadOverview = async () => {
    if (!isVendorsOverviewEnabled()) {
      return;
    }
    this.setState({ loading: true, loadError: null });
    try {
      const result = await vendorsOverviewService.getOverview();
      if (!result || result.source === "api-error") {
        this.setState({
          loading: false,
          dataSource: "api-error",
          overview: null,
          loadError: "Unable to load vendors overview from API.",
        });
        return;
      }
      this.setState({
        loading: false,
        dataSource: result.source,
        overview: result.payload,
        loadError: null,
      });
    } catch (error) {
      this.setState({
        loading: false,
        dataSource: "api-error",
        overview: null,
        loadError: (error && error.message) || "Unable to load vendors overview.",
      });
    }
  };

  loadMaster = async () => {
    if (!isVendorMasterEnabled()) {
      return;
    }
    this.setState({ masterLoading: true, masterError: null });
    try {
      const result = await vendorMasterService.listVendors();
      if (!result || result.source === "api-error") {
        this.setState({
          masterLoading: false,
          masterSource: "api-error",
          masterVendors: [],
          masterError: "Unable to load vendor master from API.",
        });
        return;
      }
      this.setState({
        masterLoading: false,
        masterSource: result.source,
        masterVendors: Array.isArray(result.payload) ? result.payload : [],
        masterError: null,
      });
    } catch (error) {
      this.setState({
        masterLoading: false,
        masterSource: "api-error",
        masterVendors: [],
        masterError: (error && error.message) || "Unable to load vendor master.",
      });
    }
  };

  handleCreateMaster = async (event) => {
    if (event && event.preventDefault) {
      event.preventDefault();
    }
    const { createName, createCode, createVendorRef, createNotes } = this.state;
    if (!createName || !createName.trim()) {
      this.setState({ masterError: "Vendor name is required." });
      return;
    }
    this.setState({ creating: true, masterError: null });
    try {
      const result = await vendorMasterService.createVendor({
        name: createName.trim(),
        code: createCode.trim() || null,
        vendorRef: createVendorRef.trim() || null,
        notes: createNotes.trim() || null,
      });
      if (!result || result.source === "api-error" || !result.payload) {
        this.setState({
          creating: false,
          masterError: "Unable to create vendor.",
        });
        return;
      }
      this.setState({
        creating: false,
        createName: "",
        createCode: "",
        createVendorRef: "",
        createNotes: "",
      });
      await this.loadMaster();
      await this.loadOverview();
    } catch (error) {
      this.setState({
        creating: false,
        masterError: (error && error.message) || "Unable to create vendor.",
      });
    }
  };

  renderMasterSection() {
    if (!isVendorMasterEnabled()) {
      return null;
    }
    const {
      masterLoading,
      masterError,
      masterVendors,
      masterSource,
      createName,
      createCode,
      createVendorRef,
      createNotes,
      creating,
    } = this.state;

    return (
      <section className="mb-5" data-testid="vendor-master-section">
        <header className="mb-3">
          <h2 className="h5 mb-1">Vendor master register</h2>
          <p className="text-muted mb-0 small">
            Writable source entity ({`ts_vendor_model`}) at /api/v2/vendors/master.
            {masterSource ? ` Source: ${masterSource}.` : ""}
          </p>
        </header>

        <form className="row g-2 align-items-end mb-3" onSubmit={this.handleCreateMaster} data-testid="vendor-master-create">
          <div className="col-md-3">
            <label className="form-label small mb-1" htmlFor="vendor-name">
              Name
            </label>
            <input
              id="vendor-name"
              className="form-control form-control-sm"
              value={createName}
              onChange={(e) => this.setState({ createName: e.target.value })}
              disabled={creating}
              placeholder="Acme Supplies"
              required
            />
          </div>
          <div className="col-md-2">
            <label className="form-label small mb-1" htmlFor="vendor-ref">
              Ref
            </label>
            <input
              id="vendor-ref"
              className="form-control form-control-sm"
              value={createVendorRef}
              onChange={(e) => this.setState({ createVendorRef: e.target.value })}
              disabled={creating}
              placeholder="VEN-001"
            />
          </div>
          <div className="col-md-2">
            <label className="form-label small mb-1" htmlFor="vendor-code">
              Code
            </label>
            <input
              id="vendor-code"
              className="form-control form-control-sm"
              value={createCode}
              onChange={(e) => this.setState({ createCode: e.target.value })}
              disabled={creating}
              placeholder="ACME"
            />
          </div>
          <div className="col-md-3">
            <label className="form-label small mb-1" htmlFor="vendor-notes">
              Notes
            </label>
            <input
              id="vendor-notes"
              className="form-control form-control-sm"
              value={createNotes}
              onChange={(e) => this.setState({ createNotes: e.target.value })}
              disabled={creating}
              placeholder="Optional"
            />
          </div>
          <div className="col-md-2">
            <AdminActionButton
              type="submit"
              variant="primary"
              disabled={creating || masterLoading}
              className="w-100"
            >
              {creating ? "Saving…" : "Add vendor"}
            </AdminActionButton>
          </div>
        </form>

        <AdminLoadAlert
          error={masterError}
          fallback="Unable to load vendor master."
          className="py-2"
          onDismiss={() => this.setState({ masterError: null })}
        />

        <div className="lux-admin-panel">
          {masterLoading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading vendors"
              description="Fetching vendor master register."
            />
          ) : masterVendors.length === 0 ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="No master vendors yet"
              description="Create one above to populate the register."
            />
          ) : (
            <div className="lux-admin-register-wrap">
              <table className="lux-admin-register" data-testid="vendor-master-table">
                <thead>
                  <tr>
                    <th>Ref</th>
                    <th>Name</th>
                    <th>Code</th>
                    <th>Status</th>
                    <th>Tax (masked)</th>
                  </tr>
                </thead>
                <tbody>
                  {masterVendors.map((vendor) => (
                    <tr key={vendor.id || vendor.vendorRef}>
                      <td>{vendor.vendorRef}</td>
                      <td>{vendor.name}</td>
                      <td>{vendor.code || "—"}</td>
                      <td>{vendor.status || "—"}</td>
                      <td>{vendor.taxIdMasked || "—"}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </section>
    );
  }

  renderOverviewSection() {
    if (!isVendorsOverviewEnabled()) {
      return (
        <LuxRegisterEmptyState
          variant="employees"
          title="Vendors overview unavailable"
          description="Enable REACT_APP_USE_VENDORS_OVERVIEW_API to load BidRequest + PurchaseOrder vendor aggregates."
        />
      );
    }

    const { loading, loadError, overview, dataSource } = this.state;
    const vendors = (overview && overview.vendors) || [];

    return (
      <section data-testid="vendors-overview-section">
        <header className="mb-3">
          <h2 className="h5 mb-1">Procurement overview</h2>
          <p className="text-muted mb-0 small">
            Live read-only aggregate of vendor master, BidRequest study names, and PurchaseOrder account/company
            fields. Create or edit vendors in the master register above — overview refreshes from those sources.
          </p>
        </header>

        <div className="d-flex align-items-center gap-2 mb-3">
          <AdminActionButton variant="ghost" className="lux-onb-action--sm" onClick={this.loadOverview} disabled={loading}>
            {loading ? "Loading…" : "Refresh overview"}
          </AdminActionButton>
          {dataSource ? <span className="small text-muted">Source: {dataSource}</span> : null}
          {overview ? (
            <span className="small text-muted">
              {overview.vendorCount} vendors · {overview.bidRequestCount} bids · {overview.purchaseOrderCount} POs
              {overview.masterVendorCount != null ? ` · ${overview.masterVendorCount} master` : ""}
            </span>
          ) : null}
        </div>

        <AdminLoadAlert
          error={loadError}
          fallback="Unable to load vendors overview."
          onDismiss={() => this.setState({ loadError: null })}
        />

        <div className="lux-admin-panel">
          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading overview"
              description="Fetching BidRequest and PurchaseOrder vendor aggregates."
            />
          ) : vendors.length === 0 ? (
            <LuxRegisterEmptyState
              variant="employees"
              title="No vendor-like names found"
              description="Create master vendors, bid requests, or purchase orders with account/company names to populate this list."
            />
          ) : (
            <div className="lux-admin-register-wrap">
              <table className="lux-admin-register" data-testid="vendors-table">
                <thead>
                  <tr>
                    <th>Name</th>
                    <th>Sources</th>
                    <th>Bids</th>
                    <th>POs</th>
                  </tr>
                </thead>
                <tbody>
                  {vendors.map((vendor) => (
                    <tr key={vendor.id}>
                      <td>{vendor.name}</td>
                      <td>{(vendor.sources || []).join(", ")}</td>
                      <td>{vendor.bidRequestCount || 0}</td>
                      <td>{vendor.purchaseOrderCount || 0}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </section>
    );
  }

  render() {
    if (!isVendorsOverviewEnabled() && !isVendorMasterEnabled()) {
      return (
        <div className="lux-register-page lux-admin-page" data-testid="vendors-flag-off">
          <div className="lux-register-page__body">
            <LuxRegisterEmptyState
              variant="employees"
              title="Vendors unavailable"
              description="Enable REACT_APP_USE_VENDORS_OVERVIEW_API and/or REACT_APP_USE_VENDOR_MASTER_API."
            />
          </div>
        </div>
      );
    }

    const { loading, overview, dataSource, masterVendors, masterLoading } = this.state;
    const vendors = (overview && overview.vendors) || [];
    const kpiCards = [
      {
        id: "master",
        label: "Master vendors",
        value: isVendorMasterEnabled() ? masterVendors.length : "—",
        hint: "Writable register",
        tone: "amber",
        icon: "fe fe-truck",
      },
      {
        id: "agg",
        label: "Overview names",
        value: overview
          ? overview.vendorCount != null
            ? overview.vendorCount
            : vendors.length
          : "—",
        hint: "Bid + PO aggregate",
        tone: "blue",
        icon: "fe fe-layers",
      },
      {
        id: "bids",
        label: "Bid requests",
        value: overview
          ? overview.bidRequestCount != null
            ? overview.bidRequestCount
            : 0
          : "—",
        hint: "Linked studies",
        tone: "violet",
        icon: "fe fe-file-text",
      },
      {
        id: "pos",
        label: "Purchase orders",
        value: overview
          ? overview.purchaseOrderCount != null
            ? overview.purchaseOrderCount
            : 0
          : "—",
        hint: "Linked POs",
        tone: "green",
        icon: "fe fe-shopping-bag",
      },
    ];

    return (
      <AdminLuxPage
        pageMeta={ADMIN_PAGE_META.vendors}
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading || masterLoading}
        testId="vendors-page"
        onRefresh={isVendorsOverviewEnabled() ? this.loadOverview : undefined}
        refreshLoading={loading}
      >
        {this.renderMasterSection()}
        {this.renderOverviewSection()}
      </AdminLuxPage>
    );
  }
}

export default VendorsPage;
