import React from "react";
import classNames from "classnames/bind";
import { DeveloperLuxPanel, DeveloperStatusBadge } from "views/developer/components/DeveloperLuxShared";

export default function WebhookSubscriptionRegister({ webhooks, loading, selectedId, onSelect }) {
  const rows = webhooks || [];

  return (
    <DeveloperLuxPanel title="Webhook subscriptions" meta="Event endpoints" icon="fe fe-link-2" accent="violet" featured>
      {loading ? (
        <div className="lux-dev-skeleton lux-dev-skeleton--panel" />
      ) : !rows.length ? (
        <div className="lux-dev-empty">No webhook subscriptions yet.</div>
      ) : (
        <div className="lux-dev-register">
          {rows.map((row, index) => (
            <article
              key={row.id}
              className={classNames(
                "lux-dev-register__row",
                row.tone && `is-${row.tone}`,
                selectedId === row.id && "is-selected"
              )}
            >
              <span className="lux-dev-register__index">{String(index + 1).padStart(2, "0")}</span>
              <button type="button" className="lux-dev-register__main lux-dev-register__main--button" onClick={() => onSelect && onSelect(row)}>
                <span className="lux-dev-register__eyebrow">{row.url}</span>
                <h3>{row.name}</h3>
                <p>{(row.events || []).join(" · ")}</p>
                <div className="lux-dev-register__meta">
                  <DeveloperStatusBadge status={row.status} />
                  <span>{row.successRate}% success</span>
                  <span>{row.lastDeliveryAt ? `Last ${row.lastDeliveryAt}` : "No deliveries"}</span>
                </div>
              </button>
            </article>
          ))}
        </div>
      )}
    </DeveloperLuxPanel>
  );
}
