import {
  isTimesheetApprovalConfigLoaded,
  shouldAllowPartialWeekTimesheetSubmission,
  shouldUseTimesheetApprovalWorkflow,
} from "./timesheetApproval.config";
import { normalizeTimesheetStatus, readAttributeValue } from "views/hrms/components/timesheet/timesheetSummary.utils";
import moment from "moment";

const SUBMITTABLE_STATUSES = new Set(["DRAFT", "REJECTED", "REOPENED"]);
const PARTIAL_SUBMITTABLE_WEEK_STATUSES = new Set(["DRAFT", "REJECTED", "REOPENED", "PENDING"]);
const RESUBMIT_STATUSES = new Set(["REJECTED", "REOPENED"]);
const SUBMITTABLE_DAY_STATUSES = new Set(["DRAFT", "REJECTED", ""]);
const DAY_LOCKED_STATUSES = new Set(["PENDING", "PENDING_APPROVAL", "APPROVED"]);

export function isViewingOwnTimesheet(selectedEmployeeId, currentUserId) {
  if (selectedEmployeeId == null || currentUserId == null) {
    return false;
  }
  return String(selectedEmployeeId) === String(currentUserId);
}

/** Save/submit/clear/add-entry chrome — employee self-service only unless logging on behalf is explicitly allowed elsewhere. */
export function canUseEmployeeTimesheetActions(selectedEmployeeId, currentUserId) {
  return isViewingOwnTimesheet(selectedEmployeeId, currentUserId);
}

export function isClearableDraftTimesheetEntry(entry) {
  if (!entry || entry.isDeleted === true) {
    return false;
  }
  const status = normalizeTimesheetStatus(entry.timesheetStatus || entry.status || "");
  if (status && DAY_LOCKED_STATUSES.has(status)) {
    return false;
  }
  const mins = parseInt(entry.timesheetTimeMins || 0, 10);
  return mins > 0 || entry.isStaged === true || entry.dayId != null;
}

/** Draft/rejected editable hours that Clear week hours can remove (not approved/pending). */
export function hasClearableDraftTimesheetHours(timeSheetData) {
  if (!timeSheetData) {
    return false;
  }
  return ["project", "nonProject"].some((sectionKey) => {
    const groups = timeSheetData[sectionKey];
    if (!groups) {
      return false;
    }
    return Object.keys(groups).some((groupId) => {
      const tasks = groups[groupId] && groups[groupId].tasks;
      if (!tasks) {
        return false;
      }
      return tasks.some((task) => {
        const timeEntry = task.timeEntry || {};
        return Object.keys(timeEntry).some((dateKey) =>
          isClearableDraftTimesheetEntry(timeEntry[dateKey])
        );
      });
    });
  });
}

export function buildClearDraftTimesheetPayload(timeSheetRequest) {
  return {
    ...(timeSheetRequest || {}),
    project: {},
    nonProject: {},
    clearDraftHours: true,
  };
}

export function normalizeTimesheetWeekStatus(rawStatus) {
  const normalized = normalizeTimesheetStatus(rawStatus);
  if (normalized === "PENDING_APPROVAL") {
    return "PENDING";
  }
  return normalized;
}

export function getTimesheetWeekStatus(timeSheetData) {
  return normalizeTimesheetWeekStatus(readAttributeValue(timeSheetData && timeSheetData.status));
}

export function timesheetHasLoggedHours(timeSheetData) {
  if (!timeSheetData) return false;
  return ["project", "nonProject"].some((sectionKey) => {
    const groups = timeSheetData[sectionKey];
    if (!groups) return false;
    return Object.keys(groups).some((groupId) => {
      const tasks = groups[groupId] && groups[groupId].tasks;
      if (!tasks) return false;
      return tasks.some((task) => {
        const timeEntry = task.timeEntry || {};
        return Object.keys(timeEntry).some(
          (dateKey) => parseInt(timeEntry[dateKey].timesheetTimeMins || 0, 10) > 0
        );
      });
    });
  });
}

/**
 * Collect calendar dates (ISO yyyy-MM-dd) that can be included in a partial submit.
 * Days must have hours and be DRAFT, REJECTED, or orphan PENDING (legacy full-week leftovers).
 */
export function collectSubmittableActivityDates(timeSheetData) {
  const byIso = new Map();
  if (!timeSheetData) return [];
  ["project", "nonProject"].forEach((sectionKey) => {
    const groups = timeSheetData[sectionKey];
    if (!groups) return;
    Object.keys(groups).forEach((groupId) => {
      const tasks = groups[groupId] && groups[groupId].tasks;
      if (!tasks) return;
      tasks.forEach((task) => {
        const timeEntry = task.timeEntry || {};
        Object.keys(timeEntry).forEach((dateKey) => {
          const entry = timeEntry[dateKey] || {};
          const mins = parseInt(entry.timesheetTimeMins || 0, 10);
          if (mins <= 0) return;
          const status = normalizeTimesheetStatus(
            entry.timesheetStatus || entry.status || ""
          );
          const isOrphanPending =
            (status === "PENDING" || status === "PENDING_APPROVAL") &&
            (entry.submissionId == null || entry.submissionId === "");
          if (status && !SUBMITTABLE_DAY_STATUSES.has(status) && !isOrphanPending) {
            return;
          }
          const iso = toIsoDate(dateKey);
          if (!iso) return;
          byIso.set(iso, {
            isoDate: iso,
            dateKey,
            label: moment(iso).isValid() ? moment(iso).format("ddd D") : iso,
          });
        });
      });
    });
  });
  return Array.from(byIso.values()).sort((a, b) => a.isoDate.localeCompare(b.isoDate));
}

function toIsoDate(dateKey) {
  if (!dateKey) return null;
  if (/^\d{4}-\d{2}-\d{2}$/.test(dateKey)) {
    return dateKey;
  }
  const parsed = moment(dateKey, ["YYYY-MMM-DD", "YYYY-MM-DD", moment.ISO_8601], true);
  if (parsed.isValid()) {
    return parsed.format("YYYY-MM-DD");
  }
  const loose = moment(dateKey);
  return loose.isValid() ? loose.format("YYYY-MM-DD") : null;
}

/**
 * Approval UI is active when org/env flag (or permission mirror) is on.
 * While config is still loading, a staged `weekId` is a soft signal.
 * After config is known off, never keep Submit/draft chrome alive from weekId alone.
 */
export function isTimesheetApprovalWorkflowActive(timeSheetData, permission) {
  if (shouldUseTimesheetApprovalWorkflow()) {
    return true;
  }
  if (permission && permission.timesheetApprovalEnabled === true) {
    return true;
  }
  if (!isTimesheetApprovalConfigLoaded()) {
    return !!(timeSheetData && timeSheetData.weekId);
  }
  return false;
}

export function canSubmitTimesheet(timeSheetData, permission) {
  if (!isTimesheetApprovalWorkflowActive(timeSheetData, permission)) {
    return false;
  }
  // Staged weeks (weekId) are already editable via save; do not hide Submit
  // solely because role enableTimeSheetEdit is missing/false while draft exists.
  if (
    permission &&
    permission.enableTimeSheetEdit === false &&
    !(timeSheetData && timeSheetData.weekId)
  ) {
    return false;
  }
  if (!timeSheetData || !timeSheetData.weekId) {
    return false;
  }
  const status = getTimesheetWeekStatus(timeSheetData);
  if (shouldAllowPartialWeekTimesheetSubmission()) {
    if (
      status === "APPROVED" ||
      status === "LOCKED" ||
      status === "PAYROLL_PROCESSED"
    ) {
      return false;
    }
    if (status && !PARTIAL_SUBMITTABLE_WEEK_STATUSES.has(status)) {
      return false;
    }
    return collectSubmittableActivityDates(timeSheetData).length > 0;
  }
  if (status && SUBMITTABLE_STATUSES.has(status)) {
    return timesheetHasLoggedHours(timeSheetData);
  }
  if (!status && timesheetHasLoggedHours(timeSheetData)) {
    return true;
  }
  return false;
}

export function isResubmitAction(timeSheetData) {
  if (shouldAllowPartialWeekTimesheetSubmission()) {
    const dates = collectSubmittableActivityDates(timeSheetData);
    // Resubmit if any selectable day is REJECTED.
    if (!timeSheetData) return false;
    let hasRejected = false;
    ["project", "nonProject"].forEach((sectionKey) => {
      const groups = timeSheetData[sectionKey];
      if (!groups) return;
      Object.keys(groups).forEach((groupId) => {
        const tasks = groups[groupId] && groups[groupId].tasks;
        if (!tasks) return;
        tasks.forEach((task) => {
          const timeEntry = task.timeEntry || {};
          Object.keys(timeEntry).forEach((dateKey) => {
            const entry = timeEntry[dateKey] || {};
            const status = normalizeTimesheetStatus(entry.timesheetStatus || entry.status || "");
            if (status === "REJECTED" && parseInt(entry.timesheetTimeMins || 0, 10) > 0) {
              hasRejected = true;
            }
          });
        });
      });
    });
    return hasRejected || RESUBMIT_STATUSES.has(getTimesheetWeekStatus(timeSheetData));
  }
  const status = getTimesheetWeekStatus(timeSheetData);
  return RESUBMIT_STATUSES.has(status);
}

export function isTimesheetPendingApproval(timeSheetData) {
  return getTimesheetWeekStatus(timeSheetData) === "PENDING";
}

export function isTimesheetRejected(timeSheetData) {
  return getTimesheetWeekStatus(timeSheetData) === "REJECTED";
}

export function getSaveDraftCopy(permission, timeSheetData) {
  if (isTimesheetApprovalWorkflowActive(timeSheetData, permission)) {
    if (shouldAllowPartialWeekTimesheetSubmission()) {
      return {
        title: "Unsaved draft changes",
        body: "Save your draft. You can submit selected days for approval independently.",
        buttonLabel: "Save draft",
      };
    }
    return {
      title: "Unsaved draft changes",
      body: "Save your draft to staging. Submit for approval when the week is ready.",
      buttonLabel: "Save draft",
    };
  }
  return {
    title: "Unsaved changes",
    body: "Review your entries and save to update the timesheet.",
    buttonLabel: "Save timesheet",
  };
}

export function collectLineRejections(timeSheetData) {
  const rows = [];
  if (!timeSheetData) return rows;

  ["project", "nonProject"].forEach((sectionKey) => {
    const groups = timeSheetData[sectionKey];
    if (!groups) return;
    Object.keys(groups).forEach((groupId) => {
      const section = groups[groupId];
      const tasks = section && section.tasks;
      if (!tasks) return;
      tasks.forEach((task) => {
        const lineStatus = normalizeTimesheetStatus(readAttributeValue(task.lineStatus));
        const comment = readAttributeValue(task.rejectionComment);
        if (lineStatus !== "REJECTED" || !comment) {
          return;
        }
        const label =
          sectionKey === "project"
            ? [task.taskName, task.workItemName].filter(Boolean).join(" · ")
            : task.workItemName || groupId;
        rows.push({ key: `${sectionKey}-${groupId}-${task.lineId || label}`, label, comment });
      });
    });
  });
  return rows;
}

export function getWeekRejectionComment(timeSheetData) {
  return readAttributeValue(timeSheetData && timeSheetData.rejectionComment);
}

export function isTimesheetApproved(timeSheetData) {
  return getTimesheetWeekStatus(timeSheetData) === "APPROVED";
}

export function isTimesheetReopened(timeSheetData) {
  return getTimesheetWeekStatus(timeSheetData) === "REOPENED";
}

export function wasTimesheetPreviouslyApproved(timeSheetData) {
  return !!(
    timeSheetData &&
    (readAttributeValue(timeSheetData.approvedBy) || readAttributeValue(timeSheetData.approvedDate))
  );
}

export function isTimesheetWeekLocked(timeSheetData) {
  const status = getTimesheetWeekStatus(timeSheetData);
  return status === "LOCKED" || status === "PAYROLL_PROCESSED";
}

export function isTimesheetPayrollProcessed(timeSheetData) {
  return getTimesheetWeekStatus(timeSheetData) === "PAYROLL_PROCESSED";
}

/**
 * ADD TIME ENTRY / create row — blocked once the week is pending, approved, or locked.
 * Partial-week mode allows adding entries while other days are still pending.
 */
export function canAddTimesheetEntry(timeSheetData, permission) {
  if (permission && permission.enableTimeSheetEntry === false) {
    return false;
  }
  const status = getTimesheetWeekStatus(timeSheetData);
  if (!status) {
    return true;
  }
  if (shouldAllowPartialWeekTimesheetSubmission()) {
    return (
      status !== "LOCKED" &&
      status !== "PAYROLL_PROCESSED" &&
      status !== "APPROVED"
    );
  }
  return status === "DRAFT" || status === "REJECTED" || status === "REOPENED";
}

/**
 * Approved submission batches available for partial-week reopen.
 * Empty when flag is off or no submission-linked APPROVED days remain.
 */
export function collectApprovedSubmissionReopenOptions(timeSheetData) {
  if (!shouldAllowPartialWeekTimesheetSubmission() || !timeSheetData) {
    return [];
  }
  const bySubmission = new Map();
  const visitBucket = (bucket) => {
    Object.values(bucket || {}).forEach((group) => {
      (group.tasks || []).forEach((task) => {
        Object.entries(task.timeEntry || {}).forEach(([dateKey, entry]) => {
          if (!entry || entry.submissionId == null || entry.submissionId === "") {
            return;
          }
          const status = String(entry.timesheetStatus || entry.status || "")
            .toUpperCase()
            .replace("PENDING_APPROVAL", "PENDING");
          if (status !== "APPROVED") {
            return;
          }
          const submissionId = entry.submissionId;
          if (!bySubmission.has(submissionId)) {
            bySubmission.set(submissionId, new Set());
          }
          bySubmission.get(submissionId).add(dateKey);
        });
      });
    });
  };
  visitBucket(timeSheetData.project);
  visitBucket(timeSheetData.nonProject);
  return Array.from(bySubmission.entries())
    .map(([submissionId, dates]) => {
      const activityDates = Array.from(dates).sort();
      return {
        submissionId,
        activityDates,
        label:
          activityDates.length > 0
            ? `Batch ${activityDates[0]}${
                activityDates.length > 1
                  ? ` – ${activityDates[activityDates.length - 1]}`
                  : ""
              }`
            : `Submission ${submissionId}`,
      };
    })
    .sort((a, b) => String(a.submissionId).localeCompare(String(b.submissionId)));
}
