/**
 * WTG-005 / WTG-006 frontend contract helpers for timesheet governance metadata.
 * The backend remains authoritative; these helpers only normalize fail-closed views.
 */

export function normalizeTimesheetValidationIssue(issue) {
  if (!issue || typeof issue !== "object") {
    return null;
  }
  return {
    rule: issue.rule || "",
    mode: String(issue.mode || "").toUpperCase(),
    outcome: String(issue.outcome || "").toUpperCase(),
    code: issue.code || "",
    message: issue.message || "",
    dayIds: Array.isArray(issue.dayIds) ? issue.dayIds : [],
    lineIds: Array.isArray(issue.lineIds) ? issue.lineIds : [],
    projectIds: Array.isArray(issue.projectIds) ? issue.projectIds : [],
    details: issue.details && typeof issue.details === "object" ? issue.details : {},
  };
}

export function normalizeTimesheetValidationResult(validation) {
  if (!validation || typeof validation !== "object") {
    return null;
  }
  const issues = Array.isArray(validation.issues)
    ? validation.issues.map(normalizeTimesheetValidationIssue).filter(Boolean)
    : [];
  return {
    enabled: validation.enabled === true,
    operation: validation.operation || "",
    blocked: validation.blocked === true,
    warningCount: Number.isFinite(validation.warningCount) ? validation.warningCount : issues.length,
    blockCount: Number.isFinite(validation.blockCount) ? validation.blockCount : 0,
    issues,
  };
}

export function normalizeTimesheetApprovalUnit(unit) {
  if (!unit || typeof unit !== "object") {
    return null;
  }
  return {
    chainInstanceRef: unit.chainInstanceRef || "",
    sourceId: unit.sourceId || "",
    sourceRef: unit.sourceRef || unit.approvalUnitRef || "",
    approvalUnitRef: unit.approvalUnitRef || unit.sourceRef || "",
    projectId: unit.projectId != null ? unit.projectId : null,
    lineId: unit.lineId != null ? unit.lineId : null,
    status: unit.status || "",
    currentStepKey: unit.currentStepKey || "",
    instanceVersion: unit.instanceVersion != null ? unit.instanceVersion : null,
    stepVersion: unit.stepVersion != null ? unit.stepVersion : null,
    dueAt: unit.dueAt || null,
  };
}

export function normalizeTimesheetDeadline(deadline) {
  if (!deadline || typeof deadline !== "object") {
    return null;
  }
  return {
    enabled: deadline.enabled === true,
    classification: String(deadline.classification || "ON_TIME").toUpperCase(),
    deadlineMode: String(deadline.deadlineMode || "ALLOW").toUpperCase(),
    bandKey: deadline.bandKey || "",
    daysLate: Number.isFinite(deadline.daysLate) ? deadline.daysLate : 0,
    policyCode: deadline.policyCode || "",
    reasonRequired: deadline.reasonRequired === true,
    reasonCategory: deadline.reasonCategory || "",
    warningMessage: deadline.warningMessage || "",
  };
}

export function deadlineFromPreview(preview) {
  if (!preview || typeof preview !== "object") {
    return null;
  }
  const status = String(preview.status || "").toUpperCase();
  const enabled = preview.enabled === true || status === "OK";
  if (!enabled || status === "DENIED" || status === "DISABLED") {
    return null;
  }
  const late =
    preview.late === true || String(preview.classification || "").toUpperCase() === "LATE";
  const daysLate = Number.isFinite(preview.daysLate) ? preview.daysLate : 0;
  return {
    enabled: true,
    classification: String(preview.classification || (late ? "LATE" : "ON_TIME")).toUpperCase(),
    deadlineMode: String(preview.deadlineMode || "ALLOW").toUpperCase(),
    bandKey: preview.bandKey || "",
    daysLate,
    policyCode: preview.policyCode || "",
    reasonRequired: preview.reasonRequired === true,
    warningMessage:
      preview.warningMessage ||
      (late ? `Timesheet submitted ${daysLate} day(s) after the configured deadline` : ""),
  };
}

export function mergeTimesheetDeadlinePreview(governance, preview) {
  const deadline = deadlineFromPreview(preview);
  if (!governance && !deadline) {
    return null;
  }
  return {
    ...(governance || {}),
    deadline,
  };
}

export function normalizeTimesheetGovernance(governance) {
  if (!governance || typeof governance !== "object") {
    return null;
  }
  return {
    approvalUnitMode: String(governance.approvalUnitMode || "WEEK").toUpperCase(),
    approvalOutcome: governance.approvalOutcome || "",
    legacyFallback: governance.legacyFallback === true,
    chainComplete: governance.chainComplete === true,
    validation: normalizeTimesheetValidationResult(governance.validation),
    deadline: normalizeTimesheetDeadline(governance.deadline),
    approvalUnits: Array.isArray(governance.approvalUnits)
      ? governance.approvalUnits.map(normalizeTimesheetApprovalUnit).filter(Boolean)
      : [],
  };
}

export function formatTimesheetGovernanceWarnings(governance) {
  const normalized = normalizeTimesheetGovernance(governance);
  if (!normalized) {
    return [];
  }
  const messages = [];
  if (normalized.validation && normalized.validation.enabled) {
    normalized.validation.issues
      .filter((issue) => issue.mode === "WARN" || issue.mode === "BLOCK")
      .forEach((issue) => {
        if (issue.message) {
          messages.push(issue.message);
        }
      });
  }
  if (normalized.deadline && normalized.deadline.warningMessage) {
    messages.push(normalized.deadline.warningMessage);
  }
  return messages;
}

function chip(id, label, tone) {
  return { id, label, tone };
}

function humanizeToken(value) {
  return String(value || "")
    .replace(/_/g, " ")
    .toLowerCase()
    .replace(/\b\w/g, (letter) => letter.toUpperCase());
}

export function buildTimesheetGovernanceBannerModel(governance) {
  const normalized = normalizeTimesheetGovernance(governance);
  if (!normalized) {
    return null;
  }
  const messages = formatTimesheetGovernanceWarnings(governance);
  const deadline = normalized.deadline;
  const validation = normalized.validation || {};
  const blocked = validation.blocked === true;
  const late =
    deadline &&
    deadline.enabled === true &&
    deadline.classification &&
    deadline.classification !== "ON_TIME";
  const reasonRequired = !!(deadline && deadline.reasonRequired === true);
  if (!messages.length && !blocked && !late && !reasonRequired) {
    return null;
  }
  if (reasonRequired && !messages.some((message) => /reason/i.test(message))) {
    messages.push(
      "A late-submission reason is required before this timesheet can proceed."
    );
  }
  const chips = [];
  if (late) {
    chips.push(
      chip("class", humanizeToken(deadline.classification), blocked ? "danger" : "warning")
    );
  }
  if (deadline && deadline.daysLate > 0) {
    chips.push(chip("late", `${deadline.daysLate}d late`, "warning"));
  }
  if (deadline && deadline.deadlineMode) {
    chips.push(chip("mode", `Mode ${humanizeToken(deadline.deadlineMode)}`, "muted"));
  }
  if (reasonRequired) {
    chips.push(chip("reason", "Late reason required", "danger"));
  }
  if (normalized.approvalUnitMode && normalized.approvalUnitMode !== "WEEK") {
    chips.push(
      chip("unit", `${humanizeToken(normalized.approvalUnitMode)} units`, "info")
    );
  }
  if (normalized.approvalOutcome) {
    chips.push(
      chip("outcome", humanizeToken(normalized.approvalOutcome), "muted")
    );
  }
  if (normalized.legacyFallback) {
    chips.push(chip("legacy", "Legacy manager path", "warning"));
  }
  if (normalized.approvalUnits.length > 0) {
    chips.push(
      chip(
        "units",
        `${normalized.approvalUnits.length} approval unit${
          normalized.approvalUnits.length === 1 ? "" : "s"
        }`,
        "info"
      )
    );
  }
  return {
    blocked,
    messages,
    chips,
    title: blocked ? "Governance is blocking submit" : "Timesheet governance",
  };
}

