export function isLikelyLateTimesheetWeek(timeSheetRequest) {
  const preview = timeSheetRequest && timeSheetRequest.deadlinePreview;
  if (!preview || typeof preview !== "object") {
    return false;
  }
  const status = String(preview.status || "").toUpperCase();
  const enabled = preview.enabled === true || status === "OK";
  if (!enabled || status === "DENIED" || status === "DISABLED") {
    return false;
  }
  return preview.late === true || String(preview.classification || "").toUpperCase() === "LATE";
}

export function isTimesheetLateReasonCaptureVisible(governance, timeSheetRequest) {
  return isTimesheetLateReasonRequired(governance, timeSheetRequest);
}

export function isTimesheetLateReasonRequired(governance, timeSheetRequest) {
  const normalized = normalizeTimesheetGovernance(governance);
  const deadline = normalized && normalized.deadline;
  if (deadline && deadline.enabled === true && deadline.reasonRequired === true) {
    return true;
  }
  const preview = timeSheetRequest && timeSheetRequest.deadlinePreview;
  if (!preview || typeof preview !== "object") {
    return false;
  }
  const status = String(preview.status || "").toUpperCase();
  const enabled = preview.enabled === true || status === "OK";
  if (!enabled || status === "DENIED" || status === "DISABLED") {
    return false;
  }
  return preview.reasonRequired === true;
}

export function validateTimesheetLateReason({
  lateReason,
  lateReasonDetail,
  required,
} = {}) {
  if (!required) {
    return "";
  }
  const category = String(lateReason || "").trim().toUpperCase();
  if (!category) {
    return "Select a late-submission reason before submitting.";
  }
  if (category === "OTHER" && !String(lateReasonDetail || "").trim()) {
    return "Add a short detail for Other.";
  }
  return "";
}

export function buildTimesheetWorkflowBody({
  activityDates,
  lateReason,
  lateReasonDetail,
  reopenReason,
  submissionId,
} = {}) {
  const body = {};
  if (activityDates && activityDates.length) {
    body.activityDates = activityDates;
  }
  if (lateReason) {
    body.lateReason = String(lateReason).trim().toUpperCase();
  }
  if (lateReasonDetail) {
    body.lateReasonDetail = String(lateReasonDetail).trim();
  }
  if (reopenReason) {
    body.reopenReason = String(reopenReason).trim();
  }
  if (submissionId != null && submissionId !== "") {
    body.submissionId = submissionId;
  }
  return Object.keys(body).length ? body : undefined;
}

export function earliestTimesheetSlaDue(week) {
  if (!week || typeof week !== "object") {
    return null;
  }
  const dues = [];
  if (week.dueAt) {
    dues.push(week.dueAt);
  }
  const weekGovernance = normalizeTimesheetGovernance(week.governance);
  const units = (weekGovernance && weekGovernance.approvalUnits) || [];
  units.forEach((unit) => {
    if (unit.dueAt) {
      dues.push(unit.dueAt);
    }
  });
  if (!dues.length) {
    return null;
  }
  const timestamps = dues
    .map((value) => new Date(value).getTime())
    .filter((value) => Number.isFinite(value));
  if (!timestamps.length) {
    return null;
  }
  return new Date(Math.min(...timestamps)).toISOString();
}

export function formatTimesheetSlaDue(dueAt) {
  if (!dueAt) {
    return "";
  }
  const date = new Date(dueAt);
  if (Number.isNaN(date.getTime())) {
    return "";
  }
  return date.toLocaleString(undefined, {
    day: "numeric",
    month: "short",
    hour: "2-digit",
    minute: "2-digit",
  });
}
