import {
  FEATURE_FLAG_MODULES,
  FEATURE_FLAG_STATUSES,
  normalizeFeatureFlag,
} from "config/feature-flag.config";

export function buildFeatureFlagMetrics(flags) {
  const rows = (flags || []).map(normalizeFeatureFlag).filter(Boolean);
  const enabled = rows.filter((row) => row.enabled);
  const pilot = rows.filter((row) => row.status === FEATURE_FLAG_STATUSES.PILOT);
  const highRisk = rows.filter((row) => row.risk === "high" && row.enabled);
  const adoption =
    rows.length > 0
      ? Math.round(rows.reduce((sum, row) => sum + (row.adoptionPct || 0), 0) / rows.length)
      : 0;

  return {
    totalFlags: rows.length,
    enabledFlags: enabled.length,
    pilotFlags: pilot.length,
    highRiskEnabled: highRisk.length,
    adoptionAvg: adoption,
    disabledFlags: rows.length - enabled.length,
  };
}

export function buildFeatureFlagInsights(flags) {
  const rows = (flags || []).map(normalizeFeatureFlag).filter(Boolean);
  const insights = [];

  const highRiskOn = rows.filter((row) => row.risk === "high" && row.enabled);
  if (highRiskOn.length > 0) {
    insights.push({
      id: "high-risk",
      tone: "rose",
      icon: "fe fe-alert-triangle",
      title: `${highRiskOn.length} high-risk flag(s) enabled`,
      copy: "Review blast radius before org-wide rollout.",
    });
  }

  const blockedDeps = rows.filter((row) => {
    if (!row.enabled || row.dependents.length === 0) {
      return false;
    }
    return row.dependents.some((depKey) => {
      const dep = rows.find((candidate) => candidate.key === depKey);
      return dep && !dep.enabled;
    });
  });
  if (blockedDeps.length > 0) {
    insights.push({
      id: "deps",
      tone: "amber",
      icon: "fe fe-link-2",
      title: `${blockedDeps.length} flag(s) missing dependencies`,
      copy: "Enable prerequisite flags to avoid partial module behavior.",
    });
  }

  const pilotOnly = rows.filter((row) => row.status === FEATURE_FLAG_STATUSES.PILOT);
  if (pilotOnly.length > 0) {
    insights.push({
      id: "pilot",
      tone: "blue",
      icon: "fe fe-toggle-right",
      title: `${pilotOnly.length} pilot flag(s) in staging`,
      copy: "Track adoption before promoting to production defaults.",
    });
  }

  if (insights.length === 0) {
    insights.push({
      id: "healthy",
      tone: "green",
      icon: "fe fe-check-circle",
      title: `${rows.filter((row) => row.enabled).length} flags aligned`,
      copy: "Org toggles match Tracopus pilot registry.",
    });
  }

  return insights.slice(0, 3);
}

export function filterFeatureFlags(flags, filters = {}) {
  const { status = "ALL", module = "ALL", query = "" } = filters;
  const normalizedQuery = String(query || "").trim().toLowerCase();

  return (flags || [])
    .map(normalizeFeatureFlag)
    .filter(Boolean)
    .filter((row) => {
      if (status === "ENABLED" && !row.enabled) {
        return false;
      }
      if (status === "DISABLED" && row.enabled) {
        return false;
      }
      if (status === "PILOT" && row.status !== FEATURE_FLAG_STATUSES.PILOT) {
        return false;
      }
      if (module !== "ALL" && row.module !== module) {
        return false;
      }
      if (!normalizedQuery) {
        return true;
      }
      const haystack = [row.name, row.key, row.module, row.description, row.owner]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      return haystack.includes(normalizedQuery);
    });
}

export function getFeatureFlagModuleMeta(moduleKey) {
  return FEATURE_FLAG_MODULES[moduleKey] || { label: moduleKey, icon: "fe fe-circle", tone: "slate" };
}

export function applyFeatureFlagToggle(flag, enabled) {
  const profile = normalizeFeatureFlag(flag);
  if (!profile) {
    return null;
  }
  return {
    ...profile,
    enabled,
    status: enabled ? FEATURE_FLAG_STATUSES.PILOT : FEATURE_FLAG_STATUSES.DISABLED,
    updatedAt: new Date().toISOString().slice(0, 10),
  };
}

export function buildFeatureAdoptionSeries(flags) {
  const rows = (flags || []).map(normalizeFeatureFlag).filter(Boolean);
  return rows
    .slice()
    .sort((a, b) => (b.adoptionPct || 0) - (a.adoptionPct || 0))
    .slice(0, 6)
    .map((row) => ({
      id: row.id,
      label: row.name,
      value: row.adoptionPct || 0,
      enabled: row.enabled,
    }));
}

export function buildFeatureRiskSeries(flags) {
  const rows = (flags || []).map(normalizeFeatureFlag).filter(Boolean);
  const buckets = [
    { id: "high", label: "High", tone: "rose", value: 0 },
    { id: "medium", label: "Medium", tone: "amber", value: 0 },
    { id: "low", label: "Low", tone: "green", value: 0 },
  ];
  rows.forEach((row) => {
    const risk = String(row.risk || "low").toLowerCase();
    const bucket = buckets.find((item) => item.id === risk) || buckets[2];
    bucket.value += 1;
  });
  return buckets.map((bucket) => ({
    ...bucket,
    meta: `${bucket.value} flag${bucket.value === 1 ? "" : "s"}`,
  }));
}
