import dateUtils from "_helpers/date.utils";
import { getWorkItemStatusMeta } from "../workItemActivity.utils";

export const CALENDAR_EVENT_STATUS = {
  COMPLETED: { label: "Completed", tone: "green", color: "#047857", bg: "rgba(16, 185, 129, 0.18)" },
  INPROGRESS: { label: "In progress", tone: "indigo", color: "#4338ca", bg: "rgba(99, 102, 241, 0.16)" },
  ASSIGNED: { label: "Assigned", tone: "sky", color: "#0369a1", bg: "rgba(14, 165, 233, 0.16)" },
  NEW: { label: "Scheduled", tone: "amber", color: "#b45309", bg: "rgba(245, 158, 11, 0.18)" },
};

export const CALENDAR_STATUS_FILTERS = [
  { key: "ALL", label: "All statuses" },
  { key: "INPROGRESS", label: "In progress" },
  { key: "ASSIGNED", label: "Assigned" },
  { key: "COMPLETED", label: "Completed" },
  { key: "NEW", label: "Scheduled" },
];

export const VIEW_MODE_LABELS = {
  PROJECT: "projects",
  DELIVERABLES: "deliverables",
  WORKITEMS: "work items",
};

export function getCalendarEventStatusMeta(status) {
  return CALENDAR_EVENT_STATUS[status] || CALENDAR_EVENT_STATUS.NEW;
}

export function getCalendarRangeForView(date, view) {
  const anchor = dateUtils.convertDateToMoment(date) || dateUtils.getCurrentTime();
  let start = anchor.clone();
  let end = anchor.clone();

  switch (view) {
    case "month":
      start = anchor.clone().startOf("month");
      end = anchor.clone().endOf("month");
      break;
    case "week":
      start = anchor.clone().startOf("week");
      end = anchor.clone().endOf("week");
      break;
    case "day":
      start = anchor.clone().startOf("day");
      end = anchor.clone().endOf("day");
      break;
    case "agenda":
      start = anchor.clone().startOf("day");
      end = anchor.clone().endOf("month");
      break;
    default:
      start = anchor.clone().startOf("week");
      end = anchor.clone().endOf("week");
  }

  return { start, end };
}

function dedupeItems(items, viewMode) {
  if (!items || !items.length) return [];
  if (viewMode === "PROJECT") {
    return items.filter(
      (item, index) => index === items.findIndex((x) => x.projectId === item.projectId)
    );
  }
  if (viewMode === "DELIVERABLES") {
    return items.filter(
      (item, index) => index === items.findIndex((x) => x.taskId === item.taskId)
    );
  }
  return items;
}

function safeDate(value) {
  if (!value) return null;
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? null : parsed;
}

function buildWorkItemDates(item) {
  const status = String(item.status || "").toUpperCase();
  const useActual = item.actualEndTime && (status === "COMPLETED" || status === "CLOSED");
  const startRaw = useActual ? item.actualStartTime : item.estimatedStartTime || item.estStartTime;
  const start = safeDate(startRaw);
  if (!start) return { start: null, end: null, allDay: false };

  let end = safeDate(
    useActual
      ? item.actualEndTime
      : item.estimatedEndTime || item.estCompletionTime || item.actualCompletionTime
  );

  if (!end) {
    const mins = item.estDurationInMins || item.durationInMinutes || 60;
    end = new Date(start.getTime() + mins * 60 * 1000);
  }

  if (end.getTime() <= start.getTime()) {
    end = new Date(start.getTime() + 60 * 60 * 1000);
  }

  const allDay = end.getTime() - start.getTime() >= 24 * 60 * 60 * 1000;
  return { start, end, allDay };
}

function buildSpanDates(startRaw, endRaw) {
  const start = safeDate(startRaw);
  const end = safeDate(endRaw);
  if (!start && !end) return { start: null, end: null, allDay: false };
  const s = start || end;
  const e = end || start;
  const allDay = e.getTime() - s.getTime() >= 24 * 60 * 60 * 1000 || !start || !end;
  return { start: s, end: e.getTime() > s.getTime() ? e : new Date(s.getTime() + 60 * 60 * 1000), allDay };
}

export function mapCalendarEvents(taskActivities, viewMode) {
  if (!taskActivities || !taskActivities.length) return [];

  return dedupeItems(taskActivities.slice(), viewMode || "WORKITEMS")
    .map((item) => {
      let title = item.name || "Untitled";
      let subtitle = "";
      let dates = { start: null, end: null, allDay: false };

      if (viewMode === "PROJECT") {
        title = item.projectName || title;
        subtitle = item.projectcode || item.projectCategory || "Project";
        dates = buildSpanDates(item.projectEstStartTime, item.projectEstCompletionTime);
      } else if (viewMode === "DELIVERABLES") {
        title = item.taskName || title;
        subtitle = item.taskActCategory || item.taskType || "Deliverable";
        dates = buildSpanDates(item.taskEstStartTime, item.taskEstCompletionTime);
      } else {
        title = item.name || item.taskName || title;
        subtitle = [item.projectName, item.taskName, item.taskActCategory].filter(Boolean).join(" · ");
        dates = buildWorkItemDates(item);
      }

      if (!dates.start) return null;

      const statusMeta = getWorkItemStatusMeta(item.status);
      const eventId =
        viewMode === "PROJECT"
          ? `project-${item.projectId}`
          : viewMode === "DELIVERABLES"
          ? `task-${item.taskId}`
          : `wi-${item.id}`;

      return {
        id: eventId,
        title,
        start: dates.start,
        end: dates.end,
        allDay: dates.allDay,
        status: item.status,
        desc: subtitle,
        subtitle,
        statusLabel: statusMeta.label,
        statusTone: statusMeta.tone,
        resource: item,
        viewMode,
      };
    })
    .filter(Boolean);
}

export function filterCalendarEvents(events, statusFilter, searchQuery) {
  let list = events || [];
  if (statusFilter && statusFilter !== "ALL") {
    list = list.filter((ev) => String(ev.status || "").toUpperCase() === statusFilter);
  }
  const q = (searchQuery || "").trim().toLowerCase();
  if (q) {
    list = list.filter((ev) => {
      const hay = [ev.title, ev.desc, ev.subtitle, ev.statusLabel].filter(Boolean).join(" ").toLowerCase();
      return hay.includes(q);
    });
  }
  return list;
}

export function buildUserCalendarSummary(events) {
  const list = events || [];
  const counts = { COMPLETED: 0, INPROGRESS: 0, ASSIGNED: 0, NEW: 0, other: 0 };
  list.forEach((ev) => {
    const key = String(ev.status || "").toUpperCase();
    if (counts[key] != null) counts[key] += 1;
    else counts.other += 1;
  });

  const todayStart = dateUtils.getCurrentTime().clone().startOf("day");
  const todayCount = list.filter((ev) => {
    const start = dateUtils.convertDateToMoment(ev.start);
    return start && start.isSame(todayStart, "day");
  }).length;

  return {
    total: list.length,
    completed: counts.COMPLETED,
    inProgress: counts.INPROGRESS,
    assigned: counts.ASSIGNED,
    todayCount,
    kpis: [
      { key: "total", label: "In view", value: list.length, icon: "fe fe-calendar", hint: "Visible events" },
      { key: "today", label: "Today", value: todayCount, icon: "fe fe-sun", tone: "amber", hint: "Starting today" },
      { key: "progress", label: "In progress", value: counts.INPROGRESS, icon: "fe fe-activity", tone: "indigo" },
      { key: "done", label: "Completed", value: counts.COMPLETED, icon: "fe fe-check-circle", tone: "green" },
    ],
  };
}

export function buildUpcomingEvents(events, limit = 10) {
  const now = dateUtils.getCurrentTime();
  return (events || [])
    .filter((ev) => {
      if (!ev.start) return false;
      const end = dateUtils.convertDateToMoment(ev.end || ev.start);
      return end.isValid() && !end.isBefore(now, "minute");
    })
    .sort((a, b) => a.start - b.start)
    .slice(0, limit);
}

export function formatEventTimeRange(event) {
  if (!event || !event.start) return "—";
  if (event.allDay) {
    const sameDay = dateUtils.convertDateToMoment(event.start).isSame(event.end, "day");
    if (sameDay) return dateUtils.convertDateFormat(event.start);
    return `${dateUtils.convertDateFormat(event.start)} – ${dateUtils.convertDateFormat(event.end)}`;
  }
  return `${dateUtils.convertDateTimeFormat(event.start)} – ${dateUtils.convertDateTimeFormat(event.end)}`;
}

export function getEventDetailHref(event) {
  const item = event && event.resource;
  if (!item) return null;

  if (event.viewMode === "PROJECT" && item.itemIdUserTeamPrefix) {
    return `/project/details/${item.itemIdUserTeamPrefix}`;
  }
  if (event.viewMode === "DELIVERABLES") {
    if (item.itemIdUserTeamPrefix) return `/project/deliverable/${item.itemIdUserTeamPrefix}`;
    if (item.taskId) return `/project/deliverable/${item.taskId}`;
  }
  return null;
}

export function calendarEventPropGetter(selectedEventId) {
  return (event) => {
    const meta = getCalendarEventStatusMeta(event.status);
    const isSelected = selectedEventId && event.id === selectedEventId;
    return {
      className: ["lux-rbc-event", `is-${meta.tone}`, isSelected ? "is-selected" : ""]
        .filter(Boolean)
        .join(" "),
      style: {
        backgroundColor: "transparent",
        border: "none",
        boxShadow: "none",
        padding: 0,
        minHeight: "1.4rem",
      },
    };
  };
}

export function calendarEventStyleGetter(event) {
  return calendarEventPropGetter(null)(event);
}

export function calendarDayPropGetter(date) {
  const m = dateUtils.convertDateToMoment(date);
  const isToday = m && m.isSame(dateUtils.getCurrentTime(), "day");
  const isWeekend = m && (m.day() === 0 || m.day() === 6);
  return {
    className: ["lux-rbc-day", isToday ? "is-today" : "", isWeekend ? "is-weekend" : ""]
      .filter(Boolean)
      .join(" "),
  };
}

export function calendarSlotPropGetter(date) {
  const m = dateUtils.convertDateToMoment(date);
  const isWeekend = m && (m.day() === 0 || m.day() === 6);
  return {
    className: isWeekend ? "lux-rbc-slot is-weekend" : "lux-rbc-slot",
  };
}

export const CALENDAR_FORMATS = {
  dayFormat: "ddd D",
  weekdayFormat: "ddd",
  monthHeaderFormat: "MMMM YYYY",
  dayHeaderFormat: "dddd, MMM D",
  dayRangeHeaderFormat: ({ start, end }) =>
    `${dateUtils.convertDateFormat(start)} – ${dateUtils.convertDateFormat(end)}`,
  agendaHeaderFormat: ({ start }) => dateUtils.convertDateFormat(start),
  agendaDateFormat: "ddd D",
  eventTimeRangeFormat: ({ start, end }, culture, localizer) =>
    `${localizer.format(start, "h:mm a", culture)} – ${localizer.format(end, "h:mm a", culture)}`,
};
