const KPI_TONE_MAP = {
  primary: "sky",
  blue: "sky",
  indigo: "indigo",
  violet: "violet",
  green: "green",
  teal: "teal",
  amber: "amber",
  rose: "rose",
  slate: "sky",
};

export function mapKpiTone(tone) {
  return KPI_TONE_MAP[tone] || tone || "sky";
}

/** Map summary KPI rows into compact atelier pulse cards. */
export function buildPulseCardsFromKpis(kpis, max = 4) {
  return (kpis || []).slice(0, max).map((kpi) => ({
    id: kpi.key || kpi.label,
    label: kpi.label,
    value:
      kpi.displayValue != null
        ? kpi.displayValue
        : kpi.value == null || kpi.value === ""
          ? "—"
          : kpi.suffix
            ? `${kpi.value}${kpi.suffix}`
            : kpi.value,
    tone: mapKpiTone(kpi.tone),
  }));
}

/** Fallback pulse when a page has no KPI builder yet. */
export function buildShownPulse(visibleCount, label = "Shown") {
  return [{ id: "shown", label, value: visibleCount, tone: "sky" }];
}

export function mergePulseCards(primary = [], fallback = []) {
  if (primary && primary.length) return primary;
  return fallback;
}
