import React, { useEffect, useState } from 'react';
import { Router, Route, Switch, Redirect } from 'react-router-dom';
import { useDispatch } from 'react-redux';

import { accessUtils, authGetItem, ensureAuthSession, history, returnUrlUtils, init as initAnalytics, trackPageView, setupGlobalTracking, applyPageSeo, bindLuxPhoneMedia, closeOffcanvasNav, isForcePasswordChangeRequired, FORCE_PASSWORD_CHANGE_PATH, startAppUpdateWatcher, forceReloadLatestApp } from './_helpers';
import { notificationActions } from './_actions';
import MainLayout from 'layouts/MainLayout';
import PersonaContextProvider from 'context/PersonaContextProvider';
import UserLayout from 'layouts/UserLayout';
import LegalLayout from 'layouts/LegalLayout';
import ErrorLayout from 'layouts/ErrorLayout';
import DocsLayout from 'layouts/DocsLayout';
import ForceChangePasswordPage from 'views/user/ForceChangePasswordPage';
import AppUpdateBanner from 'views/common/AppUpdateBanner';

// Share auth across tabs; clear non-remembered sessions on cold browser start.
ensureAuthSession();

/**
 * One shell route for all authenticated app modules.
 * Separate Route per prefix remounted PersonaContextProvider + MainLayout on
 * every module switch, so menu selection appeared only after the next page loaded.
 */
const APP_SHELL_PATHS = [
  "/hrms",
  "/sales",
  "/project",
  "/report",
  "/workspace",
  "/client",
  "/people",
  "/integrations",
  "/ai",
  "/finance",
  "/resources",
  "/payroll",
  "/performance",
  "/analytics",
  "/admin",
  "/recruiting",
  "/learning",
  "/benefits",
  "/npd",
  "/dossiers",
  "/vendors",
  "/delivery",
];

function App() {
  const dispatch = useDispatch();
  const [appUpdate, setAppUpdate] = useState(null);

  useEffect(() => {
    initAnalytics();
    const trackLocation = (location) => {
      const path = (location.pathname || "") + (location.search || "");
      const seo = applyPageSeo(location.pathname);
      trackPageView(path, seo.title);
    };
    const unlisten = history.listen((location) => {
      notificationActions && dispatch(notificationActions.clear());
      trackLocation(location);
      closeOffcanvasNav();
    });
    trackLocation(history.location);
    return () => unlisten();
  }, [dispatch]);

  useEffect(() => setupGlobalTracking(), []);

  useEffect(() => bindLuxPhoneMedia(), []);

  useEffect(() => {
    const stop = startAppUpdateWatcher({
      onUpdateAvailable: (result) => setAppUpdate(result),
    });
    const onSwUpdate = () => {
      setAppUpdate((prev) => prev || { updateAvailable: true, remoteVersion: "" });
    };
    window.addEventListener("tracopus:sw-update", onSwUpdate);
    return () => {
      stop();
      window.removeEventListener("tracopus:sw-update", onSwUpdate);
    };
  }, []);

  function getRedirectPageUrl() {
    try {
      const menuAccessControl = accessUtils.getMenuAccessControl();
      if (menuAccessControl && menuAccessControl.projectModules && menuAccessControl.projectModules.active === true) {
        return "/project/" + (menuAccessControl.projectModules.defaultRedirectPage ? menuAccessControl.projectModules.defaultRedirectPage : "dashboard");
      }
      if (menuAccessControl && menuAccessControl.peopleModules && menuAccessControl.peopleModules.active === true) {
        return "/people/" + (menuAccessControl.peopleModules.defaultRedirectPage ? menuAccessControl.peopleModules.defaultRedirectPage : "dashboard");
      }
      if (menuAccessControl && menuAccessControl.salesModules && menuAccessControl.salesModules.active === true) {
        return "/sales/" + (menuAccessControl.salesModules.defaultRedirectPage ? menuAccessControl.salesModules.defaultRedirectPage : "bidrequests");
      }
    } catch (_err) {
      // Role access-control decrypt/parse failures must not blank the app.
    }
    return "/project/dashboard";
  }

  return (
    <>
      <AppUpdateBanner
        show={!!(appUpdate && appUpdate.updateAvailable)}
        remoteVersion={appUpdate && appUpdate.remoteVersion}
        onReload={() => forceReloadLatestApp()}
      />
      <Router history={history}>
        <Switch>
          <Route path={APP_SHELL_PATHS} render={props => securePage(props)} />
          <Route path="/legal" render={props => <LegalLayout {...props} />} />
          <Redirect exact from="/user/privacy" to="/legal/privacy" />
          <Redirect exact from="/user/terms" to="/legal/terms" />
          <Route path="/user" render={props => inSecurePage(props)} />
          <Route path="/error" render={props =>  <ErrorLayout {...props} />} />
          <Route path="/document" render={props =>  <DocsLayout {...props} />} />
          {/* Lazy evaluate redirect target — do not call getRedirectPageUrl during Switch child creation */}
          <Route exact path="/" render={() => <Redirect to={getRedirectPageUrl()} />} />
          <Route render={() => <Redirect to={getRedirectPageUrl()} />} />
        </Switch>
      </Router>
    </>
  );

  function isForceChangePath(pathname) {
    return pathname === FORCE_PASSWORD_CHANGE_PATH
      || (pathname && pathname.startsWith(`${FORCE_PASSWORD_CHANGE_PATH}/`));
  }

  function inSecurePage(props) {
    const pathname = props.location && props.location.pathname;
    if (authGetItem('cu')) {
      if (isForcePasswordChangeRequired()) {
        if (isForceChangePath(pathname)) {
          // Render directly — do not rely on UserLayout route Switch matching.
          return (
            <div className="auth">
              <ForceChangePasswordPage />
            </div>
          );
        }
        return <Redirect to={{ pathname: FORCE_PASSWORD_CHANGE_PATH }} />;
      }
      return (
        <Redirect to={{ pathname: '/', state: { from: props.location } }} />
      );
    }
    if (isForceChangePath(pathname)) {
      return (
        <Redirect to={{ pathname: '/user/login', state: { from: props.location } }} />
      );
    }
    return <UserLayout {...props} />;
  }

  function securePage(props) {
    if (!authGetItem('cu')) {
      returnUrlUtils.saveReturnUrl(props.location);
      return (
        <Redirect to={{ pathname: '/user/login', state: { from: props.location } }} />
      );
    }
    if (isForcePasswordChangeRequired()) {
      return <Redirect to={{ pathname: FORCE_PASSWORD_CHANGE_PATH }} />;
    }
    // Persona provider is stable for the authenticated session; do not remount
    // it per navigation (that re-ran menu loading and delayed selection).
    return (
      <PersonaContextProvider>
        <MainLayout {...props} />
      </PersonaContextProvider>
    );
  }
}

export default App;