import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";

export const knowledgeRcaService = {
  getLessonsOverview,
  listLessons,
  publishLesson,
  getRcaOverview,
  listRcaRecords,
  getRca,
  createRca,
  submitRcaForApproval,
  approveRca,
  rejectRca,
  getKnowledgeOverview,
  searchKnowledge,
  getRcaAiDraft,
  exportLessonsCsv,
};

function teamQuery(extra) {
  const query = { userTeamId: commonUtils.getCurrentUserTeamId() };
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

async function getLessonsOverview(filters) {
  const response = await axiosUtils.getWithParam(
    `${urlConfig.KNOWLEDGE_RCA_API_PATH}/lessons/overview`,
    teamQuery(filters)
  );
  return { payload: (response && response.payload) || response || {}, source: "api" };
}

async function listLessons(filters) {
  const response = await axiosUtils.getWithParam(
    `${urlConfig.KNOWLEDGE_RCA_API_PATH}/lessons`,
    teamQuery(filters)
  );
  return { payload: (response && response.payload) || response || [], source: "api" };
}

async function publishLesson(lessonId) {
  const response = await axiosUtils.post(
    `${urlConfig.KNOWLEDGE_RCA_API_PATH}/lessons/${lessonId}/publish?userTeamId=${commonUtils.getCurrentUserTeamId()}`,
    {}
  );
  return { payload: (response && response.payload) || response, source: "api" };
}

