import React, { Component } from "react";
import { connect } from "react-redux";
import { createPortal } from "react-dom";
import {
  FONT_OPTIONS,
  LAYOUT_TOGGLES,
  TYPOGRAPHY_PRESETS,
  getActiveTypographyLabel,
  getUiSettings,
  updateUiSettings,
} from "_helpers/settings.utils";
import envconfig from "env.config";
import {
  closeLuxSettingsPanel,
  openLuxThemePanel,
} from "_helpers/luxShellPanels.utils";

class SettingsRightSidebar extends Component {
  constructor() {
    super();
    this.state = getUiSettings();
    this.panelRef = React.createRef();
  }

  componentDidMount() {
    this.syncLegacyOpenClass();
  }

  componentDidUpdate(prevProps) {
    if (prevProps.show !== this.props.show) {
      this.syncLegacyOpenClass();
    }
  }

  /** Strip legacy jQuery `.open` so it cannot fight Redux `lux-shell-panel--open`. */
  syncLegacyOpenClass = () => {
    const el = this.panelRef.current || document.getElementById("settings_right_sidebar");
    if (!el) return;
    el.classList.remove("open");
  };

  handleClose = () => {
    const el = this.panelRef.current || document.getElementById("settings_right_sidebar");
    if (el) el.classList.remove("open");
    closeLuxSettingsPanel();
  };

  handleOpenPalette = () => {
    openLuxThemePanel();
  };

  handleTypographyPreset = (presetId) => {
    this.setState(updateUiSettings({ typography: presetId }));
  }

  handleFontChange = (fontId) => {
    this.setState(updateUiSettings({ typography: 'custom', font: fontId }));
  }

  handleToggleChange = (key) => (event) => {
    this.setState(updateUiSettings({ [key]: event.target.checked }));
  }

  renderTypographyPresets() {
    return (
      <ul className="lux-settings-option-grid lux-settings-option-grid--presets">
        {TYPOGRAPHY_PRESETS.map((preset) => {
          const isActive = this.state.typography === preset.id;

          return (
            <li key={preset.id}>
              <button
                type="button"
                className={`lux-settings-option lux-settings-option--preset${isActive ? ' is-active' : ''}`}
                onClick={() => this.handleTypographyPreset(preset.id)}
                aria-pressed={isActive}
              >
                <span className="lux-settings-option__preset-samples" aria-hidden="true">
                  <span className="lux-settings-option__sample" style={{ fontFamily: preset.sampleUi }}>
                    UI
                  </span>
                  <span
                    className="lux-settings-option__sample lux-settings-option__sample--brand"
                    style={{ fontFamily: preset.sampleBrand }}
                  >
                    Aa
                  </span>
                </span>
                <span className="lux-settings-option__copy">
                  <strong>{preset.label}</strong>
                  <span>{preset.description}</span>
                  <em>{preset.mood}</em>
                </span>
                {isActive && (
                  <span className="lux-settings-option__check" aria-hidden="true">
                    <i className="fe fe-check" />
                  </span>
                )}
              </button>
            </li>
          );
        })}
      </ul>
    );
  }

  renderFontOptions() {
    const isCustom = this.state.typography === 'custom';

    return (
      <section className="lux-settings-section">
        <div className="lux-settings-section__head">
          <span className="lux-settings-section__eyebrow">Typography</span>
          <h4 className="lux-settings-section__title">Type style</h4>
          <p className="lux-settings-section__desc">
            Choose a curated pairing for UI and brand, or pick a custom UI font below.
          </p>
        </div>
        {this.renderTypographyPresets()}
        <div className="lux-settings-section__subhead">
          <h5 className="lux-settings-section__subtitle">Custom UI font</h5>
          {!isCustom && (
            <span className="lux-settings-section__hint">Select a font to override the preset</span>
          )}
        </div>
        <ul className="lux-settings-option-grid lux-settings-option-grid--fonts">
          {FONT_OPTIONS.map((font) => {
            const isActive = isCustom && this.state.font === font.id;

            return (
              <li key={font.id}>
                <button
                  type="button"
                  className={`lux-settings-option lux-settings-option--font${isActive ? ' is-active' : ''}`}
                  onClick={() => this.handleFontChange(font.id)}
                  aria-pressed={isActive}
                >
                  <span
                    className="lux-settings-option__sample"
                    style={{ fontFamily: font.family }}
                  >
                    Aa
                  </span>
                  <span className="lux-settings-option__copy">
                    <strong>{font.label}</strong>
                    <span>{font.description}</span>
                    <em>{font.mood}</em>
                  </span>
                  {isActive && (
                    <span className="lux-settings-option__check" aria-hidden="true">
                      <i className="fe fe-check" />
                    </span>
                  )}
                </button>
              </li>
            );
          })}
        </ul>
      </section>
    );
  }

  renderLayoutToggles() {
    return (
      <section className="lux-settings-section">
        <div className="lux-settings-section__head">
          <span className="lux-settings-section__eyebrow">Layout</span>
          <h4 className="lux-settings-section__title">Interface behavior</h4>
          <p className="lux-settings-section__desc">Fine-tune shell ergonomics for daily use.</p>
        </div>
        <ul className="lux-settings-toggle-list">
          {LAYOUT_TOGGLES.filter(
            (toggle) => toggle.id !== "moduleMenuRail" || envconfig.USE_MODULE_MENU_RAIL === true
          ).map((toggle) => (
            <li key={toggle.id} className="lux-settings-toggle">
              <div className="lux-settings-toggle__copy">
                <span className="lux-settings-toggle__icon" aria-hidden="true">
                  <i className={`fe ${toggle.icon}`} />
                </span>
                <div>
                  <strong>{toggle.label}</strong>
                  <span>{toggle.description}</span>
                </div>
              </div>
              <label className="custom-switch custom-switch-sm lux-settings-toggle__switch">
                <input
                  type="checkbox"
                  className="custom-switch-input"
                  checked={
                    toggle.id === "moduleMenuRail"
                      ? this.state.moduleMenuRail !== false
                      : !!this.state[toggle.id]
                  }
                  onChange={this.handleToggleChange(toggle.id)}
                />
                <span className="custom-switch-indicator" />
              </label>
            </li>
          ))}
        </ul>
      </section>
    );
  }

  render() {
    const { show } = this.props;
    const activeTypography = getActiveTypographyLabel(this.state);
    const activeToggles = LAYOUT_TOGGLES.filter((toggle) => this.state[toggle.id]).length;

    return createPortal(
      <>
        {show && (
          <button
            type="button"
            className="lux-shell-panel__backdrop"
            aria-label="Close settings panel"
            onClick={this.handleClose}
          />
        )}
        <div
          ref={this.panelRef}
          id="settings_right_sidebar"
          className={`right_sidebar settings_right_sidebar lux-settings-panel${
            show ? " lux-shell-panel--open" : ""
          }`}
          aria-hidden={!show}
        >
        <div className="lux-settings-panel__shell">
          <header className="lux-settings-panel__header">
            <div className="lux-settings-panel__header-main">
              <span className="lux-settings-panel__icon" aria-hidden="true">
                <i className="fe fe-sliders" />
              </span>
              <div className="lux-settings-panel__header-copy">
                <span className="lux-settings-panel__eyebrow">Workspace</span>
                <h3 className="lux-settings-panel__title">Settings</h3>
                <p className="lux-settings-panel__subtitle">
                  Typography and layout preferences for your {envconfig.APP_NAME} shell.
                </p>
              </div>
            </div>
            <button
              type="button"
              className="lux-settings-panel__close setting-sidebar-close-link"
              onClick={this.handleClose}
              aria-label="Close settings panel"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          <div className="lux-settings-panel__stats">
            <span className="lux-settings-panel__stat">
              <i className="fe fe-type" aria-hidden="true" />
              {activeTypography}
            </span>
            <span className="lux-settings-panel__stat">
              <i className="fe fe-toggle-left" aria-hidden="true" />
              {activeToggles} active
            </span>
            <span className="lux-settings-panel__stat">
              <i className="fe fe-check-circle" aria-hidden="true" />
              Auto-saved
            </span>
          </div>

          <div className="lux-settings-panel__palette-hint">
            <div className="lux-settings-panel__palette-copy">
              <span className="lux-settings-panel__palette-label">Accent colors</span>
              <strong>Customize palettes separately</strong>
              <span>Open the droplet icon in the left rail for 12 curated themes.</span>
            </div>
            <button
              type="button"
              className="lux-settings-panel__palette-btn"
              onClick={this.handleOpenPalette}
            >
              <i className="fe fe-droplet" aria-hidden="true" />
              Palettes
            </button>
          </div>

          <div className="lux-settings-panel__body">
            {this.renderFontOptions()}
            {this.renderLayoutToggles()}
          </div>

          <footer className="lux-settings-panel__footer">
            <p>Preferences apply instantly and persist on this device. Legacy theme switches were removed in favor of the luxury shell.</p>
          </footer>
        </div>
      </div>
      </>,
      document.body
    );
  }
}

const mapStateToProps = (state) => ({
  show: !!(state.appconfig && state.appconfig.showSettingsWindow),
});

export default connect(mapStateToProps)(SettingsRightSidebar);
