import { isLeaveEnhancementsEnabled } from "config/leave-enhancement.config";
import { leaveEnhancementService } from "_services/leave-enhancement.service";
import { leavePhase2Service } from "_services/leavePhase2.service";
import LeaveImpactDrawer from "./components/leave/LeaveImpactDrawer";
import LeaveCoveragePanel from "./components/leave/LeaveCoveragePanel";
import LeaveAnalyticsPanel from "./components/leave/LeaveAnalyticsPanel";
import LeavePayrollExtractPanel from "./components/leave/LeavePayrollExtractPanel";
import CollapsibleAuditPanel from 'views/common/fragments/CollapsibleAuditPanel';
import Alert from 'views/common/fragments/Alert';
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import './leaveLuxForms.css';
