import React from "react";
import classNames from "classnames/bind";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import { formatCurrency, INVOICE_AGING_BUCKETS } from "views/project/components/invoice/invoice.utils";

const BUCKET_META = INVOICE_AGING_BUCKETS.reduce((acc, row) => {
  acc[row.code] = row;
  return acc;
}, {});

function normalizeBuckets(aging) {
  const rows = (aging && aging.buckets) || [];
  return INVOICE_AGING_BUCKETS.map((meta) => {
    const match =
      rows.find((b) => b.code === meta.code) ||
      rows.find((b) => b.bucket === meta.code || b.bucket === meta.shortLabel.replace("–", "-"));
    return {
      code: meta.code,
      label: meta.label,
      shortLabel: meta.shortLabel,
      tone: meta.tone,
      invoiceCount: (match && match.invoiceCount) || 0,
      amount: (match && match.amount) || 0,
    };
  });
}

export default function CollectionsAgingPanel({
  aging,
  loading,
  error,
  canViewAmounts,
  selectedBucket,
  onSelectBucket,
  onClearBucket,
  onRetry,
}) {
  if (loading) {
    return (
      <section className="lux-inv-aging" data-testid="collections-aging-panel" aria-busy="true">
        <SkeletonTheme baseColor="#f1f5f9" highlightColor="#e2e8f0">
          <Skeleton height={168} borderRadius={16} />
        </SkeletonTheme>
      </section>
    );
  }

  if (error) {
    return (
      <section className="lux-inv-aging is-error" data-testid="collections-aging-panel">
        <div className="lux-inv-aging__head">
          <div>
            <div className="lux-inv-aging__eyebrow">
              <i className="fe fe-alert-triangle" aria-hidden="true" />
              Collections
            </div>
            <h3>Aging unavailable</h3>
            <p>Could not load unpaid invoice aging from the platform ledger.</p>
          </div>
          {onRetry && (
            <button type="button" className="lux-inv-aging__head-btn" onClick={onRetry}>
              Retry
            </button>
          )}
        </div>
      </section>
    );
  }

  if (!aging) {
    return null;
  }

  const buckets = normalizeBuckets(aging);
  const unpaidCount = aging.unpaidInvoiceCount || 0;
  const unpaidAmount = aging.unpaidAmount || 0;
  const asOfLabel = aging.asOf ? String(aging.asOf).slice(0, 10) : null;
  const totalAmount = Math.max(
    unpaidAmount,
    buckets.reduce((sum, b) => sum + (b.amount || 0), 0),
    1
  );
  const overdueCount = buckets
    .filter((b) => b.code !== "CURRENT")
    .reduce((sum, b) => sum + b.invoiceCount, 0);
  const critical = buckets.find((b) => b.code === "DAYS_90_PLUS");

  return (
    <section
      className={classNames("lux-inv-aging", selectedBucket && "has-filter")}
      data-testid="collections-aging-panel"
      aria-label="Collections aging"
    >
      <div className="lux-inv-aging__head">
        <div>
          <div className="lux-inv-aging__eyebrow">
            <i className="fe fe-trending-up" aria-hidden="true" />
            Collections
          </div>
          <h3>Aging of open invoices</h3>
          <p>
            Platform ledger · {unpaidCount} unpaid
            {canViewAmounts ? ` · ${formatCurrency(unpaidAmount, { compact: true })} outstanding` : ""}
            {asOfLabel ? ` · as of ${asOfLabel}` : ""}
          </p>
        </div>
        {selectedBucket && onClearBucket && (
          <button type="button" className="lux-inv-aging__head-btn" onClick={onClearBucket}>
            Clear age filter
          </button>
        )}
      </div>

      {unpaidCount === 0 ? (
        <div className="lux-inv-aging__all-clear">
          <i className="fe fe-check-circle" aria-hidden="true" />
          <span>No unpaid platform invoices in the aging window.</span>
        </div>
      ) : (
        <>
          <div className="lux-inv-aging__hero">
            <div className="lux-inv-aging__hero-card is-open">
              <span>Open AR</span>
              <strong>
                {canViewAmounts ? formatCurrency(unpaidAmount, { compact: true }) : unpaidCount}
              </strong>
              <small>{unpaidCount} invoice{unpaidCount === 1 ? "" : "s"}</small>
            </div>
            <div className="lux-inv-aging__hero-card is-overdue">
              <span>Past due</span>
              <strong>{overdueCount}</strong>
              <small>beyond current</small>
            </div>
            <div className="lux-inv-aging__hero-card is-critical">
              <span>90+ days</span>
              <strong>
                {canViewAmounts
                  ? formatCurrency((critical && critical.amount) || 0, { compact: true })
                  : (critical && critical.invoiceCount) || 0}
              </strong>
              <small>{(critical && critical.invoiceCount) || 0} at risk</small>
            </div>
          </div>

          <div
            className="lux-inv-aging__stack"
            role="img"
            aria-label="Outstanding amount by aging bucket"
          >
            {buckets.map((bucket) => {
              const pct = unpaidAmount > 0 ? (bucket.amount / totalAmount) * 100 : 0;
              if (pct <= 0) return null;
              return (
                <button
                  key={`stack-${bucket.code}`}
                  type="button"
                  className={classNames(
                    "lux-inv-aging__stack-seg",
                    `is-${bucket.tone}`,
                    selectedBucket === bucket.code && "is-active"
                  )}
                  style={{ width: `${Math.max(pct, bucket.invoiceCount > 0 ? 4 : 0)}%` }}
                  title={`${bucket.label}: ${bucket.invoiceCount} · ${
                    canViewAmounts ? formatCurrency(bucket.amount) : "—"
                  }`}
                  onClick={() =>
                    onSelectBucket &&
                    onSelectBucket(selectedBucket === bucket.code ? null : bucket.code)
                  }
                />
              );
            })}
          </div>

          <div className="lux-inv-aging__buckets" role="list">
            {buckets.map((bucket) => {
              const share =
                unpaidAmount > 0 ? Math.round((bucket.amount / unpaidAmount) * 100) : 0;
              const active = selectedBucket === bucket.code;
              return (
                <button
                  key={bucket.code}
                  type="button"
                  role="listitem"
                  className={classNames(
                    "lux-inv-aging__bucket",
                    `is-${bucket.tone}`,
                    active && "is-active",
                    bucket.invoiceCount === 0 && "is-empty"
                  )}
                  onClick={() =>
                    onSelectBucket && onSelectBucket(active ? null : bucket.code)
                  }
                  aria-pressed={active}
                  disabled={bucket.invoiceCount === 0 && !active}
                >
                  <span className="lux-inv-aging__bucket-label">{bucket.label}</span>
                  <strong className="lux-inv-aging__bucket-count">{bucket.invoiceCount}</strong>
                  <em className="lux-inv-aging__bucket-amount">
                    {canViewAmounts ? formatCurrency(bucket.amount, { compact: true }) : "—"}
                  </em>
                  <span className="lux-inv-aging__bucket-share">{share}%</span>
                </button>
              );
            })}
          </div>

          <p className="lux-inv-aging__hint">
            <i className="fe fe-filter" aria-hidden="true" />
            Tap a bucket to filter the invoice list to that age band
            {selectedBucket && BUCKET_META[selectedBucket]
              ? ` · showing ${BUCKET_META[selectedBucket].label}`
              : ""}
            .
            {aging.approximate && (
              <>
                {" "}
                Ledger sync is unavailable — totals reflect loaded invoices in your register.
              </>
            )}
          </p>
        </>
      )}
    </section>
  );
}
