import React, { Component } from "react";
import PageInnerHeaderTeamsSelectionMenu from "./fragments/PageInnerHeaderTeamsSelectionMenu";
import dateUtils from "_helpers/date.utils";
import { commonUtils } from "_helpers";
import PageInnerHeaderEmployeesSelectionMenu from "./fragments/PageInnerHeaderEmployeesSelectionMenu";

class PageInnerHeaderTimesheet extends Component {
  getWeekRangeLabel = () => {
    const { startOfTheWeek } = this.props;
    if (!startOfTheWeek) {
      return "";
    }
    const startMoment = dateUtils.convertDateStringToMoment(startOfTheWeek);
    if (!startMoment) {
      return dateUtils.convertDateFormat(startOfTheWeek);
    }
    const endMoment = startMoment.clone().endOf("isoWeek");
    return `${dateUtils.convertDateFormat(startMoment.toDate())} – ${dateUtils.convertDateFormat(endMoment.toDate())}`;
  };

  isCurrentWeekSelected = () => {
    const { currentStartOfTheWeek, startOfTheWeek } = this.props;
    return (
      currentStartOfTheWeek &&
      startOfTheWeek &&
      currentStartOfTheWeek.toDateString() === startOfTheWeek.toDateString()
    );
  };

  renderWeekNav = () => {
    const { permission, goToBack, goToCurrent, goToNext } = this.props;
    const isCurrentWeek = this.isCurrentWeekSelected();
    const backDisabled =
      permission.enablePastTimeSheetView !== true && isCurrentWeek;
    const homeDisabled = isCurrentWeek;
    const nextDisabled =
      permission.enableFutureTimeSheetView !== true && isCurrentWeek;

    return (
      <div
        className="lux-ts-header__nav"
        role="group"
        aria-label="Week navigation"
      >
        <button
          type="button"
          className="lux-ts-header__nav-btn"
          onClick={goToBack}
          disabled={backDisabled}
          title="Previous week"
          aria-label="Previous week"
        >
          <i className="fa fa-chevron-left" aria-hidden="true" />
        </button>
        <button
          type="button"
          className="lux-ts-header__nav-btn lux-ts-header__nav-btn--today"
          onClick={goToCurrent}
          disabled={homeDisabled}
          title="Current week"
          aria-label="Current week"
        >
          <i className="fa fa-circle" aria-hidden="true" />
        </button>
        <button
          type="button"
          className="lux-ts-header__nav-btn"
          onClick={goToNext}
          disabled={nextDisabled}
          title="Next week"
          aria-label="Next week"
        >
          <i className="fa fa-chevron-right" aria-hidden="true" />
        </button>
      </div>
    );
  };

  render() {
    const {
      embedded,
      isLoading,
      showUserTeamMenu,
      userTeams,
      handleUserTeamsSelection,
      permission,
      enableUserTeamSingleSelection,
      startOfTheWeek,
      showEmployeeMenu,
      employees,
      handleEmployeesSelection,
      selectedEmployeeId,
      applyEmployeeSelectionImmediately,
      showLeaveSynEnabled,
      syncLeavesHandler,
      syncLeavesInProgress,
    } = this.props;

    const isCurrentWeek = this.isCurrentWeekSelected();
    const weekNumber = startOfTheWeek && dateUtils.getWeekNumber(startOfTheWeek);
    const weekRangeLabel = this.getWeekRangeLabel();

    const toolbar = (
        <div className="lux-page-header__toolbar">
          <div className="lux-page-header__group lux-page-header__group--filters">
            {!isLoading && showUserTeamMenu && userTeams && (
              <PageInnerHeaderTeamsSelectionMenu
                userTeams={userTeams}
                handleUserTeamsSelection={handleUserTeamsSelection}
                isLoading={isLoading}
                enabled={(permission && permission.switchUserTeamsEnabled) || false}
                enableSingleSelection={enableUserTeamSingleSelection}
              />
            )}

            <div
              className={`lux-ts-header__week${isCurrentWeek ? " is-current" : ""}`}
              role="group"
              aria-label="Selected week"
            >
              <div className="lux-ts-header__week-body">
                <span className="lux-ts-header__week-badge">W{weekNumber}</span>
                <span className="lux-ts-header__week-range">{weekRangeLabel}</span>
                {isCurrentWeek && (
                  <span className="lux-ts-header__live" title="Current week">
                    Live
                  </span>
                )}
              </div>
              <span className="lux-ts-header__week-divider" aria-hidden="true" />
              {this.renderWeekNav()}
            </div>

            {!showEmployeeMenu && (
              <div className="lux-page-header__employee-wrap">
                <span className="lux-page-header__employee-btn is-static" aria-disabled="true">
                  <i className="fe fe-user" aria-hidden="true" />
                  <span className="lux-page-header__employee-name text-uppercase">
                    {commonUtils.getCurrentUserName()}
                  </span>
                </span>
              </div>
            )}
            {showEmployeeMenu && employees && employees.length > 0 && (
              <PageInnerHeaderEmployeesSelectionMenu
                employees={employees}
                handleEmployeesSelection={handleEmployeesSelection}
                selectedEmployeeId={selectedEmployeeId}
                isLoading={isLoading}
                enabled={(permission && permission.switchEmployeesEnabled) || false}
                enableSingleSelection={true}
                showEmployeeNameDropDownLabel={true}
                applyEmployeeSelectionImmediately={
                  applyEmployeeSelectionImmediately === true
                }
              />
            )}
          </div>

          <div className="lux-page-header__spacer" aria-hidden="true" />

          <div className="lux-page-header__group lux-page-header__group--actions">
            {showLeaveSynEnabled && syncLeavesInProgress === false && (
              <button
                type="button"
                onClick={syncLeavesHandler}
                className="lux-page-header__action-btn lux-ts-header__sync-btn xs-hide"
              >
                <i className="fe fe-download-cloud" aria-hidden="true" />
                Sync Leaves
              </button>
            )}
            {syncLeavesInProgress === true && (
              <button
                type="button"
                disabled
                className="lux-page-header__action-btn lux-ts-header__sync-btn is-loading xs-hide"
              >
                <i className="fa fa-spinner fa-spin" aria-hidden="true" />
                Syncing…
              </button>
            )}
          </div>
        </div>
    );

    if (embedded) {
      return toolbar;
    }

    return (
      <div className="lux-page-header lux-page-header--timesheet is-sticky">
        {toolbar}
      </div>
    );
  }
}

export default PageInnerHeaderTimesheet;
