import React from 'react';
import classNames from 'classnames/bind';

function formatLayerLabel(layer) {
  if (!layer) return '—';
  const raw = String(layer);
  if (raw.startsWith('RULE_SET:')) return `Rule set (${raw.slice(9)})`;
  const map = {
    EXPLICIT_VERSION: 'Selected version',
    POLICY_LATEST: 'Latest policy version',
    EMPLOYEE_OVERRIDE: 'Employee override',
    WORK_LOCATION: 'Work location',
    ESTABLISHMENT: 'Establishment',
    REGION: 'Region / state',
    COUNTRY: 'Country',
    LEGAL_ENTITY: 'Legal entity',
    FALLBACK: 'Company default',
    COMPANY: 'Company default',
  };
  return map[raw] || raw.replace(/_/g, ' ');
}

/**
 * Friendly summary + optional JSON for simulate / employee-preview payloads.
 */
export default function ResolveResultPanel({
  result,
  view = 'summary',
  kind = 'simulate',
  onViewChange,
  selectedPolicy,
  versions = [],
  selectedVersionId,
  employee,
  employeeId,
}) {
  if (!result) return null;

  const isJson = view === 'json';
  const entitlements = result.entitlementPreview && typeof result.entitlementPreview === 'object'
    ? result.entitlementPreview
    : {};
  const accruals = Array.isArray(entitlements._accruals) ? entitlements._accruals : [];
  const leaveTypeRows = Object.entries(entitlements)
    .filter(([key]) => key !== '_accruals')
    .map(([code, row]) => ({
      code,
      name: (row && row.name) || code,
      annualDays: row && row.annualDays != null ? row.annualDays : '—',
      paid: row && row.paid === false ? 'Unpaid' : 'Paid',
    }));
  const rules = result.rules && typeof result.rules === 'object' ? result.rules : {};
  const carryForward = Array.isArray(rules.carryForward) ? rules.carryForward : [];
  const specialLeave = Array.isArray(rules.specialLeave) ? rules.specialLeave : [];
  const eligibility = Array.isArray(rules.eligibility) ? rules.eligibility : [];
  const versionMeta = versions.find((v) => String(v.id) === String(result.versionId || selectedVersionId));
  const kindLabel = kind === 'preview' ? 'Employee preview' : 'Simulation';

  return (
    <div className="lux-glp-resolve" data-testid="glp-resolve-result">
      <div className="lux-glp-resolve__toolbar">
        <div className="lux-glp-resolve__kind">
          <i className="fe fe-check-circle" aria-hidden="true" />
          <strong>{kindLabel} result</strong>
          {result.simulationRef && <span className="lux-glp-resolve__ref">{result.simulationRef}</span>}
        </div>
        <div className="lux-glp-resolve__toggles" role="tablist" aria-label="Result view">
          <button
            type="button"
            role="tab"
            aria-selected={!isJson}
            className={classNames('lux-glp-resolve__toggle', { 'is-active': !isJson })}
            onClick={() => onViewChange && onViewChange('summary')}
          >
            Summary
          </button>
          <button
            type="button"
            role="tab"
            aria-selected={isJson}
            className={classNames('lux-glp-resolve__toggle', { 'is-active': isJson })}
            onClick={() => onViewChange && onViewChange('json')}
          >
            JSON
          </button>
        </div>
      </div>

      {isJson ? (
        <pre className="lux-glp-pre" data-testid="glp-resolve-json">{JSON.stringify(result, null, 2)}</pre>
      ) : (
        <div className="lux-glp-resolve__summary" data-testid="glp-resolve-summary">
          <div className="lux-glp-resolve__cards">
            <div className="lux-glp-resolve__card">
              <span>Matched via</span>
              <strong>{formatLayerLabel(result.matchedLayer)}</strong>
            </div>
            <div className="lux-glp-resolve__card">
              <span>Policy</span>
              <strong>
                {(selectedPolicy && selectedPolicy.name) || `Policy #${result.policyId || '—'}`}
              </strong>
            </div>
            <div className="lux-glp-resolve__card">
              <span>Version</span>
              <strong>
                {result.versionNo != null
                  ? `v${result.versionNo}`
                  : (versionMeta ? `v${versionMeta.versionNo}` : '—')}
                {' '}
                <em>({result.status || (versionMeta && versionMeta.status) || '—'})</em>
              </strong>
            </div>
            <div className="lux-glp-resolve__card">
              <span>Employee</span>
              <strong>
                {employee
                  ? `${employee.name || 'Employee'}${employee.empCode ? ` (${employee.empCode})` : ''}`
                  : (employeeId ? `#${employeeId}` : 'Not selected')}
              </strong>
            </div>
          </div>

          {(result.context && (result.context.countryCode || result.context.regionCode || result.context.tenureMonths != null)) && (
            <p className="lux-glp-resolve__context">
              Context:
              {result.context.countryCode ? ` country ${result.context.countryCode}` : ''}
              {result.context.regionCode ? ` · region ${result.context.regionCode}` : ''}
              {result.context.tenureMonths != null ? ` · tenure ${result.context.tenureMonths} months` : ''}
            </p>
          )}

          <h4 className="lux-glp-resolve__section-title">Leave entitlements</h4>
          {leaveTypeRows.length ? (
            <div className="lux-leave-register__table-wrap">
              <table className="lux-leave-register__table">
                <thead>
                  <tr>
                    <th>Code</th>
                    <th>Name</th>
                    <th>Annual days</th>
                    <th>Paid</th>
                  </tr>
                </thead>
                <tbody>
                  {leaveTypeRows.map((row) => (
                    <tr key={row.code}>
                      <td>{row.code}</td>
                      <td>{row.name}</td>
                      <td>{row.annualDays}</td>
                      <td>{row.paid}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <p className="lux-glp-resolve__empty">No leave types in the resolved rules.</p>
          )}

          <h4 className="lux-glp-resolve__section-title">Accrual preview (this period)</h4>
          {accruals.length ? (
            <div className="lux-leave-register__table-wrap">
              <table className="lux-leave-register__table">
                <thead>
                  <tr>
                    <th>Leave type</th>
                    <th>Formula</th>
                    <th>Computed days</th>
                  </tr>
                </thead>
                <tbody>
                  {accruals.map((row, idx) => (
                    <tr key={`${row.leaveTypeCode || 'acc'}-${idx}`}>
                      <td>{row.leaveTypeCode || '—'}</td>
                      <td>{row.formula || '—'}</td>
                      <td>{row.computedDays != null ? String(row.computedDays) : '—'}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <p className="lux-glp-resolve__empty">No accrual rules to preview.</p>
          )}

          {(carryForward.length > 0 || specialLeave.length > 0 || eligibility.length > 0) && (
            <>
              <h4 className="lux-glp-resolve__section-title">Other rules</h4>
              <ul className="lux-glp-resolve__bullets">
                {carryForward.map((row, idx) => (
                  <li key={`cf-${idx}`}>
                    Carry-forward {row.leaveTypeCode}: max {row.maxDays}
                    {row.expiryMonths != null ? ` · expires in ${row.expiryMonths} months` : ''}
                  </li>
                ))}
                {specialLeave.map((row, idx) => (
                  <li key={`sp-${idx}`}>
                    Special {row.typeCode || row.code}: {row.name || '—'} · {row.days || row.maxDays || '—'} days
                    {row.privacy ? ` · privacy ${row.privacy}` : ''}
                  </li>
                ))}
                {eligibility.map((row, idx) => (
                  <li key={`el-${idx}`}>
                    Eligibility: min service {row.minServiceMonths != null ? row.minServiceMonths : 0} months
                    {row.notes ? ` · ${row.notes}` : ''}
                  </li>
                ))}
              </ul>
            </>
          )}
        </div>
      )}
    </div>
  );
}
