import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import { shouldUseWorkGraphApi } from "config/work-graph.config";

import { apiErrorResult } from "config/mock-fallback.utils";

export const workGraphService = {
  getOverview,
  listNodes,
  listEdges,
  getNode,
  getNodeRelationships,
  search,
  getGraphAnalytics,
  getGraphAiContext,
  listIndexEvents,
  exportGraphCsv,
};

function teamQuery(extra) {
  const query = { userTeamId: commonUtils.getCurrentUserTeamId() };
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

async function getOverview(filters) {
  if (!shouldUseWorkGraphApi()) {
    return apiErrorResult(null);
  }
  const response = await axiosUtils.getWithParam(`${urlConfig.WORK_GRAPH_API_PATH}/overview`, teamQuery(filters));
  return { payload: (response && response.payload) || response || {}, source: "api" };
}

async function listNodes(filters) {
  if (!shouldUseWorkGraphApi()) {
    return apiErrorResult(null);
  }
  const response = await axiosUtils.getWithParam(`${urlConfig.WORK_GRAPH_API_PATH}/nodes`, teamQuery(filters));
  return { payload: (response && response.payload) || response || [], source: "api" };
}

async function listEdges() {
  if (!shouldUseWorkGraphApi()) {
    return apiErrorResult(null);
  }
  const response = await axiosUtils.getWithParam(`${urlConfig.WORK_GRAPH_API_PATH}/edges`, teamQuery());
  return { payload: (response && response.payload) || response || [], source: "api" };
}

async function getNode(nodeId) {
  if (!shouldUseWorkGraphApi()) {
    return apiErrorResult(null);
  }
  const response = await axiosUtils.getWithParam(`${urlConfig.WORK_GRAPH_API_PATH}/nodes/${nodeId}`, teamQuery());
  return { payload: (response && response.payload) || response, source: "api" };
}

async function getNodeRelationships(nodeId) {
  if (!shouldUseWorkGraphApi()) {
    return apiErrorResult(null);
  }
  const response = await axiosUtils.getWithParam(
    `${urlConfig.WORK_GRAPH_API_PATH}/nodes/${nodeId}/relationships`,
    teamQuery()
  );
  return { payload: (response && response.payload) || response, source: "api" };
}

async function search(query, filters) {
  if (!shouldUseWorkGraphApi()) {
    return apiErrorResult(null);
  }
  const response = await axiosUtils.getWithParam(
    `${urlConfig.WORK_GRAPH_API_PATH}/search`,
    teamQuery({ q: query, ...(filters || {}) })
  );
  return { payload: (response && response.payload) || response || [], source: "api" };
}

async function getGraphAnalytics(filters) {
  if (!shouldUseWorkGraphApi()) {
    return apiErrorResult(null);
  }
  const response = await axiosUtils.getWithParam(`${urlConfig.WORK_GRAPH_API_PATH}/analytics`, teamQuery(filters));
  return { payload: (response && response.payload) || response, source: "api" };
}

async function getGraphAiContext(nodeId) {
  if (!shouldUseWorkGraphApi()) {
    return apiErrorResult(null);
  }
  try {
    const response = await axiosUtils.getWithParam(
      `${urlConfig.WORK_GRAPH_API_PATH}/nodes/${nodeId}/ai-context`,
      teamQuery()
    );
    return { payload: (response && response.payload) || response, source: "api" };
  } catch (e) {
    return { payload: null, source: "api-error", error: e };
  }
}

async function listIndexEvents() {
  if (!shouldUseWorkGraphApi()) {
    return apiErrorResult(null);
  }
  const response = await axiosUtils.getWithParam(`${urlConfig.WORK_GRAPH_API_PATH}/index-events`, teamQuery());
  return { payload: (response && response.payload) || response || [], source: "api" };
}

async function exportGraphCsv(filters) {
  if (!shouldUseWorkGraphApi()) {
    return apiErrorResult(null);
  }
  const response = await axiosUtils.getWithParam(`${urlConfig.WORK_GRAPH_API_PATH}/export`, teamQuery(filters));
  return { payload: (response && response.payload) || response, source: "api" };
}
