import React from "react";
import classNames from "classnames/bind";

/**
 * Live API = green dot. Mock/demo = amber. Health down = red.
 * Accepts "api" / "live" for connected backends.
 */
export default function DataSourceIndicator({
  dataSource,
  demoLabel,
  className,
  title,
  healthStatus,
  decorative,
}) {
  if (!dataSource || dataSource === "client" || dataSource === "empty") {
    return null;
  }

  if (dataSource === "api" || dataSource === "live") {
    const isDown = healthStatus === "down";
    return (
      <span
        className={classNames("lux-data-source-dot", isDown ? "is-down" : "is-live", className)}
        title={title || (isDown ? "Services need attention" : "Connected to live API")}
        aria-hidden={decorative ? "true" : undefined}
        aria-label={decorative ? undefined : isDown ? "Services need attention" : "Live data"}
        role={decorative ? undefined : "status"}
        data-testid="header-live-dot"
      />
    );
  }

  if (dataSource === "mock" && demoLabel) {
    return (
      <span
        className={classNames("lux-data-source-dot", "is-demo", className)}
        title={demoLabel}
        aria-label={demoLabel}
        role="status"
      />
    );
  }

  return null;
}
