import React, { useEffect } from "react";
import { Link, withRouter } from "react-router-dom";
import { useReportPageDataSource } from "views/common/PageChromeContext";
import classNames from "classnames/bind";
import { AdminInsightStrip } from "views/admin/components/AdminLuxShared";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import LuxSegmentNav from "views/common/fragments/LuxSegmentNav";
import { GovernanceKpiStrip } from "views/project/components/ProjectGovernanceLuxShared";
import {
  TICKET_MODULE_NAV,
  getTicketModuleNavActiveId,
} from "config/ticket-management-nav.config";

function TicketModuleNav({ activeId }) {
  return (
    <LuxSegmentNav
      items={TICKET_MODULE_NAV}
      activeId={activeId}
      ariaLabel="Ticket workspaces"
      testId="ticket-module-nav"
    />
  );
}

function TicketsLuxPage({
  pageMeta,
  dataSource,
  demoLabel = "Demo ticket data",
  heroActions,
  kpiCards,
  loading,
  onRefresh,
  refreshLoading,
  pageHeaderNameChangeHandler,
  shellTitle,
  location,
  children,
}) {
  useReportPageDataSource(dataSource);
  const meta = pageMeta || {
    tone: "indigo",
    icon: "fe fe-life-buoy",
    eyebrow: "Service",
    titleLead: "Tickets",
    titleAccent: "& service",
    lede: "SLA-backed service desk and delivery support.",
  };
  const activeNavId = getTicketModuleNavActiveId((location && location.pathname) || "");

  useEffect(() => {
    if (pageHeaderNameChangeHandler && shellTitle) {
      pageHeaderNameChangeHandler(shellTitle);
    }
  }, [pageHeaderNameChangeHandler, shellTitle]);

  return (
    <div className={classNames("lux-register-page", "lux-tickets-module", "lux-ticket-lux", meta.tone && `is-${meta.tone}`)}>
      <div className="lux-ticket-lux__ambient" aria-hidden="true">
        <span className="lux-ticket-lux__orb lux-ticket-lux__orb--a" />
        <span className="lux-ticket-lux__orb lux-ticket-lux__orb--b" />
        <span className="lux-ticket-lux__orb lux-ticket-lux__orb--c" />
      </div>
      <LuxModuleIntro
        meta={meta}
        actions={heroActions || undefined}
        nav={<TicketModuleNav activeId={activeNavId} />}
        onRefresh={onRefresh}
        refreshLoading={refreshLoading != null ? refreshLoading : loading}
      />

      <div className="lux-register-page__body">
        {kpiCards && kpiCards.length ? (
          <GovernanceKpiStrip cards={kpiCards} loading={loading} className="lux-ticket-lux__kpi-strip" />
        ) : null}

        <div className="lux-ticket-lux__content">{children}</div>
      </div>
    </div>
  );
}

export default withRouter(TicketsLuxPage);

export function TicketActionButton({ to, onClick, icon, variant = "ghost", children, disabled, className }) {
  const classes = classNames("lux-onb-action", "lux-ticket-action", `lux-onb-action--${variant}`, className);
  const content = icon ? (
    <>
      <i className={icon} aria-hidden="true" />
      <span>{children}</span>
    </>
  ) : (
    children
  );
  if (to && !onClick) {
    return (
      <Link to={to} className={classes}>
        {content}
      </Link>
    );
  }
  return (
    <button type="button" className={classes} onClick={onClick} disabled={disabled}>
      {content}
    </button>
  );
}

export function TicketLuxPanel({ title, meta, icon, accent, actions, children, featured }) {
  return (
    <section
      className={classNames(
        "lux-hrms-dash__panel",
        "lux-ticket-lux__panel",
        accent && `is-${accent}`,
        featured && "lux-ticket-lux__panel--featured"
      )}
    >
      <header className="lux-hrms-dash__panel-head lux-ticket-lux__panel-head">
        <div className="lux-ticket-lux__panel-head-main">
          {icon ? <i className={icon} aria-hidden="true" /> : null}
          <div>
            <h2 className="lux-hrms-dash__panel-title">{title}</h2>
            {meta ? <p className="lux-hrms-dash__panel-sub">{meta}</p> : null}
          </div>
        </div>
        {actions ? <div className="lux-hrms-dash__panel-actions lux-ticket-lux__panel-actions">{actions}</div> : null}
      </header>
      <div className="lux-hrms-dash__panel-body lux-ticket-lux__panel-body">{children}</div>
    </section>
  );
}

export function TicketInsightPanel({ insights }) {
  if (!insights || !insights.length) {
    return null;
  }
  return <AdminInsightStrip insights={insights} className="lux-ticket-lux__insights" />;
}

export function TicketStatusBadge({ status }) {
  return <span className={classNames("lux-ticket-status", `is-${status}`)}>{status.replace(/_/g, " ")}</span>;
}

export function TicketSlaBadge({ slaStatus }) {
  const label = slaStatus === "on_track" ? "On track" : slaStatus === "at_risk" ? "At risk" : "Breached";
  return <span className={classNames("lux-ticket-sla", `is-${slaStatus}`)}>{label}</span>;
}

export function TicketPriorityBadge({ priority }) {
  return <span className={classNames("lux-ticket-priority", `is-${String(priority).toLowerCase()}`)}>{priority}</span>;
}
