import React from "react";
import classNames from "classnames/bind";

const TimesheetApprovalCommentField = ({
  value,
  onChange,
  disabled,
  required = false,
  error,
  id = "lux-ts-approval-comment",
}) => (
  <label
    className={classNames("lux-ts-approval-comment", { "has-error": !!error })}
    htmlFor={id}
  >
    <span>
      Rejection reason {required ? "(required)" : "(optional for approval)"}
    </span>
    <textarea
      id={id}
      className="lux-ts-approval-comment__input"
      rows={3}
      maxLength={512}
      placeholder="Explain why this timesheet is being rejected"
      value={value || ""}
      disabled={disabled}
      aria-invalid={error ? "true" : "false"}
      aria-describedby={error ? `${id}-error` : undefined}
      onChange={(event) => onChange(event.target.value)}
    />
    {error && (
      <span id={`${id}-error`} className="lux-ts-approval-comment__error" role="alert">
        {error}
      </span>
    )}
  </label>
);

export default TimesheetApprovalCommentField;
