import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import envconfig from "env.config";
import { apiErrorResult } from "config/mock-fallback.utils";

export const adminInsightsService = {
  getDashboard,
};

const API_BASE = `${urlConfig.APPCONFIG_API_PATH}/admin-insights`;

function teamQuery(extra) {
  const query = { userTeamId: commonUtils.getCurrentUserTeamId() };
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

async function getDashboard() {
  if (envconfig.USE_ADMIN_INSIGHTS_API === true) {
    try {
      const response = await axiosUtils.getWithParam(`${API_BASE}/dashboard`, teamQuery());
      const payload = (response && response.payload) || response || {};
      return { payload, source: "api" };
    } catch (e) {
      // fall through
    }
  }

  return apiErrorResult(null);
}
