import {
  INTEGRATION_ADAPTER_KINDS,
  INTEGRATION_ADAPTER_STATUSES,
  INTEGRATION_ADAPTER_TEST_STATUSES,
  INTEGRATION_TRANSPORT_TYPES,
} from "config/integration-adapter.config";

export function normalizeIntegrationAdapter(row) {
  if (!row) {
    return null;
  }
  const testStatusRaw = String(row.testStatus || "").toLowerCase();
  const testStatus =
    testStatusRaw === "passed"
      ? INTEGRATION_ADAPTER_TEST_STATUSES.PASSED
      : testStatusRaw === "failed"
        ? INTEGRATION_ADAPTER_TEST_STATUSES.FAILED
        : testStatusRaw === "running"
          ? INTEGRATION_ADAPTER_TEST_STATUSES.RUNNING
          : INTEGRATION_ADAPTER_TEST_STATUSES.UNTESTED;
  const statusRaw = String(row.status || "").toLowerCase();
  const status =
    statusRaw === "draft"
      ? INTEGRATION_ADAPTER_STATUSES.DRAFT
      : statusRaw === "paused"
        ? INTEGRATION_ADAPTER_STATUSES.PAUSED
        : INTEGRATION_ADAPTER_STATUSES.ACTIVE;
  return {
    id: row.id,
    kind: row.kind || INTEGRATION_ADAPTER_KINDS.SALESFORCE,
    name: row.name || "Adapter",
    transport: row.transport || INTEGRATION_TRANSPORT_TYPES.API,
    connectorId: row.connectorId || null,
    connectorName: row.connectorName || "",
    version: row.version || "1.0.0",
    status,
    testStatus,
    lastTestedAt: row.lastTestedAt || null,
    lastSyncAt: row.lastSyncAt || null,
    capabilities: row.capabilities || [],
    configSummary: row.configSummary || "",
    recordsPerRun: Number(row.recordsPerRun) || 0,
    successRatePct: Number(row.successRatePct) || 0,
    description: row.description || "",
    icon: row.icon || "fe fe-link",
    tone: row.tone || "blue",
  };
}

export function buildAdapterKpis(adapters) {
  const rows = (adapters || []).map(normalizeIntegrationAdapter).filter(Boolean);
  const active = rows.filter((row) => row.status === INTEGRATION_ADAPTER_STATUSES.ACTIVE).length;
  const passed = rows.filter((row) => row.testStatus === INTEGRATION_ADAPTER_TEST_STATUSES.PASSED).length;
  const failed = rows.filter((row) => row.testStatus === INTEGRATION_ADAPTER_TEST_STATUSES.FAILED).length;
  const transports = new Set(rows.map((row) => row.transport)).size;
  return [
    { id: "adapters", label: "Adapters", value: rows.length, icon: "fe fe-package", tone: "blue" },
    { id: "active", label: "Active", value: active, icon: "fe fe-check-circle", tone: "green" },
    { id: "passed", label: "Tests passed", value: passed, icon: "fe fe-shield", tone: "violet" },
    { id: "transports", label: "Transports", value: transports, icon: "fe fe-layers", tone: "indigo" },
  ];
}

export function buildAdapterInsights(adapters) {
  const rows = (adapters || []).map(normalizeIntegrationAdapter).filter(Boolean);
  const failed = rows.filter((row) => row.testStatus === INTEGRATION_ADAPTER_TEST_STATUSES.FAILED);
  if (!failed.length) {
    return [];
  }
  return [
    {
      id: "failed-tests",
      title: "Connection tests failing",
      copy: `${failed.length} adapter(s) failed the last connection test — re-run tests before enabling scheduled sync.`,
      tone: "danger",
    },
  ];
}

export function filterIntegrationAdapters(adapters, { transport, kind, query } = {}) {
  return (adapters || [])
    .map(normalizeIntegrationAdapter)
    .filter(Boolean)
    .filter((row) => !transport || transport === "ALL" || row.transport === transport)
    .filter((row) => !kind || kind === "ALL" || row.kind === kind)
    .filter((row) => {
      if (!query) {
        return true;
      }
      const q = String(query).toLowerCase();
      return (
        String(row.name).toLowerCase().includes(q) ||
        String(row.kind).toLowerCase().includes(q) ||
        String(row.connectorName).toLowerCase().includes(q)
      );
    });
}

export function getAdapterKindLabel(kind) {
  if (kind === INTEGRATION_ADAPTER_KINDS.SALESFORCE) {
    return "Salesforce CRM";
  }
  if (kind === INTEGRATION_ADAPTER_KINDS.LEAVE_FEED) {
    return "Leave feed";
  }
  if (kind === INTEGRATION_ADAPTER_KINDS.WEBHOOK) {
    return "Webhook";
  }
  if (kind === INTEGRATION_ADAPTER_KINDS.CSV) {
    return "CSV import";
  }
  if (kind === INTEGRATION_ADAPTER_KINDS.SFTP) {
    return "SFTP";
  }
  return kind || "Adapter";
}

export function getTransportLabel(transport) {
  if (transport === INTEGRATION_TRANSPORT_TYPES.WEBHOOK) {
    return "Webhook";
  }
  if (transport === INTEGRATION_TRANSPORT_TYPES.FILE) {
    return "File";
  }
  if (transport === INTEGRATION_TRANSPORT_TYPES.SFTP) {
    return "SFTP";
  }
  return "API";
}
