export function normalizeSearch(value) {
  return String(value || "").trim().toLowerCase();
}

/** Split camelCase / snake_case / kebab-case keys into searchable words. */
export function humanizeConfigToken(value) {
  return String(value || "")
    .replace(/[_./-]+/g, " ")
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1 $2")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();
}

function tokenMatchesQuery(token, query) {
  if (token == null || token === "" || !query) return false;
  const normalized = normalizeSearch(token);
  if (normalized.includes(query)) return true;
  return humanizeConfigToken(token).includes(query);
}

/**
 * Recursively match config keys and string/number values (nested object maps,
 * arrays, and list/group property bags used across Application Config).
 */
export function configValueMatchesQuery(value, query, depth = 0) {
  if (!query || value == null || depth > 6) return false;

  if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") {
    return tokenMatchesQuery(String(value), query);
  }

  if (Array.isArray(value)) {
    return value.some((entry) => configValueMatchesQuery(entry, query, depth + 1));
  }

  if (typeof value === "object") {
    return Object.entries(value).some(([key, nested]) => {
      if (tokenMatchesQuery(key, query)) return true;
      return configValueMatchesQuery(nested, query, depth + 1);
    });
  }

  return false;
}

export function nodeMatchesQuery(node, query) {
  if (!query) return true;
  const name = normalizeSearch(node && node.name);
  return name.includes(query);
}

export function treeHasMatch(node, query) {
  if (!node) return false;
  if (nodeMatchesQuery(node, query)) return true;
  const children = (node.nodes || []).filter(Boolean);
  return children.some((child) => treeHasMatch(child, query));
}

export function getOrgNodeIcon(category) {
  if (category === "Team") return "fe-users";
  if (category === "Department") return "fe-briefcase";
  if (category === "Division") return "fe-layers";
  if (category === "Section") return "fe-folder";
  if (category === "Account") return "fe-credit-card";
  return "fe-git-branch";
}

export function getOrgCategoryLabel(category) {
  return category || "Unit";
}

export function countTreeNodes(node) {
  if (!node) return 0;
  let count = node.name ? 1 : 0;
  (node.nodes || []).forEach((child) => {
    count += countTreeNodes(child);
  });
  return count;
}

export function collectExpandableIds(node, type, ids = []) {
  if (!node) return ids;
  if (node.name && node.nodes && node.nodes.length > 0 && node.id != null) {
    ids.push(`${type}-${node.id}`);
  }
  (node.nodes || []).forEach((child) => collectExpandableIds(child, type, ids));
  return ids;
}

export function findTreeNodeById(node, id) {
  if (!node || id == null) return null;
  if (node.id === id) return node;
  for (const child of node.nodes || []) {
    const found = findTreeNodeById(child, id);
    if (found) return found;
  }
  return null;
}

export function getParentLabel(parentMenuOptions, selectionId) {
  if (!parentMenuOptions || selectionId == null) return null;
  const current = parentMenuOptions.find((item) => item.value === selectionId);
  if (!current || current.parent == null) return null;
  const parent = parentMenuOptions.find((item) => item.value === current.parent);
  return parent ? parent.label : null;
}

export function getConfigModuleStats(data) {
  if (!data || !data.modules) {
    return {
      moduleCount: 0,
      settingCount: 0,
      overriddenCount: 0,
      parentOverriddenCount: 0,
      lockedCount: 0,
    };
  }

  let moduleCount = 0;
  let settingCount = 0;
  let overriddenCount = 0;
  let parentOverriddenCount = 0;
  let lockedCount = 0;

  Object.values(data.modules).forEach((module) => {
    if (!module || !module.parentEnabled) return;
    moduleCount += 1;
    const configurations = module.configurations || {};
    Object.values(configurations).forEach((item) => {
      if (!item || item.parentHidden !== false) return;
      settingCount += 1;
      if (item.overridden) overriddenCount += 1;
      if (item.parentOverridden) parentOverriddenCount += 1;
      if (item.parentLocked) lockedCount += 1;
    });
  });

  return { moduleCount, settingCount, overriddenCount, parentOverriddenCount, lockedCount };
}

export function getConfigFlaggedItems(data, flag) {
  if (!data || !data.modules) return [];

  const items = [];

  Object.entries(data.modules).forEach(([moduleKey, module]) => {
    if (!module || !module.parentEnabled) return;

    const moduleLabel = module.label || moduleKey;
    const configurations = module.configurations || {};

    Object.entries(configurations).forEach(([configKey, item]) => {
      if (!item || item.parentHidden !== false) return;

      const isMatch =
        (flag === "overridden" && item.overridden) ||
        (flag === "parentOverridden" && item.parentOverridden) ||
        (flag === "locked" && item.parentLocked);

      if (!isMatch) return;

      items.push({
        id: `${moduleKey}-${configKey}`,
        moduleLabel,
        settingLabel: item.label || configKey,
      });
    });
  });

  return items;
}

export function configItemIsVisible(item, filter, searchQuery, moduleLabel, configKey) {
  if (!item || item.parentHidden !== false) return false;

  if (filter === "overridden" && !item.overridden) return false;
  if (filter === "parentOverridden" && !item.parentOverridden) return false;
  if (filter === "locked" && !item.parentLocked) return false;

  const query = normalizeSearch(searchQuery);
  if (!query) return true;

  if (tokenMatchesQuery(item.label, query)) return true;
  if (tokenMatchesQuery(moduleLabel, query)) return true;
  if (tokenMatchesQuery(configKey, query)) return true;
  if (tokenMatchesQuery(item.inputType, query)) return true;
  if (configValueMatchesQuery(item.value, query)) return true;
  if (configValueMatchesQuery(item.parentValue, query)) return true;

  return false;
}

export function moduleHasVisibleConfigurations(module, filter, searchQuery) {
  if (!module || !module.parentEnabled) return false;

  const moduleLabel = module.label || "";
  const configurations = module.configurations || {};
  return Object.entries(configurations).some(([configKey, item]) =>
    configItemIsVisible(item, filter, searchQuery, moduleLabel, configKey)
  );
}

export function countVisibleConfigItems(data, filter, searchQuery) {
  if (!data || !data.modules) return 0;

  let count = 0;
  Object.values(data.modules).forEach((module) => {
    count += countVisibleModuleConfigItems(module, filter, searchQuery);
  });
  return count;
}

export function countVisibleModuleConfigItems(module, filter, searchQuery) {
  if (!module || !module.parentEnabled) return 0;

  const moduleLabel = module.label || "";
  let count = 0;
  Object.entries(module.configurations || {}).forEach(([configKey, item]) => {
    if (configItemIsVisible(item, filter, searchQuery, moduleLabel, configKey)) {
      count += 1;
    }
  });
  return count;
}

export function configModulesHaveChanges(currentModules, originalModules) {
  return (
    JSON.stringify(currentModules || {}) !== JSON.stringify(originalModules || {})
  );
}

export function isPrimitiveConfigScalar(value) {
  return (
    value == null ||
    typeof value === "string" ||
    typeof value === "number" ||
    typeof value === "boolean"
  );
}

/** True when a list can safely feed react-select (labels must be scalars). */
export function isPrimitiveConfigList(value) {
  return Array.isArray(value) && value.every(isPrimitiveConfigScalar);
}

/** Objects or object-arrays that must not be rendered as React children / select chips. */
export function isNestedConfigValue(value) {
  if (value == null) return false;
  if (Array.isArray(value)) return !isPrimitiveConfigList(value);
  return typeof value === "object";
}

export function stringifyConfigNestedValue(value) {
  try {
    return JSON.stringify(value, null, 2);
  } catch (e) {
    return String(value);
  }
}
