import { getApprovalDomainMeta, UNIVERSAL_APPROVAL_PRIORITIES } from "config/universal-approval.config";
import { resolveApprovalSlaState } from "config/approval-sla.utils";

const DEFAULT_CHECKLIST = {
  LEAVE: [
    { id: "coverage", label: "Check team coverage", detail: "Verify no critical meetings or deadlines conflict." },
    { id: "balance", label: "Validate leave balance", detail: "Confirm sufficient balance for requested days." },
    { id: "policy", label: "Policy compliance", detail: "Ensure leave type matches policy rules." },
  ],
  TIMESHEET: [
    { id: "hours", label: "Review total hours", detail: "Compare against expected weekly capacity." },
    { id: "projects", label: "Validate project codes", detail: "Ensure hours map to active assignments." },
    { id: "conflicts", label: "Check conflicts", detail: "Resolve overlap or missing entries." },
  ],
  ATTENDANCE_REGULARIZATION: [
    { id: "punches", label: "Verify attendance punches", detail: "Compare requested correction with raw punches." },
    { id: "reason", label: "Review reason code", detail: "Ensure justification meets attendance policy." },
  ],
  LIFECYCLE: [
    { id: "dependencies", label: "Check task dependencies", detail: "Confirm upstream tasks are complete." },
    { id: "owner", label: "Validate owner", detail: "Ensure HR/IT owners are assigned for blocked tasks." },
  ],
};

export function buildApprovalAiChecklist(domain) {
  const normalized = String(domain || "").toUpperCase();
  if (DEFAULT_CHECKLIST[normalized]) {
    return DEFAULT_CHECKLIST[normalized];
  }
  if (normalized === "ONBOARDING" || normalized === "OFFBOARDING") {
    return DEFAULT_CHECKLIST.LIFECYCLE;
  }
  return [
    {
      id: "details",
      label: "Review request details",
      detail: "Open the source module for full context.",
    },
  ];
}

export function computeApprovalAiConfidence(item, slaBucket) {
  let score = 0.62;
  if (item && item.domain) {
    score += 0.08;
  }
  if (item && item.metadata && Object.keys(item.metadata).length > 0) {
    score += 0.06;
  }
  if (item && item.priority === UNIVERSAL_APPROVAL_PRIORITIES.HIGH) {
    score += 0.06;
  }
  if (slaBucket === "overdue") {
    score += 0.08;
  }
  return Math.max(0.4, Math.min(0.92, Math.round(score * 100) / 100));
}

export function buildApprovalAiEvidence(item, slaBucket) {
  const evidence = [];
  if (item && item.priority) {
    evidence.push(`Priority ${item.priority}`);
  }
  if (item && item.submittedAt) {
    evidence.push(`Submitted ${item.submittedAt}`);
  }
  if (item && item.dueLabel) {
    evidence.push(`Due ${item.dueLabel}`);
  }
  if (slaBucket) {
    evidence.push(`SLA ${slaBucket}`);
  }
  if (item && item.actingAsDelegate) {
    evidence.push("Acting as delegate");
  }
  return evidence.slice(0, 5);
}

export function buildApprovalAiRecommendation(item, slaBucket) {
  const domain = item && item.domain ? String(item.domain).toUpperCase() : "";
  const metadata = (item && item.metadata) || {};
  const highPriority = item && item.priority === UNIVERSAL_APPROVAL_PRIORITIES.HIGH;

  if (slaBucket === "overdue") {
    return "This item is past SLA. Review immediately and approve or reject with a clear comment.";
  }
  if (highPriority) {
    const domainMeta = getApprovalDomainMeta(domain);
    return `High-priority ${domainMeta.label.toLowerCase()} request — verify supporting details and team impact before approving.`;
  }
  if (domain === "LEAVE" && metadata.leaveType) {
    return `Confirm team coverage for ${metadata.leaveType} before approving leave.`;
  }
  if (domain === "TIMESHEET" && metadata.conflictCount != null && Number(metadata.conflictCount) > 0) {
    return "Timesheet has reported conflicts — resolve or acknowledge before approval.";
  }
  return "Review supporting details in the source module before approving. No blocking conflicts detected.";
}

export function buildApprovalAiNextAction(item, slaBucket) {
  const domainMeta = getApprovalDomainMeta(item && item.domain);
  const highPriority = item && item.priority === UNIVERSAL_APPROVAL_PRIORITIES.HIGH;
  if (slaBucket === "overdue") {
    return "Action this approval now or escalate to the backup approver.";
  }
  if (highPriority) {
    return "Open the source record and validate details before signing off.";
  }
  return `Open in ${domainMeta.label} module if you need additional context.`;
}

export function buildApprovalAiSummaryBrief(item, options) {
  const opts = options || {};
  if (!item) {
    return null;
  }

  const domainMeta = getApprovalDomainMeta(item.domain);
  const requester = item.requester || "the requester";
  const subject = item.subject || domainMeta.label;
  const slaState = opts.slaState || resolveApprovalSlaState(item);
  const slaBucket = slaState && slaState.bucket ? slaState.bucket : null;

  let summary = `${requester} submitted a ${domainMeta.label.toLowerCase()} request: ${subject}.`;
  if (item.actingAsDelegate) {
    summary += " You are acting as a delegate for this approval.";
  }

  return {
    summary,
    recommendation: buildApprovalAiRecommendation(item, slaBucket),
    confidence: computeApprovalAiConfidence(item, slaBucket),
    nextBestAction: buildApprovalAiNextAction(item, slaBucket),
    evidence: buildApprovalAiEvidence(item, slaBucket),
    checklist: buildApprovalAiChecklist(item.domain),
    disclaimer:
      "Draft — approval summaries are rule-based today. Live AI integration will enrich context without auto-approving requests.",
    source: opts.source || "client",
  };
}

export function buildApprovalAiSummaryDraft(item) {
  const brief = buildApprovalAiSummaryBrief(item);
  if (!brief) {
    return null;
  }
  return {
    summary: brief.summary,
    recommendation: brief.recommendation,
    confidence: brief.confidence,
    disclaimer: brief.disclaimer,
  };
}

export function normalizeApprovalAiSummary(row) {
  if (!row) {
    return null;
  }
  return {
    summary: row.summary || "",
    recommendation: row.recommendation || "",
    confidence: row.confidence != null ? row.confidence : 0.5,
    nextBestAction: row.nextBestAction || "",
    evidence: row.evidence || [],
    checklist: (row.checklist || []).map((item, index) => ({
      id: item.id || `check-${index}`,
      label: item.label || "Check",
      detail: item.detail || "",
    })),
    disclaimer: row.disclaimer || "",
    source: row.source || "api",
  };
}

export function toApprovalAiSummaryRequest(item, slaState) {
  if (!item) {
    return null;
  }
  return {
    universalId: item.id,
    domain: item.domain,
    requester: item.requester,
    subject: item.subject,
    status: item.status,
    priority: item.priority,
    submittedAt: item.submittedAt,
    dueLabel: item.dueLabel,
    actingAsDelegate: item.actingAsDelegate === true,
    slaBucket: slaState && slaState.bucket ? slaState.bucket : null,
    metadata: item.metadata || {},
  };
}
