class FeedbackPageSection extends Component {
  constructor() {
    super();
    this.state = {
      viewMode: "PAGE",
      projectModuleConfig:{},
      filterOptions: {
        SHOW: {
          options: [
            { name: "ALL", label: "All" },
            { name: "ACTIVE", label: "Active" },
            { name: "INACTIVE", label: "In Active" },
          ],
          selected: "ALL",
        },
        SORT: {
          options: [
            { name: "CREATEDDATE", label: "Created Date" },
            { name: "A-Z", label: "A-Z" },
          ],
          selected: "CREATEDDATE",
          directionUp: true,
        },
        filterText: null,
      },
      permission: accessUtils.getFeedbackTemplateAccessControl(),
      permissionFeedbackRequest: accessUtils.getFeedbackRequestAccessControl(),
      editMode: false,
      showCreateWindow: false,
      formErrors: {},
      page: 1,
      pageSize: REGISTER_DEFAULT_PAGE_SIZE,
    };
  }

  componentDidUpdate(prevProps) {
    if (shouldResetRegisterPage(prevProps, this.props)) {
      this.setState({ page: 1 });
    }
  }

  handlePageChange = (page) => {
    this.setState({ page });
  };

  handlePageSizeChange = (pageSize) => {
    this.setState({ pageSize, page: 1 });
  };

  componentDidMount() {
    this.setState({
      type: this.props.feedbackType,
    });

    if (this.props.feedbackType) {
      this.setState({
        viewMode: this.props.feedbackType,
      });
      this.props.getAllFeedbackTemplates({
        itemType: this.props.feedbackType,
      });
      this.props.getAllFeedbackRequests({
        itemType: this.props.feedbackType,
        itemId: this.props.projectItem ? this.props.projectItem.id : null,
      });
    } else {
      this.props.getAllFeedbackRequests({
        itemType: "PROJECT",
      });
      this.props.pageHeaderNameChangeHandler(this.props.routeProp.name);
    }
    this.initialize();
    store.dispatch(projectActions.getModuleConfigData(userUtils.getCurrentTeamId(), (projectModuleConfig) => {
      this.setState({
        projectModuleConfig: projectModuleConfig
      });
    }))
  }

  initialize = () => {
    //store.dispatch(employeeActions.getAllEmployees())
    this.setState({
      showCroDropdownMenu: false,
      editMode: false,
      feedbackRequest: {
        userTeamId: commonUtils.getCurrentUserTeamId(),
        type: this.state.type || this.props.feedbackType,
        subType: "GENERAL",
        itemId: this.props.projectItem ? this.props.projectItem.id : null,
        itemName: this.props.projectItem ? this.props.projectItem.name : null,
        recurring: false,
        draft: false,
        active: true,
        feedbackRequestInfos: [],
      },
    });
  };

  onChange = (feedbackRequest) => {
    this.setState({
      feedbackRequest: feedbackRequest,
    });
  };

  onCreateItemClick = () => {
    const itemType = this.state.type || this.props.feedbackType || "PROJECT";
    this.setState(
      {
        showCreateWindow: true,
        type: itemType,
      },
      () => {
        this.props.getAllFeedbackTemplates({ itemType });
        this.initialize();
      }
    );
  };

  closeCreateItemWindow = () => {
    this.setState({
      showCreateWindow: false,
      editMode: false,
    });
  };

  editFeedbackRequest = (feedbackRequest) => {
    if (feedbackRequest !== null) {
      this.setState({
        showCreateWindow: true,
        feedbackRequest: feedbackRequest,
        editMode: true,
      });
    } else {
      this.setState({
        feedbackRequest: null,
      });
    }
  };

  createFeedbackRequest = (createAnother) => {
    this.props.createFeedbackRequest(this.state.feedbackRequest, this.initialize);
    if (createAnother === false) {
      this.closeCreateItemWindow();
    }
  };

  updateFeedbackRequest = () => {
    this.props.updateFeedback(this.state.feedbackRequest, this.initialize);
    this.closeCreateItemWindow();
  };

  showFeedbackTemplateConfigureWindow = () => {
    store.dispatch({
      type: feedbackTemplateConstants.SHOW_FEEDBACK_TEMPLATE_CONFIGURE_WINDOW,
    });
  };

  handleFilterChange = (filterOptions) => {
    this.setState({ filterOptions: filterOptions }, () => {
      store.dispatch({
        type: feedbackRequestConstants.CHANGE_FILTER_FEEDBACKS,
        filterOptions,
      });
    });
  };

  onFilterTextChange = (value) => {
    this.setState(
      (prevState) => ({
        filterOptions: {
          ...prevState.filterOptions,
          filterText: value,
        },
      }),
      () => {
        this.handleFilterChange(this.state.filterOptions);
      }
    );
  };

  render() {
    const filterOptions =
      this.props.filterOptions || this.state.filterOptions;
    const allItems = this.props.items || [];
    const pagination = paginateRegisterList(
      allItems,
      this.state.page,
      this.state.pageSize
    );
    const items = pagination.items;
    const summary = buildFeedbackSummary(allItems);
    const isPageView = this.state.viewMode === "PAGE";
    const showList = isPageView || this.state.viewMode !== "PAGE";
    const canRequestFeedback =
      this.state.showCreateWindow === false &&
      this.state.permissionFeedbackRequest.createEnabled === true;
    const requestFeedbackButton = canRequestFeedback ? (
      <PageCreateButton onClick={this.onCreateItemClick}>Request Feedback</PageCreateButton>
    ) : null;

    return (
      <div
        className={classNames(
          "lux-feedback-page",
          "lux-bid-requests",
          isPageView ? "lux-project-requests lux-register-page" : "lux-feedback-page--embedded"
        )}
        data-testid={isPageView ? "page-project-feedback" : "project-details-feedback"}
      >
        {isPageView && (
          <LuxModuleIntro
            meta={DENSE_PAGE_META.projectFeedback}
            actions={requestFeedbackButton}
          />
        )}

        {!isPageView && (
          <section className="lux-feedback-project-banner" aria-label="Project feedback overview">
            <div className="lux-feedback-project-banner__glow" aria-hidden="true" />
            <div className="lux-feedback-project-banner__copy">
              <span className="lux-feedback-project-banner__eyebrow">
                <i className="fe fe-message-square" aria-hidden="true" />
                Project feedback
              </span>
              <h2 className="lux-feedback-project-banner__title">
                {(this.props.projectItem && this.props.projectItem.name) || "Feedback campaigns"}
              </h2>
              <p className="lux-feedback-project-banner__lede">
                Request client and team feedback, track responses, and keep this delivery project's
                voice of customer in one place.
              </p>
              {requestFeedbackButton ? (
                <div className="lux-module-hero__actions lux-feedback-project-banner__actions">
                  {requestFeedbackButton}
                </div>
              ) : null}
            </div>
            <div className="lux-feedback-project-banner__kpis" role="list">
              <div className="lux-feedback-project-banner__kpi" role="listitem">
                <span>Campaigns</span>
                <strong>{summary.total}</strong>
              </div>
              <div className="lux-feedback-project-banner__kpi" role="listitem">
                <span>Active</span>
                <strong>{summary.active}</strong>
              </div>
              <div className="lux-feedback-project-banner__kpi" role="listitem">
                <span>Responded</span>
                <strong>{summary.responded}</strong>
              </div>
              <div className="lux-feedback-project-banner__kpi" role="listitem">
                <span>Response rate</span>
                <strong>{summary.responseRate}%</strong>
              </div>
            </div>
          </section>
        )}

        <PageInnerHeader
          userTeams={[]}
          handleUserTeamsSelection={this.handleUserTeamsSelection}
          showGridListMenu={false}
          searchViewEnabled={false}
          handleSearchSubmit={this.handleSearchSubmit}
          showFilter={true}
          showUserTeamMenu={isPageView}
          isLoading={this.props.isLoading}
          filterOptions={filterOptions}
          handleFilterChange={this.handleFilterChange}
          onFilterTextChange={this.onFilterTextChange}
          showDateRangeSelector={false}
          handleDateRangeChange={this.handleDateRangeChange}
          permission={this.state.permission}
          additionalButtons={
            this.state.permission.createEnabled === true ? (
              <div className="lux-feedback-header-extra">
                <button
                  type="button"
                  className="lux-planner-btn lux-planner-btn--ghost"
                  title="Configure feedback templates"
                  onClick={() => this.showFeedbackTemplateConfigureWindow()}
                >
                  <i className="fe fe-sliders" aria-hidden="true" />
                  Configure template
                </button>
              </div>
            ) : null
          }
        />

        <FeedbackPageSummary
          summary={summary}
          isLoading={this.props.isLoading}
          visibleCount={pagination.total}
          filterText={(filterOptions && filterOptions.filterText) || ""}
          filterOptions={filterOptions}
          isEmpty={!this.props.isLoading && pagination.total === 0}
        />

        <LuxFeedbackRequestCreatePanel
          show={this.state.showCreateWindow && !!this.state.feedbackRequest}
          editMode={this.state.editMode}
          onClose={this.closeCreateItemWindow}
        >
          {this.state.showCreateWindow && this.state.feedbackRequest && (
            <CreateFeedbackRequestSection
              initialize={this.initialize}
              editMode={this.state.editMode}
              projectModuleConfig={this.state.projectModuleConfig}
              feedbackRequest={this.state.feedbackRequest}
              fieldConfig={this.props.feedbackFieldConfig}
              allEmployees={this.props.allEmployees}
              feedbackTypeOptions={this.props.feedbackTypeOptions}
              feedbackSubTypeOptions={this.props.feedbackSubTypeOptions}
              userTeamId={
                this.props.projectItem
                  ? this.props.projectItem.userTeamId
                  : commonUtils.getCurrentUserTeamId()
              }
              type={this.state.type || this.props.feedbackType}
              itemId={this.props.projectItem ? this.props.projectItem.id : null}
              itemName={this.props.projectItem ? this.props.projectItem.name : null}
              closeCreateItemWindow={this.closeCreateItemWindow}
              onChange={this.onChange}
              permission={this.state.permissionFeedbackRequest}
              createFeedbackRequest={this.createFeedbackRequest}
              updateFeedbackRequest={this.updateFeedbackRequest}
              emailInfoFieldConfig={this.props.emailInfoFieldConfig}
              feedbackTemplateDataList={this.props.feedbackTemplateDataList}
            />
          )}
        </LuxFeedbackRequestCreatePanel>
        {showList && this.state.viewMode !== "PAGE" && (
          <div className="lux-register-list-section lux-feedback-list-section">
            <FeedbackRequestsTable
              items={items}
              listTotal={pagination.total}
              isLoading={this.props.isLoading}
              editMode={this.state.editMode || this.state.showCreateWindow}
              getAllFeedbackScheulers={this.handleGetAllFeedbackScheulers}
              permission={this.state.permissionFeedbackRequest}
              enableFeedback={this.props.enableFeedback}
              removeFeedback={this.props.removeFeedback}
              removeFeedbackRequest={this.props.removeFeedbackRequest}
              remindFeedbackRequest={this.props.remindFeedbackRequest}
              updateFeedbackRequestStatus={this.props.updateFeedbackRequestStatus}
              editEnabled={true}
              editFeedbackRequest={this.editFeedbackRequest}
              onCreateRequest={this.onCreateItemClick}
              allUserTeams={this.props.allUserTeams}
              allEmployees={this.props.allEmployees}
            />
            {!this.props.isLoading && pagination.total > 0 && (
              <LuxRegisterPagination
                className="lux-register-list__pagination is-standalone"
                pagination={pagination}
                onPageChange={this.handlePageChange}
                onPageSizeChange={this.handlePageSizeChange}
                pageSizeOptions={REGISTER_PAGE_SIZE_OPTIONS}
                summaryLabel="campaigns"
              />
            )}
          </div>
        )}
        {showList && this.state.viewMode === "PAGE" && (
          <div className="lux-register-list-section lux-feedback-list-section">
            <FeedbackRequestsTableByItem
              items={items}
              listTotal={pagination.total}
              isLoading={this.props.isLoading}
              editMode={this.state.editMode || this.state.showCreateWindow}
              getAllFeedbackScheulers={this.handleGetAllFeedbackScheulers}
              permission={this.state.permissionFeedbackRequest}
              enableFeedback={this.props.enableFeedback}
              removeFeedback={this.props.removeFeedback}
              removeFeedbackRequest={this.props.removeFeedbackRequest}
              remindFeedbackRequest={this.props.remindFeedbackRequest}
              updateFeedbackRequestStatus={this.props.updateFeedbackRequestStatus}
              onCreateRequest={this.onCreateItemClick}
              allUserTeams={this.props.allUserTeams}
              allEmployees={this.props.allEmployees}
            />
            {!this.props.isLoading && pagination.total > 0 && (
              <LuxRegisterPagination
                className="lux-register-list__pagination is-standalone"
                pagination={pagination}
                onPageChange={this.handlePageChange}
                onPageSizeChange={this.handlePageSizeChange}
                pageSizeOptions={REGISTER_PAGE_SIZE_OPTIONS}
                summaryLabel="campaigns"
              />
            )}
          </div>
        )}
        <ConfigureFeedbackTemplateSidebar
          type={this.props.feedbackType}
          show={this.props.showFeedbackTemplateConfigureModel}
        />
      </div>
    );
  }
}

class CreateFeedbackRequestSection extends Component {
  constructor() {
    super();
    this.state = {
      formErrors: {},
      hasFormError: false,
    };
  }

  componentDidMount() {}
  onResetFormError = () => {
    this.setState({
      hasFormError: false,
    });
  };

  getFeedbackTypeOptions = () => {
    if (this.props.type && this.props.feedbackTypeOptions) {
      return this.props.feedbackTypeOptions.filter(
        (type) => type.value === this.props.type
      );
    }
    return this.props.feedbackTypeOptions;
  };

  getFeedbackSubTypeOptions = () => {
    return this.props.feedbackSubTypeOptions;
  };

  getItemOptions = () => {
    if (this.props.itemId) {
      return [{ value: this.props.itemId, label: this.props.itemName }];
    }
    //get all project or po or bid or employees
  };

  getFeedbackTemplateDataList = () => {
    return (
      this.props.feedbackTemplateDataList &&
      this.props.feedbackTemplateDataList.filter(
        (ftdl) => ftdl.subType === this.props.feedbackRequest.subType
      )
    );
  };
  onCreateAnotherEnabled = (value) => {
    this.setState({
      createAnotherEnabled: value,
    });
  };

  onFormError = (fieldName, hasError) => {
    this.setState((prevState) => ({
      formErrors: {
        ...prevState.formErrors,
        [fieldName]: hasError,
      },
    }));
  };

  onChange = (fieldName, value) => {
    this.onResetFormError();
    var scheduleData = null;
    var templateId =
      fieldName === "templateId"
        ? value
        : this.props.feedbackRequest.templateId;
    if (fieldName === "subType") {
      templateId = null;
    }
    if (fieldName === "recurring") {
      if (value === true) {
        scheduleData = {
          cronValue: "0 0 00 ? * SUN ",
          cronString: "At 12:00 AM, only on Sunday",
        };
      }
    }
    this.props.onChange({
      ...this.props.feedbackRequest,
      [fieldName]: value,
      templateId: templateId,
      scheduleData:
        fieldName === "recurring"
          ? scheduleData
          : this.props.feedbackRequest.scheduleData,
    });
  };

  onCronValueChange = (cronValue, cronString) => {
    this.props.onChange({
      ...this.props.feedbackRequest,
      scheduleData: {
        ...this.props.feedbackRequest.scheduleData,
        cronString: cronString,
        cronValue: cronValue.substr(0, cronValue.length - 1),
      },
    });
    this.toggeleCronMenu(false);
  };

  onChangeScheduleData = (fieldName, value) => {
    this.props.onChange({
      ...this.props.feedbackRequest,
      scheduleData: {
        ...this.props.feedbackRequest.scheduleData,
        [fieldName]: value,
      },
    });
  };
  toggeleCronMenu = (isShow) => {
    this.setState((prevState) => ({
      showCroDropdownMenu: isShow,
    }));
  };

  handleSubmit = (createAnotherEnabled) => {
    let isValid = validationUtils.isValidRequest(
      this.props.fieldConfig,
      this.props.feedbackRequest,
      this.state.formErrors
    );
    if (isValid) {
      if (this.props.editMode === true) {
        this.props.updateFeedbackRequest(false);
        //this.props.toggeleCreateWindow(false);
        //this.props.toggeleEditMote(false)
      } else {
        this.props.createFeedbackRequest(createAnotherEnabled);
      }
    } else {
      this.setState({
        hasFormError: true,
      });
    }
  };

  render() {
    if (!this.props.feedbackRequest) return null;

    return (
      <LuxFeedbackRequestCreateForm
        feedbackRequest={this.props.feedbackRequest}
        fieldConfig={this.props.fieldConfig}
        emailInfoFieldConfig={this.props.emailInfoFieldConfig}
        editMode={this.props.editMode}
        onChange={this.onChange}
        onFormError={this.onFormError}
        onChangeScheduleData={this.onChangeScheduleData}
        feedbackTypeOptions={this.getFeedbackTypeOptions()}
        feedbackSubTypeOptions={this.getFeedbackSubTypeOptions()}
        feedbackTemplateDataList={this.props.feedbackTemplateDataList}
        feedbackTemplateOptions={commonUtils.convertObjectToSelectObject(
          this.getFeedbackTemplateDataList()
        )}
        itemOptions={this.getItemOptions()}
        projectModuleConfig={this.props.projectModuleConfig}
        hasFormError={this.state.hasFormError}
        onResetFormError={this.onResetFormError}
        closeCreateItemWindow={this.props.closeCreateItemWindow}
        handleSubmit={this.handleSubmit}
        createButtonLabel={
          this.props.editMode ? "Save changes" : "Create feedback request"
        }
        showCronMenu={this.state.showCroDropdownMenu}
        onToggleCronMenu={this.toggeleCronMenu}
        onCronValueChange={this.onCronValueChange}
      />
    );
  }
}

class FeedbackRequestsTableByItem extends Component {
  constructor() {
    super();
    this.state = {
      expandedIds: [],
      clicked: false,
    };
  }

  toggleExpand = (id) => {
    var expandedIds = this.state.expandedIds;
    if (!this.state.expandedIds.includes(id)) {
      expandedIds.push(id);
    } else {
      expandedIds = expandedIds.filter((item) => item !== id);
    }
    this.setState({ expandedIds, clicked: true });
  };

  buildGroupStats = (campaigns) => {
    const list = campaigns || [];
    let recipients = 0;
    let responded = 0;
    list.forEach((item) => {
      const counts = countRecipientStatuses(item.feedbackRequestInfos);
      recipients += counts.total;
      responded += counts.responded;
    });
    return {
      campaignCount: list.length,
      recipients,
      responded,
      rate: recipients > 0 ? Math.round((responded / recipients) * 100) : 0,
      active: list.filter((item) => item.active !== false).length,
    };
  };

  render() {
    const listTotal = this.props.listTotal != null ? this.props.listTotal : (this.props.items || []).length;
    const isEmpty = !this.props.isLoading && listTotal === 0;
    const listByItems =
      this.props.items &&
      this.props.items.reduce(function (r, a) {
        let itemId = a.itemId;
        r[itemId] = r[itemId] || [];
        r[itemId].push(a);
        return r;
      }, Object.create(null));
    const groupKeys = listByItems ? Object.keys(listByItems) : [];

    return (
      <div className="lux-feedback-groups">
        {this.props.isLoading &&
          [1, 2, 3].map((k) => <Skeleton key={k} height={112} borderRadius={18} />)}
        {!this.props.isLoading &&
          groupKeys.map((key, index) => {
            const campaigns = listByItems[key];
            const stats = this.buildGroupStats(campaigns);
            const expanded =
              this.state.expandedIds.includes(key) ||
              (this.state.expandedIds.length === 0 && index === 0 && this.state.clicked === false);
            return (
            <section
              key={key}
              className={classNames("lux-feedback-group", { "is-expanded": expanded })}
            >
              <div className="lux-feedback-group__header">
                <button
                  type="button"
                  className="lux-feedback-group__toggle"
                  onClick={() => this.toggleExpand(key)}
                  aria-expanded={expanded}
                >
                  <span className="lux-feedback-group__chevron" aria-hidden="true">
                    <i className={classNames("fe", expanded ? "fe-chevron-down" : "fe-chevron-right")} />
                  </span>
                  <span className="lux-feedback-group__icon" aria-hidden="true">
                    <i className="fe fe-folder" />
                  </span>
                  <span className="lux-feedback-group__copy">
                    <span className="lux-feedback-group__id">Project #{key}</span>
                    <span className="lux-feedback-group__name">{campaigns[0].itemName}</span>
                    <span className="lux-feedback-group__meta">
                      {stats.campaignCount} campaign{stats.campaignCount === 1 ? "" : "s"}
                      {" · "}
                      {stats.active} active
                      {" · "}
                      {stats.rate}% response
                    </span>
                  </span>
                </button>
                <div className="lux-feedback-group__stats" aria-hidden="true">
                  <span className="lux-feedback-group__stat">
                    <strong>{stats.responded}</strong>
                    <em>of {stats.recipients}</em>
                  </span>
                </div>
                <a
                  className="lux-feedback-group__open"
                  target="_blank"
                  rel="noopener noreferrer"
                  href={`/project/details/${key}?view=feedback`}
                  title="Open project feedback"
                  aria-label="Open project"
                >
                  <i className="fe fe-external-link" aria-hidden="true" />
                </a>
              </div>
              {expanded && (
                <div className="lux-feedback-group__body">
                  <FeedbackRequestsTable
                    items={campaigns}
                    editMode={false}
                    getAllFeedbackScheulers={this.handleGetAllFeedbackScheulers}
                    permission={this.props.permission}
                    enableFeedback={this.props.enableFeedback}
                    removeFeedback={this.props.removeFeedback}
                    removeFeedbackRequest={this.props.removeFeedbackRequest}
                    remindFeedbackRequest={this.props.remindFeedbackRequest}
                    updateFeedbackRequestStatus={
                      this.props.updateFeedbackRequestStatus
                    }
                    editEnabled={false}
                    editFeedbackRequest={() => {}}
                    allUserTeams={this.props.allUserTeams}
                    allEmployees={this.props.allEmployees}
                  />
                </div>
              )}
            </section>
            );
          })}
        {isEmpty && (
          <LuxRegisterEmptyState
            variant="projects"
            eyebrow="Feedback"
            title="No feedback campaigns yet"
            description="Request feedback from clients and teams — use templates and track responses in one place."
            hints={[
              "Click Request Feedback to start a new campaign",
              "Add recipient emails before sending",
              "Configure templates for reusable question sets",
            ]}
            showCreate={this.props.permission && this.props.permission.createEnabled}
            createLabel="Request feedback"
            onCreate={this.props.onCreateRequest}
          />
        )}
      </div>
    );
  }
}

class FeedbackRequestsTable extends Component {
  render() {
    const items = this.props.items || [];
    const listTotal = this.props.listTotal != null ? this.props.listTotal : items.length;
    const oneOff = items.filter((fr) => fr.recurring === false);
    const recurring = items.filter((fr) => fr.recurring === true);
    const isEmpty = !this.props.isLoading && listTotal === 0;

    return (
      <div className="lux-feedback-list">
          {this.props.isLoading &&
            [1, 2, 3, 4].map((k) => <Skeleton key={k} height={128} borderRadius={18} />)}
          {!this.props.isLoading && oneOff.length > 0 && (
            <FeedbackRequestsTableItems
              items={oneOff}
              editMode={this.props.editMode}
              editEnabled={this.props.editEnabled}
              permission={this.props.permission}
              removeFeedbackRequest={this.props.removeFeedbackRequest}
              remindFeedbackRequest={this.props.remindFeedbackRequest}
              editFeedbackRequest={this.props.editFeedbackRequest}
              updateFeedbackRequestStatus={
                this.props.updateFeedbackRequestStatus
              }
              enableFeedback={this.props.enableFeedback}
              removeFeedback={this.props.removeFeedback}
            />
          )}
          {!this.props.isLoading && recurring.length > 0 && (
            <div className="lux-feedback-list__section-head">
              <i className="fe fe-repeat" aria-hidden="true" />
              <span>Recurring schedules</span>
              <span className="lux-feedback-list__section-count">{recurring.length}</span>
            </div>
          )}
          {!this.props.isLoading && recurring.length > 0 && (
            <FeedbackRequestsTableItems
              items={recurring}
              editMode={this.props.editMode}
              editEnabled={this.props.editEnabled}
              permission={this.props.permission}
              removeFeedbackRequest={this.props.removeFeedbackRequest}
              remindFeedbackRequest={this.props.remindFeedbackRequest}
              editFeedbackRequest={this.props.editFeedbackRequest}
              updateFeedbackRequestStatus={
                this.props.updateFeedbackRequestStatus
              }
              enableFeedback={this.props.enableFeedback}
              removeFeedback={this.props.removeFeedback}
            />
          )}
          {isEmpty && (
            <LuxRegisterEmptyState
              variant="projects"
              eyebrow="Feedback"
              title="No feedback campaigns yet"
              description="Request feedback from clients and teams — use templates and track responses in one place."
              hints={[
                "Click Request Feedback to start a new campaign",
                "Add recipient emails before sending",
                "Configure templates for reusable question sets",
              ]}
              showCreate={this.props.permission && this.props.permission.createEnabled}
              createLabel="Request feedback"
              onCreate={this.props.onCreateRequest}
            />
          )}
        </div>
    );
  }
}

class FeedbackRequestsTableItems extends Component {
  render() {
    return (
      <>
        {this.props.items.map((item) => (
          <FeedbackRequestsTableItem
            key={item.id}
            item={item}
            editMode={this.props.editMode}
            editEnabled={this.props.editEnabled}
            permission={this.props.permission}
            removeFeedbackRequest={this.props.removeFeedbackRequest}
            remindFeedbackRequest={this.props.remindFeedbackRequest}
            editFeedbackRequest={this.props.editFeedbackRequest}
            updateFeedbackRequestStatus={this.props.updateFeedbackRequestStatus}
            enableFeedback={this.props.enableFeedback}
            removeFeedback={this.props.removeFeedback}
          />
        ))}
      </>
    );
  }
}

class FeedbackRequestsTableItem extends Component {
  constructor() {
    super();
    this.state = {
      confrimDelete: false,
      popoverOpen: false,
    };
  }

  openPopover = () => {
    this.setState({ popoverOpen: true });
  };

  closePopover = () => {
    this.setState({ popoverOpen: false });
  };

  handleEnableFeedback = (isEnabled) => {
    this.props.enableFeedback(this.props.item.id, isEnabled);
  };

  handleEdit = (id, item) => {
    this.props.editFeedbackRequest(item);
  };

  handleRemoveFeedback = (isConfrimDelete) => {
    if (isConfrimDelete) {
      this.props.removeFeedback(this.props.item.id);
    } else {
      this.setState({
        confrimDelete: true,
      });
    }
  };

  getFeedbackRequestCounts = () => {
    var totalFeedbackCount =
      (this.props.item.feedbackRequestInfos &&
        this.props.item.feedbackRequestInfos.length) ||
      0;
    var receivedFeedbackCount =
      (this.props.item.feedbackRequestInfos &&
        this.props.item.feedbackRequestInfos.filter(
          (fr) =>
            fr.status === "RECEIVED" ||
            fr.status === "REVIEWED" ||
            fr.status === "CLOSED"
        ).length) ||
      0;
    return {
      receivedFeedbackCount,
      totalFeedbackCount: totalFeedbackCount - receivedFeedbackCount,
    };
  };

  isEditEnabled = () => {
    var totalFeedbackCount =
      (this.props.item.feedbackRequestInfos &&
        this.props.item.feedbackRequestInfos.length) ||
      0;
    var draftFeedbackCount =
      (this.props.item.feedbackRequestInfos &&
        this.props.item.feedbackRequestInfos.filter(
          (fr) => fr.status === "DRAFT"
        ).length) ||
      0;
    return totalFeedbackCount === draftFeedbackCount;
  };

  getStatusValue = () => {
    if (this.props.item.recurring === true) {
      return -1;
    }

    if (this.props.item.active === false) {
      return 0;
    }

    if (this.isFeedbackExpired()) {
      return 7;
    }

    var draftFeedbackCount =
      (this.props.item.feedbackRequestInfos &&
        this.props.item.feedbackRequestInfos.filter(
          (fr) => fr.status === "DRAFT"
        ).length) ||
      0;
    if (draftFeedbackCount > 0) {
      return 1;
    }

    var requestedFeedbackCount =
      (this.props.item.feedbackRequestInfos &&
        this.props.item.feedbackRequestInfos.filter(
          (fr) => fr.status === "REQUESTED"
        ).length) ||
      0;

    var reviwedFeedbackCount =
      (this.props.item.feedbackRequestInfos &&
        this.props.item.feedbackRequestInfos.filter(
          (fr) => fr.status === "REVIEWED"
        ).length) ||
      0;

    if (requestedFeedbackCount > 0) {
      return 2;
    }
    var totalFeedbackCount =
      (this.props.item.feedbackRequestInfos &&
        this.props.item.feedbackRequestInfos.length) ||
      0;
    var closedFeedbackCount =
      (this.props.item.feedbackRequestInfos &&
        this.props.item.feedbackRequestInfos.filter(
          (fr) => fr.status === "CLOSED"
        ).length) ||
      0;
    if (closedFeedbackCount > 0 && closedFeedbackCount === totalFeedbackCount) {
      return 3;
    }
    var receivedFeedbackCount =
      (this.props.item.feedbackRequestInfos &&
        this.props.item.feedbackRequestInfos.filter(
          (fr) => fr.status === "RECEIVED"
        ).length) ||
      0;
    if (
      receivedFeedbackCount > 0 &&
      receivedFeedbackCount === totalFeedbackCount
    ) {
      return 4;
    }
    if (
      reviwedFeedbackCount > 0 &&
      reviwedFeedbackCount === totalFeedbackCount
    ) {
      return 5;
    }
    return 6;
  };

  isFeedbackExpired = () => {
    return (
      dateUtils.compareTwoMoments(
        moment(this.props.item.expiryDate).endOf("day"),
        moment()
      ) === 1
    );
  };

  getStatusIconClass = () => {
    const v = this.getStatusValue();
    if (v === -1) return this.props.item.active ? "fe-repeat is-on" : "fe-repeat is-off";
    if (v === 0) return "fe-pause-circle is-off";
    if (v === 1 && this.isFeedbackExpired()) return "fe-alert-circle is-off blink_text";
    if (v === 1) return "fe-edit-3 is-info";
    if (v === 2) return "fe-loader is-spin";
    if (v === 3) return "fe-check-square is-on";
    if (v === 4) return "fe-inbox is-warn";
    if (v === 5) return "fe-check-circle is-on";
    if (v === 7) return "fe-alert-circle is-off blink_text";
    return "fe-help-circle is-warn";
  };

  render() {
    const item = this.props.item;
    const campaignStatus = getCampaignStatusSummary(item);
    const recipientCounts = countRecipientStatuses(item.feedbackRequestInfos);
    const responseRate =
      recipientCounts.total > 0
        ? Math.round((recipientCounts.responded / recipientCounts.total) * 100)
        : 0;
    const { popoverOpen } = this.state;
    const cronLabel =
      (item.scheduleData && item.scheduleData.cronString) || item.cronString || "";

    return (
      <article
        className={classNames("lux-feedback-card", `is-tone-${campaignStatus.tone}`, {
          "is-popover-open": popoverOpen,
          "is-recurring": item.recurring === true,
        })}
      >
        <div className="lux-feedback-card__accent" aria-hidden="true" />
        <div
          className="lux-feedback-card__bar"
          onClick={this.openPopover}
          onKeyDown={(e) => {
            if (e.key === "Enter" || e.key === " ") {
              e.preventDefault();
              this.openPopover();
            }
          }}
          role="button"
          tabIndex={0}
          aria-expanded={popoverOpen}
          aria-haspopup="dialog"
        >
          <div className="lux-feedback-card__main">
            <span
              className={classNames(
                "lux-feedback-card__badge",
                `is-${campaignStatus.tone}`
              )}
              aria-hidden="true"
            >
              <i className={classNames("fe", campaignStatus.icon || "fe-message-square")} />
            </span>

            <div className="lux-feedback-card__copy">
              <div className="lux-feedback-card__title-row">
                <h3 className="lux-feedback-card__name" title={item.name}>
                  {item.name || "Untitled campaign"}
                </h3>
                <span className={`lux-feedback-card__status-pill is-${campaignStatus.tone}`}>
                  {campaignStatus.label}
                </span>
              </div>
              {campaignStatus.hint ? (
                <p className="lux-feedback-card__hint">{campaignStatus.hint}</p>
              ) : null}
              <div className="lux-feedback-card__meta">
                <span className="lux-feedback-card__meta-chip">
                  <i className="fe fe-hash" aria-hidden="true" />
                  {item.id}
                </span>
                {item.subType ? (
                  <span className="lux-feedback-card__meta-chip">
                    <i className="fe fe-tag" aria-hidden="true" />
                    {item.subType}
                  </span>
                ) : null}
                {item.type ? (
                  <span className="lux-feedback-card__meta-chip">
                    <i className="fe fe-layers" aria-hidden="true" />
                    {getFeedbackTypeLabel(item.type)}
                  </span>
                ) : null}
                <span className="lux-feedback-card__meta-chip">
                  <i className="fe fe-calendar" aria-hidden="true" />
                  {dateUtils.convertDateFormat(item.createdDate)}
                </span>
                {item.expiryDate && item.recurring !== true ? (
                  <span className="lux-feedback-card__meta-chip">
                    <i className="fe fe-clock" aria-hidden="true" />
                    Expires {dateUtils.convertDateFormat(item.expiryDate)}
                  </span>
                ) : null}
                {cronLabel ? (
                  <span className="lux-feedback-card__meta-chip" title={cronLabel}>
                    <i className="fe fe-repeat" aria-hidden="true" />
                    {cronLabel}
                  </span>
                ) : null}
              </div>
            </div>
          </div>

          <div className="lux-feedback-card__side" onClick={(e) => e.stopPropagation()}>
            {item.recurring !== true && (
              <div className="lux-feedback-card__metrics" aria-label="Campaign metrics">
                <div className="lux-feedback-card__metric">
                  <span>Recipients</span>
                  <strong>{recipientCounts.total}</strong>
                </div>
                <div className="lux-feedback-card__metric is-good">
                  <span>Responded</span>
                  <strong>{recipientCounts.responded}</strong>
                </div>
                <div className="lux-feedback-card__metric is-warn">
                  <span>Awaiting</span>
                  <strong>{recipientCounts.awaiting}</strong>
                </div>
                <div className="lux-feedback-card__metric is-rate">
                  <span>Rate</span>
                  <strong>{responseRate}%</strong>
                </div>
              </div>
            )}

            <div className="lux-feedback-card__actions">
              <span className="lux-feedback-card__open-hint">
                <i className="fe fe-maximize-2" aria-hidden="true" />
                Details
              </span>
              {this.props.permission.activateEnabled === true && (
                <label className="custom-switch custom-switch-sm m-0" title={item.active ? "Active" : "Inactive"}>
                  <input
                    type="checkbox"
                    onChange={() => {}}
                    onClick={() => this.handleEnableFeedback(!item.active)}
                    checked={!!item.active}
                    className="custom-switch-input"
                  />
                  <span className="custom-switch-indicator" />
                </label>
              )}
              {this.props.editMode === false &&
                this.props.editEnabled === true &&
                this.props.permission.editEnabled === true && (
                  <button
                    type="button"
                    className="lux-feedback-card__icon-btn"
                    disabled={!this.isEditEnabled()}
                    onClick={() => this.handleEdit(item.id, item)}
                    title="Edit"
                    aria-label="Edit"
                  >
                    <i className="fe fe-edit-2" aria-hidden="true" />
                  </button>
                )}
              {this.props.permission.removeEnabled === true && (
                <button
                  type="button"
                  className={classNames("lux-feedback-card__icon-btn", "is-delete", {
                    blink_text: this.state.confrimDelete,
                  })}
                  onClick={() => this.handleRemoveFeedback(this.state.confrimDelete)}
                  title={this.state.confrimDelete ? "Confirm delete" : "Remove"}
                  aria-label={this.state.confrimDelete ? "Confirm delete" : "Remove"}
                >
                  <i
                    className={classNames("fe", this.state.confrimDelete ? "fe-check" : "fe-trash-2")}
                    aria-hidden="true"
                  />
                </button>
              )}
            </div>
          </div>

          {item.recurring !== true && recipientCounts.total > 0 && (
            <div className="lux-feedback-card__progress" aria-hidden="true">
              <div className="lux-feedback-card__progress-track">
                <div
                  className="lux-feedback-card__progress-fill"
                  style={{ width: `${responseRate}%` }}
                />
              </div>
            </div>
          )}
        </div>

        {popoverOpen && (
          <LuxFeedbackCampaignPopover
            show
            onClose={this.closePopover}
            item={item}
            permission={this.props.permission}
            editMode={this.props.editMode}
            editEnabled={this.props.editEnabled}
            onEdit={this.handleEdit}
            onToggleActive={this.handleEnableFeedback}
            removeFeedbackRequest={this.props.removeFeedbackRequest}
            remindFeedbackRequest={this.props.remindFeedbackRequest}
            updateFeedbackRequestStatus={this.props.updateFeedbackRequestStatus}
          />
        )}
      </article>
    );
  }
}

const mapStateToProps = (state) => ({
  showFeedbackTemplateConfigureModel:
    state.feedbackTemplate.isShowConfigureFeedbackTemplateSidebar,
  isLoading: state.feedbackRequest.feedbackTemplatesLoading,
  userTeams: commonUtils.getUserTeams(state.feedbackRequest.userTeams),
  allUserTeams: state.appconfig.allTeams,
  items: commonUtils.filterFeedbacks(
    state.feedbackRequest.feedbackItems,
    state.feedbackRequest.filterOptions
  ),
  feedbackTemplateDataList: state.feedbackTemplate.templateItems,
  filterOptions: state.feedbackRequest.filterOptions,
  emailInfoFieldConfig: state.feedbackRequest.emailInfoFieldConfig,
  feedbackFieldConfig: state.feedbackRequest.feedbackFieldConfig,
  feedbackTypeOptions: state.feedbackRequest.feedbackTypeOptions,
  feedbackSubTypeOptions: state.feedbackRequest.feedbackSubTypeOptions,
});
const mapDispatchToProps = (dispatch) => ({
  createFeedbackRequest: (request, callback) =>
    dispatch(feedbackRequestActions.createFeedbackRequest(request, callback)),
  updateFeedback: (request, callback) =>
    dispatch(feedbackRequestActions.updateFeedback(request, callback)),
  updateFeedbackRequestStatus: (...args) =>
    dispatch(feedbackRequestActions.updateFeedbackRequestStatus(...args)),
  updateFeedbackTemplate: (...args) =>
    dispatch(feedbackRequestActions.updateFeedbackTemplate(...args)),
  getAllFeedbackTemplates: (params) =>
    dispatch(feedbackTemplateActions.getAllFeedbackTemplates(params)),
  getAllFeedbackRequests: (params) =>
    dispatch(feedbackRequestActions.getAllFeedbackRequests(params)),
  removeFeedbackRequest: (...args) =>
    dispatch(feedbackRequestActions.removeFeedbackRequest(...args)),
  remindFeedbackRequest: (id) => dispatch(feedbackRequestActions.remindFeedbackRequest(id)),
  enableFeedback: (id, enabled) =>
    dispatch(feedbackRequestActions.activateFeedback(id, enabled)),
  removeFeedback: (id) => dispatch(feedbackRequestActions.removeFeedback(id)),
});
export default connect(
  mapStateToProps,
  mapDispatchToProps
)(FeedbackPageSection);
