import { shouldUseWorkflowAutomation } from "config/tracopus-pilot.config";
import envconfig from "env.config";
import { isMockDataEnabled } from "mock/mock.config";

/** F27 — Workflow automation studio. */

export function isWorkflowAutomationEnabled() {
  if (shouldUseWorkflowAutomation()) {
    return true;
  }
  if (isMockDataEnabled()) {
    return true;
  }
  return envconfig.ENV_NAME === "development";
}

export function shouldUseWorkflowAutomationApi() {
  return envconfig.USE_WORKFLOW_AUTOMATION_API === true;
}

