import React, { Component } from "react";
import classNames from "classnames/bind";
import { PersonaContext } from "context/PersonaContextProvider";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { onboardingService } from "_services/onboarding.service";
import {
  isOnboardingSelfServiceRouteEnabled,
  SELF_SERVICE_TASK_FILTERS,
} from "config/onboarding.config";
import {
  buildSelfServiceMetrics,
  canSelfServiceCompleteTask,
  filterSelfServiceTasksByStatus,
} from "config/onboarding.utils";
import SelfServiceSummary from "views/people/components/onboarding/SelfServiceSummary";
import SelfServiceTaskPanel from "views/people/components/onboarding/SelfServiceTaskPanel";
import OnboardingTaskDrawer from "views/people/components/onboarding/OnboardingTaskDrawer";

class OnboardingSelfServicePage extends Component {
  static contextType = PersonaContext;

  state = {
    caseData: null,
    loading: true,
    loadError: null,
    statusFilter: "ACTION",
    selectedTask: null,
    drawerOpen: false,
    completing: false,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("My onboarding");
    this.loadCase();
  }

  loadCase = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const res = await onboardingService.getMyOnboardingCase();
      if (!res.payload) {
        this.setState({
          caseData: null,
          loading: false,
          loadError: "no_case",
        });
        return;
      }
      this.setState({ caseData: res.payload, loading: false, loadError: null });
    } catch (_e) {
      this.setState({ loading: false, loadError: "fetch_error" });
    }
  };

  handleStatusChange = (statusFilter) => {
    this.setState({ statusFilter });
  };

  handleTaskSelect = (task) => {
    this.setState({ selectedTask: task, drawerOpen: true });
  };

  handleDrawerClose = () => {
    this.setState({ drawerOpen: false, selectedTask: null });
  };

  handleCompleteTask = async (task) => {
    const { caseData } = this.state;
    if (!caseData || !task || this.state.completing) {
      return;
    }
    if (!canSelfServiceCompleteTask(task, caseData.tasks)) {
      return;
    }
    this.setState({ completing: true });
    try {
      await onboardingService.completeMyOnboardingTask(caseData.id, task.id);
      await this.loadCase();
      this.setState({ drawerOpen: false, selectedTask: null, completing: false });
    } catch (_e) {
      this.setState({ completing: false });
    }
  };

  renderFilterBar = (resultCount) => {
    const { statusFilter } = this.state;
    return (
      <div className="lux-onb-self-service__toolbar">
        <div className="lux-hrms-dash__filter-group" role="group" aria-label="Task filter">
          {SELF_SERVICE_TASK_FILTERS.map((filter) => (
            <button
              key={filter.id}
              type="button"
              className={classNames("lux-hrms-dash__filter-chip", {
                "is-active": statusFilter === filter.id,
              })}
              onClick={() => this.handleStatusChange(filter.id)}
            >
              {filter.label}
            </button>
          ))}
        </div>
        <span className="lux-onb-self-service__result-count">
          {resultCount} task{resultCount === 1 ? "" : "s"}
        </span>
      </div>
    );
  };

  render() {
    const personaCtx = this.context || {};
    if (!isOnboardingSelfServiceRouteEnabled(personaCtx.menuAccessControl)) {
      return (
        <PersonaAccessDenied
          moduleName="My onboarding"
          reason="The new-hire self-service portal is not enabled for your organization."
        />
      );
    }

    const {
      caseData,
      loading,
      loadError,
      statusFilter,
      selectedTask,
      drawerOpen,
      completing,
    } = this.state;

    const tasks = caseData ? caseData.tasks || [] : [];
    const filteredTasks = filterSelfServiceTasksByStatus(tasks, statusFilter);
    const metrics = buildSelfServiceMetrics(tasks);

    return (
      <div className="lux-onb-page lux-onb-self-service-page lux-hrms-dash" data-testid="page-onboarding-self-service">
        {!loading && loadError === "no_case" && (
          <LuxRegisterEmptyState
            className="lux-register-empty--compact lux-onb-empty"
            icon="fe fe-user-plus"
            title="No onboarding checklist found"
            description="We could not match an active onboarding case to your account. Contact HR if you are expecting pre-boarding tasks."
          />
        )}

        {loadError === "fetch_error" && (
          <div className="lux-onb-page__error" role="alert">
            Unable to load your onboarding tasks.{" "}
            <button type="button" className="lux-onb-self-service__retry" onClick={this.loadCase}>
              Retry
            </button>
          </div>
        )}

        {(loading || caseData) && (
          <>
            <SelfServiceSummary caseData={caseData} metrics={metrics} loading={loading} />

            <section className="lux-hrms-dash__panel lux-onb-self-service__queue">
              <header className="lux-hrms-dash__panel-head">
                <div>
                  <h2 className="lux-hrms-dash__panel-title">Your tasks</h2>
                  <p className="lux-hrms-dash__panel-sub">
                    Complete documents, policy acknowledgments, payroll details, and training before day one.
                  </p>
                </div>
              </header>
              <div className="lux-hrms-dash__panel-body">
                {this.renderFilterBar(filteredTasks.length)}
                <SelfServiceTaskPanel
                  tasks={filteredTasks}
                  statusFilter={statusFilter}
                  onTaskSelect={this.handleTaskSelect}
                  loading={loading}
                />
              </div>
            </section>
          </>
        )}

        <OnboardingTaskDrawer
          task={selectedTask}
          caseData={caseData}
          open={drawerOpen}
          completing={completing}
          lifecycle="onboarding"
          selfServiceMode
          onClose={this.handleDrawerClose}
          onComplete={this.handleCompleteTask}
        />
      </div>
    );
  }
}

export default OnboardingSelfServicePage;
